def render_planning_chain_plain(chain: dict[str, Any]) -> None:
    validate_growth_planning_chain_preview(chain)
    gap_counts = chain["capability_gap_preview"]["counts"]
    upgrade_plan = chain["upgrade_execution_plan"]
    branch_plan = chain["implementation_branch_plan"]
    work_packages = chain["implementation_work_packages"]
    verification = chain["verification_plan"]
    stage_summary = chain["stage_summary"]
    action = chain["top_recommended_next_action"]
    print("Growth planning-chain preview")
    print(f"planning_chain_id: {chain['planning_chain_id']}")
    print(f"gaps: direct={gap_counts['direct_gap_count']} maturity={gap_counts['maturity_gap_count']} onboarding={gap_counts['onboarding_gap_count']} optional={gap_counts['optional_cross_cluster_idea_count']}")
    print(f"upgrade_plans: {upgrade_plan['upgrade_plan_count']}")
    print(f"branch_plan: {branch_plan['proposed_branch_name']} ({branch_plan['risk_level']}/{branch_plan['complexity']})")
    print(f"work_packages: {work_packages['package_count']}")
    print(f"verification_plans: {verification['plan_count']}")
    review_bundle = chain["planning_chain_review_bundle"]
    print(f"quality_gate: {stage_summary['quality_gate_status']}")
    print(f"execution_stages: {stage_summary['execution_stage_count']}")
    readiness = chain.get("execution_readiness_bundle", {})
    journal = chain.get("execution_journal_plan", {})
    evidence_contract = chain.get("execution_evidence_contract", {})
    preflight = chain.get("execution_preflight_checklist", {})
    attempt_history = chain.get("execution_attempt_history", {})
    dashboard_summary = chain.get("execution_readiness_dashboard_summary", {})
    if readiness:
        print(f"readiness_bundle: {readiness['execution_readiness_bundle_id']} ({readiness['readiness_status']})")
    if journal:
        print(f"execution_journal: {journal['execution_journal_id']} ({len(journal['journal_entries'])} planned entries)")
    if evidence_contract:
        print(f"evidence_contract: {evidence_contract['execution_evidence_contract_id']} ({evidence_contract['evidence_item_count']} required items)")
    if preflight and attempt_history:
        print(f"preflight: {preflight['pass_status']} blockers={preflight['blocker_count']} warnings={preflight['warning_count']} attempts={attempt_history['attempt_count']}")
    if dashboard_summary:
        print(f"dashboard: {dashboard_summary['readiness_status']}/{dashboard_summary['preflight_status']} blockers={len(dashboard_summary['top_blockers'])} warnings={len(dashboard_summary['top_warnings'])} next={dashboard_summary['recommended_next_action']}")
    print(f"review_bundle: {review_bundle['review_bundle_id']} ({review_bundle['patch_behavior_quality_gate']['pass_status']})")
    print(f"next_action: {review_bundle['recommended_next_action']}")


