PLANNING_CHAIN_REVIEW_BUNDLE_VERSION = "link-planning-chain-review-bundle-v1"


def make_planning_chain_review_bundle_id(chain: dict[str, Any]) -> str:
    import hashlib

    payload = _stable_ruflo_json({
        "execution_package_id": chain["autonomous_execution_package"]["execution_package_id"],
        "planning_chain_id": chain["planning_chain_id"],
        "quality_gate_id": chain["patch_behavior_quality_gate"]["quality_gate_id"],
        "verified_patch_diff_id": chain["verified_patch_diff"]["verified_patch_diff_id"],
        "verified_patch_plan_id": chain["verified_patch_plan"]["verified_patch_plan_id"],
        "version": PLANNING_CHAIN_REVIEW_BUNDLE_VERSION,
    })
    digest = hashlib.sha256(payload.encode("utf-8")).hexdigest()[:12]
    return f"planning-chain-review-bundle-{digest}"


def collect_planning_chain_review_bundle(
    chain: dict[str, Any] | None = None,
    *,
    metadata: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Summarize a full read-only planning chain for human review."""
    source_chain = chain if chain is not None else collect_growth_planning_chain_preview()
    validate_growth_planning_chain_preview(source_chain, require_review_bundle=False)
    action = source_chain["top_recommended_next_action"]
    patch_plan = source_chain["verified_patch_plan"]
    quality_gate = source_chain["patch_behavior_quality_gate"]
    execution_package = source_chain["autonomous_execution_package"]
    readiness_bundle = source_chain.get("execution_readiness_bundle")
    readiness_bundle_id = ""
    if isinstance(readiness_bundle, dict):
        readiness_bundle_id = str(readiness_bundle.get("execution_readiness_bundle_id") or "")
    evidence_contract = source_chain.get("execution_evidence_contract")
    evidence_contract_id = ""
    evidence_item_count = 0
    evidence_required_types: list[str] = []
    if isinstance(evidence_contract, dict):
        evidence_contract_id = str(evidence_contract.get("execution_evidence_contract_id") or "")
        evidence_item_count = int(evidence_contract.get("evidence_item_count") or 0)
        raw_items = evidence_contract.get("evidence_items") or []
        if isinstance(raw_items, list):
            evidence_required_types = _normalize_implementation_branch_refs([
                str(item.get("evidence_type") or "")
                for item in raw_items
                if isinstance(item, dict) and item.get("evidence_type")
            ])
    bundle = {
        "review_bundle_version": PLANNING_CHAIN_REVIEW_BUNDLE_VERSION,
        "review_bundle_id": make_planning_chain_review_bundle_id(source_chain),
        "planning_chain_id": source_chain["planning_chain_id"],
        "top_upgrade_id": action["upgrade_id"],
        "top_upgrade_title": action["title"],
        "branch_plan_id": action["branch_plan_id"],
        "work_package_id": action["package_id"],
        "verification_plan_id": action["verification_plan_id"],
        "verified_patch_plan_id": action["verified_patch_plan_id"],
        "verified_patch_diff_id": action["verified_patch_diff_id"],
        "patch_behavior_quality_gate": {
            "quality_gate_id": quality_gate["quality_gate_id"],
            "pass_status": quality_gate["pass_status"],
            "quality_score": quality_gate["quality_score"],
            "risk_score": quality_gate["risk_score"],
        },
        "autonomous_execution_package_id": action["execution_package_id"],
        "execution_readiness_bundle_id": readiness_bundle_id,
        "execution_evidence_contract_id": evidence_contract_id,
        "evidence_item_count": evidence_item_count,
        "evidence_required_types": evidence_required_types,
        "execution_stage_count": execution_package["stage_count"],
        "required_evidence": _normalize_implementation_branch_refs(patch_plan["required_evidence"]),
        "missing_evidence": _normalize_implementation_branch_refs(patch_plan["missing_evidence"]),
        "top_risks": _planning_chain_review_top_risks(quality_gate, source_chain["verified_patch_diff"]),
        "required_clarifications": _normalize_patch_behavior_text_list(quality_gate["required_clarifications"])
        if quality_gate["required_clarifications"] else [],
        "recommended_next_action": source_chain["top_recommended_next_action"]["summary"],
        "dry_run": True,
        "write_allowed": False,
        "automation_allowed": False,
        "metadata": dict(metadata or {}),
        "writes": [],
    }
    validate_planning_chain_review_bundle(bundle, source_chain)
    return bundle


def validate_planning_chain_review_bundle(
    bundle: dict[str, Any],
    chain: dict[str, Any] | None = None,
) -> None:
    required = (
        "review_bundle_version", "review_bundle_id", "planning_chain_id", "top_upgrade_id",
        "top_upgrade_title", "branch_plan_id", "work_package_id", "verification_plan_id",
        "verified_patch_plan_id", "verified_patch_diff_id", "patch_behavior_quality_gate",
        "autonomous_execution_package_id", "execution_readiness_bundle_id", "execution_evidence_contract_id", "evidence_item_count", "evidence_required_types", "execution_stage_count", "required_evidence",
        "missing_evidence", "top_risks", "required_clarifications", "recommended_next_action",
        "dry_run", "write_allowed", "automation_allowed", "metadata", "writes",
    )
    missing = [field for field in required if field not in bundle]
    if missing:
        raise ValueError(f"planning-chain review bundle missing fields: {missing}")
    if bundle["review_bundle_version"] != PLANNING_CHAIN_REVIEW_BUNDLE_VERSION:
        raise ValueError("unsupported planning-chain review bundle version")
    for field in (
        "review_bundle_id", "planning_chain_id", "top_upgrade_id", "top_upgrade_title",
        "branch_plan_id", "work_package_id", "verification_plan_id", "verified_patch_plan_id",
        "verified_patch_diff_id", "autonomous_execution_package_id", "recommended_next_action",
    ):
        if not isinstance(bundle[field], str) or not bundle[field].strip():
            raise ValueError(f"{field} must be a non-empty string")
    if not isinstance(bundle["execution_readiness_bundle_id"], str):
        raise TypeError("execution_readiness_bundle_id must be a string")
    if not isinstance(bundle["execution_evidence_contract_id"], str):
        raise TypeError("execution_evidence_contract_id must be a string")
    if not isinstance(bundle["evidence_item_count"], int) or bundle["evidence_item_count"] < 0:
        raise ValueError("evidence_item_count must be a non-negative integer")
    if not isinstance(bundle["evidence_required_types"], list):
        raise TypeError("evidence_required_types must be a list")
    if bundle["evidence_required_types"] != _normalize_implementation_branch_refs(bundle["evidence_required_types"]):
        raise ValueError("evidence_required_types must be normalized and sorted")
    if bundle["dry_run"] is not True or bundle["write_allowed"] is not False or bundle["automation_allowed"] is not False:
        raise ValueError("planning-chain review bundle must remain read-only")
    if bundle["writes"] != []:
        raise ValueError("planning-chain review bundle must not write files")
    if not isinstance(bundle["metadata"], dict):
        raise TypeError("planning-chain review bundle metadata must be a dict")
    if not isinstance(bundle["execution_stage_count"], int) or bundle["execution_stage_count"] < 0:
        raise ValueError("execution_stage_count must be a non-negative integer")
    gate = bundle["patch_behavior_quality_gate"]
    if not isinstance(gate, dict):
        raise TypeError("patch_behavior_quality_gate must be a dict")
    for field in ("quality_gate_id", "pass_status"):
        if not isinstance(gate.get(field), str) or not gate[field].strip():
            raise ValueError(f"patch_behavior_quality_gate.{field} must be a non-empty string")
    if gate["pass_status"] not in {"pass", "review", "block"}:
        raise ValueError("patch_behavior_quality_gate.pass_status must be pass, review, or block")
    _validate_probability_score(gate.get("quality_score"), "patch_behavior_quality_gate.quality_score")
    _validate_probability_score(gate.get("risk_score"), "patch_behavior_quality_gate.risk_score")
    for field in ("required_evidence", "missing_evidence", "top_risks", "required_clarifications"):
        values = bundle[field]
        if not isinstance(values, list):
            raise TypeError(f"{field} must be a list")
        if not all(isinstance(value, str) and value.strip() for value in values):
            raise TypeError(f"{field} must contain non-empty strings")
    for field in ("required_evidence", "missing_evidence"):
        if bundle[field] != _normalize_implementation_branch_refs(bundle[field]):
            raise ValueError(f"{field} must be normalized and sorted")
    for field in ("top_risks", "required_clarifications"):
        if bundle[field] and bundle[field] != _normalize_patch_behavior_text_list(bundle[field]):
            raise ValueError(f"{field} must be normalized and sorted")
    if chain is not None:
        validate_growth_planning_chain_preview(chain, require_review_bundle=False)
        action = chain["top_recommended_next_action"]
        patch_plan = chain["verified_patch_plan"]
        quality_gate = chain["patch_behavior_quality_gate"]
        execution_package = chain["autonomous_execution_package"]
        expected = {
            "planning_chain_id": chain["planning_chain_id"],
            "top_upgrade_id": action["upgrade_id"],
            "top_upgrade_title": action["title"],
            "branch_plan_id": action["branch_plan_id"],
            "work_package_id": action["package_id"],
            "verification_plan_id": action["verification_plan_id"],
            "verified_patch_plan_id": action["verified_patch_plan_id"],
            "verified_patch_diff_id": action["verified_patch_diff_id"],
            "autonomous_execution_package_id": action["execution_package_id"],
        }
        for field, value in expected.items():
            if bundle[field] != value:
                raise ValueError(f"planning-chain review bundle {field} does not match planning chain")
        if bundle["review_bundle_id"] != make_planning_chain_review_bundle_id(chain):
            raise ValueError("planning-chain review bundle id does not match planning chain")
        if bundle["execution_stage_count"] != execution_package["stage_count"]:
            raise ValueError("execution_stage_count must match autonomous execution package")
        if bundle["required_evidence"] != _normalize_implementation_branch_refs(patch_plan["required_evidence"]):
            raise ValueError("required_evidence must summarize verified patch plan")
        if bundle["missing_evidence"] != _normalize_implementation_branch_refs(patch_plan["missing_evidence"]):
            raise ValueError("missing_evidence must summarize verified patch plan")
        if bundle["patch_behavior_quality_gate"]["quality_gate_id"] != quality_gate["quality_gate_id"]:
            raise ValueError("quality gate summary must reference planning-chain quality gate")
        if bundle["patch_behavior_quality_gate"]["pass_status"] != quality_gate["pass_status"]:
            raise ValueError("quality gate summary must preserve pass_status")
        readiness_bundle = chain.get("execution_readiness_bundle")
        if isinstance(readiness_bundle, dict):
            expected_readiness_id = readiness_bundle.get("execution_readiness_bundle_id")
            if bundle["execution_readiness_bundle_id"] != expected_readiness_id:
                raise ValueError("review bundle must reference execution readiness bundle")
        elif bundle["execution_readiness_bundle_id"]:
            raise ValueError("review bundle cannot reference missing execution readiness bundle")
        evidence_contract = chain.get("execution_evidence_contract")
        if isinstance(evidence_contract, dict):
            expected_contract_id = evidence_contract.get("execution_evidence_contract_id")
            if bundle["execution_evidence_contract_id"] != expected_contract_id:
                raise ValueError("review bundle must reference execution evidence contract")
            if bundle["evidence_item_count"] != evidence_contract.get("evidence_item_count"):
                raise ValueError("review bundle evidence_item_count must summarize evidence contract")
            expected_types = _normalize_implementation_branch_refs([
                item["evidence_type"] for item in evidence_contract["evidence_items"]
            ])
            if bundle["evidence_required_types"] != expected_types:
                raise ValueError("review bundle evidence_required_types must summarize evidence contract")
        elif bundle["execution_evidence_contract_id"] or bundle["evidence_item_count"] or bundle["evidence_required_types"]:
            raise ValueError("review bundle cannot summarize missing execution evidence contract")


def stable_planning_chain_review_bundle_json(bundle: dict[str, Any]) -> str:
    validate_planning_chain_review_bundle(bundle)
    return _stable_ruflo_json(bundle, indent=2) + "\n"


def parse_planning_chain_review_bundle_json(text: str) -> dict[str, Any]:
    import json as _json

    bundle = _json.loads(text)
    validate_planning_chain_review_bundle(bundle)
    return bundle


def _planning_chain_review_top_risks(
    quality_gate: dict[str, Any],
    patch_diff: dict[str, Any],
) -> list[str]:
    risks: list[str] = []
    for finding in quality_gate["findings"]:
        if finding["severity"] in {"block", "review"}:
            risks.append(f"{finding['severity']}: {finding['message']}")
    if patch_diff["risk_score"] >= 0.55:
        risks.append(f"patch diff risk score is {patch_diff['risk_score']}")
    if not risks and quality_gate["pass_status"] == "pass":
        risks.append("no blocking or review-level patch behavior risks detected")
    return _normalize_patch_behavior_text_list(risks)



EXECUTION_WORKSPACE_PLAN_VERSION = "link-execution-workspace-plan-v1"
EXECUTION_EVENT_TIMELINE_VERSION = "link-execution-event-timeline-v1"
EXECUTION_RETRY_POLICY_VERSION = "link-execution-retry-policy-v1"
WITNESS_MANIFEST_PLAN_VERSION = "link-witness-manifest-plan-v1"
HUMAN_APPROVAL_PACKAGE_VERSION = "link-human-approval-package-v1"
EXECUTION_READINESS_BUNDLE_VERSION = "link-execution-readiness-bundle-v1"


def _execution_readiness_id(prefix: str, payload: dict[str, Any]) -> str:
    import hashlib

    digest = hashlib.sha256(_stable_ruflo_json(payload).encode("utf-8")).hexdigest()[:12]
    return f"{prefix}-{digest}"


def _validate_execution_read_only(payload: dict[str, Any], label: str) -> None:
    if payload.get("dry_run") is not True or payload.get("write_allowed") is not False or payload.get("automation_allowed") is not False:
        raise ValueError(f"{label} must remain read-only")
    if payload.get("writes") != []:
        raise ValueError(f"{label} must not write files")
    if not isinstance(payload.get("metadata"), dict):
        raise TypeError(f"{label} metadata must be a dict")


def _validate_non_empty_string(value: Any, field: str) -> None:
    if not isinstance(value, str) or not value.strip():
        raise ValueError(f"{field} must be a non-empty string")


def make_execution_workspace_plan_id(review_bundle: dict[str, Any], execution_package: dict[str, Any]) -> str:
    return _execution_readiness_id("execution-workspace-plan", {
        "execution_package_id": execution_package["execution_package_id"],
        "planning_chain_id": review_bundle["planning_chain_id"],
        "review_bundle_id": review_bundle["review_bundle_id"],
        "version": EXECUTION_WORKSPACE_PLAN_VERSION,
    })


def collect_execution_workspace_plan(
    chain: dict[str, Any] | None = None,
    *,
    repo_path: str = "/home/user/link",
    base_branch: str = "mine-hermes-upgrades-20260524",
    base_ref: str = "safe-link-latest",
    metadata: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Plan isolated future execution workspace state without creating anything."""
    source_chain = chain if chain is not None else collect_growth_planning_chain_preview()
    source_chain = _growth_planning_chain_without_runtime_fields(source_chain)
    validate_growth_planning_chain_preview(source_chain)
    review_bundle = source_chain["planning_chain_review_bundle"]
    execution_package = source_chain["autonomous_execution_package"]
    branch_plan = source_chain["implementation_branch_plan"]
    patch_plan = source_chain["verified_patch_plan"]
    workspace_id = make_execution_workspace_plan_id(review_bundle, execution_package)
    short_id = workspace_id.removeprefix("execution-workspace-plan-")
    proposed_branch = f"link/exec-{review_bundle['top_upgrade_id'][-24:]}-{short_id[:8]}"
    plan = {
        "workspace_plan_version": EXECUTION_WORKSPACE_PLAN_VERSION,
        "workspace_id": workspace_id,
        "planning_chain_id": review_bundle["planning_chain_id"],
        "review_bundle_id": review_bundle["review_bundle_id"],
        "execution_package_id": execution_package["execution_package_id"],
        "repo_path": str(repo_path).rstrip("/"),
        "base_branch": base_branch,
        "base_ref": base_ref,
        "proposed_branch_name": proposed_branch,
        "proposed_worktree_path": f"{str(repo_path).rstrip('/')}/.link/worktrees/{short_id}",
        "target_files": _normalize_implementation_branch_refs(patch_plan["target_files"]),
        "target_subsystems": _normalize_implementation_branch_refs(branch_plan["target_subsystems"]),
        "isolation_strategy": "planned_worktree",
        "cleanup_policy": "keep_on_unknown_or_failed_verification",
        "rollback_policy": "keep workspace for review unless explicit human approval authorizes discard",
        "preflight_checks": _normalize_patch_behavior_text_list([
            "confirm working tree state is clean or explicitly snapshotted",
            "confirm target files are inside the repository",
            "confirm patch behavior quality gate is not block",
            "confirm verification commands are allowlisted before execution",
            "confirm no research or runtime state paths are targeted",
        ]),
        "approval_requirements": _normalize_patch_behavior_text_list([
            "human approval required before branch creation",
            "human approval required before worktree creation",
            "human approval required before patch application",
            "human approval required before cleanup discard",
        ]),
        "verification_requirements": _normalize_patch_behavior_text_list([
            *source_chain["verification_plan"]["plans"][0]["compile_commands"],
            *source_chain["verification_plan"]["plans"][0]["test_commands"],
            *source_chain["verification_plan"]["plans"][0]["healthcheck_commands"],
        ]),
        "blocked": bool(review_bundle["missing_evidence"] or review_bundle["patch_behavior_quality_gate"]["pass_status"] == "block"),
        "requires_approval": True,
        "dry_run": True,
        "write_allowed": False,
        "automation_allowed": False,
        "metadata": dict(metadata or {}),
        "writes": [],
    }
    validate_execution_workspace_plan(plan, source_chain)
    return plan


def validate_execution_workspace_plan(plan: dict[str, Any], chain: dict[str, Any] | None = None) -> None:
    required = (
        "workspace_plan_version", "workspace_id", "planning_chain_id", "review_bundle_id",
        "execution_package_id", "repo_path", "base_branch", "base_ref", "proposed_branch_name",
        "proposed_worktree_path", "target_files", "target_subsystems", "isolation_strategy",
        "cleanup_policy", "rollback_policy", "preflight_checks", "approval_requirements",
        "verification_requirements", "blocked", "requires_approval", "dry_run", "write_allowed",
        "automation_allowed", "metadata", "writes",
    )
    missing = [field for field in required if field not in plan]
    if missing:
        raise ValueError(f"execution workspace plan missing fields: {missing}")
    if plan["workspace_plan_version"] != EXECUTION_WORKSPACE_PLAN_VERSION:
        raise ValueError("unsupported execution workspace plan version")
    _validate_execution_read_only(plan, "execution workspace plan")
    for field in ("workspace_id", "planning_chain_id", "review_bundle_id", "execution_package_id", "repo_path", "base_branch", "base_ref", "proposed_branch_name", "proposed_worktree_path", "isolation_strategy", "cleanup_policy", "rollback_policy"):
        _validate_non_empty_string(plan[field], field)
    if plan["isolation_strategy"] != "planned_worktree":
        raise ValueError("execution workspace plan must use planned_worktree isolation")
    if plan["cleanup_policy"] != "keep_on_unknown_or_failed_verification":
        raise ValueError("execution workspace plan cleanup policy must fail closed")
    if not isinstance(plan["blocked"], bool) or not isinstance(plan["requires_approval"], bool):
        raise TypeError("blocked and requires_approval must be booleans")
    for field in ("target_files", "target_subsystems", "preflight_checks", "approval_requirements", "verification_requirements"):
        values = plan[field]
        if not isinstance(values, list) or not values:
            raise TypeError(f"{field} must be a non-empty list")
        if values != _normalize_patch_behavior_text_list(values):
            raise ValueError(f"{field} must be normalized and sorted")
    if chain is not None:
        validate_growth_planning_chain_preview(chain)
        review_bundle = chain["planning_chain_review_bundle"]
        execution_package = chain["autonomous_execution_package"]
        if plan["workspace_id"] != make_execution_workspace_plan_id(review_bundle, execution_package):
            raise ValueError("workspace_id does not match planning chain")
        if plan["planning_chain_id"] != chain["planning_chain_id"]:
            raise ValueError("workspace plan must reference planning chain")
        if plan["review_bundle_id"] != review_bundle["review_bundle_id"]:
            raise ValueError("workspace plan must reference review bundle")
        if plan["execution_package_id"] != execution_package["execution_package_id"]:
            raise ValueError("workspace plan must reference execution package")


def stable_execution_workspace_plan_json(plan: dict[str, Any]) -> str:
    validate_execution_workspace_plan(plan)
    return _stable_ruflo_json(plan, indent=2) + "\n"


def parse_execution_workspace_plan_json(text: str) -> dict[str, Any]:
    import json as _json

    plan = _json.loads(text)
    validate_execution_workspace_plan(plan)
    return plan


_EXECUTION_TIMELINE_EVENT_TYPES = (
    "workspace_planned", "branch_planned", "patch_application_planned", "compile_planned",
    "tests_planned", "healthcheck_planned", "quality_gate_planned", "review_bundle_planned",
    "cleanup_planned",
)


def make_execution_event_id(workspace_id: str, order: int, event_type: str) -> str:
    return _execution_readiness_id("execution-event", {
        "event_type": event_type,
        "order": order,
        "workspace_id": workspace_id,
        "version": EXECUTION_EVENT_TIMELINE_VERSION,
    })


def make_execution_event_timeline_id(workspace_plan: dict[str, Any], events: list[dict[str, Any]]) -> str:
    return _execution_readiness_id("execution-event-timeline", {
        "event_ids": [event["event_id"] for event in events],
        "workspace_id": workspace_plan["workspace_id"],
        "version": EXECUTION_EVENT_TIMELINE_VERSION,
    })


def collect_execution_event_timeline(
    workspace_plan: dict[str, Any] | None = None,
    *,
    chain: dict[str, Any] | None = None,
    metadata: dict[str, Any] | None = None,
) -> dict[str, Any]:
    source_chain = chain if chain is not None else collect_growth_planning_chain_preview()
    source_chain = _growth_planning_chain_without_runtime_fields(source_chain)
    if workspace_plan is None:
        workspace_plan = collect_execution_workspace_plan(source_chain)
    validate_execution_workspace_plan(workspace_plan)
    execution_package = source_chain["autonomous_execution_package"]
    review_bundle = source_chain["planning_chain_review_bundle"]
    specs = [
        ("workspace_planned", [workspace_plan["workspace_id"]], [workspace_plan["proposed_worktree_path"]], ["workspace path is planned but not created"], ["workspace path cannot be reviewed"], workspace_plan["rollback_policy"]),
        ("branch_planned", [workspace_plan["base_branch"], workspace_plan["base_ref"]], [workspace_plan["proposed_branch_name"]], ["branch name is deterministic and reviewable"], ["branch name is missing or unsafe"], "keep current branch unchanged"),
        ("patch_application_planned", [review_bundle["verified_patch_plan_id"], review_bundle["verified_patch_diff_id"]], workspace_plan["target_files"], ["all patch operations map to target files"], ["patch operation lacks verified diff preview"], "do not apply patch operations"),
        ("compile_planned", source_chain["verification_plan"]["plans"][0]["compile_commands"], ["compile result evidence"], ["compile commands are allowlisted before execution"], ["compile command fails or is not allowlisted"], "stop and keep workspace for review"),
        ("tests_planned", source_chain["verification_plan"]["plans"][0]["test_commands"], ["test result evidence"], ["test commands are allowlisted before execution"], ["test command fails or is not allowlisted"], "stop and keep workspace for review"),
        ("healthcheck_planned", source_chain["verification_plan"]["plans"][0]["healthcheck_commands"], ["healthcheck result evidence"], ["healthcheck command is allowlisted before execution"], ["healthcheck fails or is not allowlisted"], "stop and keep workspace for review"),
        ("quality_gate_planned", [review_bundle["patch_behavior_quality_gate"]["quality_gate_id"]], [review_bundle["patch_behavior_quality_gate"]["pass_status"]], ["quality gate status is reviewed"], ["quality gate blocks implementation"], "do not proceed past review"),
        ("review_bundle_planned", [review_bundle["review_bundle_id"]], ["human review bundle"], ["review bundle summarizes evidence, risks, rollback, and decision"], ["review bundle missing evidence summary"], "keep workspace for manual review"),
        ("cleanup_planned", [execution_package["execution_package_id"]], [workspace_plan["cleanup_policy"]], ["cleanup policy keeps unknown or failed workspaces"], ["cleanup would discard unreviewed changes"], workspace_plan["rollback_policy"]),
    ]
    events = []
    for order, (event_type, inputs, outputs, success, failure, rollback) in enumerate(specs, start=1):
        event = {
            "event_id": make_execution_event_id(workspace_plan["workspace_id"], order, event_type),
            "event_type": event_type,
            "order": order,
            "inputs": _normalize_patch_behavior_text_list(inputs),
            "expected_outputs": _normalize_patch_behavior_text_list(outputs),
            "success_criteria": _normalize_patch_behavior_text_list(success),
            "failure_criteria": _normalize_patch_behavior_text_list(failure),
            "rollback_action": rollback,
        }
        validate_execution_timeline_event(event)
        events.append(event)
    timeline = {
        "execution_event_timeline_version": EXECUTION_EVENT_TIMELINE_VERSION,
        "execution_event_timeline_id": make_execution_event_timeline_id(workspace_plan, events),
        "workspace_id": workspace_plan["workspace_id"],
        "planning_chain_id": workspace_plan["planning_chain_id"],
        "review_bundle_id": workspace_plan["review_bundle_id"],
        "execution_package_id": workspace_plan["execution_package_id"],
        "events": events,
        "event_count": len(events),
        "dry_run": True,
        "write_allowed": False,
        "automation_allowed": False,
        "metadata": dict(metadata or {}),
        "writes": [],
    }
    validate_execution_event_timeline(timeline, workspace_plan)
    return timeline


def validate_execution_timeline_event(event: dict[str, Any]) -> None:
    required = ("event_id", "event_type", "order", "inputs", "expected_outputs", "success_criteria", "failure_criteria", "rollback_action")
    missing = [field for field in required if field not in event]
    if missing:
        raise ValueError(f"execution timeline event missing fields: {missing}")
    _validate_non_empty_string(event["event_id"], "event_id")
    if event["event_type"] not in _EXECUTION_TIMELINE_EVENT_TYPES:
        raise ValueError(f"invalid execution timeline event type: {event['event_type']}")
    if not isinstance(event["order"], int) or event["order"] < 1:
        raise ValueError("execution timeline event order must be positive")
    for field in ("inputs", "expected_outputs", "success_criteria", "failure_criteria"):
        values = event[field]
        if not isinstance(values, list) or not values:
            raise TypeError(f"{field} must be a non-empty list")
        if values != _normalize_patch_behavior_text_list(values):
            raise ValueError(f"{field} must be normalized and sorted")
    _validate_non_empty_string(event["rollback_action"], "rollback_action")


def validate_execution_event_timeline(timeline: dict[str, Any], workspace_plan: dict[str, Any] | None = None) -> None:
    required = ("execution_event_timeline_version", "execution_event_timeline_id", "workspace_id", "planning_chain_id", "review_bundle_id", "execution_package_id", "events", "event_count", "dry_run", "write_allowed", "automation_allowed", "metadata", "writes")
    missing = [field for field in required if field not in timeline]
    if missing:
        raise ValueError(f"execution event timeline missing fields: {missing}")
    if timeline["execution_event_timeline_version"] != EXECUTION_EVENT_TIMELINE_VERSION:
        raise ValueError("unsupported execution event timeline version")
    _validate_execution_read_only(timeline, "execution event timeline")
    for field in ("execution_event_timeline_id", "workspace_id", "planning_chain_id", "review_bundle_id", "execution_package_id"):
        _validate_non_empty_string(timeline[field], field)
    events = timeline["events"]
    if not isinstance(events, list) or len(events) != len(_EXECUTION_TIMELINE_EVENT_TYPES):
        raise ValueError("execution event timeline must contain all canonical events")
    if timeline["event_count"] != len(events):
        raise ValueError("event_count must match events length")
    ids = set()
    for index, event in enumerate(events, start=1):
        validate_execution_timeline_event(event)
        if event["event_id"] in ids:
            raise ValueError("duplicate execution timeline event id")
        ids.add(event["event_id"])
        if event["order"] != index or event["event_type"] != _EXECUTION_TIMELINE_EVENT_TYPES[index - 1]:
            raise ValueError("execution timeline events must use canonical order")
    if workspace_plan is not None:
        validate_execution_workspace_plan(workspace_plan)
        if timeline["workspace_id"] != workspace_plan["workspace_id"]:
            raise ValueError("timeline must reference workspace plan")
        if timeline["execution_event_timeline_id"] != make_execution_event_timeline_id(workspace_plan, events):
            raise ValueError("execution event timeline id does not match events")


def stable_execution_event_timeline_json(timeline: dict[str, Any]) -> str:
    validate_execution_event_timeline(timeline)
    return _stable_ruflo_json(timeline, indent=2) + "\n"


def parse_execution_event_timeline_json(text: str) -> dict[str, Any]:
    import json as _json

    timeline = _json.loads(text)
    validate_execution_event_timeline(timeline)
    return timeline


def make_execution_retry_policy_id(timeline: dict[str, Any]) -> str:
    return _execution_readiness_id("execution-retry-policy", {
        "timeline_id": timeline["execution_event_timeline_id"],
        "version": EXECUTION_RETRY_POLICY_VERSION,
    })


def collect_execution_retry_policy(
    timeline: dict[str, Any] | None = None,
    *,
    workspace_plan: dict[str, Any] | None = None,
    chain: dict[str, Any] | None = None,
    max_attempts: int = 2,
    metadata: dict[str, Any] | None = None,
) -> dict[str, Any]:
    if timeline is None:
        timeline = collect_execution_event_timeline(workspace_plan, chain=chain)
    validate_execution_event_timeline(timeline, workspace_plan)
    policy = {
        "retry_policy_version": EXECUTION_RETRY_POLICY_VERSION,
        "retry_policy_id": make_execution_retry_policy_id(timeline),
        "execution_event_timeline_id": timeline["execution_event_timeline_id"],
        "workspace_id": timeline["workspace_id"],
        "max_attempts": max_attempts,
        "retryable_failures": _normalize_patch_behavior_text_list([
            "transient filesystem lock before patch application",
            "transient test harness timeout with no source changes after failure",
            "healthcheck infrastructure timeout before assertions run",
        ]),
        "non_retryable_failures": _normalize_patch_behavior_text_list([
            "patch behavior quality gate block",
            "compile failure after patch application",
            "test assertion failure",
            "secret or destructive-operation gate block",
            "target file outside repository boundary",
        ]),
        "stop_conditions": _normalize_patch_behavior_text_list([
            "any non-retryable failure occurs",
            "max_attempts is reached",
            "working tree state becomes unknown",
            "human approval is missing",
        ]),
        "escalation_conditions": _normalize_patch_behavior_text_list([
            "same retryable failure repeats twice",
            "verification output is ambiguous",
            "rollback policy cannot be evaluated",
        ]),
        "required_human_review_conditions": _normalize_patch_behavior_text_list([
            "before first write or branch creation",
            "after any failed verification",
            "before cleanup discard",
            "before marking execution ready for merge",
        ]),
        "attempt_history_schema": {
            "attempt": "positive integer",
            "event_id": "execution timeline event id",
            "failure_type": "normalized failure label",
            "retryable": "boolean",
            "decision": "retry | stop | escalate",
            "evidence": "list of evidence references",
        },
        "dry_run": True,
        "write_allowed": False,
        "automation_allowed": False,
        "metadata": dict(metadata or {}),
        "writes": [],
    }
    validate_execution_retry_policy(policy, timeline)
    return policy


def validate_execution_retry_policy(policy: dict[str, Any], timeline: dict[str, Any] | None = None) -> None:
    required = ("retry_policy_version", "retry_policy_id", "execution_event_timeline_id", "workspace_id", "max_attempts", "retryable_failures", "non_retryable_failures", "stop_conditions", "escalation_conditions", "required_human_review_conditions", "attempt_history_schema", "dry_run", "write_allowed", "automation_allowed", "metadata", "writes")
    missing = [field for field in required if field not in policy]
    if missing:
        raise ValueError(f"execution retry policy missing fields: {missing}")
    if policy["retry_policy_version"] != EXECUTION_RETRY_POLICY_VERSION:
        raise ValueError("unsupported execution retry policy version")
    _validate_execution_read_only(policy, "execution retry policy")
    for field in ("retry_policy_id", "execution_event_timeline_id", "workspace_id"):
        _validate_non_empty_string(policy[field], field)
    if not isinstance(policy["max_attempts"], int) or policy["max_attempts"] < 1 or policy["max_attempts"] > 5:
        raise ValueError("max_attempts must be an integer from 1 to 5")
    for field in ("retryable_failures", "non_retryable_failures", "stop_conditions", "escalation_conditions", "required_human_review_conditions"):
        values = policy[field]
        if not isinstance(values, list) or not values:
            raise TypeError(f"{field} must be a non-empty list")
        if values != _normalize_patch_behavior_text_list(values):
            raise ValueError(f"{field} must be normalized and sorted")
    schema = policy["attempt_history_schema"]
    if not isinstance(schema, dict) or not all(isinstance(k, str) and isinstance(v, str) for k, v in schema.items()):
        raise TypeError("attempt_history_schema must be a string dictionary")
    if timeline is not None:
        validate_execution_event_timeline(timeline)
        if policy["retry_policy_id"] != make_execution_retry_policy_id(timeline):
            raise ValueError("retry_policy_id does not match timeline")


def stable_execution_retry_policy_json(policy: dict[str, Any]) -> str:
    validate_execution_retry_policy(policy)
    return _stable_ruflo_json(policy, indent=2) + "\n"


def parse_execution_retry_policy_json(text: str) -> dict[str, Any]:
    import json as _json

    policy = _json.loads(text)
    validate_execution_retry_policy(policy)
    return policy


def make_witness_manifest_plan_id(review_bundle: dict[str, Any], execution_package: dict[str, Any]) -> str:
    return _execution_readiness_id("witness-manifest-plan", {
        "execution_package_id": execution_package["execution_package_id"],
        "review_bundle_id": review_bundle["review_bundle_id"],
        "verified_patch_diff_id": review_bundle["verified_patch_diff_id"],
        "version": WITNESS_MANIFEST_PLAN_VERSION,
    })


def collect_witness_manifest_plan(
    chain: dict[str, Any] | None = None,
    *,
    provided_evidence: list[str] | None = None,
    metadata: dict[str, Any] | None = None,
) -> dict[str, Any]:
    source_chain = chain if chain is not None else collect_growth_planning_chain_preview()
    source_chain = _growth_planning_chain_without_runtime_fields(source_chain)
    validate_growth_planning_chain_preview(source_chain)
    review_bundle = source_chain["planning_chain_review_bundle"]
    execution_package = source_chain["autonomous_execution_package"]
    patch_plan = source_chain["verified_patch_plan"]
    verification = source_chain["verification_plan"]["plans"][0]
    required = _normalize_implementation_branch_refs(review_bundle["required_evidence"])
    provided = _normalize_implementation_branch_refs(provided_evidence or [])
    missing = [item for item in required if item not in provided]
    plan = {
        "witness_manifest_version": WITNESS_MANIFEST_PLAN_VERSION,
        "witness_manifest_id": make_witness_manifest_plan_id(review_bundle, execution_package),
        "planning_chain_id": source_chain["planning_chain_id"],
        "review_bundle_id": review_bundle["review_bundle_id"],
        "expected_changed_files": _normalize_implementation_branch_refs(patch_plan["target_files"]),
        "expected_test_commands": _normalize_patch_behavior_text_list(verification["test_commands"]),
        "expected_healthcheck_commands": _normalize_patch_behavior_text_list(verification["healthcheck_commands"]),
        "expected_quality_gate_result": review_bundle["patch_behavior_quality_gate"]["pass_status"],
        "expected_patch_diff_id": review_bundle["verified_patch_diff_id"],
        "expected_execution_package_id": execution_package["execution_package_id"],
        "expected_review_bundle_id": review_bundle["review_bundle_id"],
        "required_evidence": required,
        "provided_evidence": provided,
        "missing_evidence": missing,
        "evidence_hash_inputs": _normalize_patch_behavior_text_list([
            review_bundle["verified_patch_plan_id"],
            review_bundle["verified_patch_diff_id"],
            execution_package["execution_package_id"],
            *patch_plan["target_files"],
        ]),
        "dry_run": True,
        "write_allowed": False,
        "automation_allowed": False,
        "metadata": dict(metadata or {}),
        "writes": [],
    }
    validate_witness_manifest_plan(plan, source_chain)
    return plan


def validate_witness_manifest_plan(plan: dict[str, Any], chain: dict[str, Any] | None = None) -> None:
    required = ("witness_manifest_version", "witness_manifest_id", "planning_chain_id", "review_bundle_id", "expected_changed_files", "expected_test_commands", "expected_healthcheck_commands", "expected_quality_gate_result", "expected_patch_diff_id", "expected_execution_package_id", "expected_review_bundle_id", "required_evidence", "provided_evidence", "missing_evidence", "evidence_hash_inputs", "dry_run", "write_allowed", "automation_allowed", "metadata", "writes")
    missing = [field for field in required if field not in plan]
    if missing:
        raise ValueError(f"witness manifest plan missing fields: {missing}")
    if plan["witness_manifest_version"] != WITNESS_MANIFEST_PLAN_VERSION:
        raise ValueError("unsupported witness manifest plan version")
    _validate_execution_read_only(plan, "witness manifest plan")
    for field in ("witness_manifest_id", "planning_chain_id", "review_bundle_id", "expected_quality_gate_result", "expected_patch_diff_id", "expected_execution_package_id", "expected_review_bundle_id"):
        _validate_non_empty_string(plan[field], field)
    if plan["expected_quality_gate_result"] not in {"pass", "review", "block"}:
        raise ValueError("invalid expected quality gate result")
    for field in ("expected_changed_files", "expected_test_commands", "expected_healthcheck_commands", "required_evidence", "provided_evidence", "missing_evidence", "evidence_hash_inputs"):
        values = plan[field]
        if not isinstance(values, list):
            raise TypeError(f"{field} must be a list")
        if field in {"expected_changed_files", "expected_test_commands", "expected_healthcheck_commands", "required_evidence", "evidence_hash_inputs"} and not values:
            raise ValueError(f"{field} must not be empty")
        if values and values != _normalize_patch_behavior_text_list(values):
            raise ValueError(f"{field} must be normalized and sorted")
    expected_missing = [item for item in plan["required_evidence"] if item not in plan["provided_evidence"]]
    if plan["missing_evidence"] != expected_missing:
        raise ValueError("missing_evidence must match required evidence not provided")
    if chain is not None:
        validate_growth_planning_chain_preview(chain)
        review_bundle = chain["planning_chain_review_bundle"]
        execution_package = chain["autonomous_execution_package"]
        if plan["witness_manifest_id"] != make_witness_manifest_plan_id(review_bundle, execution_package):
            raise ValueError("witness manifest id does not match planning chain")
        if plan["expected_patch_diff_id"] != review_bundle["verified_patch_diff_id"]:
            raise ValueError("witness manifest must reference patch diff")


def stable_witness_manifest_plan_json(plan: dict[str, Any]) -> str:
    validate_witness_manifest_plan(plan)
    return _stable_ruflo_json(plan, indent=2) + "\n"


def parse_witness_manifest_plan_json(text: str) -> dict[str, Any]:
    import json as _json

    plan = _json.loads(text)
    validate_witness_manifest_plan(plan)
    return plan


def make_human_approval_package_id(review_bundle: dict[str, Any], workspace_plan: dict[str, Any], witness_plan: dict[str, Any]) -> str:
    return _execution_readiness_id("human-approval-package", {
        "review_bundle_id": review_bundle["review_bundle_id"],
        "witness_manifest_id": witness_plan["witness_manifest_id"],
        "workspace_id": workspace_plan["workspace_id"],
        "version": HUMAN_APPROVAL_PACKAGE_VERSION,
    })


def collect_human_approval_package(
    chain: dict[str, Any] | None = None,
    *,
    workspace_plan: dict[str, Any] | None = None,
    witness_manifest_plan: dict[str, Any] | None = None,
    metadata: dict[str, Any] | None = None,
) -> dict[str, Any]:
    source_chain = chain if chain is not None else collect_growth_planning_chain_preview()
    source_chain = _growth_planning_chain_without_runtime_fields(source_chain)
    validate_growth_planning_chain_preview(source_chain)
    if workspace_plan is None:
        workspace_plan = collect_execution_workspace_plan(source_chain)
    if witness_manifest_plan is None:
        witness_manifest_plan = collect_witness_manifest_plan(source_chain)
    validate_execution_workspace_plan(workspace_plan, source_chain)
    validate_witness_manifest_plan(witness_manifest_plan, source_chain)
    review_bundle = source_chain["planning_chain_review_bundle"]
    quality_status = review_bundle["patch_behavior_quality_gate"]["pass_status"]
    blocking = _normalize_patch_behavior_text_list([
        *(["missing required evidence"] if witness_manifest_plan["missing_evidence"] else []),
        *(["patch behavior quality gate blocks execution"] if quality_status == "block" else []),
        *(["workspace plan is blocked"] if workspace_plan["blocked"] else []),
    ]) if (witness_manifest_plan["missing_evidence"] or quality_status == "block" or workspace_plan["blocked"]) else []
    decision = "approve"
    if quality_status == "block" or blocking:
        decision = "revise"
    if quality_status == "block" and len(blocking) > 1:
        decision = "reject"
    package = {
        "approval_package_version": HUMAN_APPROVAL_PACKAGE_VERSION,
        "approval_package_id": make_human_approval_package_id(review_bundle, workspace_plan, witness_manifest_plan),
        "planning_chain_id": source_chain["planning_chain_id"],
        "review_bundle_id": review_bundle["review_bundle_id"],
        "workspace_id": workspace_plan["workspace_id"],
        "witness_manifest_id": witness_manifest_plan["witness_manifest_id"],
        "quality_gate_status": quality_status,
        "risk_summary": _normalize_patch_behavior_text_list(review_bundle["top_risks"]),
        "evidence_summary": {
            "required_count": len(witness_manifest_plan["required_evidence"]),
            "provided_count": len(witness_manifest_plan["provided_evidence"]),
            "missing_count": len(witness_manifest_plan["missing_evidence"]),
        },
        "rollback_summary": workspace_plan["rollback_policy"],
        "required_approvals": _normalize_patch_behavior_text_list(workspace_plan["approval_requirements"]),
        "blocking_concerns": blocking,
        "recommended_human_decision": decision,
        "dry_run": True,
        "write_allowed": False,
        "automation_allowed": False,
        "metadata": dict(metadata or {}),
        "writes": [],
    }
    validate_human_approval_package(package, source_chain, workspace_plan, witness_manifest_plan)
    return package


def validate_human_approval_package(package: dict[str, Any], chain: dict[str, Any] | None = None, workspace_plan: dict[str, Any] | None = None, witness_manifest_plan: dict[str, Any] | None = None) -> None:
    required = ("approval_package_version", "approval_package_id", "planning_chain_id", "review_bundle_id", "workspace_id", "witness_manifest_id", "quality_gate_status", "risk_summary", "evidence_summary", "rollback_summary", "required_approvals", "blocking_concerns", "recommended_human_decision", "dry_run", "write_allowed", "automation_allowed", "metadata", "writes")
    missing = [field for field in required if field not in package]
    if missing:
        raise ValueError(f"human approval package missing fields: {missing}")
    if package["approval_package_version"] != HUMAN_APPROVAL_PACKAGE_VERSION:
        raise ValueError("unsupported human approval package version")
    _validate_execution_read_only(package, "human approval package")
    for field in ("approval_package_id", "planning_chain_id", "review_bundle_id", "workspace_id", "witness_manifest_id", "quality_gate_status", "rollback_summary", "recommended_human_decision"):
        _validate_non_empty_string(package[field], field)
    if package["quality_gate_status"] not in {"pass", "review", "block"}:
        raise ValueError("invalid quality gate status")
    if package["recommended_human_decision"] not in {"approve", "revise", "reject"}:
        raise ValueError("invalid recommended human decision")
    summary = package["evidence_summary"]
    if not isinstance(summary, dict):
        raise TypeError("evidence_summary must be a dict")
    for field in ("required_count", "provided_count", "missing_count"):
        if not isinstance(summary.get(field), int) or summary[field] < 0:
            raise ValueError(f"evidence_summary.{field} must be a non-negative integer")
    for field in ("risk_summary", "required_approvals", "blocking_concerns"):
        values = package[field]
        if not isinstance(values, list):
            raise TypeError(f"{field} must be a list")
        if field != "blocking_concerns" and not values:
            raise ValueError(f"{field} must not be empty")
        if values and values != _normalize_patch_behavior_text_list(values):
            raise ValueError(f"{field} must be normalized and sorted")
    if witness_manifest_plan is not None:
        validate_witness_manifest_plan(witness_manifest_plan)
        if summary["required_count"] != len(witness_manifest_plan["required_evidence"]):
            raise ValueError("approval evidence required_count mismatch")
        if summary["missing_count"] != len(witness_manifest_plan["missing_evidence"]):
            raise ValueError("approval evidence missing_count mismatch")
    if chain is not None and workspace_plan is not None and witness_manifest_plan is not None:
        validate_growth_planning_chain_preview(chain)
        validate_execution_workspace_plan(workspace_plan, chain)
        review_bundle = chain["planning_chain_review_bundle"]
        if package["approval_package_id"] != make_human_approval_package_id(review_bundle, workspace_plan, witness_manifest_plan):
            raise ValueError("approval package id does not match inputs")


def stable_human_approval_package_json(package: dict[str, Any]) -> str:
    validate_human_approval_package(package)
    return _stable_ruflo_json(package, indent=2) + "\n"


def parse_human_approval_package_json(text: str) -> dict[str, Any]:
    import json as _json

    package = _json.loads(text)
    validate_human_approval_package(package)
    return package


def make_execution_readiness_bundle_id(chain: dict[str, Any], workspace_plan: dict[str, Any], timeline: dict[str, Any], retry_policy: dict[str, Any], witness_plan: dict[str, Any], approval_package: dict[str, Any]) -> str:
    return _execution_readiness_id("execution-readiness-bundle", {
        "approval_package_id": approval_package["approval_package_id"],
        "planning_chain_id": chain["planning_chain_id"],
        "retry_policy_id": retry_policy["retry_policy_id"],
        "timeline_id": timeline["execution_event_timeline_id"],
        "witness_manifest_id": witness_plan["witness_manifest_id"],
        "workspace_id": workspace_plan["workspace_id"],
        "version": EXECUTION_READINESS_BUNDLE_VERSION,
    })


def collect_execution_readiness_bundle(
    chain: dict[str, Any] | None = None,
    *,
    workspace_plan: dict[str, Any] | None = None,
    event_timeline: dict[str, Any] | None = None,
    retry_policy: dict[str, Any] | None = None,
    witness_manifest_plan: dict[str, Any] | None = None,
    human_approval_package: dict[str, Any] | None = None,
    metadata: dict[str, Any] | None = None,
) -> dict[str, Any]:
    source_chain = chain if chain is not None else collect_growth_planning_chain_preview()
    source_chain = _growth_planning_chain_without_runtime_fields(source_chain)
    validate_growth_planning_chain_preview(source_chain)
    workspace = workspace_plan or collect_execution_workspace_plan(source_chain)
    timeline = event_timeline or collect_execution_event_timeline(workspace, chain=source_chain)
    retry = retry_policy or collect_execution_retry_policy(timeline, workspace_plan=workspace)
    witness = witness_manifest_plan or collect_witness_manifest_plan(source_chain)
    approval = human_approval_package or collect_human_approval_package(source_chain, workspace_plan=workspace, witness_manifest_plan=witness)
    validate_execution_workspace_plan(workspace, source_chain)
    validate_execution_event_timeline(timeline, workspace)
    validate_execution_retry_policy(retry, timeline)
    validate_witness_manifest_plan(witness, source_chain)
    validate_human_approval_package(approval, source_chain, workspace, witness)
    blocking_reasons = _execution_readiness_blocking_reasons(workspace, witness, approval)
    if blocking_reasons:
        status = "blocked" if any("quality gate" in item or "workspace" in item for item in blocking_reasons) else "needs_evidence"
    else:
        status = "ready_for_review"
    bundle = {
        "execution_readiness_bundle_version": EXECUTION_READINESS_BUNDLE_VERSION,
        "execution_readiness_bundle_id": make_execution_readiness_bundle_id(source_chain, workspace, timeline, retry, witness, approval),
        "planning_chain": source_chain,
        "review_bundle": source_chain["planning_chain_review_bundle"],
        "execution_workspace_plan": workspace,
        "execution_event_timeline": timeline,
        "retry_policy": retry,
        "witness_manifest_plan": witness,
        "human_approval_package": approval,
        "readiness_status": status,
        "blocking_reasons": blocking_reasons,
        "recommended_next_action": _execution_readiness_next_action(status),
        "dry_run": True,
        "write_allowed": False,
        "automation_allowed": False,
        "metadata": dict(metadata or {}),
        "writes": [],
    }
    validate_execution_readiness_bundle(bundle)
    return bundle


def _execution_readiness_blocking_reasons(workspace: dict[str, Any], witness: dict[str, Any], approval: dict[str, Any]) -> list[str]:
    reasons: list[str] = []
    if workspace["blocked"]:
        reasons.append("workspace plan is blocked")
    if witness["missing_evidence"]:
        reasons.append("witness manifest plan is missing required evidence")
    if approval["quality_gate_status"] == "block":
        reasons.append("quality gate blocks execution readiness")
    if approval["recommended_human_decision"] != "approve":
        reasons.append(f"human approval package recommends {approval['recommended_human_decision']}")
    return _normalize_patch_behavior_text_list(reasons) if reasons else []


def _execution_readiness_next_action(status: str) -> str:
    if status == "ready_for_review":
        return "Present the read-only execution readiness bundle to a human reviewer; do not execute without approval."
    if status == "needs_evidence":
        return "Collect or explicitly waive missing evidence before requesting execution approval."
    return "Resolve blocking readiness concerns before any branch, worktree, patch, or verification execution."


def validate_execution_readiness_bundle(bundle: dict[str, Any]) -> None:
    required = ("execution_readiness_bundle_version", "execution_readiness_bundle_id", "planning_chain", "review_bundle", "execution_workspace_plan", "execution_event_timeline", "retry_policy", "witness_manifest_plan", "human_approval_package", "readiness_status", "blocking_reasons", "recommended_next_action", "dry_run", "write_allowed", "automation_allowed", "metadata", "writes")
    missing = [field for field in required if field not in bundle]
    if missing:
        raise ValueError(f"execution readiness bundle missing fields: {missing}")
    if bundle["execution_readiness_bundle_version"] != EXECUTION_READINESS_BUNDLE_VERSION:
        raise ValueError("unsupported execution readiness bundle version")
    _validate_execution_read_only(bundle, "execution readiness bundle")
    _validate_non_empty_string(bundle["execution_readiness_bundle_id"], "execution_readiness_bundle_id")
    if bundle["readiness_status"] not in {"ready_for_review", "blocked", "needs_evidence"}:
        raise ValueError("invalid readiness status")
    _validate_non_empty_string(bundle["recommended_next_action"], "recommended_next_action")
    if not isinstance(bundle["blocking_reasons"], list):
        raise TypeError("blocking_reasons must be a list")
    if bundle["blocking_reasons"] and bundle["blocking_reasons"] != _normalize_patch_behavior_text_list(bundle["blocking_reasons"]):
        raise ValueError("blocking_reasons must be normalized and sorted")
    chain = bundle["planning_chain"]
    workspace = bundle["execution_workspace_plan"]
    timeline = bundle["execution_event_timeline"]
    retry = bundle["retry_policy"]
    witness = bundle["witness_manifest_plan"]
    approval = bundle["human_approval_package"]
    validate_growth_planning_chain_preview(chain)
    validate_planning_chain_review_bundle(bundle["review_bundle"], chain)
    validate_execution_workspace_plan(workspace, chain)
    validate_execution_event_timeline(timeline, workspace)
    validate_execution_retry_policy(retry, timeline)
    validate_witness_manifest_plan(witness, chain)
    validate_human_approval_package(approval, chain, workspace, witness)
    expected_id = make_execution_readiness_bundle_id(chain, workspace, timeline, retry, witness, approval)
    if bundle["execution_readiness_bundle_id"] != expected_id:
        raise ValueError("execution readiness bundle id does not match components")
    expected_reasons = _execution_readiness_blocking_reasons(workspace, witness, approval)
    if bundle["blocking_reasons"] != expected_reasons:
        raise ValueError("blocking_reasons do not match component state")
    if expected_reasons and bundle["readiness_status"] == "ready_for_review":
        raise ValueError("ready_for_review cannot have blocking reasons")
    if not expected_reasons and bundle["readiness_status"] != "ready_for_review":
        raise ValueError("readiness status should be ready_for_review when unblocked")


def stable_execution_readiness_bundle_json(bundle: dict[str, Any]) -> str:
    validate_execution_readiness_bundle(bundle)
    return _stable_ruflo_json(bundle, indent=2) + "\n"


def parse_execution_readiness_bundle_json(text: str) -> dict[str, Any]:
    import json as _json

    bundle = _json.loads(text)
    validate_execution_readiness_bundle(bundle)
    return bundle



_GROWTH_PLANNING_CHAIN_RUNTIME_FIELDS = (
    "execution_workspace_plan",
    "execution_event_timeline",
    "execution_retry_policy",
    "witness_manifest_plan",
    "human_approval_package",
    "execution_readiness_bundle",
    "execution_journal_plan",
    "execution_evidence_contract",
    "execution_preflight_checklist",
    "execution_attempt_history",
    "execution_readiness_dashboard_summary",
)


def _growth_planning_chain_without_runtime_fields(chain: dict[str, Any]) -> dict[str, Any]:
    """Return a non-recursive planning-chain view for nested runtime payloads."""
    base = {
        key: value
        for key, value in chain.items()
        if key not in _GROWTH_PLANNING_CHAIN_RUNTIME_FIELDS
    }
    review_bundle = base.get("planning_chain_review_bundle")
    if isinstance(review_bundle, dict):
        review_copy = dict(review_bundle)
        if review_copy.get("execution_readiness_bundle_id"):
            review_copy["execution_readiness_bundle_id"] = ""
        if review_copy.get("execution_evidence_contract_id"):
            review_copy["execution_evidence_contract_id"] = ""
            review_copy["evidence_item_count"] = 0
            review_copy["evidence_required_types"] = []
        base["planning_chain_review_bundle"] = review_copy
    return base


EXECUTION_JOURNAL_PLAN_VERSION = "link-execution-journal-plan-v1"
_EXECUTION_JOURNAL_STAGES = (
    "create_workspace",
    "create_branch",
    "apply_patch_operations",
    "run_compile",
    "run_tests",
    "run_healthcheck",
    "evaluate_quality_gate",
    "produce_review_bundle",
)
_EXECUTION_JOURNAL_STATUSES = (
    "planned",
    "running",
    "passed",
    "failed",
    "skipped",
    "rolled_back",
)
_EXECUTION_STAGE_NAME_TO_JOURNAL_STAGE = {
    "create workspace": "create_workspace",
    "create branch": "create_branch",
    "apply patch operations": "apply_patch_operations",
    "run compile": "run_compile",
    "run tests": "run_tests",
    "run healthcheck": "run_healthcheck",
    "evaluate quality gate": "evaluate_quality_gate",
    "produce review bundle": "produce_review_bundle",
}


def make_execution_journal_entry_id(execution_package_id: str, sequence: int, stage: str, event_type: str) -> str:
    return _execution_readiness_id("execution-journal-entry", {
        "event_type": event_type,
        "execution_package_id": execution_package_id,
        "sequence": sequence,
        "stage": stage,
        "version": EXECUTION_JOURNAL_PLAN_VERSION,
    })


def make_execution_journal_plan_id(execution_package: dict[str, Any], entries: list[dict[str, Any]]) -> str:
    return _execution_readiness_id("execution-journal", {
        "entry_ids": [entry["entry_id"] for entry in entries],
        "execution_package_id": execution_package["execution_package_id"],
        "upgrade_id": execution_package["upgrade_id"],
        "version": EXECUTION_JOURNAL_PLAN_VERSION,
    })


def collect_execution_journal_plan(
    readiness_bundle: dict[str, Any] | None = None,
    *,
    evidence_refs_by_stage: dict[str, list[str]] | None = None,
    metadata: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Build a read-only append-only execution journal plan for future execution."""
    source_readiness = readiness_bundle if readiness_bundle is not None else collect_execution_readiness_bundle()
    validate_execution_readiness_bundle(source_readiness)
    chain = source_readiness["planning_chain"]
    execution_package = chain["autonomous_execution_package"]
    validate_autonomous_execution_package(execution_package)
    if evidence_refs_by_stage is None:
        evidence_refs_by_stage = {}
    if not isinstance(evidence_refs_by_stage, dict):
        raise TypeError("evidence_refs_by_stage must be a dict")

    entries: list[dict[str, Any]] = []
    for index, stage in enumerate(execution_package["execution_stages"], start=1):
        journal_stage = _EXECUTION_STAGE_NAME_TO_JOURNAL_STAGE[stage["stage_name"]]
        refs = evidence_refs_by_stage.get(journal_stage, [])
        if not isinstance(refs, list):
            raise TypeError("evidence refs by stage must map to lists")
        evidence_refs = _normalize_implementation_branch_refs(refs)
        event_type = f"{journal_stage}_planned"
        entry = {
            "entry_id": make_execution_journal_entry_id(
                execution_package["execution_package_id"],
                index,
                journal_stage,
                event_type,
            ),
            "sequence": index,
            "stage": journal_stage,
            "event_type": event_type,
            "status": "planned",
            "timestamp_policy": "assign_utc_timestamp_when_event_is_appended",
            "actor": "link.execution_journal_planner",
            "inputs": _normalize_patch_behavior_text_list(stage["inputs"]),
            "outputs": _normalize_patch_behavior_text_list(stage["outputs"]),
            "evidence_refs": evidence_refs,
            "failure_reason": "",
            "retryable": journal_stage in {"run_compile", "run_tests", "run_healthcheck"},
            "rollback_required": journal_stage in {
                "create_workspace",
                "create_branch",
                "apply_patch_operations",
                "run_compile",
                "run_tests",
                "run_healthcheck",
                "evaluate_quality_gate",
            },
        }
        validate_execution_journal_entry(entry, execution_package)
        entries.append(entry)

    journal = {
        "execution_journal_version": EXECUTION_JOURNAL_PLAN_VERSION,
        "execution_journal_id": make_execution_journal_plan_id(execution_package, entries),
        "execution_readiness_bundle_id": source_readiness["execution_readiness_bundle_id"],
        "execution_package_id": execution_package["execution_package_id"],
        "planning_chain_id": chain["planning_chain_id"],
        "upgrade_id": execution_package["upgrade_id"],
        "branch_plan_id": execution_package["branch_plan_id"],
        "work_package_id": execution_package["work_package_id"],
        "verification_plan_id": execution_package["verification_plan_id"],
        "journal_entries": entries,
        "dry_run": True,
        "write_allowed": False,
        "automation_allowed": False,
        "metadata": dict(metadata or {}),
        "writes": [],
    }
    validate_execution_journal_plan(journal, source_readiness)
    return journal


def validate_execution_journal_entry(entry: dict[str, Any], execution_package: dict[str, Any] | None = None) -> None:
    required = (
        "entry_id", "sequence", "stage", "event_type", "status", "timestamp_policy",
        "actor", "inputs", "outputs", "evidence_refs", "failure_reason", "retryable",
        "rollback_required",
    )
    missing = [field for field in required if field not in entry]
    if missing:
        raise ValueError(f"execution journal entry missing fields: {missing}")
    for field in ("entry_id", "stage", "event_type", "status", "timestamp_policy", "actor"):
        _validate_non_empty_string(entry[field], field)
    if not isinstance(entry["sequence"], int) or entry["sequence"] < 1:
        raise ValueError("journal entry sequence must be a positive integer")
    if entry["stage"] not in _EXECUTION_JOURNAL_STAGES:
        raise ValueError(f"invalid execution journal stage: {entry['stage']}")
    if entry["status"] not in _EXECUTION_JOURNAL_STATUSES:
        raise ValueError(f"invalid execution journal status: {entry['status']}")
    expected_event_type = f"{entry['stage']}_{entry['status']}"
    if entry["status"] == "planned":
        expected_event_type = f"{entry['stage']}_planned"
    if entry["event_type"] != expected_event_type:
        raise ValueError("journal entry event_type must match stage and status")
    for field in ("inputs", "outputs", "evidence_refs"):
        values = entry[field]
        if not isinstance(values, list):
            raise TypeError(f"{field} must be a list")
        if field in {"inputs", "outputs"} and not values:
            raise ValueError(f"{field} must not be empty")
        if not all(isinstance(value, str) and value.strip() for value in values):
            raise TypeError(f"{field} must contain non-empty strings")
    if entry["inputs"] != _normalize_patch_behavior_text_list(entry["inputs"]):
        raise ValueError("journal entry inputs must be normalized and sorted")
    if entry["outputs"] != _normalize_patch_behavior_text_list(entry["outputs"]):
        raise ValueError("journal entry outputs must be normalized and sorted")
    if entry["evidence_refs"] != _normalize_implementation_branch_refs(entry["evidence_refs"]):
        raise ValueError("journal entry evidence_refs must be normalized and sorted")
    if not isinstance(entry["failure_reason"], str):
        raise TypeError("failure_reason must be a string")
    if entry["status"] == "failed" and not entry["failure_reason"].strip():
        raise ValueError("failed journal entries require failure_reason")
    if entry["status"] != "failed" and entry["failure_reason"]:
        raise ValueError("non-failed journal entries must not include failure_reason")
    for field in ("retryable", "rollback_required"):
        if not isinstance(entry[field], bool):
            raise TypeError(f"{field} must be a boolean")
    if execution_package is not None:
        validate_autonomous_execution_package(execution_package)
        stage_names = [_EXECUTION_STAGE_NAME_TO_JOURNAL_STAGE[stage["stage_name"]] for stage in execution_package["execution_stages"]]
        if entry["sequence"] <= len(stage_names) and entry["stage"] != stage_names[entry["sequence"] - 1]:
            raise ValueError("journal entry stage does not match execution package stage order")
        expected_id = make_execution_journal_entry_id(
            execution_package["execution_package_id"],
            entry["sequence"],
            entry["stage"],
            entry["event_type"],
        )
        if entry["entry_id"] != expected_id:
            raise ValueError("journal entry id does not match execution package")


def validate_execution_journal_plan(journal: dict[str, Any], readiness_bundle: dict[str, Any] | None = None) -> None:
    required = (
        "execution_journal_version", "execution_journal_id", "execution_readiness_bundle_id",
        "execution_package_id", "planning_chain_id", "upgrade_id", "branch_plan_id",
        "work_package_id", "verification_plan_id", "journal_entries", "dry_run",
        "write_allowed", "automation_allowed", "metadata", "writes",
    )
    missing = [field for field in required if field not in journal]
    if missing:
        raise ValueError(f"execution journal plan missing fields: {missing}")
    if journal["execution_journal_version"] != EXECUTION_JOURNAL_PLAN_VERSION:
        raise ValueError("unsupported execution journal plan version")
    _validate_execution_read_only(journal, "execution journal plan")
    for field in (
        "execution_journal_id", "execution_readiness_bundle_id", "execution_package_id",
        "planning_chain_id", "upgrade_id", "branch_plan_id", "work_package_id",
        "verification_plan_id",
    ):
        _validate_non_empty_string(journal[field], field)
    entries = journal["journal_entries"]
    if not isinstance(entries, list) or not entries:
        raise TypeError("journal_entries must be a non-empty list")
    sequences: set[int] = set()
    entry_ids: set[str] = set()
    for index, entry in enumerate(entries, start=1):
        validate_execution_journal_entry(entry)
        if entry["sequence"] in sequences:
            raise ValueError(f"duplicate journal entry sequence: {entry['sequence']}")
        if entry["entry_id"] in entry_ids:
            raise ValueError(f"duplicate journal entry id: {entry['entry_id']}")
        sequences.add(entry["sequence"])
        entry_ids.add(entry["entry_id"])
        if entry["sequence"] != index:
            raise ValueError("journal entries must be ordered by sequence without gaps")
        if entry["stage"] != _EXECUTION_JOURNAL_STAGES[index - 1]:
            raise ValueError("journal entries must use the canonical stage order")
    if len(entries) != len(_EXECUTION_JOURNAL_STAGES):
        raise ValueError("journal entry count must match supported execution stages")
    if not isinstance(journal["metadata"], dict):
        raise TypeError("execution journal metadata must be a dict")
    if readiness_bundle is not None:
        validate_execution_readiness_bundle(readiness_bundle)
        chain = readiness_bundle["planning_chain"]
        execution_package = chain["autonomous_execution_package"]
        expected = {
            "execution_readiness_bundle_id": readiness_bundle["execution_readiness_bundle_id"],
            "execution_package_id": execution_package["execution_package_id"],
            "planning_chain_id": chain["planning_chain_id"],
            "upgrade_id": execution_package["upgrade_id"],
            "branch_plan_id": execution_package["branch_plan_id"],
            "work_package_id": execution_package["work_package_id"],
            "verification_plan_id": execution_package["verification_plan_id"],
        }
        for field, value in expected.items():
            if journal[field] != value:
                raise ValueError(f"execution journal {field} does not match readiness bundle")
        for entry in entries:
            validate_execution_journal_entry(entry, execution_package)
        if journal["execution_journal_id"] != make_execution_journal_plan_id(execution_package, entries):
            raise ValueError("execution journal id does not match readiness bundle")


def stable_execution_journal_plan_json(journal: dict[str, Any]) -> str:
    validate_execution_journal_plan(journal)
    return _stable_ruflo_json(journal, indent=2) + "\n"


def parse_execution_journal_plan_json(text: str) -> dict[str, Any]:
    import json as _json

    journal = _json.loads(text)
    validate_execution_journal_plan(journal)
    return journal



EXECUTION_EVIDENCE_CONTRACT_VERSION = "link-execution-evidence-contract-v1"
EXECUTION_PREFLIGHT_CHECKLIST_VERSION = "link-execution-preflight-checklist-v1"
EXECUTION_ATTEMPT_HISTORY_VERSION = "link-execution-attempt-history-v1"
_EXECUTION_EVIDENCE_TYPES = (
    "compile",
    "tests",
    "healthcheck",
    "patch_application",
    "quality_gate",
    "rollback",
)
_EXECUTION_EVIDENCE_STAGE_BY_TYPE = {
    "compile": "run_compile",
    "tests": "run_tests",
    "healthcheck": "run_healthcheck",
    "patch_application": "apply_patch_operations",
    "quality_gate": "evaluate_quality_gate",
    "rollback": "produce_review_bundle",
}
_EXECUTION_EVIDENCE_COMMON_FIELDS = (
    "attempt_id",
    "completed_at_policy",
    "journal_entry_id",
    "reviewer_visible_summary",
    "started_at_policy",
)
_EXECUTION_EVIDENCE_COMMAND_FIELDS = (
    "command",
    "exit_code",
    "stdout_log_ref",
    "stderr_log_ref",
    "combined_log_ref",
    "log_hash",
)
_EXECUTION_EVIDENCE_PATCH_FIELDS = (
    "changed_file_refs",
    "changed_file_hashes",
    "diff_hash",
)


def make_execution_evidence_item_id(journal_id: str, evidence_type: str, stage: str) -> str:
    return _execution_readiness_id("execution-evidence", {
        "evidence_type": evidence_type,
        "journal_id": journal_id,
        "stage": stage,
        "version": EXECUTION_EVIDENCE_CONTRACT_VERSION,
    })


def make_execution_evidence_contract_id(journal: dict[str, Any], evidence_items: list[dict[str, Any]]) -> str:
    return _execution_readiness_id("execution-evidence-contract", {
        "evidence_ids": [item["evidence_id"] for item in evidence_items],
        "execution_journal_id": journal["execution_journal_id"],
        "execution_package_id": journal["execution_package_id"],
        "version": EXECUTION_EVIDENCE_CONTRACT_VERSION,
    })


def collect_execution_evidence_contract(
    journal_plan: dict[str, Any] | None = None,
    *,
    metadata: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Define required future execution evidence without collecting it."""
    journal = journal_plan if journal_plan is not None else collect_execution_journal_plan()
    validate_execution_journal_plan(journal)
    entries_by_stage = {entry["stage"]: entry for entry in journal["journal_entries"]}
    evidence_types = ["compile", "tests", "healthcheck", "patch_application", "quality_gate"]
    if any(entry["rollback_required"] for entry in journal["journal_entries"]):
        evidence_types.append("rollback")

    evidence_items: list[dict[str, Any]] = []
    for evidence_type in evidence_types:
        stage = _EXECUTION_EVIDENCE_STAGE_BY_TYPE[evidence_type]
        journal_entry = entries_by_stage[stage]
        required_fields = _execution_evidence_required_fields(evidence_type)
        item = {
            "evidence_id": make_execution_evidence_item_id(
                journal["execution_journal_id"],
                evidence_type,
                stage,
            ),
            "evidence_type": evidence_type,
            "stage": stage,
            "required_fields": required_fields,
            "optional_fields": _execution_evidence_optional_fields(evidence_type),
            "producing_stage": stage,
            "consuming_stage": "produce_review_bundle",
            "validation_rule": _execution_evidence_validation_rule(evidence_type),
            "reviewer_summary_required": True,
            "blocks_completion_if_missing": True,
            "journal_entry_id": journal_entry["entry_id"],
        }
        validate_execution_evidence_item(item, journal)
        evidence_items.append(item)

    contract = {
        "execution_evidence_contract_version": EXECUTION_EVIDENCE_CONTRACT_VERSION,
        "execution_evidence_contract_id": make_execution_evidence_contract_id(journal, evidence_items),
        "execution_journal_id": journal["execution_journal_id"],
        "execution_package_id": journal["execution_package_id"],
        "planning_chain_id": journal["planning_chain_id"],
        "upgrade_id": journal["upgrade_id"],
        "branch_plan_id": journal["branch_plan_id"],
        "work_package_id": journal["work_package_id"],
        "verification_plan_id": journal["verification_plan_id"],
        "evidence_items": evidence_items,
        "evidence_item_count": len(evidence_items),
        "dry_run": True,
        "write_allowed": False,
        "automation_allowed": False,
        "metadata": dict(metadata or {}),
        "writes": [],
    }
    validate_execution_evidence_contract(contract, journal)
    return contract


def _execution_evidence_required_fields(evidence_type: str) -> list[str]:
    fields = list(_EXECUTION_EVIDENCE_COMMON_FIELDS)
    if evidence_type in {"compile", "tests", "healthcheck"}:
        fields.extend(_EXECUTION_EVIDENCE_COMMAND_FIELDS)
    if evidence_type == "patch_application":
        fields.extend(_EXECUTION_EVIDENCE_PATCH_FIELDS)
    if evidence_type == "quality_gate":
        fields.extend(("diff_hash", "quality_gate_result"))
    if evidence_type == "rollback":
        fields.extend(("rollback_ref", "rollback_reason"))
    return _normalize_implementation_branch_refs(fields)


def _execution_evidence_optional_fields(evidence_type: str) -> list[str]:
    fields = ["notes", "artifact_refs"]
    if evidence_type in {"compile", "tests", "healthcheck"}:
        fields.append("duration_ms")
    if evidence_type == "rollback":
        fields.extend(("restored_file_hashes", "cleanup_ref"))
    return _normalize_implementation_branch_refs(fields)


def _execution_evidence_validation_rule(evidence_type: str) -> str:
    if evidence_type in {"compile", "tests", "healthcheck"}:
        return "require command, exit_code, log references, log_hash, attempt_id, journal_entry_id, and reviewer_visible_summary before completion"
    if evidence_type == "patch_application":
        return "require diff_hash, changed_file_refs, changed_file_hashes, attempt_id, journal_entry_id, and reviewer_visible_summary before completion"
    if evidence_type == "quality_gate":
        return "require quality_gate_result, diff_hash, attempt_id, journal_entry_id, and reviewer_visible_summary before completion"
    if evidence_type == "rollback":
        return "require rollback_ref, rollback_reason, attempt_id, journal_entry_id, and reviewer_visible_summary when rollback is required"
    raise ValueError(f"invalid execution evidence type: {evidence_type}")


def validate_execution_evidence_item(item: dict[str, Any], journal: dict[str, Any] | None = None) -> None:
    required = (
        "evidence_id", "evidence_type", "stage", "required_fields", "optional_fields",
        "producing_stage", "consuming_stage", "validation_rule", "reviewer_summary_required",
        "blocks_completion_if_missing", "journal_entry_id",
    )
    missing = [field for field in required if field not in item]
    if missing:
        raise ValueError(f"execution evidence item missing fields: {missing}")
    for field in ("evidence_id", "evidence_type", "stage", "producing_stage", "consuming_stage", "validation_rule", "journal_entry_id"):
        _validate_non_empty_string(item[field], field)
    if item["evidence_type"] not in _EXECUTION_EVIDENCE_TYPES:
        raise ValueError(f"invalid execution evidence type: {item['evidence_type']}")
    expected_stage = _EXECUTION_EVIDENCE_STAGE_BY_TYPE[item["evidence_type"]]
    if item["stage"] != expected_stage or item["producing_stage"] != expected_stage:
        raise ValueError("evidence stage must match evidence type")
    if item["consuming_stage"] not in _EXECUTION_JOURNAL_STAGES:
        raise ValueError("evidence consuming_stage must be a supported journal stage")
    if not isinstance(item["reviewer_summary_required"], bool):
        raise TypeError("reviewer_summary_required must be a boolean")
    if not isinstance(item["blocks_completion_if_missing"], bool):
        raise TypeError("blocks_completion_if_missing must be a boolean")
    if item["reviewer_summary_required"] is not True:
        raise ValueError("execution evidence must require reviewer-visible summaries")
    if item["blocks_completion_if_missing"] is not True:
        raise ValueError("execution evidence must block completion if missing")
    for field in ("required_fields", "optional_fields"):
        values = item[field]
        if not isinstance(values, list):
            raise TypeError(f"{field} must be a list")
        if field == "required_fields" and not values:
            raise ValueError("required_fields must not be empty")
        if not all(isinstance(value, str) and value.strip() for value in values):
            raise TypeError(f"{field} must contain non-empty strings")
        if values != _normalize_implementation_branch_refs(values):
            raise ValueError(f"{field} must be normalized and sorted")
    required_fields = set(item["required_fields"])
    common_required = set(_EXECUTION_EVIDENCE_COMMON_FIELDS)
    if not common_required.issubset(required_fields):
        raise ValueError("execution evidence required_fields missing common fields")
    if item["evidence_type"] in {"compile", "tests", "healthcheck"} and not set(_EXECUTION_EVIDENCE_COMMAND_FIELDS).issubset(required_fields):
        raise ValueError("command evidence required_fields missing command/log fields")
    if item["evidence_type"] == "patch_application" and not set(_EXECUTION_EVIDENCE_PATCH_FIELDS).issubset(required_fields):
        raise ValueError("patch evidence required_fields missing diff/file hash fields")
    if item["evidence_type"] == "rollback" and "rollback_ref" not in required_fields:
        raise ValueError("rollback evidence required_fields missing rollback_ref")
    if journal is not None:
        validate_execution_journal_plan(journal)
        entries = {entry["stage"]: entry for entry in journal["journal_entries"]}
        expected_entry = entries[item["stage"]]
        if item["journal_entry_id"] != expected_entry["entry_id"]:
            raise ValueError("execution evidence item journal_entry_id does not match journal stage")
        expected_id = make_execution_evidence_item_id(
            journal["execution_journal_id"],
            item["evidence_type"],
            item["stage"],
        )
        if item["evidence_id"] != expected_id:
            raise ValueError("execution evidence item id does not match journal")


def validate_execution_evidence_contract(contract: dict[str, Any], journal: dict[str, Any] | None = None) -> None:
    required = (
        "execution_evidence_contract_version", "execution_evidence_contract_id", "execution_journal_id",
        "execution_package_id", "planning_chain_id", "upgrade_id", "branch_plan_id",
        "work_package_id", "verification_plan_id", "evidence_items", "evidence_item_count",
        "dry_run", "write_allowed", "automation_allowed", "metadata", "writes",
    )
    missing = [field for field in required if field not in contract]
    if missing:
        raise ValueError(f"execution evidence contract missing fields: {missing}")
    if contract["execution_evidence_contract_version"] != EXECUTION_EVIDENCE_CONTRACT_VERSION:
        raise ValueError("unsupported execution evidence contract version")
    _validate_execution_read_only(contract, "execution evidence contract")
    for field in (
        "execution_evidence_contract_id", "execution_journal_id", "execution_package_id",
        "planning_chain_id", "upgrade_id", "branch_plan_id", "work_package_id",
        "verification_plan_id",
    ):
        _validate_non_empty_string(contract[field], field)
    items = contract["evidence_items"]
    if not isinstance(items, list) or not items:
        raise TypeError("evidence_items must be a non-empty list")
    if not isinstance(contract["evidence_item_count"], int) or contract["evidence_item_count"] != len(items):
        raise ValueError("evidence_item_count must match evidence_items length")
    seen_types: set[str] = set()
    seen_ids: set[str] = set()
    for item in items:
        validate_execution_evidence_item(item)
        if item["evidence_type"] in seen_types:
            raise ValueError(f"duplicate evidence type: {item['evidence_type']}")
        if item["evidence_id"] in seen_ids:
            raise ValueError(f"duplicate evidence id: {item['evidence_id']}")
        seen_types.add(item["evidence_type"])
        seen_ids.add(item["evidence_id"])
    required_types = {"compile", "tests", "healthcheck", "patch_application", "quality_gate"}
    if not required_types.issubset(seen_types):
        raise ValueError("execution evidence contract missing required evidence types")
    if journal is not None:
        validate_execution_journal_plan(journal)
        expected = {
            "execution_journal_id": journal["execution_journal_id"],
            "execution_package_id": journal["execution_package_id"],
            "planning_chain_id": journal["planning_chain_id"],
            "upgrade_id": journal["upgrade_id"],
            "branch_plan_id": journal["branch_plan_id"],
            "work_package_id": journal["work_package_id"],
            "verification_plan_id": journal["verification_plan_id"],
        }
        for field, value in expected.items():
            if contract[field] != value:
                raise ValueError(f"execution evidence contract {field} does not match journal")
        rollback_applies = any(entry["rollback_required"] for entry in journal["journal_entries"])
        if rollback_applies and "rollback" not in seen_types:
            raise ValueError("rollback evidence is required when rollback applies")
        if not rollback_applies and "rollback" in seen_types:
            raise ValueError("rollback evidence must not be required when rollback does not apply")
        for item in items:
            validate_execution_evidence_item(item, journal)
        if contract["execution_evidence_contract_id"] != make_execution_evidence_contract_id(journal, items):
            raise ValueError("execution evidence contract id does not match journal")


def stable_execution_evidence_contract_json(contract: dict[str, Any]) -> str:
    validate_execution_evidence_contract(contract)
    return _stable_ruflo_json(contract, indent=2) + "\n"


def parse_execution_evidence_contract_json(text: str) -> dict[str, Any]:
    import json as _json

    contract = _json.loads(text)
    validate_execution_evidence_contract(contract)
    return contract


def make_execution_preflight_check_id(planning_chain_id: str, category: str, name: str, source_ref: str) -> str:
    return _execution_readiness_id("execution-preflight-check", {
        "category": category,
        "name": name,
        "planning_chain_id": planning_chain_id,
        "source_ref": source_ref,
        "version": EXECUTION_PREFLIGHT_CHECKLIST_VERSION,
    })


def make_execution_preflight_checklist_id(
    planning_chain: dict[str, Any],
    readiness_bundle: dict[str, Any],
    evidence_contract: dict[str, Any],
    human_approval_package: dict[str, Any],
    workspace_plan: dict[str, Any],
    checks: list[dict[str, Any]],
) -> str:
    return _execution_readiness_id("execution-preflight-checklist", {
        "check_ids": [check["check_id"] for check in checks],
        "execution_evidence_contract_id": evidence_contract["execution_evidence_contract_id"],
        "execution_readiness_bundle_id": readiness_bundle["execution_readiness_bundle_id"],
        "human_approval_package_id": human_approval_package["approval_package_id"],
        "planning_chain_id": planning_chain["planning_chain_id"],
        "workspace_id": workspace_plan["workspace_id"],
        "version": EXECUTION_PREFLIGHT_CHECKLIST_VERSION,
    })


def _execution_preflight_check(
    planning_chain_id: str,
    category: str,
    name: str,
    requirement: str,
    status: str,
    severity: str,
    source_ref: str,
) -> dict[str, Any]:
    return {
        "check_id": make_execution_preflight_check_id(planning_chain_id, category, name, source_ref),
        "category": category,
        "name": name,
        "requirement": requirement,
        "status": status,
        "severity": severity,
        "source_ref": source_ref,
        "blocking": status == "block",
    }


def collect_execution_preflight_checklist(
    planning_chain: dict[str, Any] | None = None,
    *,
    execution_readiness_bundle: dict[str, Any] | None = None,
    execution_evidence_contract: dict[str, Any] | None = None,
    human_approval_package: dict[str, Any] | None = None,
    execution_workspace_plan: dict[str, Any] | None = None,
    metadata: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Build a read-only checklist for future execution preflight review."""
    chain = planning_chain if planning_chain is not None else collect_growth_planning_chain_preview()
    validate_growth_planning_chain_preview(chain)
    readiness = execution_readiness_bundle if execution_readiness_bundle is not None else chain["execution_readiness_bundle"]
    evidence_contract = execution_evidence_contract if execution_evidence_contract is not None else chain["execution_evidence_contract"]
    approval = human_approval_package if human_approval_package is not None else chain["human_approval_package"]
    workspace = execution_workspace_plan if execution_workspace_plan is not None else chain["execution_workspace_plan"]
    validate_execution_readiness_bundle(readiness)
    journal_for_contract = chain.get("execution_journal_plan") if isinstance(chain, dict) else None
    validate_execution_evidence_contract(evidence_contract, journal_for_contract)
    validate_human_approval_package(approval)
    validate_execution_workspace_plan(workspace)

    planning_chain_id = chain["planning_chain_id"]
    approval_status = "pass" if approval["recommended_human_decision"] == "approve" else "block"
    readiness_status = "pass" if readiness["readiness_status"] == "ready_for_review" else "block"
    quality_status = approval["quality_gate_status"]
    quality_check_status = "pass" if quality_status == "pass" else ("block" if quality_status == "block" else "warning")

    required_human_approvals = [
        _execution_preflight_check(
            planning_chain_id,
            "human_approval",
            approval_text,
            approval_text,
            approval_status,
            "block" if approval_status == "block" else "info",
            approval["approval_package_id"],
        )
        for approval_text in approval["required_approvals"]
    ]
    clean_tree_checks = [
        _execution_preflight_check(
            planning_chain_id,
            "clean_tree",
            "clean or snapshotted working tree",
            "confirm working tree state is clean or explicitly snapshotted before creating any workspace",
            readiness_status,
            "block" if readiness_status == "block" else "info",
            readiness["execution_readiness_bundle_id"],
        ),
        _execution_preflight_check(
            planning_chain_id,
            "clean_tree",
            "safe base ref",
            f"confirm base ref {workspace['base_ref']} matches the reviewed safe point",
            "pass",
            "info",
            workspace["workspace_id"],
        ),
    ]
    path_safety_checks = [
        _execution_preflight_check(
            planning_chain_id,
            "path_safety",
            "target files stay inside repository",
            "confirm all target files are relative project paths and exclude research/runtime state",
            "pass" if workspace["target_files"] else "block",
            "info" if workspace["target_files"] else "block",
            workspace["workspace_id"],
        ),
        _execution_preflight_check(
            planning_chain_id,
            "path_safety",
            "planned worktree path is isolated",
            "confirm proposed worktree path is under .link/worktrees and is not created until approval",
            "pass" if "/.link/worktrees/" in workspace["proposed_worktree_path"] else "block",
            "info" if "/.link/worktrees/" in workspace["proposed_worktree_path"] else "block",
            workspace["workspace_id"],
        ),
    ]
    command_allowlist_checks = [
        _execution_preflight_check(
            planning_chain_id,
            "command_allowlist",
            command,
            "confirm command is allowlisted before future execution",
            "warning",
            "warning",
            workspace["workspace_id"],
        )
        for command in workspace["verification_requirements"]
    ]
    isolation_checks = [
        _execution_preflight_check(
            planning_chain_id,
            "branch_worktree_isolation",
            "branch creation remains human gated",
            "confirm no branch is created until explicit human approval",
            "pass",
            "info",
            workspace["workspace_id"],
        ),
        _execution_preflight_check(
            planning_chain_id,
            "branch_worktree_isolation",
            "worktree creation remains human gated",
            "confirm no worktree is created until explicit human approval",
            "pass",
            "info",
            workspace["workspace_id"],
        ),
    ]
    evidence_contract_checks = [
        _execution_preflight_check(
            planning_chain_id,
            "evidence_contract",
            item["evidence_type"],
            f"future {item['evidence_type']} evidence must include {', '.join(item['required_fields'])}",
            "pass",
            "info",
            item["evidence_id"],
        )
        for item in evidence_contract["evidence_items"]
    ]
    if quality_check_status != "pass":
        evidence_contract_checks.append(_execution_preflight_check(
            planning_chain_id,
            "evidence_contract",
            "quality gate must not block",
            "confirm patch behavior quality gate is pass or explicitly revised before execution",
            quality_check_status,
            "block" if quality_check_status == "block" else "warning",
            approval["approval_package_id"],
        ))

    all_checks = [
        *required_human_approvals,
        *clean_tree_checks,
        *path_safety_checks,
        *command_allowlist_checks,
        *isolation_checks,
        *evidence_contract_checks,
    ]
    blocker_count = sum(1 for check in all_checks if check["status"] == "block")
    warning_count = sum(1 for check in all_checks if check["status"] == "warning")
    pass_status = "block" if blocker_count else ("review" if warning_count else "pass")
    if pass_status == "pass":
        next_action = "Preflight checklist is clear for human review; execution remains disabled until explicit approval."
    elif pass_status == "review":
        next_action = "Review preflight warnings and command allowlist expectations before approving any workspace creation."
    else:
        next_action = "Resolve preflight blockers before creating any branch, worktree, patch, or verification run."

    checklist = {
        "preflight_checklist_version": EXECUTION_PREFLIGHT_CHECKLIST_VERSION,
        "preflight_checklist_id": make_execution_preflight_checklist_id(
            chain,
            readiness,
            evidence_contract,
            approval,
            workspace,
            all_checks,
        ),
        "planning_chain_id": planning_chain_id,
        "execution_package_id": chain["autonomous_execution_package"]["execution_package_id"],
        "execution_readiness_bundle_id": readiness["execution_readiness_bundle_id"],
        "execution_evidence_contract_id": evidence_contract["execution_evidence_contract_id"],
        "human_approval_package_id": approval["approval_package_id"],
        "workspace_id": workspace["workspace_id"],
        "required_human_approvals": required_human_approvals,
        "clean_tree_checks": clean_tree_checks,
        "path_safety_checks": path_safety_checks,
        "command_allowlist_checks": command_allowlist_checks,
        "branch_worktree_isolation_checks": isolation_checks,
        "evidence_contract_checks": evidence_contract_checks,
        "blocker_count": blocker_count,
        "warning_count": warning_count,
        "pass_status": pass_status,
        "recommended_next_action": next_action,
        "dry_run": True,
        "write_allowed": False,
        "automation_allowed": False,
        "metadata": dict(metadata or {}),
        "writes": [],
    }
    validation_chain = chain if "execution_readiness_bundle" in chain else None
    validate_execution_preflight_checklist(checklist, validation_chain)
    return checklist


def validate_execution_preflight_check(item: dict[str, Any]) -> None:
    required = ("check_id", "category", "name", "requirement", "status", "severity", "source_ref", "blocking")
    missing = [field for field in required if field not in item]
    if missing:
        raise ValueError(f"execution preflight check missing fields: {missing}")
    for field in ("check_id", "category", "name", "requirement", "status", "severity", "source_ref"):
        _validate_non_empty_string(item[field], field)
    if item["category"] not in {"human_approval", "clean_tree", "path_safety", "command_allowlist", "branch_worktree_isolation", "evidence_contract"}:
        raise ValueError(f"invalid preflight check category: {item['category']}")
    if item["status"] not in {"pass", "warning", "block"}:
        raise ValueError("invalid preflight check status")
    if item["severity"] not in {"info", "warning", "block"}:
        raise ValueError("invalid preflight check severity")
    if not isinstance(item["blocking"], bool):
        raise TypeError("preflight check blocking must be a boolean")
    if item["blocking"] is not (item["status"] == "block"):
        raise ValueError("preflight check blocking must match block status")


def validate_execution_preflight_checklist(
    checklist: dict[str, Any],
    planning_chain: dict[str, Any] | None = None,
) -> None:
    required = (
        "preflight_checklist_version", "preflight_checklist_id", "planning_chain_id",
        "execution_package_id", "execution_readiness_bundle_id", "execution_evidence_contract_id",
        "human_approval_package_id", "workspace_id", "required_human_approvals",
        "clean_tree_checks", "path_safety_checks", "command_allowlist_checks",
        "branch_worktree_isolation_checks", "evidence_contract_checks", "blocker_count",
        "warning_count", "pass_status", "recommended_next_action", "dry_run",
        "write_allowed", "automation_allowed", "metadata", "writes",
    )
    missing = [field for field in required if field not in checklist]
    if missing:
        raise ValueError(f"execution preflight checklist missing fields: {missing}")
    if checklist["preflight_checklist_version"] != EXECUTION_PREFLIGHT_CHECKLIST_VERSION:
        raise ValueError("unsupported execution preflight checklist version")
    _validate_execution_read_only(checklist, "execution preflight checklist")
    for field in (
        "preflight_checklist_id", "planning_chain_id", "execution_package_id",
        "execution_readiness_bundle_id", "execution_evidence_contract_id",
        "human_approval_package_id", "workspace_id", "recommended_next_action",
    ):
        _validate_non_empty_string(checklist[field], field)
    if checklist["pass_status"] not in {"pass", "review", "block"}:
        raise ValueError("invalid preflight checklist pass_status")
    if not isinstance(checklist["blocker_count"], int) or checklist["blocker_count"] < 0:
        raise ValueError("blocker_count must be a non-negative integer")
    if not isinstance(checklist["warning_count"], int) or checklist["warning_count"] < 0:
        raise ValueError("warning_count must be a non-negative integer")
    check_groups = (
        "required_human_approvals",
        "clean_tree_checks",
        "path_safety_checks",
        "command_allowlist_checks",
        "branch_worktree_isolation_checks",
        "evidence_contract_checks",
    )
    all_checks: list[dict[str, Any]] = []
    for group in check_groups:
        checks = checklist[group]
        if not isinstance(checks, list) or not checks:
            raise TypeError(f"{group} must be a non-empty list")
        for check in checks:
            validate_execution_preflight_check(check)
            all_checks.append(check)
    check_ids = [check["check_id"] for check in all_checks]
    if len(check_ids) != len(set(check_ids)):
        raise ValueError("preflight check ids must be unique")
    blocker_count = sum(1 for check in all_checks if check["status"] == "block")
    warning_count = sum(1 for check in all_checks if check["status"] == "warning")
    if checklist["blocker_count"] != blocker_count:
        raise ValueError("blocker_count must match checks")
    if checklist["warning_count"] != warning_count:
        raise ValueError("warning_count must match checks")
    expected_status = "block" if blocker_count else ("review" if warning_count else "pass")
    if checklist["pass_status"] != expected_status:
        raise ValueError("preflight pass_status must match blocker/warning counts")
    if planning_chain is not None:
        if not isinstance(planning_chain, dict):
            raise TypeError("planning_chain must be a dict")
        readiness = planning_chain["execution_readiness_bundle"]
        evidence_contract = planning_chain["execution_evidence_contract"]
        approval = planning_chain["human_approval_package"]
        workspace = planning_chain["execution_workspace_plan"]
        expected = {
            "planning_chain_id": planning_chain["planning_chain_id"],
            "execution_package_id": planning_chain["autonomous_execution_package"]["execution_package_id"],
            "execution_readiness_bundle_id": readiness["execution_readiness_bundle_id"],
            "execution_evidence_contract_id": evidence_contract["execution_evidence_contract_id"],
            "human_approval_package_id": approval["approval_package_id"],
            "workspace_id": workspace["workspace_id"],
        }
        for field, value in expected.items():
            if checklist[field] != value:
                raise ValueError(f"preflight checklist {field} does not match planning chain")
        expected_id = make_execution_preflight_checklist_id(
            planning_chain,
            readiness,
            evidence_contract,
            approval,
            workspace,
            all_checks,
        )
        if checklist["preflight_checklist_id"] != expected_id:
            raise ValueError("preflight checklist id does not match planning chain")


def stable_execution_preflight_checklist_json(checklist: dict[str, Any]) -> str:
    validate_execution_preflight_checklist(checklist)
    return _stable_ruflo_json(checklist, indent=2) + "\n"


def parse_execution_preflight_checklist_json(text: str) -> dict[str, Any]:
    import json as _json

    checklist = _json.loads(text)
    validate_execution_preflight_checklist(checklist)
    return checklist


_EXECUTION_ATTEMPT_STATUSES = (
    "planned",
    "running",
    "success",
    "failed",
    "rolled_back",
    "abandoned",
)


def _execution_attempt_expected_evidence(journal: dict[str, Any]) -> list[str]:
    stage_to_evidence = {
        "apply_patch_operations": "patch_application",
        "run_compile": "compile",
        "run_tests": "tests",
        "run_healthcheck": "healthcheck",
        "evaluate_quality_gate": "quality_gate",
    }
    expected = [
        evidence_type
        for entry in journal["journal_entries"]
        for stage, evidence_type in stage_to_evidence.items()
        if entry["stage"] == stage
    ]
    if any(entry["rollback_required"] for entry in journal["journal_entries"]):
        expected.append("rollback")
    return _normalize_implementation_branch_refs(expected)


def make_execution_attempt_id(execution_package_id: str, journal_id: str, retry_policy_id: str, sequence: int) -> str:
    return _execution_readiness_id("execution-attempt", {
        "execution_package_id": execution_package_id,
        "journal_id": journal_id,
        "retry_policy_id": retry_policy_id,
        "sequence": sequence,
        "version": EXECUTION_ATTEMPT_HISTORY_VERSION,
    })


def make_execution_attempt_history_id(
    execution_package: dict[str, Any],
    journal: dict[str, Any],
    retry_policy: dict[str, Any],
    attempts: list[dict[str, Any]],
) -> str:
    return _execution_readiness_id("execution-attempt-history", {
        "attempt_ids": [attempt["attempt_id"] for attempt in attempts],
        "execution_package_id": execution_package["execution_package_id"],
        "journal_id": journal["execution_journal_id"],
        "retry_policy_id": retry_policy["retry_policy_id"],
        "version": EXECUTION_ATTEMPT_HISTORY_VERSION,
    })


def _planned_execution_attempt(
    execution_package: dict[str, Any],
    journal: dict[str, Any],
    retry_policy: dict[str, Any],
    sequence: int,
    expected_evidence: list[str],
) -> dict[str, Any]:
    max_attempts = retry_policy["max_attempts"]
    retry_allowed = sequence < max_attempts
    rollback_required = any(entry["rollback_required"] for entry in journal["journal_entries"])
    triggering_event = "initial_execution_request" if sequence == 1 else "retry_after_retryable_failure"
    next_action = (
        "await explicit human approval before starting the planned execution attempt"
        if sequence == 1
        else "retry only after a retryable failure and human review confirms the workspace state is known"
    )
    return {
        "attempt_id": make_execution_attempt_id(
            execution_package["execution_package_id"],
            journal["execution_journal_id"],
            retry_policy["retry_policy_id"],
            sequence,
        ),
        "sequence": sequence,
        "status": "planned",
        "start_policy": "assign_utc_timestamp_when_attempt_starts_after_explicit_approval",
        "completion_policy": "record terminal status only after evidence contract requirements are satisfied or blocked",
        "triggering_event": triggering_event,
        "expected_evidence": list(expected_evidence),
        "retry_allowed": retry_allowed,
        "rollback_required": rollback_required,
        "next_action": next_action,
    }


def collect_execution_attempt_history(
    execution_journal_plan: dict[str, Any] | None = None,
    *,
    retry_policy: dict[str, Any] | None = None,
    execution_package: dict[str, Any] | None = None,
    attempts: list[dict[str, Any]] | None = None,
    metadata: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Model future execution attempts without starting them."""
    if execution_journal_plan is None or retry_policy is None or execution_package is None:
        chain = collect_growth_planning_chain_preview()
        journal = execution_journal_plan if execution_journal_plan is not None else chain["execution_journal_plan"]
        retry = retry_policy if retry_policy is not None else chain["execution_retry_policy"]
        package = execution_package if execution_package is not None else chain["autonomous_execution_package"]
    else:
        journal = execution_journal_plan
        retry = retry_policy
        package = execution_package
    validate_execution_journal_plan(journal)
    validate_execution_retry_policy(retry)
    validate_autonomous_execution_package(package)
    if journal["execution_package_id"] != package["execution_package_id"]:
        raise ValueError("execution attempt history journal must reference execution package")

    expected_evidence = _execution_attempt_expected_evidence(journal)
    if attempts is None:
        planned_attempts = [
            _planned_execution_attempt(package, journal, retry, sequence, expected_evidence)
            for sequence in range(1, retry["max_attempts"] + 1)
        ]
    else:
        if not isinstance(attempts, list):
            raise TypeError("attempts must be a list")
        planned_attempts = [dict(attempt) for attempt in attempts]

    history = {
        "attempt_history_version": EXECUTION_ATTEMPT_HISTORY_VERSION,
        "attempt_history_id": make_execution_attempt_history_id(package, journal, retry, planned_attempts),
        "execution_package_id": package["execution_package_id"],
        "execution_journal_plan_id": journal["execution_journal_id"],
        "retry_policy_id": retry["retry_policy_id"],
        "max_attempts": retry["max_attempts"],
        "attempts": planned_attempts,
        "attempt_count": len(planned_attempts),
        "retry_allowed_count": sum(1 for attempt in planned_attempts if attempt["retry_allowed"]),
        "rollback_required_count": sum(1 for attempt in planned_attempts if attempt["rollback_required"]),
        "dry_run": True,
        "write_allowed": False,
        "automation_allowed": False,
        "metadata": dict(metadata or {}),
        "writes": [],
    }
    validate_execution_attempt_history(history, journal, retry, package)
    return history


def validate_execution_attempt(attempt: dict[str, Any]) -> None:
    required = (
        "attempt_id", "sequence", "status", "start_policy", "completion_policy",
        "triggering_event", "expected_evidence", "retry_allowed", "rollback_required",
        "next_action",
    )
    missing = [field for field in required if field not in attempt]
    if missing:
        raise ValueError(f"execution attempt missing fields: {missing}")
    for field in ("attempt_id", "status", "start_policy", "completion_policy", "triggering_event", "next_action"):
        _validate_non_empty_string(attempt[field], field)
    if not isinstance(attempt["sequence"], int) or attempt["sequence"] < 1:
        raise ValueError("attempt sequence must be a positive integer")
    if attempt["status"] not in _EXECUTION_ATTEMPT_STATUSES:
        raise ValueError(f"invalid execution attempt status: {attempt['status']}")
    if not isinstance(attempt["expected_evidence"], list) or not attempt["expected_evidence"]:
        raise TypeError("expected_evidence must be a non-empty list")
    if attempt["expected_evidence"] != _normalize_implementation_branch_refs(attempt["expected_evidence"]):
        raise ValueError("expected_evidence must be normalized and sorted")
    for field in ("retry_allowed", "rollback_required"):
        if not isinstance(attempt[field], bool):
            raise TypeError(f"{field} must be a boolean")
    if attempt["status"] == "success" and attempt["rollback_required"]:
        raise ValueError("successful attempts must not require rollback")
    if attempt["status"] == "rolled_back" and not attempt["rollback_required"]:
        raise ValueError("rolled_back attempts must require rollback")


def validate_execution_attempt_history(
    history: dict[str, Any],
    execution_journal_plan: dict[str, Any] | None = None,
    retry_policy: dict[str, Any] | None = None,
    execution_package: dict[str, Any] | None = None,
) -> None:
    required = (
        "attempt_history_version", "attempt_history_id", "execution_package_id",
        "execution_journal_plan_id", "retry_policy_id", "max_attempts", "attempts",
        "attempt_count", "retry_allowed_count", "rollback_required_count", "dry_run",
        "write_allowed", "automation_allowed", "metadata", "writes",
    )
    missing = [field for field in required if field not in history]
    if missing:
        raise ValueError(f"execution attempt history missing fields: {missing}")
    if history["attempt_history_version"] != EXECUTION_ATTEMPT_HISTORY_VERSION:
        raise ValueError("unsupported execution attempt history version")
    _validate_execution_read_only(history, "execution attempt history")
    for field in ("attempt_history_id", "execution_package_id", "execution_journal_plan_id", "retry_policy_id"):
        _validate_non_empty_string(history[field], field)
    if not isinstance(history["max_attempts"], int) or history["max_attempts"] < 1 or history["max_attempts"] > 5:
        raise ValueError("max_attempts must be an integer from 1 to 5")
    attempts = history["attempts"]
    if not isinstance(attempts, list) or not attempts:
        raise TypeError("attempts must be a non-empty list")
    if not isinstance(history["attempt_count"], int) or history["attempt_count"] != len(attempts):
        raise ValueError("attempt_count must match attempts length")
    if len(attempts) > history["max_attempts"]:
        raise ValueError("attempt_count must not exceed max_attempts")
    sequences: set[int] = set()
    attempt_ids: set[str] = set()
    for index, attempt in enumerate(attempts, start=1):
        validate_execution_attempt(attempt)
        if attempt["sequence"] in sequences:
            raise ValueError(f"duplicate execution attempt sequence: {attempt['sequence']}")
        if attempt["attempt_id"] in attempt_ids:
            raise ValueError(f"duplicate execution attempt id: {attempt['attempt_id']}")
        sequences.add(attempt["sequence"])
        attempt_ids.add(attempt["attempt_id"])
        if attempt["sequence"] != index:
            raise ValueError("execution attempts must be ordered by sequence without gaps")
    retry_count = sum(1 for attempt in attempts if attempt["retry_allowed"])
    rollback_count = sum(1 for attempt in attempts if attempt["rollback_required"])
    if history["retry_allowed_count"] != retry_count:
        raise ValueError("retry_allowed_count must match attempts")
    if history["rollback_required_count"] != rollback_count:
        raise ValueError("rollback_required_count must match attempts")
    if execution_journal_plan is not None:
        validate_execution_journal_plan(execution_journal_plan)
        if history["execution_journal_plan_id"] != execution_journal_plan["execution_journal_id"]:
            raise ValueError("attempt history must reference execution journal")
        if history["execution_package_id"] != execution_journal_plan["execution_package_id"]:
            raise ValueError("attempt history package id must match journal")
    if retry_policy is not None:
        validate_execution_retry_policy(retry_policy)
        if history["retry_policy_id"] != retry_policy["retry_policy_id"]:
            raise ValueError("attempt history must reference retry policy")
        if history["max_attempts"] != retry_policy["max_attempts"]:
            raise ValueError("attempt history max_attempts must match retry policy")
        for attempt in attempts:
            expected_retry = attempt["sequence"] < retry_policy["max_attempts"]
            if attempt["retry_allowed"] != expected_retry:
                raise ValueError("attempt retry_allowed must match retry policy")
    if execution_package is not None:
        validate_autonomous_execution_package(execution_package)
        if history["execution_package_id"] != execution_package["execution_package_id"]:
            raise ValueError("attempt history must reference execution package")
    if execution_journal_plan is not None and retry_policy is not None and execution_package is not None:
        expected_evidence = _execution_attempt_expected_evidence(execution_journal_plan)
        rollback_required = any(entry["rollback_required"] for entry in execution_journal_plan["journal_entries"])
        for attempt in attempts:
            if attempt["expected_evidence"] != expected_evidence:
                raise ValueError("attempt expected_evidence must match execution journal")
            if attempt["rollback_required"] != rollback_required:
                raise ValueError("attempt rollback_required must match execution journal")
            expected_id = make_execution_attempt_id(
                execution_package["execution_package_id"],
                execution_journal_plan["execution_journal_id"],
                retry_policy["retry_policy_id"],
                attempt["sequence"],
            )
            if attempt["attempt_id"] != expected_id:
                raise ValueError("execution attempt id does not match inputs")
        expected_history_id = make_execution_attempt_history_id(
            execution_package,
            execution_journal_plan,
            retry_policy,
            attempts,
        )
        if history["attempt_history_id"] != expected_history_id:
            raise ValueError("execution attempt history id does not match inputs")


def stable_execution_attempt_history_json(history: dict[str, Any]) -> str:
    validate_execution_attempt_history(history)
    return _stable_ruflo_json(history, indent=2) + "\n"


def parse_execution_attempt_history_json(text: str) -> dict[str, Any]:
    import json as _json

    history = _json.loads(text)
    validate_execution_attempt_history(history)
    return history


EXECUTION_READINESS_DASHBOARD_SUMMARY_VERSION = "link-execution-readiness-dashboard-summary-v1"


def make_execution_readiness_dashboard_summary_id(chain: dict[str, Any]) -> str:
    return _execution_readiness_id("execution-readiness-dashboard-summary", {
        "attempt_history_id": chain["execution_attempt_history"]["attempt_history_id"],
        "evidence_contract_id": chain["execution_evidence_contract"]["execution_evidence_contract_id"],
        "planning_chain_id": chain["planning_chain_id"],
        "preflight_checklist_id": chain["execution_preflight_checklist"]["preflight_checklist_id"],
        "readiness_bundle_id": chain["execution_readiness_bundle"]["execution_readiness_bundle_id"],
        "version": EXECUTION_READINESS_DASHBOARD_SUMMARY_VERSION,
    })


def _execution_dashboard_top_blockers(chain: dict[str, Any]) -> list[str]:
    readiness = chain["execution_readiness_bundle"]
    preflight = chain["execution_preflight_checklist"]
    quality_gate = chain["patch_behavior_quality_gate"]
    blockers = list(readiness["blocking_reasons"])
    blockers.extend(
        f"{check['category']}: {check['name']}"
        for group in (
            preflight["required_human_approvals"],
            preflight["clean_tree_checks"],
            preflight["path_safety_checks"],
            preflight["command_allowlist_checks"],
            preflight["branch_worktree_isolation_checks"],
            preflight["evidence_contract_checks"],
        )
        for check in group
        if check["status"] == "block"
    )
    blockers.extend(
        finding["message"]
        for finding in quality_gate["findings"]
        if finding["severity"] == "block"
    )
    return _normalize_patch_behavior_text_list(blockers)[:8] if blockers else []


def _execution_dashboard_top_warnings(chain: dict[str, Any]) -> list[str]:
    preflight = chain["execution_preflight_checklist"]
    quality_gate = chain["patch_behavior_quality_gate"]
    warnings = [
        f"{check['category']}: {check['name']}"
        for group in (
            preflight["required_human_approvals"],
            preflight["clean_tree_checks"],
            preflight["path_safety_checks"],
            preflight["command_allowlist_checks"],
            preflight["branch_worktree_isolation_checks"],
            preflight["evidence_contract_checks"],
        )
        for check in group
        if check["status"] == "warning"
    ]
    warnings.extend(
        finding["message"]
        for finding in quality_gate["findings"]
        if finding["severity"] == "review"
    )
    return _normalize_patch_behavior_text_list(warnings)[:8] if warnings else []


def _execution_dashboard_gate_stack_blockers(gate_stack: dict[str, Any] | None) -> list[str]:
    if not gate_stack:
        return []
    blockers = [
        f"{gate['gate_type']}: {blocker}"
        for gate in gate_stack.get("gates", [])
        for blocker in gate.get("blockers", [])
    ]
    return _normalize_patch_behavior_text_list(blockers)[:8] if blockers else []


def _execution_dashboard_gate_stack_warnings(gate_stack: dict[str, Any] | None) -> list[str]:
    if not gate_stack:
        return []
    warnings = [
        f"{gate['gate_type']}: {warning}"
        for gate in gate_stack.get("gates", [])
        for warning in gate.get("warnings", [])
    ]
    return _normalize_patch_behavior_text_list(warnings)[:8] if warnings else []


def collect_execution_readiness_dashboard_summary(
    planning_chain: dict[str, Any] | None = None,
    *,
    metadata: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Summarize full execution readiness state for human review."""
    chain = planning_chain if planning_chain is not None else collect_growth_planning_chain_preview()
    validate_growth_planning_chain_preview(chain)
    action = chain["top_recommended_next_action"]
    quality_gate = chain["patch_behavior_quality_gate"]
    evidence_contract = chain["execution_evidence_contract"]
    preflight = chain["execution_preflight_checklist"]
    attempt_history = chain["execution_attempt_history"]
    readiness = chain["execution_readiness_bundle"]
    execution_package = chain["autonomous_execution_package"]
    approval = chain["human_approval_package"]
    review_bundle = chain["planning_chain_review_bundle"]
    gate_stack = chain.get("execution_gate_stack_preview")
    if gate_stack is not None:
        if "execution_readiness_dashboard_summary" in chain:
            validate_execution_gate_stack_preview(gate_stack, chain)
        else:
            validate_execution_gate_stack_preview(gate_stack)
    summary = {
        "dashboard_summary_version": EXECUTION_READINESS_DASHBOARD_SUMMARY_VERSION,
        "dashboard_summary_id": make_execution_readiness_dashboard_summary_id(chain),
        "planning_chain_id": chain["planning_chain_id"],
        "top_upgrade_id": action["upgrade_id"],
        "top_upgrade_title": action["title"],
        "quality_gate": {
            "quality_gate_id": quality_gate["quality_gate_id"],
            "pass_status": quality_gate["pass_status"],
            "quality_score": quality_gate["quality_score"],
            "risk_score": quality_gate["risk_score"],
        },
        "execution_evidence_contract_id": evidence_contract["execution_evidence_contract_id"],
        "required_evidence_count": evidence_contract["evidence_item_count"],
        "preflight_checklist_id": preflight["preflight_checklist_id"],
        "preflight_status": preflight["pass_status"],
        "preflight_blocker_count": preflight["blocker_count"],
        "preflight_warning_count": preflight["warning_count"],
        "attempt_history_id": attempt_history["attempt_history_id"],
        "planned_attempt_count": attempt_history["attempt_count"],
        "execution_readiness_bundle_id": readiness["execution_readiness_bundle_id"],
        "readiness_status": readiness["readiness_status"],
        "execution_package_id": execution_package["execution_package_id"],
        "execution_stage_count": execution_package["stage_count"],
        "required_approvals_count": len(approval["required_approvals"]),
        "missing_evidence_count": len(review_bundle["missing_evidence"]),
        "required_clarifications_count": len(review_bundle["required_clarifications"]),
        "gate_stack_preview_id": gate_stack["gate_stack_preview_id"] if gate_stack else "",
        "gate_count": gate_stack["gate_count"] if gate_stack else 0,
        "pass_count": gate_stack["pass_count"] if gate_stack else 0,
        "review_count": gate_stack["review_count"] if gate_stack else 0,
        "block_count": gate_stack["block_count"] if gate_stack else 0,
        "gate_stack_top_blockers": _execution_dashboard_gate_stack_blockers(gate_stack),
        "gate_stack_top_warnings": _execution_dashboard_gate_stack_warnings(gate_stack),
        "top_blockers": _execution_dashboard_top_blockers(chain),
        "top_warnings": _execution_dashboard_top_warnings(chain),
        "recommended_next_action": gate_stack["recommended_next_action"] if gate_stack else readiness["recommended_next_action"],
        "dry_run": True,
        "write_allowed": False,
        "automation_allowed": False,
        "metadata": dict(metadata or {}),
        "writes": [],
    }
    validate_execution_readiness_dashboard_summary(summary, chain)
    return summary


def validate_execution_readiness_dashboard_summary(
    summary: dict[str, Any],
    planning_chain: dict[str, Any] | None = None,
) -> None:
    required = (
        "dashboard_summary_version", "dashboard_summary_id", "planning_chain_id",
        "top_upgrade_id", "top_upgrade_title", "quality_gate",
        "execution_evidence_contract_id", "required_evidence_count",
        "preflight_checklist_id", "preflight_status", "preflight_blocker_count",
        "preflight_warning_count", "attempt_history_id", "planned_attempt_count",
        "execution_readiness_bundle_id", "readiness_status", "execution_package_id",
        "execution_stage_count", "required_approvals_count", "missing_evidence_count",
        "required_clarifications_count", "gate_stack_preview_id", "gate_count",
        "pass_count", "review_count", "block_count", "gate_stack_top_blockers",
        "gate_stack_top_warnings", "top_blockers", "top_warnings",
        "recommended_next_action", "dry_run", "write_allowed", "automation_allowed",
        "metadata", "writes",
    )
    missing = [field for field in required if field not in summary]
    if missing:
        raise ValueError(f"execution readiness dashboard summary missing fields: {missing}")
    if summary["dashboard_summary_version"] != EXECUTION_READINESS_DASHBOARD_SUMMARY_VERSION:
        raise ValueError("unsupported execution readiness dashboard summary version")
    _validate_execution_read_only(summary, "execution readiness dashboard summary")
    for field in (
        "dashboard_summary_id", "planning_chain_id", "top_upgrade_id", "top_upgrade_title",
        "execution_evidence_contract_id", "preflight_checklist_id", "preflight_status",
        "attempt_history_id", "execution_readiness_bundle_id", "readiness_status",
        "execution_package_id", "recommended_next_action",
    ):
        _validate_non_empty_string(summary[field], field)
    if summary["gate_stack_preview_id"]:
        _validate_non_empty_string(summary["gate_stack_preview_id"], "gate_stack_preview_id")
    if summary["preflight_status"] not in {"pass", "review", "block"}:
        raise ValueError("invalid preflight_status")
    if summary["readiness_status"] not in {"ready_for_review", "blocked", "needs_evidence"}:
        raise ValueError("invalid readiness_status")
    quality_gate = summary["quality_gate"]
    if not isinstance(quality_gate, dict):
        raise TypeError("quality_gate must be a dict")
    for field in ("quality_gate_id", "pass_status"):
        _validate_non_empty_string(quality_gate.get(field), f"quality_gate.{field}")
    if quality_gate["pass_status"] not in {"pass", "review", "block"}:
        raise ValueError("invalid quality gate status")
    for field in ("quality_score", "risk_score"):
        value = quality_gate.get(field)
        if not isinstance(value, (int, float)) or value < 0 or value > 1:
            raise ValueError(f"quality_gate.{field} must be between 0 and 1")
    for field in (
        "required_evidence_count", "preflight_blocker_count", "preflight_warning_count",
        "planned_attempt_count", "execution_stage_count", "required_approvals_count",
        "missing_evidence_count", "required_clarifications_count", "gate_count",
        "pass_count", "review_count", "block_count",
    ):
        if not isinstance(summary[field], int) or summary[field] < 0:
            raise ValueError(f"{field} must be a non-negative integer")
    for field in ("top_blockers", "top_warnings", "gate_stack_top_blockers", "gate_stack_top_warnings"):
        values = summary[field]
        if not isinstance(values, list):
            raise TypeError(f"{field} must be a list")
        if values != _normalize_patch_behavior_text_list(values):
            raise ValueError(f"{field} must be normalized and sorted")
    if summary["gate_count"] != summary["pass_count"] + summary["review_count"] + summary["block_count"]:
        raise ValueError("gate stack counts must add up")
    if planning_chain is not None:
        if not isinstance(planning_chain, dict):
            raise TypeError("planning_chain must be a dict")
        action = planning_chain["top_recommended_next_action"]
        evidence_contract = planning_chain["execution_evidence_contract"]
        preflight = planning_chain["execution_preflight_checklist"]
        attempt_history = planning_chain["execution_attempt_history"]
        readiness = planning_chain["execution_readiness_bundle"]
        execution_package = planning_chain["autonomous_execution_package"]
        approval = planning_chain["human_approval_package"]
        review_bundle = planning_chain["planning_chain_review_bundle"]
        gate_stack = planning_chain.get("execution_gate_stack_preview")
        expected = {
            "dashboard_summary_id": make_execution_readiness_dashboard_summary_id(planning_chain),
            "planning_chain_id": planning_chain["planning_chain_id"],
            "top_upgrade_id": action["upgrade_id"],
            "top_upgrade_title": action["title"],
            "execution_evidence_contract_id": evidence_contract["execution_evidence_contract_id"],
            "required_evidence_count": evidence_contract["evidence_item_count"],
            "preflight_checklist_id": preflight["preflight_checklist_id"],
            "preflight_status": preflight["pass_status"],
            "preflight_blocker_count": preflight["blocker_count"],
            "preflight_warning_count": preflight["warning_count"],
            "attempt_history_id": attempt_history["attempt_history_id"],
            "planned_attempt_count": attempt_history["attempt_count"],
            "execution_readiness_bundle_id": readiness["execution_readiness_bundle_id"],
            "readiness_status": readiness["readiness_status"],
            "execution_package_id": execution_package["execution_package_id"],
            "execution_stage_count": execution_package["stage_count"],
            "required_approvals_count": len(approval["required_approvals"]),
            "missing_evidence_count": len(review_bundle["missing_evidence"]),
            "required_clarifications_count": len(review_bundle["required_clarifications"]),
            "gate_stack_preview_id": gate_stack["gate_stack_preview_id"] if gate_stack else "",
            "gate_count": gate_stack["gate_count"] if gate_stack else 0,
            "pass_count": gate_stack["pass_count"] if gate_stack else 0,
            "review_count": gate_stack["review_count"] if gate_stack else 0,
            "block_count": gate_stack["block_count"] if gate_stack else 0,
        }
        for field, value in expected.items():
            if summary[field] != value:
                raise ValueError(f"dashboard summary {field} does not match planning chain")
        if summary["quality_gate"]["quality_gate_id"] != planning_chain["patch_behavior_quality_gate"]["quality_gate_id"]:
            raise ValueError("dashboard summary quality gate id does not match planning chain")
        if gate_stack is not None:
            if summary["gate_stack_top_blockers"] != _execution_dashboard_gate_stack_blockers(gate_stack):
                raise ValueError("dashboard summary gate stack blockers do not match planning chain")
            if summary["gate_stack_top_warnings"] != _execution_dashboard_gate_stack_warnings(gate_stack):
                raise ValueError("dashboard summary gate stack warnings do not match planning chain")


def stable_execution_readiness_dashboard_summary_json(summary: dict[str, Any]) -> str:
    validate_execution_readiness_dashboard_summary(summary)
    return _stable_ruflo_json(summary, indent=2) + "\n"


def parse_execution_readiness_dashboard_summary_json(text: str) -> dict[str, Any]:
    import json as _json

    summary = _json.loads(text)
    validate_execution_readiness_dashboard_summary(summary)
    return summary


EXECUTION_GATE_STACK_PREVIEW_VERSION = "link-execution-gate-stack-preview-v1"
EXECUTION_GATE_TYPES = (
    "human_approval",
    "clean_tree",
    "path_safety",
    "command_allowlist",
    "evidence_contract",
    "quality_gate",
    "retry_policy",
    "workspace_isolation",
)


def make_execution_gate_id(planning_chain_id: str, gate_type: str, source_component: str) -> str:
    return _execution_readiness_id("execution-gate", {
        "gate_type": gate_type,
        "planning_chain_id": planning_chain_id,
        "source_component": source_component,
        "version": EXECUTION_GATE_STACK_PREVIEW_VERSION,
    })


def make_execution_gate_stack_preview_id(
    planning_chain_id: str,
    execution_package_id: str,
    gates: list[dict[str, Any]],
) -> str:
    return _execution_readiness_id("execution-gate-stack-preview", {
        "execution_package_id": execution_package_id,
        "gate_ids": [gate["gate_id"] for gate in gates],
        "planning_chain_id": planning_chain_id,
        "version": EXECUTION_GATE_STACK_PREVIEW_VERSION,
    })


def _execution_gate_status(blockers: list[str], warnings: list[str], preferred: str | None = None) -> str:
    if blockers:
        return "block"
    if preferred == "block":
        return "block"
    if warnings or preferred in {"review", "warning"}:
        return "review"
    return "pass"


def _execution_gate_from_preflight_checks(
    *,
    planning_chain_id: str,
    gate_name: str,
    gate_type: str,
    source_component: str,
    checks: list[dict[str, Any]],
    required_human_action: str,
    required_evidence: list[str] | None = None,
    recommended_next_action: str,
) -> dict[str, Any]:
    blockers = _normalize_patch_behavior_text_list([
        f"{check['name']}: {check['requirement']}"
        for check in checks
        if check["status"] == "block"
    ])
    warnings = _normalize_patch_behavior_text_list([
        f"{check['name']}: {check['requirement']}"
        for check in checks
        if check["status"] == "warning"
    ])
    return {
        "gate_id": make_execution_gate_id(planning_chain_id, gate_type, source_component),
        "gate_name": gate_name,
        "gate_type": gate_type,
        "source_component": source_component,
        "pass_status": _execution_gate_status(blockers, warnings),
        "blockers": blockers,
        "warnings": warnings,
        "required_human_action": required_human_action,
        "required_evidence": _normalize_implementation_branch_refs(required_evidence or []),
        "recommended_next_action": recommended_next_action,
    }


def _execution_quality_gate_preview(planning_chain_id: str, quality_gate: dict[str, Any]) -> dict[str, Any]:
    blockers = _normalize_patch_behavior_text_list([
        finding["message"]
        for finding in quality_gate["findings"]
        if finding["severity"] == "block"
    ])
    warnings = _normalize_patch_behavior_text_list([
        finding["message"]
        for finding in quality_gate["findings"]
        if finding["severity"] == "review"
    ])
    return {
        "gate_id": make_execution_gate_id(planning_chain_id, "quality_gate", quality_gate["quality_gate_id"]),
        "gate_name": "patch behavior quality gate",
        "gate_type": "quality_gate",
        "source_component": quality_gate["quality_gate_id"],
        "pass_status": _execution_gate_status(blockers, warnings, quality_gate["pass_status"]),
        "blockers": blockers,
        "warnings": warnings,
        "required_human_action": "revise or explicitly review patch behavior quality findings before execution",
        "required_evidence": _normalize_implementation_branch_refs(["quality_gate"]),
        "recommended_next_action": quality_gate["recommended_next_action"],
    }


def _execution_retry_gate_preview(planning_chain_id: str, attempt_history: dict[str, Any]) -> dict[str, Any]:
    warnings = []
    if attempt_history["retry_allowed_count"]:
        warnings.append(f"{attempt_history['retry_allowed_count']} retry attempt(s) require human review before reuse")
    if attempt_history["rollback_required_count"]:
        warnings.append(f"{attempt_history['rollback_required_count']} planned attempt(s) require rollback readiness")
    return {
        "gate_id": make_execution_gate_id(planning_chain_id, "retry_policy", attempt_history["attempt_history_id"]),
        "gate_name": "retry and attempt policy",
        "gate_type": "retry_policy",
        "source_component": attempt_history["attempt_history_id"],
        "pass_status": _execution_gate_status([], warnings),
        "blockers": [],
        "warnings": _normalize_patch_behavior_text_list(warnings),
        "required_human_action": "confirm retryable failures and stop conditions before any repeated execution attempt",
        "required_evidence": _normalize_implementation_branch_refs(
            attempt_history["attempts"][0]["expected_evidence"] if attempt_history["attempts"] else []
        ),
        "recommended_next_action": "Keep retries planned only; execute attempts only after explicit approval and evidence capture is ready.",
    }


def collect_execution_gate_stack_preview(
    planning_chain: dict[str, Any] | None = None,
    *,
    execution_readiness_dashboard_summary: dict[str, Any] | None = None,
    execution_preflight_checklist: dict[str, Any] | None = None,
    execution_evidence_contract: dict[str, Any] | None = None,
    patch_behavior_quality_gate: dict[str, Any] | None = None,
    human_approval_package: dict[str, Any] | None = None,
    execution_attempt_history: dict[str, Any] | None = None,
    metadata: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Aggregate future execution gates without creating workspaces or running commands."""
    chain = planning_chain if planning_chain is not None else collect_growth_planning_chain_preview()
    validate_growth_planning_chain_preview(chain)
    dashboard = execution_readiness_dashboard_summary if execution_readiness_dashboard_summary is not None else chain["execution_readiness_dashboard_summary"]
    preflight = execution_preflight_checklist if execution_preflight_checklist is not None else chain["execution_preflight_checklist"]
    evidence_contract = execution_evidence_contract if execution_evidence_contract is not None else chain["execution_evidence_contract"]
    quality_gate = patch_behavior_quality_gate if patch_behavior_quality_gate is not None else chain["patch_behavior_quality_gate"]
    approval = human_approval_package if human_approval_package is not None else chain["human_approval_package"]
    attempts = execution_attempt_history if execution_attempt_history is not None else chain["execution_attempt_history"]
    validate_execution_readiness_dashboard_summary(dashboard, chain)
    validate_execution_preflight_checklist(preflight, chain)
    validate_execution_evidence_contract(evidence_contract, chain["execution_journal_plan"])
    validate_patch_behavior_quality_gate(quality_gate)
    validate_human_approval_package(approval)
    validate_execution_attempt_history(
        attempts,
        chain["execution_journal_plan"],
        chain["execution_retry_policy"],
        chain["autonomous_execution_package"],
    )

    planning_chain_id = chain["planning_chain_id"]
    evidence_types = _normalize_implementation_branch_refs([
        item["evidence_type"] for item in evidence_contract["evidence_items"]
    ])
    gates = [
        _execution_gate_from_preflight_checks(
            planning_chain_id=planning_chain_id,
            gate_name="human approval gate",
            gate_type="human_approval",
            source_component=approval["approval_package_id"],
            checks=preflight["required_human_approvals"],
            required_human_action="Brandon must explicitly approve the specific workspace and patch application before any writes.",
            required_evidence=evidence_types,
            recommended_next_action=approval["recommended_human_decision"],
        ),
        _execution_gate_from_preflight_checks(
            planning_chain_id=planning_chain_id,
            gate_name="clean tree gate",
            gate_type="clean_tree",
            source_component=preflight["preflight_checklist_id"],
            checks=preflight["clean_tree_checks"],
            required_human_action="confirm the main worktree is clean or intentionally snapshotted before isolation",
            required_evidence=["journal_entry_id", "reviewer_visible_summary"],
            recommended_next_action="Resolve clean-tree blockers before creating any workspace.",
        ),
        _execution_gate_from_preflight_checks(
            planning_chain_id=planning_chain_id,
            gate_name="path safety gate",
            gate_type="path_safety",
            source_component=preflight["preflight_checklist_id"],
            checks=preflight["path_safety_checks"],
            required_human_action="confirm target and workspace paths are inside approved Link execution boundaries",
            required_evidence=["changed_file_refs", "changed_file_hashes"],
            recommended_next_action="Keep path checks read-only until every target path is reviewable.",
        ),
        _execution_gate_from_preflight_checks(
            planning_chain_id=planning_chain_id,
            gate_name="command allowlist gate",
            gate_type="command_allowlist",
            source_component=preflight["preflight_checklist_id"],
            checks=preflight["command_allowlist_checks"],
            required_human_action="approve only bounded allowlisted compile/test/healthcheck commands",
            required_evidence=["command", "exit_code", "combined_log_ref", "log_hash"],
            recommended_next_action="Review command warnings before enabling any verification runner.",
        ),
        _execution_gate_from_preflight_checks(
            planning_chain_id=planning_chain_id,
            gate_name="evidence contract gate",
            gate_type="evidence_contract",
            source_component=evidence_contract["execution_evidence_contract_id"],
            checks=preflight["evidence_contract_checks"],
            required_human_action="confirm every required evidence item can be captured before execution starts",
            required_evidence=evidence_types,
            recommended_next_action="Do not execute until missing evidence fields have a capture path.",
        ),
        _execution_quality_gate_preview(planning_chain_id, quality_gate),
        _execution_retry_gate_preview(planning_chain_id, attempts),
        _execution_gate_from_preflight_checks(
            planning_chain_id=planning_chain_id,
            gate_name="workspace isolation gate",
            gate_type="workspace_isolation",
            source_component=preflight["workspace_id"],
            checks=preflight["branch_worktree_isolation_checks"],
            required_human_action="confirm branch and worktree creation remain disabled until explicit approval",
            required_evidence=["journal_entry_id", "attempt_id", "reviewer_visible_summary"],
            recommended_next_action="Keep branch/worktree creation planned-only until all gates pass or are explicitly reviewed.",
        ),
    ]
    pass_count = sum(1 for gate in gates if gate["pass_status"] == "pass")
    review_count = sum(1 for gate in gates if gate["pass_status"] == "review")
    block_count = sum(1 for gate in gates if gate["pass_status"] == "block")
    if block_count:
        next_action = "Resolve execution gate blockers before any workspace, branch, patch, or verification execution."
    elif review_count:
        next_action = "Review execution gate warnings and required human actions before enabling any runtime step."
    else:
        next_action = "Gate stack is clear for human review; execution remains disabled until explicitly approved."
    preview = {
        "gate_stack_preview_version": EXECUTION_GATE_STACK_PREVIEW_VERSION,
        "gate_stack_preview_id": make_execution_gate_stack_preview_id(
            planning_chain_id,
            chain["autonomous_execution_package"]["execution_package_id"],
            gates,
        ),
        "planning_chain_id": planning_chain_id,
        "execution_package_id": chain["autonomous_execution_package"]["execution_package_id"],
        "dashboard_summary_id": dashboard["dashboard_summary_id"],
        "preflight_checklist_id": preflight["preflight_checklist_id"],
        "execution_evidence_contract_id": evidence_contract["execution_evidence_contract_id"],
        "quality_gate_id": quality_gate["quality_gate_id"],
        "human_approval_package_id": approval["approval_package_id"],
        "attempt_history_id": attempts["attempt_history_id"],
        "gate_count": len(gates),
        "pass_count": pass_count,
        "review_count": review_count,
        "block_count": block_count,
        "gates": gates,
        "recommended_next_action": next_action,
        "dry_run": True,
        "write_allowed": False,
        "automation_allowed": False,
        "metadata": dict(metadata or {}),
        "writes": [],
    }
    validate_execution_gate_stack_preview(preview, chain)
    return preview


def validate_execution_gate_preview_gate(gate: dict[str, Any]) -> None:
    required = (
        "gate_id", "gate_name", "gate_type", "source_component", "pass_status",
        "blockers", "warnings", "required_human_action", "required_evidence",
        "recommended_next_action",
    )
    missing = [field for field in required if field not in gate]
    if missing:
        raise ValueError(f"execution gate missing fields: {missing}")
    for field in ("gate_id", "gate_name", "gate_type", "source_component", "pass_status", "required_human_action", "recommended_next_action"):
        _validate_non_empty_string(gate[field], field)
    if gate["gate_type"] not in EXECUTION_GATE_TYPES:
        raise ValueError(f"invalid execution gate type: {gate['gate_type']}")
    if gate["pass_status"] not in {"pass", "review", "block"}:
        raise ValueError("invalid execution gate pass_status")
    for field in ("blockers", "warnings"):
        values = gate[field]
        if not isinstance(values, list):
            raise TypeError(f"gate {field} must be a list")
        if values != _normalize_patch_behavior_text_list(values):
            raise ValueError(f"gate {field} must be normalized and sorted")
    evidence = gate["required_evidence"]
    if not isinstance(evidence, list):
        raise TypeError("gate required_evidence must be a list")
    if evidence != _normalize_implementation_branch_refs(evidence):
        raise ValueError("gate required_evidence must be normalized and sorted")
    expected_status = _execution_gate_status(gate["blockers"], gate["warnings"])
    if gate["pass_status"] == "pass" and expected_status != "pass":
        raise ValueError("gate pass_status must account for blockers and warnings")
    if gate["pass_status"] == "review" and gate["blockers"]:
        raise ValueError("review gates must not contain blockers")


def validate_execution_gate_stack_preview(
    preview: dict[str, Any],
    planning_chain: dict[str, Any] | None = None,
) -> None:
    required = (
        "gate_stack_preview_version", "gate_stack_preview_id", "planning_chain_id",
        "execution_package_id", "dashboard_summary_id", "preflight_checklist_id",
        "execution_evidence_contract_id", "quality_gate_id", "human_approval_package_id",
        "attempt_history_id", "gate_count", "pass_count", "review_count", "block_count",
        "gates", "recommended_next_action", "dry_run", "write_allowed",
        "automation_allowed", "metadata", "writes",
    )
    missing = [field for field in required if field not in preview]
    if missing:
        raise ValueError(f"execution gate stack preview missing fields: {missing}")
    if preview["gate_stack_preview_version"] != EXECUTION_GATE_STACK_PREVIEW_VERSION:
        raise ValueError("unsupported execution gate stack preview version")
    _validate_execution_read_only(preview, "execution gate stack preview")
    for field in (
        "gate_stack_preview_id", "planning_chain_id", "execution_package_id",
        "dashboard_summary_id", "preflight_checklist_id", "execution_evidence_contract_id",
        "quality_gate_id", "human_approval_package_id", "attempt_history_id",
        "recommended_next_action",
    ):
        _validate_non_empty_string(preview[field], field)
    gates = preview["gates"]
    if not isinstance(gates, list) or not gates:
        raise TypeError("execution gate stack gates must be a non-empty list")
    gate_ids: set[str] = set()
    gate_types: set[str] = set()
    for gate in gates:
        validate_execution_gate_preview_gate(gate)
        if gate["gate_id"] in gate_ids:
            raise ValueError(f"duplicate execution gate id: {gate['gate_id']}")
        gate_ids.add(gate["gate_id"])
        gate_types.add(gate["gate_type"])
    missing_gate_types = set(EXECUTION_GATE_TYPES) - gate_types
    if missing_gate_types:
        raise ValueError(f"execution gate stack missing gate types: {sorted(missing_gate_types)}")
    if not isinstance(preview["gate_count"], int) or preview["gate_count"] != len(gates):
        raise ValueError("gate_count must match gates")
    counts = {
        "pass_count": sum(1 for gate in gates if gate["pass_status"] == "pass"),
        "review_count": sum(1 for gate in gates if gate["pass_status"] == "review"),
        "block_count": sum(1 for gate in gates if gate["pass_status"] == "block"),
    }
    for field, value in counts.items():
        if preview[field] != value:
            raise ValueError(f"{field} must match gates")
    expected_id = make_execution_gate_stack_preview_id(
        preview["planning_chain_id"],
        preview["execution_package_id"],
        gates,
    )
    if preview["gate_stack_preview_id"] != expected_id:
        raise ValueError("execution gate stack preview id does not match gates")
    if planning_chain is not None:
        if not isinstance(planning_chain, dict):
            raise TypeError("planning_chain must be a dict")
        expected_refs = {
            "planning_chain_id": planning_chain["planning_chain_id"],
            "execution_package_id": planning_chain["autonomous_execution_package"]["execution_package_id"],
            "dashboard_summary_id": planning_chain["execution_readiness_dashboard_summary"]["dashboard_summary_id"],
            "preflight_checklist_id": planning_chain["execution_preflight_checklist"]["preflight_checklist_id"],
            "execution_evidence_contract_id": planning_chain["execution_evidence_contract"]["execution_evidence_contract_id"],
            "quality_gate_id": planning_chain["patch_behavior_quality_gate"]["quality_gate_id"],
            "human_approval_package_id": planning_chain["human_approval_package"]["approval_package_id"],
            "attempt_history_id": planning_chain["execution_attempt_history"]["attempt_history_id"],
        }
        for field, value in expected_refs.items():
            if preview[field] != value:
                raise ValueError(f"execution gate stack {field} does not match planning chain")


def stable_execution_gate_stack_preview_json(preview: dict[str, Any]) -> str:
    validate_execution_gate_stack_preview(preview)
    return _stable_ruflo_json(preview, indent=2) + "\n"


def parse_execution_gate_stack_preview_json(text: str) -> dict[str, Any]:
    import json as _json

    preview = _json.loads(text)
    validate_execution_gate_stack_preview(preview)
    return preview


EXECUTION_APPROVAL_CHECKLIST_VERSION = "link-execution-approval-checklist-v1"


def make_execution_approval_checklist_id(
    planning_chain_id: str,
    execution_package_id: str,
    human_approval_package_id: str,
    gate_stack_preview_id: str,
    required_approvals: list[str],
    approval_blockers: list[str],
    approval_warnings: list[str],
) -> str:
    return _execution_readiness_id("execution-approval-checklist", {
        "approval_blockers": approval_blockers,
        "approval_warnings": approval_warnings,
        "execution_package_id": execution_package_id,
        "gate_stack_preview_id": gate_stack_preview_id,
        "human_approval_package_id": human_approval_package_id,
        "planning_chain_id": planning_chain_id,
        "required_approvals": required_approvals,
        "version": EXECUTION_APPROVAL_CHECKLIST_VERSION,
    })


def _execution_approval_human_gate(gate_stack: dict[str, Any]) -> dict[str, Any]:
    human_gates = [gate for gate in gate_stack["gates"] if gate["gate_type"] == "human_approval"]
    if len(human_gates) != 1:
        raise ValueError("execution approval checklist requires exactly one human approval gate")
    return human_gates[0]


def collect_execution_approval_checklist(
    planning_chain: dict[str, Any] | None = None,
    *,
    human_approval_package: dict[str, Any] | None = None,
    execution_gate_stack_preview: dict[str, Any] | None = None,
    metadata: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Return a human approval checklist without enabling execution."""
    chain = planning_chain if planning_chain is not None else collect_growth_planning_chain_preview()
    validate_growth_planning_chain_preview(chain)
    approval = human_approval_package if human_approval_package is not None else chain["human_approval_package"]
    gate_stack = execution_gate_stack_preview if execution_gate_stack_preview is not None else chain["execution_gate_stack_preview"]
    validate_human_approval_package(approval)
    validate_execution_gate_stack_preview(gate_stack, chain)
    human_gate = _execution_approval_human_gate(gate_stack)

    required_approvals = _normalize_patch_behavior_text_list(approval["required_approvals"])
    approval_blockers = _normalize_patch_behavior_text_list([
        *approval["blocking_concerns"],
        *human_gate["blockers"],
    ]) if (approval["blocking_concerns"] or human_gate["blockers"]) else []
    approval_warnings = _normalize_patch_behavior_text_list([
        *approval["risk_summary"],
        *human_gate["warnings"],
        *(approval["required_approvals"] if approval["recommended_human_decision"] != "approve" else []),
    ]) if (approval["risk_summary"] or human_gate["warnings"] or approval["recommended_human_decision"] != "approve") else []
    if approval_blockers or human_gate["pass_status"] == "block" or approval["recommended_human_decision"] == "reject":
        approval_status = "block"
    elif approval_warnings or human_gate["pass_status"] == "review" or approval["recommended_human_decision"] == "revise":
        approval_status = "review"
    else:
        approval_status = "pass"
    if approval_status == "block":
        next_action = "Resolve approval blockers before any workspace, branch, patch, or verification execution."
    elif approval_status == "review":
        next_action = "Present the approval checklist to a human reviewer; execution remains disabled until explicit approval."
    else:
        next_action = "Approval checklist is clear for human review; execution remains disabled until explicitly approved."
    checklist = {
        "approval_checklist_version": EXECUTION_APPROVAL_CHECKLIST_VERSION,
        "approval_checklist_id": make_execution_approval_checklist_id(
            chain["planning_chain_id"],
            chain["autonomous_execution_package"]["execution_package_id"],
            approval["approval_package_id"],
            gate_stack["gate_stack_preview_id"],
            required_approvals,
            approval_blockers,
            approval_warnings,
        ),
        "planning_chain_id": chain["planning_chain_id"],
        "execution_package_id": chain["autonomous_execution_package"]["execution_package_id"],
        "human_approval_package_id": approval["approval_package_id"],
        "gate_stack_preview_id": gate_stack["gate_stack_preview_id"],
        "required_approvals": required_approvals,
        "approval_blockers": approval_blockers,
        "approval_warnings": approval_warnings,
        "approval_status": approval_status,
        "recommended_next_action": next_action,
        "dry_run": True,
        "write_allowed": False,
        "automation_allowed": False,
        "metadata": dict(metadata or {}),
        "writes": [],
    }
    validate_execution_approval_checklist(checklist, chain)
    return checklist


def validate_execution_approval_checklist(
    checklist: dict[str, Any],
    planning_chain: dict[str, Any] | None = None,
) -> None:
    required = (
        "approval_checklist_version", "approval_checklist_id", "planning_chain_id",
        "execution_package_id", "human_approval_package_id", "gate_stack_preview_id",
        "required_approvals", "approval_blockers", "approval_warnings",
        "approval_status", "recommended_next_action", "dry_run", "write_allowed",
        "automation_allowed", "metadata", "writes",
    )
    missing = [field for field in required if field not in checklist]
    if missing:
        raise ValueError(f"execution approval checklist missing fields: {missing}")
    if checklist["approval_checklist_version"] != EXECUTION_APPROVAL_CHECKLIST_VERSION:
        raise ValueError("unsupported execution approval checklist version")
    _validate_execution_read_only(checklist, "execution approval checklist")
    for field in (
        "approval_checklist_id", "planning_chain_id", "execution_package_id",
        "human_approval_package_id", "gate_stack_preview_id", "approval_status",
        "recommended_next_action",
    ):
        _validate_non_empty_string(checklist[field], field)
    if checklist["approval_status"] not in {"pass", "review", "block"}:
        raise ValueError("invalid approval_status")
    for field in ("required_approvals", "approval_blockers", "approval_warnings"):
        values = checklist[field]
        if not isinstance(values, list):
            raise TypeError(f"{field} must be a list")
        if field == "required_approvals" and not values:
            raise ValueError("required_approvals must not be empty")
        if values != _normalize_patch_behavior_text_list(values):
            raise ValueError(f"{field} must be normalized and sorted")
    if checklist["approval_blockers"] and checklist["approval_status"] != "block":
        raise ValueError("approval blockers must produce block status")
    if checklist["approval_status"] == "pass" and checklist["approval_warnings"]:
        raise ValueError("approval warnings must not produce pass status")
    expected_id = make_execution_approval_checklist_id(
        checklist["planning_chain_id"],
        checklist["execution_package_id"],
        checklist["human_approval_package_id"],
        checklist["gate_stack_preview_id"],
        checklist["required_approvals"],
        checklist["approval_blockers"],
        checklist["approval_warnings"],
    )
    if checklist["approval_checklist_id"] != expected_id:
        raise ValueError("execution approval checklist id does not match contents")
    if planning_chain is not None:
        validate_growth_planning_chain_preview(planning_chain)
        approval = planning_chain["human_approval_package"]
        gate_stack = planning_chain["execution_gate_stack_preview"]
        expected_refs = {
            "planning_chain_id": planning_chain["planning_chain_id"],
            "execution_package_id": planning_chain["autonomous_execution_package"]["execution_package_id"],
            "human_approval_package_id": approval["approval_package_id"],
            "gate_stack_preview_id": gate_stack["gate_stack_preview_id"],
        }
        for field, value in expected_refs.items():
            if checklist[field] != value:
                raise ValueError(f"execution approval checklist {field} does not match planning chain")
        human_gate = _execution_approval_human_gate(gate_stack)
        expected_required = _normalize_patch_behavior_text_list(approval["required_approvals"])
        expected_blockers = _normalize_patch_behavior_text_list([
            *approval["blocking_concerns"],
            *human_gate["blockers"],
        ]) if (approval["blocking_concerns"] or human_gate["blockers"]) else []
        if checklist["required_approvals"] != expected_required:
            raise ValueError("execution approval checklist required approvals do not match planning chain")
        if checklist["approval_blockers"] != expected_blockers:
            raise ValueError("execution approval checklist blockers do not match planning chain")


def stable_execution_approval_checklist_json(checklist: dict[str, Any]) -> str:
    validate_execution_approval_checklist(checklist)
    return _stable_ruflo_json(checklist, indent=2) + "\n"


def parse_execution_approval_checklist_json(text: str) -> dict[str, Any]:
    import json as _json

    checklist = _json.loads(text)
    validate_execution_approval_checklist(checklist)
    return checklist


EXECUTION_REVIEW_VERSION = "link-execution-review-v1"


def make_execution_review_id(
    planning_chain_id: str,
    execution_package_id: str,
    dashboard_summary_id: str,
    gate_stack_preview_id: str,
    approval_checklist_id: str,
) -> str:
    return _execution_readiness_id("execution-review", {
        "approval_checklist_id": approval_checklist_id,
        "dashboard_summary_id": dashboard_summary_id,
        "execution_package_id": execution_package_id,
        "gate_stack_preview_id": gate_stack_preview_id,
        "planning_chain_id": planning_chain_id,
        "version": EXECUTION_REVIEW_VERSION,
    })


def _execution_review_blockers(dashboard: dict[str, Any], gate_stack: dict[str, Any], checklist: dict[str, Any]) -> list[str]:
    blockers = [
        *dashboard["top_blockers"],
        *checklist["approval_blockers"],
    ]
    blockers.extend(
        f"{gate['gate_type']}: {blocker}"
        for gate in gate_stack["gates"]
        for blocker in gate["blockers"]
    )
    return _normalize_patch_behavior_text_list(blockers)[:12] if blockers else []


def _execution_review_warnings(dashboard: dict[str, Any], gate_stack: dict[str, Any], checklist: dict[str, Any]) -> list[str]:
    warnings = [
        *dashboard["top_warnings"],
        *checklist["approval_warnings"],
    ]
    warnings.extend(
        f"{gate['gate_type']}: {warning}"
        for gate in gate_stack["gates"]
        for warning in gate["warnings"]
    )
    return _normalize_patch_behavior_text_list(warnings)[:12] if warnings else []


def collect_execution_review(
    planning_chain: dict[str, Any] | None = None,
    *,
    execution_readiness_dashboard_summary: dict[str, Any] | None = None,
    execution_gate_stack_preview: dict[str, Any] | None = None,
    execution_approval_checklist: dict[str, Any] | None = None,
    metadata: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Return a compact read-only reviewer-facing execution payload."""
    chain = planning_chain if planning_chain is not None else collect_growth_planning_chain_preview()
    validate_growth_planning_chain_preview(chain)
    dashboard = execution_readiness_dashboard_summary if execution_readiness_dashboard_summary is not None else chain["execution_readiness_dashboard_summary"]
    gate_stack = execution_gate_stack_preview if execution_gate_stack_preview is not None else chain["execution_gate_stack_preview"]
    checklist = execution_approval_checklist if execution_approval_checklist is not None else collect_execution_approval_checklist(chain)
    validate_execution_readiness_dashboard_summary(dashboard, chain)
    validate_execution_gate_stack_preview(gate_stack, chain)
    validate_execution_approval_checklist(checklist, chain)

    blockers = _execution_review_blockers(dashboard, gate_stack, checklist)
    warnings = _execution_review_warnings(dashboard, gate_stack, checklist)
    if checklist["approval_status"] == "block" or gate_stack["block_count"]:
        next_action = "Resolve execution review blockers before any workspace, branch, patch, or verification execution."
    elif checklist["approval_status"] == "review" or gate_stack["review_count"] or warnings:
        next_action = "Review execution warnings and required approvals with Brandon before enabling any runtime step."
    else:
        next_action = "Execution review is clear for human approval; execution remains disabled until explicitly approved."
    review = {
        "execution_review_version": EXECUTION_REVIEW_VERSION,
        "execution_review_id": make_execution_review_id(
            chain["planning_chain_id"],
            chain["autonomous_execution_package"]["execution_package_id"],
            dashboard["dashboard_summary_id"],
            gate_stack["gate_stack_preview_id"],
            checklist["approval_checklist_id"],
        ),
        "planning_chain_id": chain["planning_chain_id"],
        "execution_package_id": chain["autonomous_execution_package"]["execution_package_id"],
        "dashboard_summary_id": dashboard["dashboard_summary_id"],
        "gate_stack_preview_id": gate_stack["gate_stack_preview_id"],
        "approval_checklist_id": checklist["approval_checklist_id"],
        "readiness_summary": {
            "top_upgrade_id": dashboard["top_upgrade_id"],
            "top_upgrade_title": dashboard["top_upgrade_title"],
            "readiness_status": dashboard["readiness_status"],
            "preflight_status": dashboard["preflight_status"],
            "quality_gate_status": dashboard["quality_gate"]["pass_status"],
            "quality_score": dashboard["quality_gate"]["quality_score"],
            "risk_score": dashboard["quality_gate"]["risk_score"],
        },
        "gate_summary": {
            "gate_count": gate_stack["gate_count"],
            "pass_count": gate_stack["pass_count"],
            "review_count": gate_stack["review_count"],
            "block_count": gate_stack["block_count"],
        },
        "approval_summary": {
            "approval_status": checklist["approval_status"],
            "required_approval_count": len(checklist["required_approvals"]),
            "human_approval_package_id": checklist["human_approval_package_id"],
        },
        "blocker_summary": {
            "blocker_count": len(blockers),
            "top_blockers": blockers,
        },
        "warning_summary": {
            "warning_count": len(warnings),
            "top_warnings": warnings,
        },
        "attempt_summary": {
            "attempt_history_id": dashboard["attempt_history_id"],
            "planned_attempt_count": dashboard["planned_attempt_count"],
        },
        "recommended_next_action": next_action,
        "dry_run": True,
        "write_allowed": False,
        "automation_allowed": False,
        "metadata": dict(metadata or {}),
        "writes": [],
    }
    validate_execution_review(review, chain)
    return review


def validate_execution_review(review: dict[str, Any], planning_chain: dict[str, Any] | None = None) -> None:
    required = (
        "execution_review_version", "execution_review_id", "planning_chain_id",
        "execution_package_id", "dashboard_summary_id", "gate_stack_preview_id",
        "approval_checklist_id", "readiness_summary", "gate_summary",
        "approval_summary", "blocker_summary", "warning_summary", "attempt_summary",
        "recommended_next_action", "dry_run", "write_allowed", "automation_allowed",
        "metadata", "writes",
    )
    missing = [field for field in required if field not in review]
    if missing:
        raise ValueError(f"execution review missing fields: {missing}")
    if review["execution_review_version"] != EXECUTION_REVIEW_VERSION:
        raise ValueError("unsupported execution review version")
    _validate_execution_read_only(review, "execution review")
    for field in (
        "execution_review_id", "planning_chain_id", "execution_package_id",
        "dashboard_summary_id", "gate_stack_preview_id", "approval_checklist_id",
        "recommended_next_action",
    ):
        _validate_non_empty_string(review[field], field)
    readiness = review["readiness_summary"]
    if not isinstance(readiness, dict):
        raise TypeError("readiness_summary must be a dict")
    for field in ("top_upgrade_id", "top_upgrade_title", "readiness_status", "preflight_status", "quality_gate_status"):
        _validate_non_empty_string(readiness.get(field), f"readiness_summary.{field}")
    if readiness["readiness_status"] not in {"ready_for_review", "blocked", "needs_evidence"}:
        raise ValueError("invalid readiness status")
    if readiness["preflight_status"] not in {"pass", "review", "block"}:
        raise ValueError("invalid preflight status")
    if readiness["quality_gate_status"] not in {"pass", "review", "block"}:
        raise ValueError("invalid quality gate status")
    _validate_probability_score(readiness.get("quality_score"), "readiness_summary.quality_score")
    _validate_probability_score(readiness.get("risk_score"), "readiness_summary.risk_score")
    gate_summary = review["gate_summary"]
    if not isinstance(gate_summary, dict):
        raise TypeError("gate_summary must be a dict")
    for field in ("gate_count", "pass_count", "review_count", "block_count"):
        if not isinstance(gate_summary.get(field), int) or gate_summary[field] < 0:
            raise ValueError(f"gate_summary.{field} must be a non-negative integer")
    if gate_summary["gate_count"] != gate_summary["pass_count"] + gate_summary["review_count"] + gate_summary["block_count"]:
        raise ValueError("gate summary counts must add up")
    approval = review["approval_summary"]
    if not isinstance(approval, dict):
        raise TypeError("approval_summary must be a dict")
    _validate_non_empty_string(approval.get("approval_status"), "approval_summary.approval_status")
    _validate_non_empty_string(approval.get("human_approval_package_id"), "approval_summary.human_approval_package_id")
    if approval["approval_status"] not in {"pass", "review", "block"}:
        raise ValueError("invalid approval status")
    if not isinstance(approval.get("required_approval_count"), int) or approval["required_approval_count"] < 0:
        raise ValueError("approval_summary.required_approval_count must be a non-negative integer")
    for section_name, list_name, count_name in (
        ("blocker_summary", "top_blockers", "blocker_count"),
        ("warning_summary", "top_warnings", "warning_count"),
    ):
        section = review[section_name]
        if not isinstance(section, dict):
            raise TypeError(f"{section_name} must be a dict")
        if not isinstance(section.get(count_name), int) or section[count_name] < 0:
            raise ValueError(f"{section_name}.{count_name} must be a non-negative integer")
        values = section.get(list_name)
        if not isinstance(values, list):
            raise TypeError(f"{section_name}.{list_name} must be a list")
        if values != _normalize_patch_behavior_text_list(values):
            raise ValueError(f"{section_name}.{list_name} must be normalized and sorted")
        if section[count_name] != len(values):
            raise ValueError(f"{section_name}.{count_name} must match {list_name}")
    attempts = review["attempt_summary"]
    if not isinstance(attempts, dict):
        raise TypeError("attempt_summary must be a dict")
    _validate_non_empty_string(attempts.get("attempt_history_id"), "attempt_summary.attempt_history_id")
    if not isinstance(attempts.get("planned_attempt_count"), int) or attempts["planned_attempt_count"] < 0:
        raise ValueError("attempt_summary.planned_attempt_count must be a non-negative integer")
    expected_id = make_execution_review_id(
        review["planning_chain_id"],
        review["execution_package_id"],
        review["dashboard_summary_id"],
        review["gate_stack_preview_id"],
        review["approval_checklist_id"],
    )
    if review["execution_review_id"] != expected_id:
        raise ValueError("execution review id does not match contents")
    if planning_chain is not None:
        validate_growth_planning_chain_preview(planning_chain)
        dashboard = planning_chain["execution_readiness_dashboard_summary"]
        gate_stack = planning_chain["execution_gate_stack_preview"]
        checklist = collect_execution_approval_checklist(planning_chain)
        expected_refs = {
            "planning_chain_id": planning_chain["planning_chain_id"],
            "execution_package_id": planning_chain["autonomous_execution_package"]["execution_package_id"],
            "dashboard_summary_id": dashboard["dashboard_summary_id"],
            "gate_stack_preview_id": gate_stack["gate_stack_preview_id"],
            "approval_checklist_id": checklist["approval_checklist_id"],
        }
        for field, value in expected_refs.items():
            if review[field] != value:
                raise ValueError(f"execution review {field} does not match planning chain")
        if review["readiness_summary"]["readiness_status"] != dashboard["readiness_status"]:
            raise ValueError("execution review readiness status does not match dashboard")
        if review["gate_summary"]["gate_count"] != gate_stack["gate_count"]:
            raise ValueError("execution review gate count does not match gate stack")
        if review["approval_summary"]["approval_status"] != checklist["approval_status"]:
            raise ValueError("execution review approval status does not match checklist")


def stable_execution_review_json(review: dict[str, Any]) -> str:
    validate_execution_review(review)
    return _stable_ruflo_json(review, indent=2) + "\n"


def parse_execution_review_json(text: str) -> dict[str, Any]:
    import json as _json

    review = _json.loads(text)
    validate_execution_review(review)
    return review


WORKSPACE_CREATOR_RUNTIME_BOUNDARY_VERSION = "link-workspace-creator-runtime-boundary-v1"


def make_workspace_creator_runtime_boundary_id(
    planning_chain_id: str,
    execution_package_id: str,
    execution_review_id: str,
    gate_stack_preview_id: str,
    preflight_checklist_id: str,
    approval_checklist_id: str,
    target_branch_name: str,
) -> str:
    return _execution_readiness_id("workspace-creator-boundary", {
        "approval_checklist_id": approval_checklist_id,
        "execution_package_id": execution_package_id,
        "execution_review_id": execution_review_id,
        "gate_stack_preview_id": gate_stack_preview_id,
        "planning_chain_id": planning_chain_id,
        "preflight_checklist_id": preflight_checklist_id,
        "target_branch_name": target_branch_name,
        "version": WORKSPACE_CREATOR_RUNTIME_BOUNDARY_VERSION,
    })


def _workspace_boundary_check_messages(preflight: dict[str, Any]) -> tuple[list[str], list[str], list[str]]:
    groups = (
        "required_human_approvals",
        "clean_tree_checks",
        "path_safety_checks",
        "command_allowlist_checks",
        "branch_worktree_isolation_checks",
        "evidence_contract_checks",
    )
    checks = [check for group in groups for check in preflight[group]]
    all_messages = _normalize_patch_behavior_text_list([
        f"{check['category']}: {check['name']} - {check['requirement']} ({check['status']})"
        for check in checks
    ])
    blockers = _normalize_patch_behavior_text_list([
        f"{check['category']}: {check['name']} - {check['requirement']}"
        for check in checks
        if check["status"] == "block"
    ])
    warnings = _normalize_patch_behavior_text_list([
        f"{check['category']}: {check['name']} - {check['requirement']}"
        for check in checks
        if check["status"] == "warning"
    ])
    return all_messages, blockers, warnings


def collect_workspace_creator_runtime_boundary(
    planning_chain: dict[str, Any] | None = None,
    *,
    execution_review: dict[str, Any] | None = None,
    execution_gate_stack_preview: dict[str, Any] | None = None,
    execution_preflight_checklist: dict[str, Any] | None = None,
    execution_approval_checklist: dict[str, Any] | None = None,
    execution_attempt_history: dict[str, Any] | None = None,
    execution_evidence_contract: dict[str, Any] | None = None,
    metadata: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Describe the future workspace creation boundary without creating anything."""
    chain = planning_chain if planning_chain is not None else collect_growth_planning_chain_preview()
    validate_growth_planning_chain_preview(chain)
    review = execution_review if execution_review is not None else collect_execution_review(chain)
    gate_stack = execution_gate_stack_preview if execution_gate_stack_preview is not None else chain["execution_gate_stack_preview"]
    preflight = execution_preflight_checklist if execution_preflight_checklist is not None else chain["execution_preflight_checklist"]
    approval = execution_approval_checklist if execution_approval_checklist is not None else collect_execution_approval_checklist(chain)
    attempts = execution_attempt_history if execution_attempt_history is not None else chain["execution_attempt_history"]
    evidence_contract = execution_evidence_contract if execution_evidence_contract is not None else chain["execution_evidence_contract"]
    validate_execution_review(review, chain)
    validate_execution_gate_stack_preview(gate_stack, chain)
    validate_execution_preflight_checklist(preflight, chain)
    validate_execution_approval_checklist(approval, chain)
    validate_execution_attempt_history(
        attempts,
        chain["execution_journal_plan"],
        chain["execution_retry_policy"],
        chain["autonomous_execution_package"],
    )
    validate_execution_evidence_contract(evidence_contract, chain["execution_journal_plan"])

    workspace = chain["execution_workspace_plan"]
    branch_plan = chain["implementation_branch_plan"]
    pre_creation_checks, preflight_blockers, preflight_warnings = _workspace_boundary_check_messages(preflight)
    review_blockers = review["blocker_summary"]["top_blockers"]
    review_warnings = review["warning_summary"]["top_warnings"]
    blocker_count = len(_normalize_patch_behavior_text_list([*preflight_blockers, *review_blockers]))
    warning_count = len(_normalize_patch_behavior_text_list([*preflight_warnings, *review_warnings]))
    boundary_status = "block" if blocker_count else ("review" if warning_count else "pass")
    if boundary_status == "block":
        next_action = "Resolve workspace boundary blockers before creating any directory, branch, worktree, patch, or verification run."
    elif boundary_status == "review":
        next_action = "Review workspace boundary warnings and required approvals before enabling workspace creation."
    else:
        next_action = "Workspace creator boundary is clear for human review; workspace creation remains disabled until explicitly approved."
    allowed_operations = _normalize_patch_behavior_text_list([
        "collect read-only planning chain payload",
        "preview deterministic workspace path policy",
        "review human approval requirements",
        "validate evidence contract requirements",
        "validate path and isolation rules",
    ])
    forbidden_operations = _normalize_patch_behavior_text_list([
        "apply patches",
        "create branches",
        "create directories",
        "create git worktrees",
        "execute verification commands",
        "modify runtime state",
        "run subprocesses",
    ])
    boundary = {
        "workspace_boundary_version": WORKSPACE_CREATOR_RUNTIME_BOUNDARY_VERSION,
        "workspace_boundary_id": make_workspace_creator_runtime_boundary_id(
            chain["planning_chain_id"],
            chain["autonomous_execution_package"]["execution_package_id"],
            review["execution_review_id"],
            gate_stack["gate_stack_preview_id"],
            preflight["preflight_checklist_id"],
            approval["approval_checklist_id"],
            workspace["proposed_branch_name"],
        ),
        "planning_chain_id": chain["planning_chain_id"],
        "execution_package_id": chain["autonomous_execution_package"]["execution_package_id"],
        "branch_plan_id": branch_plan["branch_plan_id"],
        "execution_review_id": review["execution_review_id"],
        "gate_stack_preview_id": gate_stack["gate_stack_preview_id"],
        "preflight_checklist_id": preflight["preflight_checklist_id"],
        "approval_checklist_id": approval["approval_checklist_id"],
        "attempt_history_id": attempts["attempt_history_id"],
        "execution_evidence_contract_id": evidence_contract["execution_evidence_contract_id"],
        "target_branch_name": workspace["proposed_branch_name"],
        "workspace_root_policy": "future workspaces must live under the reviewed repo .link/worktrees path and this helper must not create them",
        "worktree_name_policy": "derive the worktree name deterministically from the reviewed execution workspace plan id",
        "isolation_rules": _normalize_patch_behavior_text_list([
            "branch creation remains disabled until explicit human approval",
            "patch application must happen only inside the approved isolated workspace",
            "target files must stay inside the repository and outside research/runtime state",
            "verification commands must be allowlisted before execution",
            "worktree creation remains disabled until explicit human approval",
        ]),
        "pre_creation_checks": pre_creation_checks,
        "cleanup_policy": workspace["cleanup_policy"],
        "rollback_policy": workspace["rollback_policy"],
        "required_approvals": approval["required_approvals"],
        "required_evidence": _normalize_implementation_branch_refs([
            item["evidence_type"] for item in evidence_contract["evidence_items"]
        ]),
        "allowed_operations": allowed_operations,
        "forbidden_operations": forbidden_operations,
        "boundary_status": boundary_status,
        "blocker_count": blocker_count,
        "warning_count": warning_count,
        "recommended_next_action": next_action,
        "dry_run": True,
        "write_allowed": False,
        "automation_allowed": False,
        "metadata": dict(metadata or {}),
        "writes": [],
    }
    validate_workspace_creator_runtime_boundary(boundary, chain)
    return boundary


def validate_workspace_creator_runtime_boundary(
    boundary: dict[str, Any],
    planning_chain: dict[str, Any] | None = None,
) -> None:
    required = (
        "workspace_boundary_version", "workspace_boundary_id", "planning_chain_id",
        "execution_package_id", "branch_plan_id", "execution_review_id",
        "gate_stack_preview_id", "preflight_checklist_id", "approval_checklist_id",
        "attempt_history_id", "execution_evidence_contract_id", "target_branch_name",
        "workspace_root_policy", "worktree_name_policy", "isolation_rules",
        "pre_creation_checks", "cleanup_policy", "rollback_policy", "required_approvals",
        "required_evidence", "allowed_operations", "forbidden_operations",
        "boundary_status", "blocker_count", "warning_count", "recommended_next_action",
        "dry_run", "write_allowed", "automation_allowed", "metadata", "writes",
    )
    missing = [field for field in required if field not in boundary]
    if missing:
        raise ValueError(f"workspace creator runtime boundary missing fields: {missing}")
    if boundary["workspace_boundary_version"] != WORKSPACE_CREATOR_RUNTIME_BOUNDARY_VERSION:
        raise ValueError("unsupported workspace creator runtime boundary version")
    _validate_execution_read_only(boundary, "workspace creator runtime boundary")
    for field in (
        "workspace_boundary_id", "planning_chain_id", "execution_package_id",
        "branch_plan_id", "execution_review_id", "gate_stack_preview_id",
        "preflight_checklist_id", "approval_checklist_id", "attempt_history_id",
        "execution_evidence_contract_id", "target_branch_name", "workspace_root_policy",
        "worktree_name_policy", "cleanup_policy", "rollback_policy", "boundary_status",
        "recommended_next_action",
    ):
        _validate_non_empty_string(boundary[field], field)
    if boundary["boundary_status"] not in {"pass", "review", "block"}:
        raise ValueError("invalid workspace boundary status")
    for field in ("blocker_count", "warning_count"):
        if not isinstance(boundary[field], int) or boundary[field] < 0:
            raise ValueError(f"{field} must be a non-negative integer")
    for field in (
        "isolation_rules", "pre_creation_checks", "required_approvals",
        "required_evidence", "allowed_operations", "forbidden_operations",
    ):
        values = boundary[field]
        if not isinstance(values, list) or not values:
            raise TypeError(f"{field} must be a non-empty list")
        expected = _normalize_implementation_branch_refs(values) if field == "required_evidence" else _normalize_patch_behavior_text_list(values)
        if values != expected:
            raise ValueError(f"{field} must be normalized and sorted")
    forbidden_set = set(boundary["forbidden_operations"])
    if set(boundary["allowed_operations"]) & forbidden_set:
        raise ValueError("allowed operations must not overlap forbidden operations")
    required_forbidden = {
        "apply patches",
        "create branches",
        "create directories",
        "create git worktrees",
        "execute verification commands",
        "modify runtime state",
        "run subprocesses",
    }
    if not required_forbidden.issubset(forbidden_set):
        raise ValueError("workspace boundary missing required forbidden operations")
    if boundary["blocker_count"] and boundary["boundary_status"] != "block":
        raise ValueError("workspace boundary blockers must produce block status")
    if not boundary["blocker_count"] and boundary["warning_count"] and boundary["boundary_status"] != "review":
        raise ValueError("workspace boundary warnings must produce review status")
    expected_id = make_workspace_creator_runtime_boundary_id(
        boundary["planning_chain_id"],
        boundary["execution_package_id"],
        boundary["execution_review_id"],
        boundary["gate_stack_preview_id"],
        boundary["preflight_checklist_id"],
        boundary["approval_checklist_id"],
        boundary["target_branch_name"],
    )
    if boundary["workspace_boundary_id"] != expected_id:
        raise ValueError("workspace creator runtime boundary id does not match contents")
    if planning_chain is not None:
        validate_growth_planning_chain_preview(planning_chain)
        review = collect_execution_review(planning_chain)
        approval = collect_execution_approval_checklist(planning_chain)
        expected_refs = {
            "planning_chain_id": planning_chain["planning_chain_id"],
            "execution_package_id": planning_chain["autonomous_execution_package"]["execution_package_id"],
            "branch_plan_id": planning_chain["implementation_branch_plan"]["branch_plan_id"],
            "execution_review_id": review["execution_review_id"],
            "gate_stack_preview_id": planning_chain["execution_gate_stack_preview"]["gate_stack_preview_id"],
            "preflight_checklist_id": planning_chain["execution_preflight_checklist"]["preflight_checklist_id"],
            "approval_checklist_id": approval["approval_checklist_id"],
            "attempt_history_id": planning_chain["execution_attempt_history"]["attempt_history_id"],
            "execution_evidence_contract_id": planning_chain["execution_evidence_contract"]["execution_evidence_contract_id"],
            "target_branch_name": planning_chain["execution_workspace_plan"]["proposed_branch_name"],
        }
        for field, value in expected_refs.items():
            if boundary[field] != value:
                raise ValueError(f"workspace creator runtime boundary {field} does not match planning chain")
        if boundary["required_approvals"] != approval["required_approvals"]:
            raise ValueError("workspace boundary required approvals do not match approval checklist")


def stable_workspace_creator_runtime_boundary_json(boundary: dict[str, Any]) -> str:
    validate_workspace_creator_runtime_boundary(boundary)
    return _stable_ruflo_json(boundary, indent=2) + "\n"


def parse_workspace_creator_runtime_boundary_json(text: str) -> dict[str, Any]:
    import json as _json

    boundary = _json.loads(text)
    validate_workspace_creator_runtime_boundary(boundary)
    return boundary


WORKSPACE_CREATOR_RUNTIME_PLAN_VERSION = "link-workspace-creator-runtime-plan-v1"


def make_workspace_creator_runtime_plan_id(
    planning_chain_id: str,
    execution_package_id: str,
    workspace_boundary_id: str,
    execution_review_id: str,
    gate_stack_preview_id: str,
    approval_checklist_id: str,
    preflight_checklist_id: str,
    branch_name: str,
) -> str:
    return _execution_readiness_id("workspace-creator-runtime-plan", {
        "approval_checklist_id": approval_checklist_id,
        "branch_name": branch_name,
        "execution_package_id": execution_package_id,
        "execution_review_id": execution_review_id,
        "gate_stack_preview_id": gate_stack_preview_id,
        "planning_chain_id": planning_chain_id,
        "preflight_checklist_id": preflight_checklist_id,
        "version": WORKSPACE_CREATOR_RUNTIME_PLAN_VERSION,
        "workspace_boundary_id": workspace_boundary_id,
    })


def _workspace_runtime_gate_requirements(gate_stack: dict[str, Any]) -> list[str]:
    return _normalize_patch_behavior_text_list([
        f"{gate['gate_type']}: {gate['gate_name']} must be {gate['pass_status']} before workspace creation"
        for gate in gate_stack["gates"]
    ])


def _workspace_runtime_clean_tree_requirements(preflight: dict[str, Any]) -> list[str]:
    return _normalize_patch_behavior_text_list([
        f"{check['name']}: {check['requirement']} ({check['status']})"
        for check in preflight["clean_tree_checks"]
    ])


def _workspace_runtime_command_allowlist_requirements(preflight: dict[str, Any]) -> list[str]:
    return _normalize_patch_behavior_text_list([
        f"{check['name']}: {check['requirement']} ({check['status']})"
        for check in preflight["command_allowlist_checks"]
    ])


def collect_workspace_creator_runtime_plan(
    planning_chain: dict[str, Any] | None = None,
    *,
    workspace_creator_runtime_boundary: dict[str, Any] | None = None,
    execution_review: dict[str, Any] | None = None,
    execution_gate_stack_preview: dict[str, Any] | None = None,
    execution_approval_checklist: dict[str, Any] | None = None,
    execution_preflight_checklist: dict[str, Any] | None = None,
    metadata: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Return the disabled runtime specification for future workspace creation."""
    chain = planning_chain if planning_chain is not None else collect_growth_planning_chain_preview()
    validate_growth_planning_chain_preview(chain)
    boundary = workspace_creator_runtime_boundary if workspace_creator_runtime_boundary is not None else collect_workspace_creator_runtime_boundary(chain)
    review = execution_review if execution_review is not None else collect_execution_review(chain)
    gate_stack = execution_gate_stack_preview if execution_gate_stack_preview is not None else chain["execution_gate_stack_preview"]
    approval = execution_approval_checklist if execution_approval_checklist is not None else collect_execution_approval_checklist(chain)
    preflight = execution_preflight_checklist if execution_preflight_checklist is not None else chain["execution_preflight_checklist"]
    validate_workspace_creator_runtime_boundary(boundary, chain)
    validate_execution_review(review, chain)
    validate_execution_gate_stack_preview(gate_stack, chain)
    validate_execution_approval_checklist(approval, chain)
    validate_execution_preflight_checklist(preflight, chain)

    branch_name = boundary["target_branch_name"]
    workspace_name = f"workspace-{boundary['workspace_boundary_id'].split('-')[-1]}"
    gate_requirements = _workspace_runtime_gate_requirements(gate_stack)
    clean_tree_requirements = _workspace_runtime_clean_tree_requirements(preflight)
    command_allowlist_requirements = _workspace_runtime_command_allowlist_requirements(preflight)
    evidence_requirements = boundary["required_evidence"]
    approval_requirements = boundary["required_approvals"]
    allowed_runtime_actions = _normalize_patch_behavior_text_list([
        "derive deterministic workspace name",
        "prepare disabled runtime contract",
        "validate approval requirements",
        "validate gate requirements",
        "validate read-only boundary inputs",
    ])
    forbidden_runtime_actions = _normalize_patch_behavior_text_list([
        "apply patches",
        "create branches",
        "create directories",
        "create git worktrees",
        "execute verification commands",
        "modify runtime state",
        "run subprocesses",
    ])
    failure_states = _normalize_patch_behavior_text_list([
        "approval missing",
        "boundary blocked",
        "clean tree check failed",
        "command allowlist missing",
        "evidence contract incomplete",
        "gate stack blocked",
        "path isolation failed",
    ])
    rollback_triggers = _normalize_patch_behavior_text_list([
        "branch or worktree creation attempted outside approved runtime",
        "evidence contract cannot be satisfied",
        "pre-creation checks report block status",
        "workspace path would escape repository policy",
    ])
    cleanup_triggers = _normalize_patch_behavior_text_list([
        "future workspace creation aborts before patch application",
        "future workspace verification fails before review bundle creation",
        "human approval is revoked before runtime execution",
    ])
    escalation_requirements = _normalize_patch_behavior_text_list([
        "Brandon approval is required before enabling any workspace creation action",
        "blocked gate stack requires human review before runtime execution",
        "missing evidence requirements require review before runtime execution",
    ])
    expected_outputs = _normalize_patch_behavior_text_list([
        "approved workspace path plan",
        "isolated branch or worktree identifier once future execution is explicitly enabled",
        "workspace creation evidence refs once future execution is explicitly enabled",
    ])
    plan_status = "block" if boundary["boundary_status"] == "block" else ("review" if boundary["boundary_status"] == "review" else "pass")
    if plan_status == "block":
        next_action = "Resolve runtime workspace plan blockers before enabling any workspace creation component."
    elif plan_status == "review":
        next_action = "Review runtime workspace plan warnings and approval requirements before enabling workspace creation."
    else:
        next_action = "Runtime workspace plan is ready for human review; execution remains disabled until explicitly approved."

    plan = {
        "workspace_creator_runtime_plan_version": WORKSPACE_CREATOR_RUNTIME_PLAN_VERSION,
        "runtime_workspace_plan_id": make_workspace_creator_runtime_plan_id(
            chain["planning_chain_id"],
            boundary["execution_package_id"],
            boundary["workspace_boundary_id"],
            review["execution_review_id"],
            gate_stack["gate_stack_preview_id"],
            approval["approval_checklist_id"],
            preflight["preflight_checklist_id"],
            branch_name,
        ),
        "planning_chain_id": chain["planning_chain_id"],
        "execution_package_id": boundary["execution_package_id"],
        "workspace_boundary_id": boundary["workspace_boundary_id"],
        "execution_review_id": review["execution_review_id"],
        "gate_stack_preview_id": gate_stack["gate_stack_preview_id"],
        "approval_checklist_id": approval["approval_checklist_id"],
        "preflight_checklist_id": preflight["preflight_checklist_id"],
        "workspace_root": ".link/worktrees",
        "workspace_name": workspace_name,
        "branch_name": branch_name,
        "workspace_type": "git_worktree_planned",
        "isolation_mode": "disabled_until_explicit_human_approval",
        "cleanup_policy": boundary["cleanup_policy"],
        "rollback_policy": boundary["rollback_policy"],
        "approval_requirements": approval_requirements,
        "gate_requirements": gate_requirements,
        "evidence_requirements": evidence_requirements,
        "clean_tree_requirements": clean_tree_requirements,
        "command_allowlist_requirements": command_allowlist_requirements,
        "failure_states": failure_states,
        "rollback_triggers": rollback_triggers,
        "cleanup_triggers": cleanup_triggers,
        "escalation_requirements": escalation_requirements,
        "allowed_runtime_actions": allowed_runtime_actions,
        "forbidden_runtime_actions": forbidden_runtime_actions,
        "expected_outputs": expected_outputs,
        "required_evidence": evidence_requirements,
        "plan_status": plan_status,
        "recommended_next_action": next_action,
        "dry_run": True,
        "write_allowed": False,
        "automation_allowed": False,
        "metadata": dict(metadata or {}),
        "writes": [],
    }
    validate_workspace_creator_runtime_plan(plan, boundary, review, gate_stack, approval, preflight)
    return plan


def validate_workspace_creator_runtime_plan(
    plan: dict[str, Any],
    workspace_creator_runtime_boundary: dict[str, Any] | None = None,
    execution_review: dict[str, Any] | None = None,
    execution_gate_stack_preview: dict[str, Any] | None = None,
    execution_approval_checklist: dict[str, Any] | None = None,
    execution_preflight_checklist: dict[str, Any] | None = None,
) -> None:
    required = (
        "workspace_creator_runtime_plan_version", "runtime_workspace_plan_id",
        "planning_chain_id", "execution_package_id", "workspace_boundary_id",
        "execution_review_id", "gate_stack_preview_id", "approval_checklist_id",
        "preflight_checklist_id", "workspace_root", "workspace_name", "branch_name",
        "workspace_type", "isolation_mode", "cleanup_policy", "rollback_policy",
        "approval_requirements", "gate_requirements", "evidence_requirements",
        "clean_tree_requirements", "command_allowlist_requirements", "failure_states",
        "rollback_triggers", "cleanup_triggers", "escalation_requirements",
        "allowed_runtime_actions", "forbidden_runtime_actions", "expected_outputs",
        "required_evidence", "plan_status", "recommended_next_action", "dry_run",
        "write_allowed", "automation_allowed", "metadata", "writes",
    )
    missing = [field for field in required if field not in plan]
    if missing:
        raise ValueError(f"workspace creator runtime plan missing fields: {missing}")
    if plan["workspace_creator_runtime_plan_version"] != WORKSPACE_CREATOR_RUNTIME_PLAN_VERSION:
        raise ValueError("unsupported workspace creator runtime plan version")
    _validate_execution_read_only(plan, "workspace creator runtime plan")
    for field in (
        "runtime_workspace_plan_id", "planning_chain_id", "execution_package_id",
        "workspace_boundary_id", "execution_review_id", "gate_stack_preview_id",
        "approval_checklist_id", "preflight_checklist_id", "workspace_root",
        "workspace_name", "branch_name", "workspace_type", "isolation_mode",
        "cleanup_policy", "rollback_policy", "plan_status", "recommended_next_action",
    ):
        _validate_non_empty_string(plan[field], field)
    if plan["workspace_root"] != ".link/worktrees":
        raise ValueError("workspace root must use the reviewed .link/worktrees policy")
    if plan["workspace_type"] != "git_worktree_planned":
        raise ValueError("workspace type must remain planned only")
    if plan["isolation_mode"] != "disabled_until_explicit_human_approval":
        raise ValueError("workspace isolation mode must remain approval-gated")
    if plan["plan_status"] not in {"pass", "review", "block"}:
        raise ValueError("invalid workspace creator runtime plan status")
    for field in (
        "approval_requirements", "gate_requirements", "evidence_requirements",
        "clean_tree_requirements", "command_allowlist_requirements", "failure_states",
        "rollback_triggers", "cleanup_triggers", "escalation_requirements",
        "allowed_runtime_actions", "forbidden_runtime_actions", "expected_outputs",
        "required_evidence",
    ):
        values = plan[field]
        if not isinstance(values, list) or not values:
            raise TypeError(f"{field} must be a non-empty list")
        expected = _normalize_implementation_branch_refs(values) if field in {"evidence_requirements", "required_evidence"} else _normalize_patch_behavior_text_list(values)
        if values != expected:
            raise ValueError(f"{field} must be normalized and sorted")
    if plan["evidence_requirements"] != plan["required_evidence"]:
        raise ValueError("runtime plan evidence requirements must match required evidence")
    forbidden_set = set(plan["forbidden_runtime_actions"])
    if set(plan["allowed_runtime_actions"]) & forbidden_set:
        raise ValueError("allowed runtime actions must not overlap forbidden runtime actions")
    required_forbidden = {
        "apply patches",
        "create branches",
        "create directories",
        "create git worktrees",
        "execute verification commands",
        "modify runtime state",
        "run subprocesses",
    }
    if not required_forbidden.issubset(forbidden_set):
        raise ValueError("workspace creator runtime plan missing required forbidden actions")
    expected_id = make_workspace_creator_runtime_plan_id(
        plan["planning_chain_id"],
        plan["execution_package_id"],
        plan["workspace_boundary_id"],
        plan["execution_review_id"],
        plan["gate_stack_preview_id"],
        plan["approval_checklist_id"],
        plan["preflight_checklist_id"],
        plan["branch_name"],
    )
    if plan["runtime_workspace_plan_id"] != expected_id:
        raise ValueError("workspace creator runtime plan id does not match contents")
    if workspace_creator_runtime_boundary is not None:
        validate_workspace_creator_runtime_boundary(workspace_creator_runtime_boundary)
        expected_refs = {
            "planning_chain_id": workspace_creator_runtime_boundary["planning_chain_id"],
            "execution_package_id": workspace_creator_runtime_boundary["execution_package_id"],
            "workspace_boundary_id": workspace_creator_runtime_boundary["workspace_boundary_id"],
            "branch_name": workspace_creator_runtime_boundary["target_branch_name"],
            "cleanup_policy": workspace_creator_runtime_boundary["cleanup_policy"],
            "rollback_policy": workspace_creator_runtime_boundary["rollback_policy"],
        }
        for field, value in expected_refs.items():
            if plan[field] != value:
                raise ValueError(f"workspace creator runtime plan {field} does not match boundary")
        if plan["approval_requirements"] != workspace_creator_runtime_boundary["required_approvals"]:
            raise ValueError("workspace creator runtime plan approval requirements do not match boundary")
        if plan["evidence_requirements"] != workspace_creator_runtime_boundary["required_evidence"]:
            raise ValueError("workspace creator runtime plan evidence requirements do not match boundary")
        if plan["plan_status"] != workspace_creator_runtime_boundary["boundary_status"]:
            raise ValueError("workspace creator runtime plan status does not match boundary")
    if execution_review is not None:
        validate_execution_review(execution_review)
        if plan["execution_review_id"] != execution_review["execution_review_id"]:
            raise ValueError("workspace creator runtime plan execution review id mismatch")
    if execution_gate_stack_preview is not None:
        validate_execution_gate_stack_preview(execution_gate_stack_preview)
        if plan["gate_stack_preview_id"] != execution_gate_stack_preview["gate_stack_preview_id"]:
            raise ValueError("workspace creator runtime plan gate stack id mismatch")
    if execution_approval_checklist is not None:
        validate_execution_approval_checklist(execution_approval_checklist)
        if plan["approval_checklist_id"] != execution_approval_checklist["approval_checklist_id"]:
            raise ValueError("workspace creator runtime plan approval checklist id mismatch")
    if execution_preflight_checklist is not None:
        validate_execution_preflight_checklist(execution_preflight_checklist)
        if plan["preflight_checklist_id"] != execution_preflight_checklist["preflight_checklist_id"]:
            raise ValueError("workspace creator runtime plan preflight checklist id mismatch")


def stable_workspace_creator_runtime_plan_json(plan: dict[str, Any]) -> str:
    validate_workspace_creator_runtime_plan(plan)
    return _stable_ruflo_json(plan, indent=2) + "\n"


def parse_workspace_creator_runtime_plan_json(text: str) -> dict[str, Any]:
    import json as _json

    plan = _json.loads(text)
    validate_workspace_creator_runtime_plan(plan)
    return plan


GUARDED_WORKSPACE_CREATOR_VERSION = "link-guarded-workspace-creator-v1"
WORKSPACE_CREATION_RECEIPT_VERSION = "link-workspace-creation-receipt-v1"


def make_guarded_workspace_request_id(
    runtime_workspace_plan_id: str,
    workspace_boundary_id: str,
    execution_review_id: str,
    approval_checklist_id: str,
    workspace_root: str,
    workspace_name: str,
    approved: bool,
    write: bool,
) -> str:
    return _execution_readiness_id("guarded-workspace-request", {
        "approval_checklist_id": approval_checklist_id,
        "approved": approved,
        "execution_review_id": execution_review_id,
        "runtime_workspace_plan_id": runtime_workspace_plan_id,
        "version": GUARDED_WORKSPACE_CREATOR_VERSION,
        "workspace_boundary_id": workspace_boundary_id,
        "workspace_name": workspace_name,
        "workspace_root": workspace_root,
        "write": write,
    })


def make_workspace_creation_receipt_id(
    request_id: str,
    runtime_workspace_plan_id: str,
    workspace_id: str,
    manifest_hash: str,
) -> str:
    return _execution_readiness_id("workspace-creation-receipt", {
        "manifest_hash": manifest_hash,
        "request_id": request_id,
        "runtime_workspace_plan_id": runtime_workspace_plan_id,
        "version": WORKSPACE_CREATION_RECEIPT_VERSION,
        "workspace_id": workspace_id,
    })


def make_guarded_workspace_request(
    workspace_runtime_plan: dict[str, Any],
    *,
    approved: bool = False,
    write: bool = False,
    workspace_root: str | None = None,
    metadata: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Build a guarded workspace creation request without touching the filesystem."""
    validate_workspace_creator_runtime_plan(workspace_runtime_plan)
    root = workspace_root or workspace_runtime_plan["workspace_root"]
    name = workspace_runtime_plan["workspace_name"]
    request = {
        "guarded_workspace_creator_version": GUARDED_WORKSPACE_CREATOR_VERSION,
        "request_id": make_guarded_workspace_request_id(
            workspace_runtime_plan["runtime_workspace_plan_id"],
            workspace_runtime_plan["workspace_boundary_id"],
            workspace_runtime_plan["execution_review_id"],
            workspace_runtime_plan["approval_checklist_id"],
            root,
            name,
            approved,
            write,
        ),
        "runtime_workspace_plan_id": workspace_runtime_plan["runtime_workspace_plan_id"],
        "planning_chain_id": workspace_runtime_plan["planning_chain_id"],
        "execution_package_id": workspace_runtime_plan["execution_package_id"],
        "workspace_boundary_id": workspace_runtime_plan["workspace_boundary_id"],
        "execution_review_id": workspace_runtime_plan["execution_review_id"],
        "gate_stack_preview_id": workspace_runtime_plan["gate_stack_preview_id"],
        "approval_checklist_id": workspace_runtime_plan["approval_checklist_id"],
        "preflight_checklist_id": workspace_runtime_plan["preflight_checklist_id"],
        "workspace_root": root,
        "workspace_name": name,
        "branch_name": workspace_runtime_plan["branch_name"],
        "approved": approved,
        "write": write,
        "required_approval_state": "explicit_approved_flag_and_passing_checklists",
        "dry_run": not write,
        "metadata": dict(metadata or {}),
    }
    validate_guarded_workspace_request(request, workspace_runtime_plan)
    return request


def _guarded_workspace_path(root: str, name: str):
    from pathlib import Path

    root_path = Path(root).expanduser()
    workspace_path = root_path / name
    resolved_root = root_path.resolve(strict=False)
    resolved_workspace = workspace_path.resolve(strict=False)
    try:
        resolved_workspace.relative_to(resolved_root)
    except ValueError as exc:
        raise ValueError("workspace path must stay under workspace root") from exc
    return root_path, workspace_path


def validate_guarded_workspace_request(
    request: dict[str, Any],
    workspace_runtime_plan: dict[str, Any] | None = None,
    execution_review: dict[str, Any] | None = None,
    execution_gate_stack_preview: dict[str, Any] | None = None,
    execution_approval_checklist: dict[str, Any] | None = None,
    execution_preflight_checklist: dict[str, Any] | None = None,
) -> None:
    required = (
        "guarded_workspace_creator_version", "request_id", "runtime_workspace_plan_id",
        "planning_chain_id", "execution_package_id", "workspace_boundary_id",
        "execution_review_id", "gate_stack_preview_id", "approval_checklist_id",
        "preflight_checklist_id", "workspace_root", "workspace_name", "branch_name",
        "approved", "write", "required_approval_state", "dry_run", "metadata",
    )
    missing = [field for field in required if field not in request]
    if missing:
        raise ValueError(f"guarded workspace request missing fields: {missing}")
    if request["guarded_workspace_creator_version"] != GUARDED_WORKSPACE_CREATOR_VERSION:
        raise ValueError("unsupported guarded workspace creator version")
    for field in (
        "request_id", "runtime_workspace_plan_id", "planning_chain_id", "execution_package_id",
        "workspace_boundary_id", "execution_review_id", "gate_stack_preview_id",
        "approval_checklist_id", "preflight_checklist_id", "workspace_root", "workspace_name",
        "branch_name", "required_approval_state",
    ):
        _validate_non_empty_string(request[field], field)
    if not isinstance(request["approved"], bool) or not isinstance(request["write"], bool):
        raise TypeError("approved and write must be booleans")
    if request["dry_run"] != (not request["write"]):
        raise ValueError("guarded workspace request dry_run must invert write")
    if not isinstance(request["metadata"], dict):
        raise TypeError("metadata must be a dict")
    if ".." in request["workspace_name"] or "/" in request["workspace_name"] or "\\" in request["workspace_name"]:
        raise ValueError("workspace_name must be a simple directory name")
    _guarded_workspace_path(request["workspace_root"], request["workspace_name"])
    expected_id = make_guarded_workspace_request_id(
        request["runtime_workspace_plan_id"],
        request["workspace_boundary_id"],
        request["execution_review_id"],
        request["approval_checklist_id"],
        request["workspace_root"],
        request["workspace_name"],
        request["approved"],
        request["write"],
    )
    if request["request_id"] != expected_id:
        raise ValueError("guarded workspace request id does not match contents")
    if request["write"] and not request["approved"]:
        raise PermissionError("guarded workspace creation requires explicit approval")
    if workspace_runtime_plan is not None:
        validate_workspace_creator_runtime_plan(workspace_runtime_plan)
        expected_refs = {
            "runtime_workspace_plan_id": workspace_runtime_plan["runtime_workspace_plan_id"],
            "planning_chain_id": workspace_runtime_plan["planning_chain_id"],
            "execution_package_id": workspace_runtime_plan["execution_package_id"],
            "workspace_boundary_id": workspace_runtime_plan["workspace_boundary_id"],
            "execution_review_id": workspace_runtime_plan["execution_review_id"],
            "gate_stack_preview_id": workspace_runtime_plan["gate_stack_preview_id"],
            "approval_checklist_id": workspace_runtime_plan["approval_checklist_id"],
            "preflight_checklist_id": workspace_runtime_plan["preflight_checklist_id"],
            "branch_name": workspace_runtime_plan["branch_name"],
        }
        for field, value in expected_refs.items():
            if request[field] != value:
                raise ValueError(f"guarded workspace request {field} does not match runtime plan")
        if workspace_runtime_plan["plan_status"] == "block" and request["write"]:
            raise PermissionError("guarded workspace creation blocked by runtime plan")
    if execution_review is not None:
        validate_execution_review(execution_review)
        if request["execution_review_id"] != execution_review["execution_review_id"]:
            raise ValueError("guarded workspace request execution review mismatch")
        if execution_review["approval_summary"]["approval_status"] != "pass" and request["write"]:
            raise PermissionError("guarded workspace creation requires passing approval summary")
    if execution_gate_stack_preview is not None:
        validate_execution_gate_stack_preview(execution_gate_stack_preview)
        if request["gate_stack_preview_id"] != execution_gate_stack_preview["gate_stack_preview_id"]:
            raise ValueError("guarded workspace request gate stack mismatch")
        if execution_gate_stack_preview["block_count"] and request["write"]:
            raise PermissionError("guarded workspace creation blocked by gate stack")
    if execution_approval_checklist is not None:
        validate_execution_approval_checklist(execution_approval_checklist)
        if request["approval_checklist_id"] != execution_approval_checklist["approval_checklist_id"]:
            raise ValueError("guarded workspace request approval checklist mismatch")
        if execution_approval_checklist["approval_status"] != "pass" and request["write"]:
            raise PermissionError("guarded workspace creation requires passing approval checklist")
    if execution_preflight_checklist is not None:
        validate_execution_preflight_checklist(execution_preflight_checklist)
        if request["preflight_checklist_id"] != execution_preflight_checklist["preflight_checklist_id"]:
            raise ValueError("guarded workspace request preflight checklist mismatch")
        if execution_preflight_checklist["pass_status"] != "pass" and request["write"]:
            raise PermissionError("guarded workspace creation requires passing preflight checklist")


def _workspace_hash(path: str) -> str:
    import hashlib
    from pathlib import Path

    root = Path(path)
    entries: list[str] = []
    if root.exists():
        for child in sorted(root.rglob("*")):
            if child.is_file():
                rel = child.relative_to(root).as_posix()
                entries.append(f"{rel}:{hashlib.sha256(child.read_bytes()).hexdigest()}")
            elif child.is_dir():
                entries.append(f"{child.relative_to(root).as_posix()}/")
    return hashlib.sha256("\n".join(entries).encode("utf-8")).hexdigest()


def collect_workspace_creation_receipt(
    request: dict[str, Any],
    *,
    workspace_id: str,
    workspace_path: str,
    workspace_manifest: dict[str, Any],
    creation_timestamp: str,
    manifest_hash: str,
    workspace_hash: str,
    status: str = "created",
    metadata: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Build a workspace creation receipt from already-collected evidence."""
    validate_guarded_workspace_request(request)
    receipt = {
        "workspace_creation_receipt_version": WORKSPACE_CREATION_RECEIPT_VERSION,
        "creation_receipt_id": make_workspace_creation_receipt_id(
            request["request_id"],
            request["runtime_workspace_plan_id"],
            workspace_id,
            manifest_hash,
        ),
        "request_id": request["request_id"],
        "runtime_workspace_plan_id": request["runtime_workspace_plan_id"],
        "planning_chain_id": request["planning_chain_id"],
        "execution_package_id": request["execution_package_id"],
        "workspace_boundary_id": request["workspace_boundary_id"],
        "execution_review_id": request["execution_review_id"],
        "gate_stack_preview_id": request["gate_stack_preview_id"],
        "approval_checklist_id": request["approval_checklist_id"],
        "preflight_checklist_id": request["preflight_checklist_id"],
        "workspace_id": workspace_id,
        "workspace_path": workspace_path,
        "creation_timestamp": creation_timestamp,
        "workspace_manifest": workspace_manifest,
        "manifest_hash": manifest_hash,
        "workspace_hash": workspace_hash,
        "status": status,
        "allowed_actions_performed": _normalize_patch_behavior_text_list([
            "create metadata manifest",
            "create temporary workspace directory",
            "create workspace receipt",
        ]),
        "forbidden_actions_avoided": _normalize_patch_behavior_text_list([
            "apply patches",
            "create commits",
            "create git branches",
            "execute verification commands",
            "merge changes",
            "modify repository files",
            "modify repository working tree",
            "run network commands",
        ]),
        "metadata": dict(metadata or {}),
    }
    validate_workspace_creation_receipt(receipt, request)
    return receipt


def validate_workspace_creation_receipt(
    receipt: dict[str, Any],
    request: dict[str, Any] | None = None,
) -> None:
    required = (
        "workspace_creation_receipt_version", "creation_receipt_id", "request_id",
        "runtime_workspace_plan_id", "planning_chain_id", "execution_package_id",
        "workspace_boundary_id", "execution_review_id", "gate_stack_preview_id",
        "approval_checklist_id", "preflight_checklist_id", "workspace_id", "workspace_path",
        "creation_timestamp", "workspace_manifest", "manifest_hash", "workspace_hash",
        "status", "allowed_actions_performed", "forbidden_actions_avoided", "metadata",
    )
    missing = [field for field in required if field not in receipt]
    if missing:
        raise ValueError(f"workspace creation receipt missing fields: {missing}")
    if receipt["workspace_creation_receipt_version"] != WORKSPACE_CREATION_RECEIPT_VERSION:
        raise ValueError("unsupported workspace creation receipt version")
    for field in (
        "creation_receipt_id", "request_id", "runtime_workspace_plan_id", "planning_chain_id",
        "execution_package_id", "workspace_boundary_id", "execution_review_id",
        "gate_stack_preview_id", "approval_checklist_id", "preflight_checklist_id",
        "workspace_id", "workspace_path", "creation_timestamp", "manifest_hash",
        "workspace_hash", "status",
    ):
        _validate_non_empty_string(receipt[field], field)
    if receipt["status"] not in {"created", "preview"}:
        raise ValueError("invalid workspace creation receipt status")
    if not isinstance(receipt["workspace_manifest"], dict):
        raise TypeError("workspace_manifest must be a dict")
    manifest = receipt["workspace_manifest"]
    for field in ("workspace_id", "runtime_workspace_plan_id", "planning_chain_id", "branch_name", "created_by"):
        _validate_non_empty_string(manifest.get(field), f"workspace_manifest.{field}")
    for field in ("allowed_actions_performed", "forbidden_actions_avoided"):
        values = receipt[field]
        if not isinstance(values, list) or not values:
            raise TypeError(f"{field} must be a non-empty list")
        if values != _normalize_patch_behavior_text_list(values):
            raise ValueError(f"{field} must be normalized and sorted")
    if "modify repository files" not in receipt["forbidden_actions_avoided"]:
        raise ValueError("workspace receipt must record repository mutation avoidance")
    expected_id = make_workspace_creation_receipt_id(
        receipt["request_id"],
        receipt["runtime_workspace_plan_id"],
        receipt["workspace_id"],
        receipt["manifest_hash"],
    )
    if receipt["creation_receipt_id"] != expected_id:
        raise ValueError("workspace creation receipt id does not match contents")
    if request is not None:
        validate_guarded_workspace_request(request)
        expected_refs = {
            "request_id": request["request_id"],
            "runtime_workspace_plan_id": request["runtime_workspace_plan_id"],
            "planning_chain_id": request["planning_chain_id"],
            "execution_package_id": request["execution_package_id"],
            "workspace_boundary_id": request["workspace_boundary_id"],
            "execution_review_id": request["execution_review_id"],
            "gate_stack_preview_id": request["gate_stack_preview_id"],
            "approval_checklist_id": request["approval_checklist_id"],
            "preflight_checklist_id": request["preflight_checklist_id"],
        }
        for field, value in expected_refs.items():
            if receipt[field] != value:
                raise ValueError(f"workspace creation receipt {field} does not match request")


def stable_workspace_creation_receipt_json(receipt: dict[str, Any]) -> str:
    validate_workspace_creation_receipt(receipt)
    return _stable_ruflo_json(receipt, indent=2) + "\n"


def create_guarded_workspace(
    request: dict[str, Any],
    workspace_runtime_plan: dict[str, Any],
    *,
    execution_review: dict[str, Any] | None = None,
    execution_gate_stack_preview: dict[str, Any] | None = None,
    execution_approval_checklist: dict[str, Any] | None = None,
    execution_preflight_checklist: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Create a guarded temporary workspace directory and manifest after approval."""
    import hashlib
    import shutil
    from datetime import datetime, timezone

    validate_guarded_workspace_request(
        request,
        workspace_runtime_plan,
        execution_review,
        execution_gate_stack_preview,
        execution_approval_checklist,
        execution_preflight_checklist,
    )
    if not request["write"]:
        raise PermissionError("guarded workspace creation requires --write")
    if not request["approved"]:
        raise PermissionError("guarded workspace creation requires explicit approval")
    root_path, workspace_path = _guarded_workspace_path(request["workspace_root"], request["workspace_name"])
    workspace_id = _execution_readiness_id("guarded-workspace", {
        "request_id": request["request_id"],
        "runtime_workspace_plan_id": request["runtime_workspace_plan_id"],
        "workspace_path": str(workspace_path),
    })
    created_workspace = False
    try:
        root_path.mkdir(parents=True, exist_ok=True)
        workspace_path.mkdir(mode=0o700, parents=False, exist_ok=False)
        created_workspace = True
        timestamp = datetime.now(timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")
        manifest = {
            "workspace_manifest_version": "link-guarded-workspace-manifest-v1",
            "workspace_id": workspace_id,
            "runtime_workspace_plan_id": request["runtime_workspace_plan_id"],
            "planning_chain_id": request["planning_chain_id"],
            "execution_package_id": request["execution_package_id"],
            "workspace_boundary_id": request["workspace_boundary_id"],
            "branch_name": request["branch_name"],
            "workspace_path": str(workspace_path),
            "created_by": "growth workspace-create --write",
            "created_at": timestamp,
            "no_patch_application": True,
            "no_verification_execution": True,
            "no_repo_mutation": True,
        }
        manifest_text = _stable_ruflo_json(manifest, indent=2) + "\n"
        manifest_path = workspace_path / "workspace_manifest.json"
        manifest_path.write_text(manifest_text, encoding="utf-8")
        manifest_hash = hashlib.sha256(manifest_text.encode("utf-8")).hexdigest()
        workspace_hash = _workspace_hash(str(workspace_path))
        receipt = collect_workspace_creation_receipt(
            request,
            workspace_id=workspace_id,
            workspace_path=str(workspace_path),
            workspace_manifest=manifest,
            creation_timestamp=timestamp,
            manifest_hash=manifest_hash,
            workspace_hash=workspace_hash,
        )
        return receipt
    except Exception:
        if created_workspace and workspace_path.exists():
            shutil.rmtree(workspace_path)
        raise


def preview_guarded_workspace_creation(
    request: dict[str, Any],
    workspace_runtime_plan: dict[str, Any],
) -> dict[str, Any]:
    """Return a read-only preview receipt shape without creating a workspace."""
    import hashlib

    validate_guarded_workspace_request(request, workspace_runtime_plan)
    _, workspace_path = _guarded_workspace_path(request["workspace_root"], request["workspace_name"])
    workspace_id = _execution_readiness_id("guarded-workspace-preview", {
        "request_id": request["request_id"],
        "runtime_workspace_plan_id": request["runtime_workspace_plan_id"],
        "workspace_path": str(workspace_path),
    })
    manifest = {
        "workspace_manifest_version": "link-guarded-workspace-manifest-v1",
        "workspace_id": workspace_id,
        "runtime_workspace_plan_id": request["runtime_workspace_plan_id"],
        "planning_chain_id": request["planning_chain_id"],
        "execution_package_id": request["execution_package_id"],
        "workspace_boundary_id": request["workspace_boundary_id"],
        "branch_name": request["branch_name"],
        "workspace_path": str(workspace_path),
        "created_by": "growth workspace-create preview",
        "created_at": "preview-only",
        "no_patch_application": True,
        "no_verification_execution": True,
        "no_repo_mutation": True,
    }
    manifest_text = _stable_ruflo_json(manifest, indent=2) + "\n"
    return collect_workspace_creation_receipt(
        request,
        workspace_id=workspace_id,
        workspace_path=str(workspace_path),
        workspace_manifest=manifest,
        creation_timestamp="preview-only",
        manifest_hash=hashlib.sha256(manifest_text.encode("utf-8")).hexdigest(),
        workspace_hash=hashlib.sha256(b"preview-only").hexdigest(),
        status="preview",
    )


WORKSPACE_CLEANUP_PLAN_VERSION = "link-workspace-cleanup-plan-v1"
WORKSPACE_ABANDON_PLAN_VERSION = "link-workspace-abandon-plan-v1"
WORKSPACE_CLEANUP_RECEIPT_VERSION = "link-workspace-cleanup-receipt-v1"
WORKSPACE_ABANDON_RECEIPT_VERSION = "link-workspace-abandon-receipt-v1"


def _workspace_manifest_id(receipt: dict[str, Any]) -> str:
    return _execution_readiness_id("workspace-manifest", {
        "manifest_hash": receipt["manifest_hash"],
        "workspace_id": receipt["workspace_id"],
    })


def make_workspace_cleanup_plan_id(workspace_id: str, workspace_path: str, creation_receipt_id: str, cleanup_reason: str) -> str:
    return _execution_readiness_id("workspace-cleanup-plan", {
        "creation_receipt_id": creation_receipt_id,
        "cleanup_reason": cleanup_reason,
        "version": WORKSPACE_CLEANUP_PLAN_VERSION,
        "workspace_id": workspace_id,
        "workspace_path": workspace_path,
    })


def make_workspace_abandon_plan_id(workspace_id: str, workspace_path: str, creation_receipt_id: str, abandonment_reason: str, abandonment_category: str) -> str:
    return _execution_readiness_id("workspace-abandon-plan", {
        "abandonment_category": abandonment_category,
        "abandonment_reason": abandonment_reason,
        "creation_receipt_id": creation_receipt_id,
        "version": WORKSPACE_ABANDON_PLAN_VERSION,
        "workspace_id": workspace_id,
        "workspace_path": workspace_path,
    })


def make_workspace_cleanup_receipt_id(cleanup_plan_id: str, workspace_id: str, cleanup_result: str, evidence_refs: list[str]) -> str:
    return _execution_readiness_id("workspace-cleanup-receipt", {
        "cleanup_plan_id": cleanup_plan_id,
        "cleanup_result": cleanup_result,
        "evidence_refs": evidence_refs,
        "version": WORKSPACE_CLEANUP_RECEIPT_VERSION,
        "workspace_id": workspace_id,
    })


def make_workspace_abandon_receipt_id(abandon_plan_id: str, workspace_id: str, abandonment_result: str, evidence_refs: list[str]) -> str:
    return _execution_readiness_id("workspace-abandon-receipt", {
        "abandon_plan_id": abandon_plan_id,
        "abandonment_result": abandonment_result,
        "evidence_refs": evidence_refs,
        "version": WORKSPACE_ABANDON_RECEIPT_VERSION,
        "workspace_id": workspace_id,
    })


def _validate_workspace_lifecycle_path(workspace_path: str, workspace_id: str | None = None) -> None:
    from pathlib import Path

    path = Path(workspace_path).expanduser().resolve(strict=False)
    if path == Path.cwd().resolve(strict=False) or path == Path.cwd().resolve(strict=False).parent:
        raise ValueError("workspace lifecycle path must not be the repository root")
    if workspace_id:
        manifest_path = path / "workspace_manifest.json"
        if path.exists():
            if not path.is_dir():
                raise ValueError("workspace lifecycle path must be a directory")
            if not manifest_path.exists():
                raise ValueError("workspace lifecycle path missing guarded workspace manifest")
            try:
                manifest = json.loads(manifest_path.read_text(encoding="utf-8"))
            except Exception as exc:
                raise ValueError("workspace manifest must be readable JSON") from exc
            if manifest.get("workspace_id") != workspace_id:
                raise ValueError("workspace manifest workspace_id mismatch")
            if manifest.get("no_repo_mutation") is not True:
                raise ValueError("workspace manifest must record no_repo_mutation")


def collect_workspace_cleanup_plan(
    creation_receipt: dict[str, Any],
    *,
    cleanup_reason: str = "successful closure",
    metadata: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Plan cleanup of a guarded temporary workspace without removing it."""
    validate_workspace_creation_receipt(creation_receipt)
    workspace_id = creation_receipt["workspace_id"]
    workspace_path = creation_receipt["workspace_path"]
    manifest_id = _workspace_manifest_id(creation_receipt)
    actions = _normalize_patch_behavior_text_list([
        "remove guarded temporary workspace directory",
        "remove workspace manifest inside guarded workspace",
        "return cleanup receipt to caller",
        "verify workspace path is not repository root",
    ])
    required_evidence = _normalize_implementation_branch_refs([
        "creation_receipt_id",
        "manifest_hash",
        "workspace_hash",
        "workspace_id",
    ])
    expected_outputs = _normalize_patch_behavior_text_list([
        "cleanup receipt",
        "workspace path absent after cleanup",
    ])
    cleanup_status = "eligible" if creation_receipt["status"] == "created" else "preview"
    plan = {
        "workspace_cleanup_plan_version": WORKSPACE_CLEANUP_PLAN_VERSION,
        "cleanup_plan_id": make_workspace_cleanup_plan_id(
            workspace_id,
            workspace_path,
            creation_receipt["creation_receipt_id"],
            cleanup_reason,
        ),
        "workspace_id": workspace_id,
        "workspace_path": workspace_path,
        "manifest_id": manifest_id,
        "creation_receipt_id": creation_receipt["creation_receipt_id"],
        "cleanup_reason": cleanup_reason,
        "cleanup_actions": actions,
        "required_evidence": required_evidence,
        "expected_cleanup_outputs": expected_outputs,
        "cleanup_status": cleanup_status,
        "dry_run": True,
        "write_allowed": False,
        "automation_allowed": False,
        "metadata": dict(metadata or {}),
        "writes": [],
    }
    validate_workspace_cleanup_plan(plan, creation_receipt)
    return plan


def validate_workspace_cleanup_plan(plan: dict[str, Any], creation_receipt: dict[str, Any] | None = None) -> None:
    required = (
        "workspace_cleanup_plan_version", "cleanup_plan_id", "workspace_id", "workspace_path",
        "manifest_id", "creation_receipt_id", "cleanup_reason", "cleanup_actions",
        "required_evidence", "expected_cleanup_outputs", "cleanup_status", "dry_run",
        "write_allowed", "automation_allowed", "metadata", "writes",
    )
    missing = [field for field in required if field not in plan]
    if missing:
        raise ValueError(f"workspace cleanup plan missing fields: {missing}")
    if plan["workspace_cleanup_plan_version"] != WORKSPACE_CLEANUP_PLAN_VERSION:
        raise ValueError("unsupported workspace cleanup plan version")
    _validate_execution_read_only(plan, "workspace cleanup plan")
    for field in ("cleanup_plan_id", "workspace_id", "workspace_path", "manifest_id", "creation_receipt_id", "cleanup_reason", "cleanup_status"):
        _validate_non_empty_string(plan[field], field)
    if plan["cleanup_status"] not in {"eligible", "preview", "blocked"}:
        raise ValueError("invalid workspace cleanup status")
    for field in ("cleanup_actions", "expected_cleanup_outputs"):
        values = plan[field]
        if not isinstance(values, list) or not values:
            raise TypeError(f"{field} must be a non-empty list")
        if values != _normalize_patch_behavior_text_list(values):
            raise ValueError(f"{field} must be normalized and sorted")
    evidence = plan["required_evidence"]
    if not isinstance(evidence, list) or not evidence:
        raise TypeError("required_evidence must be a non-empty list")
    if evidence != _normalize_implementation_branch_refs(evidence):
        raise ValueError("required_evidence must be normalized and sorted")
    if "remove guarded temporary workspace directory" not in plan["cleanup_actions"]:
        raise ValueError("cleanup plan must remove only guarded temporary workspace")
    expected_id = make_workspace_cleanup_plan_id(plan["workspace_id"], plan["workspace_path"], plan["creation_receipt_id"], plan["cleanup_reason"])
    if plan["cleanup_plan_id"] != expected_id:
        raise ValueError("workspace cleanup plan id does not match contents")
    if creation_receipt is not None:
        validate_workspace_creation_receipt(creation_receipt)
        if plan["workspace_id"] != creation_receipt["workspace_id"]:
            raise ValueError("workspace cleanup plan workspace_id mismatch")
        if plan["workspace_path"] != creation_receipt["workspace_path"]:
            raise ValueError("workspace cleanup plan workspace_path mismatch")
        if plan["creation_receipt_id"] != creation_receipt["creation_receipt_id"]:
            raise ValueError("workspace cleanup plan creation receipt mismatch")


def stable_workspace_cleanup_plan_json(plan: dict[str, Any]) -> str:
    validate_workspace_cleanup_plan(plan)
    return _stable_ruflo_json(plan, indent=2) + "\n"


def parse_workspace_cleanup_plan_json(text: str) -> dict[str, Any]:
    plan = json.loads(text)
    validate_workspace_cleanup_plan(plan)
    return plan


def collect_workspace_abandon_plan(
    creation_receipt: dict[str, Any],
    *,
    abandonment_reason: str = "blocked execution",
    abandonment_category: str = "blocked",
    blockers: list[str] | None = None,
    metadata: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Plan abandonment of a guarded workspace without mutating it."""
    validate_workspace_creation_receipt(creation_receipt)
    if abandonment_category not in {"failed", "canceled", "blocked"}:
        raise ValueError("invalid abandonment category")
    workspace_id = creation_receipt["workspace_id"]
    workspace_path = creation_receipt["workspace_path"]
    normalized_blockers = _normalize_patch_behavior_text_list(blockers or [abandonment_reason])
    required_evidence = _normalize_implementation_branch_refs([
        "abandonment_reason",
        "creation_receipt_id",
        "workspace_id",
    ])
    status = "blocked" if normalized_blockers else "eligible"
    plan = {
        "workspace_abandon_plan_version": WORKSPACE_ABANDON_PLAN_VERSION,
        "abandon_plan_id": make_workspace_abandon_plan_id(
            workspace_id,
            workspace_path,
            creation_receipt["creation_receipt_id"],
            abandonment_reason,
            abandonment_category,
        ),
        "workspace_id": workspace_id,
        "workspace_path": workspace_path,
        "manifest_id": _workspace_manifest_id(creation_receipt),
        "creation_receipt_id": creation_receipt["creation_receipt_id"],
        "abandonment_reason": abandonment_reason,
        "abandonment_category": abandonment_category,
        "blockers": normalized_blockers,
        "required_evidence": required_evidence,
        "abandonment_status": status,
        "dry_run": True,
        "write_allowed": False,
        "automation_allowed": False,
        "metadata": dict(metadata or {}),
        "writes": [],
    }
    validate_workspace_abandon_plan(plan, creation_receipt)
    return plan


def validate_workspace_abandon_plan(plan: dict[str, Any], creation_receipt: dict[str, Any] | None = None) -> None:
    required = (
        "workspace_abandon_plan_version", "abandon_plan_id", "workspace_id", "workspace_path",
        "manifest_id", "creation_receipt_id", "abandonment_reason", "abandonment_category",
        "blockers", "required_evidence", "abandonment_status", "dry_run", "write_allowed",
        "automation_allowed", "metadata", "writes",
    )
    missing = [field for field in required if field not in plan]
    if missing:
        raise ValueError(f"workspace abandon plan missing fields: {missing}")
    if plan["workspace_abandon_plan_version"] != WORKSPACE_ABANDON_PLAN_VERSION:
        raise ValueError("unsupported workspace abandon plan version")
    _validate_execution_read_only(plan, "workspace abandon plan")
    for field in ("abandon_plan_id", "workspace_id", "workspace_path", "manifest_id", "creation_receipt_id", "abandonment_reason", "abandonment_category", "abandonment_status"):
        _validate_non_empty_string(plan[field], field)
    if plan["abandonment_category"] not in {"failed", "canceled", "blocked"}:
        raise ValueError("invalid abandonment category")
    if plan["abandonment_status"] not in {"eligible", "blocked"}:
        raise ValueError("invalid abandonment status")
    blockers = plan["blockers"]
    if not isinstance(blockers, list):
        raise TypeError("blockers must be a list")
    if blockers != _normalize_patch_behavior_text_list(blockers):
        raise ValueError("blockers must be normalized and sorted")
    evidence = plan["required_evidence"]
    if not isinstance(evidence, list) or not evidence:
        raise TypeError("required_evidence must be a non-empty list")
    if evidence != _normalize_implementation_branch_refs(evidence):
        raise ValueError("required_evidence must be normalized and sorted")
    if plan["blockers"] and plan["abandonment_status"] != "blocked":
        raise ValueError("abandonment blockers must produce blocked status")
    expected_id = make_workspace_abandon_plan_id(
        plan["workspace_id"], plan["workspace_path"], plan["creation_receipt_id"],
        plan["abandonment_reason"], plan["abandonment_category"],
    )
    if plan["abandon_plan_id"] != expected_id:
        raise ValueError("workspace abandon plan id does not match contents")
    if creation_receipt is not None:
        validate_workspace_creation_receipt(creation_receipt)
        if plan["workspace_id"] != creation_receipt["workspace_id"]:
            raise ValueError("workspace abandon plan workspace_id mismatch")
        if plan["workspace_path"] != creation_receipt["workspace_path"]:
            raise ValueError("workspace abandon plan workspace_path mismatch")
        if plan["creation_receipt_id"] != creation_receipt["creation_receipt_id"]:
            raise ValueError("workspace abandon plan creation receipt mismatch")


def stable_workspace_abandon_plan_json(plan: dict[str, Any]) -> str:
    validate_workspace_abandon_plan(plan)
    return _stable_ruflo_json(plan, indent=2) + "\n"


def parse_workspace_abandon_plan_json(text: str) -> dict[str, Any]:
    plan = json.loads(text)
    validate_workspace_abandon_plan(plan)
    return plan


