def _timestamp_now_utc() -> str:
    from datetime import datetime, timezone
    return datetime.now(timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")


def cleanup_guarded_workspace(cleanup_plan: dict[str, Any]) -> dict[str, Any]:
    import shutil
    from pathlib import Path

    validate_workspace_cleanup_plan(cleanup_plan)
    _validate_workspace_lifecycle_path(cleanup_plan["workspace_path"], cleanup_plan["workspace_id"])
    path = Path(cleanup_plan["workspace_path"]).expanduser().resolve(strict=False)
    if not path.exists():
        raise FileNotFoundError("workspace path does not exist")
    shutil.rmtree(path)
    return collect_workspace_cleanup_receipt(
        cleanup_plan,
        cleanup_result="cleaned",
        cleanup_timestamp=_timestamp_now_utc(),
        evidence_refs=["creation_receipt_id", "manifest_hash", "workspace_removed", cleanup_plan["workspace_id"]],
    )


def abandon_guarded_workspace(abandon_plan: dict[str, Any]) -> dict[str, Any]:
    from pathlib import Path

    validate_workspace_abandon_plan(abandon_plan)
    _validate_workspace_lifecycle_path(abandon_plan["workspace_path"], abandon_plan["workspace_id"])
    path = Path(abandon_plan["workspace_path"]).expanduser().resolve(strict=False)
    receipt = collect_workspace_abandon_receipt(
        abandon_plan,
        abandonment_result="abandoned",
        abandonment_timestamp=_timestamp_now_utc(),
        evidence_refs=["abandonment_reason", "creation_receipt_id", abandon_plan["workspace_id"]],
    )
    receipt_path = path / "workspace_abandon_receipt.json"
    receipt_path.write_text(_stable_ruflo_json(receipt, indent=2) + "\n", encoding="utf-8")
    return receipt


def _workspace_lifecycle_preview_receipt() -> dict[str, Any]:
    chain = collect_growth_planning_chain_preview()
    runtime_plan = collect_workspace_creator_runtime_plan(chain)
    request = make_guarded_workspace_request(runtime_plan, approved=False, write=False)
    return preview_guarded_workspace_creation(request, runtime_plan)


def _workspace_lifecycle_receipt_from_manifest(workspace_path: str, workspace_id: str) -> dict[str, Any]:
    import hashlib
    from pathlib import Path

    _validate_workspace_lifecycle_path(workspace_path, workspace_id)
    path = Path(workspace_path).expanduser().resolve(strict=False)
    manifest_path = path / "workspace_manifest.json"
    manifest = json.loads(manifest_path.read_text(encoding="utf-8"))
    manifest_text = _stable_ruflo_json(manifest, indent=2) + "\n"
    manifest_hash = hashlib.sha256(manifest_text.encode("utf-8")).hexdigest()
    return {
        "workspace_creation_receipt_version": WORKSPACE_CREATION_RECEIPT_VERSION,
        "creation_receipt_id": make_workspace_creation_receipt_id(
            f"manifest-request-{workspace_id}",
            manifest["runtime_workspace_plan_id"],
            workspace_id,
            manifest_hash,
        ),
        "request_id": f"manifest-request-{workspace_id}",
        "runtime_workspace_plan_id": manifest["runtime_workspace_plan_id"],
        "planning_chain_id": manifest["planning_chain_id"],
        "execution_package_id": manifest["execution_package_id"],
        "workspace_boundary_id": manifest["workspace_boundary_id"],
        "execution_review_id": "manifest-only-execution-review",
        "gate_stack_preview_id": "manifest-only-gate-stack",
        "approval_checklist_id": "manifest-only-approval-checklist",
        "preflight_checklist_id": "manifest-only-preflight-checklist",
        "workspace_id": workspace_id,
        "workspace_path": str(path),
        "creation_timestamp": manifest.get("created_at", "manifest-only"),
        "workspace_manifest": manifest,
        "manifest_hash": manifest_hash,
        "workspace_hash": _workspace_hash(str(path)),
        "status": "created",
        "allowed_actions_performed": _normalize_patch_behavior_text_list([
            "create metadata manifest",
            "create temporary workspace directory",
            "create workspace receipt",
        ]),
        "forbidden_actions_avoided": _normalize_patch_behavior_text_list([
            "apply patches",
            "create commits",
            "create git branches",
            "execute verification commands",
            "merge changes",
            "modify repository files",
            "modify repository working tree",
            "run network commands",
        ]),
        "metadata": {"source": "workspace_manifest"},
    }


def make_verified_patch_plan_id(work_package: dict[str, Any], operations: list[dict[str, Any]]) -> str:
    import hashlib

    payload = _stable_ruflo_json({
        "operation_ids": [operation["operation_id"] for operation in operations],
        "package_id": work_package["package_id"],
        "upgrade_id": work_package["upgrade_id"],
        "version": VERIFIED_PATCH_PLAN_VERSION,
    })
    digest = hashlib.sha256(payload.encode("utf-8")).hexdigest()[:12]
    return f"verified-patch-plan-{digest}"


def make_verified_patch_operation_id(operation_type: str, file_path: str, work_package_id: str) -> str:
    import hashlib

    payload = _stable_ruflo_json({
        "file_path": file_path,
        "operation_type": operation_type,
        "version": VERIFIED_PATCH_PLAN_VERSION,
        "work_package_id": work_package_id,
    })
    digest = hashlib.sha256(payload.encode("utf-8")).hexdigest()[:12]
    return f"patch-operation-{digest}"


def collect_verified_patch_plan(
    work_package: dict[str, Any],
    *,
    verification_plan: dict[str, Any] | None = None,
    provided_evidence: list[str] | None = None,
    metadata: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Describe intended code changes for a work package without modifying files."""
    validate_implementation_work_package(work_package)
    verification_entry = _verified_patch_verification_entry(work_package, verification_plan)
    target_files = _normalize_implementation_branch_refs(work_package["target_files"])
    operations = [_verified_patch_operation_for_file(work_package, file_path) for file_path in target_files]
    operations.sort(key=lambda item: (item["file_path"], item["operation_type"], item["operation_id"]))
    required_evidence = _verified_patch_required_evidence(work_package, verification_entry)
    provided = _normalize_implementation_branch_refs(provided_evidence or [])
    missing = [item for item in required_evidence if item not in provided]
    patch_plan = {
        "verified_patch_plan_version": VERIFIED_PATCH_PLAN_VERSION,
        "verified_patch_plan_id": make_verified_patch_plan_id(work_package, operations),
        "upgrade_id": work_package["upgrade_id"],
        "branch_plan_id": work_package["branch_plan_id"],
        "work_package_id": work_package["package_id"],
        "target_files": target_files,
        "estimated_files_changed": len(target_files),
        "estimated_tests_affected": len([path for path in target_files if _verified_patch_is_test_path(path)]),
        "patch_operations": operations,
        "compile_expectations": _verified_patch_compile_expectations(verification_entry),
        "test_expectations": _verified_patch_test_expectations(verification_entry),
        "healthcheck_expectations": _verified_patch_healthcheck_expectations(verification_entry),
        "required_evidence": required_evidence,
        "provided_evidence": provided,
        "missing_evidence": missing,
        "dry_run": True,
        "write_allowed": False,
        "automation_allowed": False,
        "metadata": dict(metadata or {}),
        "writes": [],
    }
    validate_verified_patch_plan(patch_plan)
    return patch_plan


def validate_verified_patch_plan(patch_plan: dict[str, Any]) -> None:
    required = (
        "verified_patch_plan_version", "verified_patch_plan_id", "upgrade_id", "branch_plan_id",
        "work_package_id", "target_files", "estimated_files_changed", "estimated_tests_affected",
        "patch_operations", "compile_expectations", "test_expectations", "healthcheck_expectations",
        "required_evidence", "provided_evidence", "missing_evidence", "dry_run", "write_allowed",
        "automation_allowed", "metadata", "writes",
    )
    missing = [field for field in required if field not in patch_plan]
    if missing:
        raise ValueError(f"verified patch plan missing fields: {missing}")
    if patch_plan["verified_patch_plan_version"] != VERIFIED_PATCH_PLAN_VERSION:
        raise ValueError("unsupported verified patch plan version")
    for field in ("verified_patch_plan_id", "upgrade_id", "branch_plan_id", "work_package_id"):
        if not isinstance(patch_plan[field], str) or not patch_plan[field].strip():
            raise ValueError(f"{field} must be a non-empty string")
    if patch_plan["dry_run"] is not True or patch_plan["write_allowed"] is not False or patch_plan["automation_allowed"] is not False:
        raise ValueError("verified patch plan must remain read-only")
    if patch_plan["writes"] != []:
        raise ValueError("verified patch plan must not write files")
    if not isinstance(patch_plan["metadata"], dict):
        raise TypeError("verified patch plan metadata must be a dict")
    target_files = patch_plan["target_files"]
    if not isinstance(target_files, list) or not target_files:
        raise TypeError("target_files must be a non-empty list")
    if target_files != _normalize_implementation_branch_refs(target_files):
        raise ValueError("target_files must be normalized and sorted")
    if not isinstance(patch_plan["estimated_files_changed"], int) or patch_plan["estimated_files_changed"] != len(target_files):
        raise ValueError("estimated_files_changed must match target_files length")
    expected_tests = len([path for path in target_files if _verified_patch_is_test_path(path)])
    if not isinstance(patch_plan["estimated_tests_affected"], int) or patch_plan["estimated_tests_affected"] != expected_tests:
        raise ValueError("estimated_tests_affected must match test target count")
    operations = patch_plan["patch_operations"]
    if not isinstance(operations, list) or not operations:
        raise TypeError("patch_operations must be a non-empty list")
    operation_ids: set[str] = set()
    operation_files: set[str] = set()
    for operation in operations:
        validate_verified_patch_operation(operation, set(target_files))
        if operation["operation_id"] in operation_ids:
            raise ValueError(f"duplicate verified patch operation id: {operation['operation_id']}")
        operation_ids.add(operation["operation_id"])
        operation_files.add(operation["file_path"])
    if operation_files != set(target_files):
        raise ValueError("patch_operations must cover every target file exactly at least once")
    for field in ("compile_expectations", "test_expectations", "healthcheck_expectations", "required_evidence", "provided_evidence", "missing_evidence"):
        values = patch_plan[field]
        if not isinstance(values, list):
            raise TypeError(f"{field} must be a list")
        if field in {"compile_expectations", "test_expectations", "healthcheck_expectations", "required_evidence"} and not values:
            raise ValueError(f"{field} must be non-empty")
        if not all(isinstance(value, str) and value.strip() for value in values):
            raise TypeError(f"{field} must contain non-empty strings")
    for field in ("required_evidence", "provided_evidence", "missing_evidence"):
        if patch_plan[field] != _normalize_implementation_branch_refs(patch_plan[field]):
            raise ValueError(f"{field} must be normalized and sorted")
    expected_missing = [item for item in patch_plan["required_evidence"] if item not in patch_plan["provided_evidence"]]
    if patch_plan["missing_evidence"] != expected_missing:
        raise ValueError("missing_evidence must match required evidence not present in provided evidence")


def stable_verified_patch_plan_json(patch_plan: dict[str, Any]) -> str:
    validate_verified_patch_plan(patch_plan)
    return _stable_ruflo_json(patch_plan, indent=2) + "\n"


def parse_verified_patch_plan_json(text: str) -> dict[str, Any]:
    import json as _json

    patch_plan = _json.loads(text)
    validate_verified_patch_plan(patch_plan)
    return patch_plan


def validate_verified_patch_operation(operation: dict[str, Any], target_files: set[str]) -> None:
    required = ("operation_id", "operation_type", "file_path", "rationale", "expected_result", "risk_level")
    missing = [field for field in required if field not in operation]
    if missing:
        raise ValueError(f"verified patch operation missing fields: {missing}")
    for field in required:
        if not isinstance(operation[field], str) or not operation[field].strip():
            raise ValueError(f"{field} must be a non-empty string")
    if operation["operation_type"] not in VERIFIED_PATCH_OPERATION_TYPES:
        raise ValueError(f"invalid verified patch operation type: {operation['operation_type']}")
    if operation["risk_level"] not in UPGRADE_RISK_LEVELS:
        raise ValueError(f"invalid verified patch operation risk_level: {operation['risk_level']}")
    if operation["file_path"] not in target_files:
        raise ValueError(f"verified patch operation file_path is not a target file: {operation['file_path']}")
    if _normalize_implementation_branch_refs([operation["file_path"]]) != [operation["file_path"]]:
        raise ValueError("verified patch operation file_path must be normalized")


def _verified_patch_verification_entry(work_package: dict[str, Any], verification_plan: dict[str, Any] | None) -> dict[str, Any]:
    if verification_plan is None:
        generated = collect_verification_plan(work_package)
        return generated["plans"][0]
    if "plans" in verification_plan:
        validate_verification_plan(verification_plan)
        for plan in verification_plan["plans"]:
            if plan["package_id"] == work_package["package_id"]:
                return dict(plan)
        raise ValueError("verification_plan does not contain a plan for the work package")
    validate_verification_plan_entry(verification_plan)
    if verification_plan["package_id"] != work_package["package_id"]:
        raise ValueError("verification plan package_id does not match work package")
    return dict(verification_plan)


def _verified_patch_operation_for_file(work_package: dict[str, Any], file_path: str) -> dict[str, Any]:
    operation_type = _verified_patch_operation_type(file_path)
    operation = {
        "operation_id": make_verified_patch_operation_id(operation_type, file_path, work_package["package_id"]),
        "operation_type": operation_type,
        "file_path": file_path,
        "rationale": _verified_patch_operation_rationale(operation_type, file_path),
        "expected_result": _verified_patch_operation_expected_result(operation_type, file_path),
        "risk_level": work_package["risk"],
    }
    validate_verified_patch_operation(operation, set(work_package["target_files"]))
    return operation


def _verified_patch_operation_type(file_path: str) -> str:
    lower = file_path.lower()
    if _verified_patch_is_test_path(lower):
        return "update_test"
    if lower.endswith((".md", ".rst", ".txt")):
        return "documentation_update"
    return "modify_file"


def _verified_patch_is_test_path(file_path: str) -> bool:
    lower = file_path.lower()
    return lower.startswith("tests/") or "/test" in lower or lower.endswith("_test.py") or lower.endswith(".test.py")


def _verified_patch_operation_rationale(operation_type: str, file_path: str) -> str:
    return {
        "modify_file": f"Update {file_path} to implement the planned Link-native behavior.",
        "update_test": f"Update {file_path} to cover the planned behavior and guard regressions.",
        "add_test": f"Add {file_path} to cover the planned behavior and guard regressions.",
        "create_file": f"Create {file_path} only after review confirms no existing module is appropriate.",
        "delete_file": f"Delete {file_path} only after review confirms the file is obsolete and safe to remove.",
        "documentation_update": f"Update {file_path} to document the planned behavior and operation path.",
    }[operation_type]


def _verified_patch_operation_expected_result(operation_type: str, file_path: str) -> str:
    return {
        "modify_file": f"{file_path} contains the smallest implementation change needed for the work package.",
        "update_test": f"{file_path} verifies the new behavior without adding runtime state writes.",
        "add_test": f"{file_path} verifies the new behavior without adding runtime state writes.",
        "create_file": f"{file_path} exists only if the reviewed implementation requires a new module boundary.",
        "delete_file": f"{file_path} is removed only if tests prove no live behavior depends on it.",
        "documentation_update": f"{file_path} explains the verified behavior, safety limits, and verification path.",
    }[operation_type]


def _verified_patch_compile_expectations(verification_entry: dict[str, Any]) -> list[str]:
    return [f"compile command should pass: {command}" for command in verification_entry["compile_commands"]]


def _verified_patch_test_expectations(verification_entry: dict[str, Any]) -> list[str]:
    return [f"test command should pass: {command}" for command in verification_entry["test_commands"]]


def _verified_patch_healthcheck_expectations(verification_entry: dict[str, Any]) -> list[str]:
    return [f"healthcheck command should pass: {command}" for command in verification_entry["healthcheck_commands"]]


def _verified_patch_required_evidence(work_package: dict[str, Any], verification_entry: dict[str, Any]) -> list[str]:
    evidence = [
        "verified patch plan JSON reviewed",
        "patch operations reviewed before implementation",
        "git diff --stat",
        "git status --short --branch",
    ]
    evidence.extend(verification_entry["required_evidence"])
    evidence.extend(work_package["acceptance_criteria"])
    return _normalize_implementation_branch_refs(evidence)


def make_verified_patch_diff_id(patch_plan: dict[str, Any], diff_entries: list[dict[str, Any]]) -> str:
    import hashlib

    payload = _stable_ruflo_json({
        "diff_entry_ids": [entry["diff_entry_id"] for entry in diff_entries],
        "verified_patch_plan_id": patch_plan["verified_patch_plan_id"],
        "version": VERIFIED_PATCH_DIFF_VERSION,
    })
    digest = hashlib.sha256(payload.encode("utf-8")).hexdigest()[:12]
    return f"verified-patch-diff-{digest}"


def make_verified_patch_diff_entry_id(operation: dict[str, Any]) -> str:
    import hashlib

    payload = _stable_ruflo_json({
        "file_path": operation["file_path"],
        "operation_id": operation["operation_id"],
        "operation_type": operation["operation_type"],
        "version": VERIFIED_PATCH_DIFF_VERSION,
    })
    digest = hashlib.sha256(payload.encode("utf-8")).hexdigest()[:12]
    return f"verified-patch-diff-entry-{digest}"


def collect_verified_patch_diff(
    patch_plan: dict[str, Any],
    *,
    metadata: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Convert a verified patch plan into a deterministic read-only diff preview."""
    validate_verified_patch_plan(patch_plan)
    diff_entries = [_verified_patch_diff_entry(operation) for operation in patch_plan["patch_operations"]]
    diff_entries.sort(key=lambda item: item["diff_entry_id"])
    added = sum(entry["estimated_added_lines"] for entry in diff_entries)
    removed = sum(entry["estimated_removed_lines"] for entry in diff_entries)
    modified = sum(entry["estimated_modified_lines"] for entry in diff_entries)
    diff = {
        "verified_patch_diff_version": VERIFIED_PATCH_DIFF_VERSION,
        "verified_patch_diff_id": make_verified_patch_diff_id(patch_plan, diff_entries),
        "verified_patch_plan_id": patch_plan["verified_patch_plan_id"],
        "branch_plan_id": patch_plan["branch_plan_id"],
        "work_package_id": patch_plan["work_package_id"],
        "upgrade_id": patch_plan["upgrade_id"],
        "diff_entries": diff_entries,
        "estimated_added_lines": added,
        "estimated_removed_lines": removed,
        "estimated_modified_lines": modified,
        "compile_impact": list(patch_plan["compile_expectations"]),
        "test_impact": list(patch_plan["test_expectations"]),
        "healthcheck_impact": list(patch_plan["healthcheck_expectations"]),
        "confidence_score": _verified_patch_diff_confidence_score(patch_plan, diff_entries),
        "risk_score": _verified_patch_diff_risk_score(diff_entries),
        "dry_run": True,
        "write_allowed": False,
        "automation_allowed": False,
        "metadata": dict(metadata or {}),
        "writes": [],
    }
    validate_verified_patch_diff(diff)
    return diff


def validate_verified_patch_diff(diff: dict[str, Any]) -> None:
    required = (
        "verified_patch_diff_version", "verified_patch_diff_id", "verified_patch_plan_id",
        "branch_plan_id", "work_package_id", "upgrade_id", "diff_entries",
        "estimated_added_lines", "estimated_removed_lines", "estimated_modified_lines",
        "compile_impact", "test_impact", "healthcheck_impact", "confidence_score",
        "risk_score", "dry_run", "write_allowed", "automation_allowed", "metadata", "writes",
    )
    missing = [field for field in required if field not in diff]
    if missing:
        raise ValueError(f"verified patch diff missing fields: {missing}")
    if diff["verified_patch_diff_version"] != VERIFIED_PATCH_DIFF_VERSION:
        raise ValueError("unsupported verified patch diff version")
    for field in ("verified_patch_diff_id", "verified_patch_plan_id", "branch_plan_id", "work_package_id", "upgrade_id"):
        if not isinstance(diff[field], str) or not diff[field].strip():
            raise ValueError(f"{field} must be a non-empty string")
    if diff["dry_run"] is not True or diff["write_allowed"] is not False or diff["automation_allowed"] is not False:
        raise ValueError("verified patch diff must remain read-only")
    if diff["writes"] != []:
        raise ValueError("verified patch diff must not write files")
    if not isinstance(diff["metadata"], dict):
        raise TypeError("verified patch diff metadata must be a dict")
    entries = diff["diff_entries"]
    if not isinstance(entries, list) or not entries:
        raise TypeError("diff_entries must be a non-empty list")
    entry_ids: set[str] = set()
    operation_ids: set[str] = set()
    for entry in entries:
        validate_verified_patch_diff_entry(entry)
        if entry["diff_entry_id"] in entry_ids:
            raise ValueError(f"duplicate verified patch diff entry id: {entry['diff_entry_id']}")
        if entry["operation_id"] in operation_ids:
            raise ValueError(f"duplicate verified patch diff operation id: {entry['operation_id']}")
        entry_ids.add(entry["diff_entry_id"])
        operation_ids.add(entry["operation_id"])
    if [entry["diff_entry_id"] for entry in entries] != sorted(entry["diff_entry_id"] for entry in entries):
        raise ValueError("diff_entries must be sorted by diff_entry_id")
    for field in ("estimated_added_lines", "estimated_removed_lines", "estimated_modified_lines"):
        if not isinstance(diff[field], int) or diff[field] < 0:
            raise ValueError(f"{field} must be a non-negative integer")
    if diff["estimated_added_lines"] != sum(entry["estimated_added_lines"] for entry in entries):
        raise ValueError("estimated_added_lines must match diff entry sum")
    if diff["estimated_removed_lines"] != sum(entry["estimated_removed_lines"] for entry in entries):
        raise ValueError("estimated_removed_lines must match diff entry sum")
    if diff["estimated_modified_lines"] != sum(entry["estimated_modified_lines"] for entry in entries):
        raise ValueError("estimated_modified_lines must match diff entry sum")
    for field in ("compile_impact", "test_impact", "healthcheck_impact"):
        values = diff[field]
        if not isinstance(values, list) or not values:
            raise TypeError(f"{field} must be a non-empty list")
        if not all(isinstance(value, str) and value.strip() for value in values):
            raise TypeError(f"{field} must contain non-empty strings")
    _validate_probability_score(diff["confidence_score"], "confidence_score")
    _validate_probability_score(diff["risk_score"], "risk_score")


def stable_verified_patch_diff_json(diff: dict[str, Any]) -> str:
    validate_verified_patch_diff(diff)
    return _stable_ruflo_json(diff, indent=2) + "\n"


def parse_verified_patch_diff_json(text: str) -> dict[str, Any]:
    import json as _json

    diff = _json.loads(text)
    validate_verified_patch_diff(diff)
    return diff


PATCH_APPLIER_BOUNDARY_VERSION = "link-patch-applier-boundary-v1"
PATCH_APPLIER_FORBIDDEN_PATH_PREFIXES = (".agents/", ".git/", ".link/", "research/")
PATCH_APPLIER_FORBIDDEN_OPERATION_TYPES = ("execute_shell", "git_operation", "network_call", "run_verification")
PATCH_APPLIER_RISKY_OPERATION_TYPES = ("create_file", "delete_file")


def make_patch_applier_boundary_id(
    planning_chain_id: str,
    verified_patch_plan_id: str,
    verified_patch_diff_id: str,
    execution_package_id: str,
    workspace_boundary_id: str,
    runtime_workspace_plan_id: str,
) -> str:
    return _execution_readiness_id("patch-applier-boundary", {
        "execution_package_id": execution_package_id,
        "planning_chain_id": planning_chain_id,
        "runtime_workspace_plan_id": runtime_workspace_plan_id,
        "verified_patch_diff_id": verified_patch_diff_id,
        "verified_patch_plan_id": verified_patch_plan_id,
        "version": PATCH_APPLIER_BOUNDARY_VERSION,
        "workspace_boundary_id": workspace_boundary_id,
    })


def _patch_applier_validate_target_path(path: str) -> None:
    _validate_non_empty_string(path, "target path")
    normalized = _normalize_implementation_branch_refs([path])
    if normalized != [path]:
        raise ValueError("patch target path must be normalized")
    if path.startswith("/") or ".." in path.split("/"):
        raise ValueError("patch target path must stay relative to the workspace")
    for prefix in PATCH_APPLIER_FORBIDDEN_PATH_PREFIXES:
        if path == prefix.rstrip("/") or path.startswith(prefix):
            raise ValueError(f"patch target path uses forbidden prefix: {prefix}")


def collect_patch_applier_boundary(
    verified_patch_plan: dict[str, Any],
    verified_patch_diff: dict[str, Any],
    execution_gate_stack_preview: dict[str, Any],
    execution_approval_checklist: dict[str, Any],
    execution_evidence_contract: dict[str, Any],
    workspace_creator_runtime_boundary: dict[str, Any],
    workspace_runtime_plan: dict[str, Any],
    *,
    planning_chain_id: str | None = None,
    metadata: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Return a strict read-only boundary for future patch application."""
    validate_verified_patch_plan(verified_patch_plan)
    validate_verified_patch_diff(verified_patch_diff)
    validate_execution_gate_stack_preview(execution_gate_stack_preview)
    validate_execution_approval_checklist(execution_approval_checklist)
    validate_execution_evidence_contract(execution_evidence_contract)
    validate_workspace_creator_runtime_boundary(workspace_creator_runtime_boundary)
    validate_workspace_creator_runtime_plan(workspace_runtime_plan, workspace_creator_runtime_boundary)
    source_planning_chain_id = planning_chain_id or execution_gate_stack_preview["planning_chain_id"]
    allowed_target_files = _normalize_implementation_branch_refs(verified_patch_plan["target_files"])
    for target in allowed_target_files:
        _patch_applier_validate_target_path(target)
    operation_types = _normalize_patch_behavior_text_list([
        operation["operation_type"] for operation in verified_patch_plan["patch_operations"]
    ])
    risky_present = _normalize_patch_behavior_text_list([
        operation_type for operation_type in operation_types
        if operation_type in PATCH_APPLIER_RISKY_OPERATION_TYPES
    ])
    operation_requires_review = _normalize_patch_behavior_text_list([
        *risky_present,
        *(["review_gate_status"] if execution_gate_stack_preview["review_count"] else []),
        *(["approval_status"] if execution_approval_checklist["approval_status"] != "pass" else []),
    ]) or ["human_patch_review"]
    fail_closed = _normalize_patch_behavior_text_list([
        "approval checklist is not pass",
        "diff id does not match verified patch plan",
        "evidence contract missing patch application evidence",
        "gate stack contains block status",
        "patch target path is outside allowed workspace files",
        "workspace boundary is not pass",
        "workspace runtime plan is not pass",
    ])
    rollback_triggers = _normalize_patch_behavior_text_list([
        "applied patch differs from verified patch diff preview",
        "file hash evidence cannot be produced",
        "patch operation touches forbidden target path",
        "reviewer rejects patch boundary",
    ])
    cleanup_triggers = _normalize_patch_behavior_text_list([
        "patch boundary validation fails before application",
        "workspace is abandoned before patch application",
    ])
    escalation_conditions = _normalize_patch_behavior_text_list([
        "delete_file operation requested",
        "gate stack review or block status present",
        "human approval checklist not pass",
        "required patch evidence missing",
    ])
    required_patch_evidence = _normalize_implementation_branch_refs([
        "applied_patch_hash",
        "patch_application_status",
        "patch_operation_results",
    ])
    required_diff_evidence = _normalize_implementation_branch_refs([
        "verified_patch_diff_id",
        "diff_hash",
        "diff_preview_reviewed",
    ])
    required_file_hash_evidence = _normalize_implementation_branch_refs([
        "before_file_hashes",
        "after_file_hashes",
        "changed_file_refs",
    ])
    required_journal_evidence = _normalize_implementation_branch_refs([
        "execution_journal_entry_id",
        "patch_attempt_id",
    ])
    boundary = {
        "patch_applier_boundary_version": PATCH_APPLIER_BOUNDARY_VERSION,
        "patch_applier_boundary_id": make_patch_applier_boundary_id(
            source_planning_chain_id,
            verified_patch_plan["verified_patch_plan_id"],
            verified_patch_diff["verified_patch_diff_id"],
            workspace_runtime_plan["execution_package_id"],
            workspace_creator_runtime_boundary["workspace_boundary_id"],
            workspace_runtime_plan["runtime_workspace_plan_id"],
        ),
        "planning_chain_id": source_planning_chain_id,
        "verified_patch_plan_id": verified_patch_plan["verified_patch_plan_id"],
        "verified_patch_diff_id": verified_patch_diff["verified_patch_diff_id"],
        "execution_package_id": workspace_runtime_plan["execution_package_id"],
        "workspace_boundary_id": workspace_creator_runtime_boundary["workspace_boundary_id"],
        "runtime_workspace_plan_id": workspace_runtime_plan["runtime_workspace_plan_id"],
        "source_type": "verified_patch_plan_and_diff",
        "allowed_source_ids": _normalize_implementation_branch_refs([
            verified_patch_plan["verified_patch_plan_id"],
            verified_patch_diff["verified_patch_diff_id"],
        ]),
        "required_source_evidence": _normalize_implementation_branch_refs([
            "verified patch diff JSON reviewed",
            "verified patch plan JSON reviewed",
            "workspace creation receipt reviewed",
        ]),
        "forbidden_source_types": _normalize_patch_behavior_text_list([
            "ad_hoc_shell_patch",
            "generated_unreviewed_diff",
            "network_downloaded_patch",
            "research_archive_direct_copy",
        ]),
        "allowed_target_files": allowed_target_files,
        "forbidden_target_paths": _normalize_implementation_branch_refs([
            ".agents",
            ".git",
            ".link",
            "research",
        ]),
        "forbidden_path_prefixes": list(PATCH_APPLIER_FORBIDDEN_PATH_PREFIXES),
        "max_files_changed": verified_patch_plan["estimated_files_changed"],
        "max_operations": len(verified_patch_plan["patch_operations"]),
        "max_estimated_added_lines": verified_patch_diff["estimated_added_lines"],
        "max_estimated_removed_lines": verified_patch_diff["estimated_removed_lines"],
        "allowed_operation_types": _normalize_patch_behavior_text_list(VERIFIED_PATCH_OPERATION_TYPES),
        "forbidden_operation_types": _normalize_patch_behavior_text_list(PATCH_APPLIER_FORBIDDEN_OPERATION_TYPES),
        "risky_operation_types": _normalize_patch_behavior_text_list(PATCH_APPLIER_RISKY_OPERATION_TYPES),
        "operation_requires_review": _normalize_patch_behavior_text_list([
            *PATCH_APPLIER_RISKY_OPERATION_TYPES,
            *operation_requires_review,
        ]),
        "quality_gate_required": True,
        "approval_required": True,
        "workspace_required": True,
        "evidence_required": True,
        "rollback_required": True,
        "fail_closed_conditions": fail_closed,
        "rollback_triggers": rollback_triggers,
        "cleanup_triggers": cleanup_triggers,
        "escalation_required_conditions": escalation_conditions,
        "required_patch_evidence": required_patch_evidence,
        "required_diff_evidence": required_diff_evidence,
        "required_file_hash_evidence": required_file_hash_evidence,
        "required_journal_evidence": required_journal_evidence,
        "required_reviewer_summary": True,
        "dry_run": True,
        "write_allowed": False,
        "automation_allowed": False,
        "metadata": dict(metadata or {}),
        "writes": [],
    }
    validate_patch_applier_boundary(
        boundary,
        verified_patch_plan,
        verified_patch_diff,
        execution_gate_stack_preview,
        execution_approval_checklist,
        execution_evidence_contract,
        workspace_creator_runtime_boundary,
        workspace_runtime_plan,
    )
    return boundary


def validate_patch_applier_boundary(
    boundary: dict[str, Any],
    verified_patch_plan: dict[str, Any] | None = None,
    verified_patch_diff: dict[str, Any] | None = None,
    execution_gate_stack_preview: dict[str, Any] | None = None,
    execution_approval_checklist: dict[str, Any] | None = None,
    execution_evidence_contract: dict[str, Any] | None = None,
    workspace_creator_runtime_boundary: dict[str, Any] | None = None,
    workspace_runtime_plan: dict[str, Any] | None = None,
) -> None:
    required = (
        "patch_applier_boundary_version", "patch_applier_boundary_id", "planning_chain_id",
        "verified_patch_plan_id", "verified_patch_diff_id", "execution_package_id",
        "workspace_boundary_id", "runtime_workspace_plan_id", "source_type",
        "allowed_source_ids", "required_source_evidence", "forbidden_source_types",
        "allowed_target_files", "forbidden_target_paths", "forbidden_path_prefixes",
        "max_files_changed", "max_operations", "max_estimated_added_lines",
        "max_estimated_removed_lines", "allowed_operation_types", "forbidden_operation_types",
        "risky_operation_types", "operation_requires_review", "quality_gate_required",
        "approval_required", "workspace_required", "evidence_required", "rollback_required",
        "fail_closed_conditions", "rollback_triggers", "cleanup_triggers",
        "escalation_required_conditions", "required_patch_evidence", "required_diff_evidence",
        "required_file_hash_evidence", "required_journal_evidence", "required_reviewer_summary",
        "dry_run", "write_allowed", "automation_allowed", "metadata", "writes",
    )
    missing = [field for field in required if field not in boundary]
    if missing:
        raise ValueError(f"patch applier boundary missing fields: {missing}")
    if boundary["patch_applier_boundary_version"] != PATCH_APPLIER_BOUNDARY_VERSION:
        raise ValueError("unsupported patch applier boundary version")
    _validate_execution_read_only(boundary, "patch applier boundary")
    for field in (
        "patch_applier_boundary_id", "planning_chain_id", "verified_patch_plan_id",
        "verified_patch_diff_id", "execution_package_id", "workspace_boundary_id",
        "runtime_workspace_plan_id", "source_type",
    ):
        _validate_non_empty_string(boundary[field], field)
    if boundary["source_type"] != "verified_patch_plan_and_diff":
        raise ValueError("patch source type must remain verified_patch_plan_and_diff")
    for field in ("max_files_changed", "max_operations", "max_estimated_added_lines", "max_estimated_removed_lines"):
        if not isinstance(boundary[field], int) or boundary[field] < 0:
            raise ValueError(f"{field} must be a non-negative integer")
    for field in ("quality_gate_required", "approval_required", "workspace_required", "evidence_required", "rollback_required", "required_reviewer_summary"):
        if boundary[field] is not True:
            raise ValueError(f"{field} must be true")
    ref_lists = (
        "allowed_source_ids", "allowed_target_files", "forbidden_target_paths",
        "required_patch_evidence", "required_diff_evidence", "required_file_hash_evidence",
        "required_journal_evidence", "required_source_evidence",
    )
    for field in ref_lists:
        values = boundary[field]
        if not isinstance(values, list) or not values:
            raise TypeError(f"{field} must be a non-empty list")
        if values != _normalize_implementation_branch_refs(values):
            raise ValueError(f"{field} must be normalized and sorted")
    text_lists = (
        "forbidden_source_types", "forbidden_path_prefixes", "allowed_operation_types",
        "forbidden_operation_types", "risky_operation_types", "operation_requires_review",
        "fail_closed_conditions", "rollback_triggers", "cleanup_triggers",
        "escalation_required_conditions",
    )
    for field in text_lists:
        values = boundary[field]
        if not isinstance(values, list) or not values:
            raise TypeError(f"{field} must be a non-empty list")
        if values != _normalize_patch_behavior_text_list(values):
            raise ValueError(f"{field} must be normalized and sorted")
    for target in boundary["allowed_target_files"]:
        _patch_applier_validate_target_path(target)
    forbidden_prefixes = tuple(boundary["forbidden_path_prefixes"])
    for target in boundary["allowed_target_files"]:
        if any(target == prefix.rstrip("/") or target.startswith(prefix) for prefix in forbidden_prefixes):
            raise ValueError("allowed target file overlaps forbidden path prefix")
    if set(boundary["allowed_operation_types"]) & set(boundary["forbidden_operation_types"]):
        raise ValueError("allowed operation types overlap forbidden operation types")
    if not set(boundary["risky_operation_types"]).issubset(set(boundary["allowed_operation_types"])):
        raise ValueError("risky operation types must be allowed operation types")
    if not set(boundary["risky_operation_types"]).issubset(set(boundary["operation_requires_review"])):
        raise ValueError("risky operation types must require review")
    for required_item in (
        "approval checklist is not pass",
        "gate stack contains block status",
        "patch target path is outside allowed workspace files",
    ):
        if required_item not in boundary["fail_closed_conditions"]:
            raise ValueError("patch applier boundary missing required fail-closed condition")
    expected_id = make_patch_applier_boundary_id(
        boundary["planning_chain_id"],
        boundary["verified_patch_plan_id"],
        boundary["verified_patch_diff_id"],
        boundary["execution_package_id"],
        boundary["workspace_boundary_id"],
        boundary["runtime_workspace_plan_id"],
    )
    if boundary["patch_applier_boundary_id"] != expected_id:
        raise ValueError("patch applier boundary id does not match contents")
    if verified_patch_plan is not None:
        validate_verified_patch_plan(verified_patch_plan)
        if boundary["verified_patch_plan_id"] != verified_patch_plan["verified_patch_plan_id"]:
            raise ValueError("patch applier boundary patch plan id mismatch")
        if boundary["allowed_target_files"] != verified_patch_plan["target_files"]:
            raise ValueError("patch applier boundary target files mismatch")
        if boundary["max_files_changed"] != verified_patch_plan["estimated_files_changed"]:
            raise ValueError("patch applier boundary max files mismatch")
        if boundary["max_operations"] != len(verified_patch_plan["patch_operations"]):
            raise ValueError("patch applier boundary max operations mismatch")
        operation_types = {operation["operation_type"] for operation in verified_patch_plan["patch_operations"]}
        if not operation_types.issubset(set(boundary["allowed_operation_types"])):
            raise ValueError("patch applier boundary missing allowed operation type")
    if verified_patch_diff is not None:
        validate_verified_patch_diff(verified_patch_diff)
        if boundary["verified_patch_diff_id"] != verified_patch_diff["verified_patch_diff_id"]:
            raise ValueError("patch applier boundary patch diff id mismatch")
        if verified_patch_plan is not None and verified_patch_diff["verified_patch_plan_id"] != verified_patch_plan["verified_patch_plan_id"]:
            raise ValueError("patch applier boundary diff does not match patch plan")
        if boundary["max_estimated_added_lines"] != verified_patch_diff["estimated_added_lines"]:
            raise ValueError("patch applier boundary added line limit mismatch")
        if boundary["max_estimated_removed_lines"] != verified_patch_diff["estimated_removed_lines"]:
            raise ValueError("patch applier boundary removed line limit mismatch")
    if execution_gate_stack_preview is not None:
        validate_execution_gate_stack_preview(execution_gate_stack_preview)
        if boundary["planning_chain_id"] != execution_gate_stack_preview["planning_chain_id"]:
            raise ValueError("patch applier boundary planning chain mismatch")
        if boundary["execution_package_id"] != execution_gate_stack_preview["execution_package_id"]:
            raise ValueError("patch applier boundary execution package mismatch")
    if execution_approval_checklist is not None:
        validate_execution_approval_checklist(execution_approval_checklist)
        if boundary["execution_package_id"] != execution_approval_checklist["execution_package_id"]:
            raise ValueError("patch applier boundary approval package mismatch")
    if execution_evidence_contract is not None:
        validate_execution_evidence_contract(execution_evidence_contract)
        evidence_types = {item["evidence_type"] for item in execution_evidence_contract["evidence_items"]}
        if "patch_application" not in evidence_types:
            raise ValueError("patch applier boundary requires patch application evidence contract")
    if workspace_creator_runtime_boundary is not None:
        validate_workspace_creator_runtime_boundary(workspace_creator_runtime_boundary)
        if boundary["workspace_boundary_id"] != workspace_creator_runtime_boundary["workspace_boundary_id"]:
            raise ValueError("patch applier boundary workspace boundary mismatch")
    if workspace_runtime_plan is not None:
        validate_workspace_creator_runtime_plan(workspace_runtime_plan)
        if boundary["runtime_workspace_plan_id"] != workspace_runtime_plan["runtime_workspace_plan_id"]:
            raise ValueError("patch applier boundary workspace runtime plan mismatch")
        if boundary["execution_package_id"] != workspace_runtime_plan["execution_package_id"]:
            raise ValueError("patch applier boundary runtime execution package mismatch")


def stable_patch_applier_boundary_json(boundary: dict[str, Any]) -> str:
    validate_patch_applier_boundary(boundary)
    return _stable_ruflo_json(boundary, indent=2) + "\n"


def parse_patch_applier_boundary_json(text: str) -> dict[str, Any]:
    boundary = json.loads(text)
    validate_patch_applier_boundary(boundary)
    return boundary



GUARDED_PATCH_APPLIER_VERSION = "link-guarded-patch-applier-v1"
GUARDED_PATCH_RECEIPT_VERSION = "link-guarded-patch-receipt-v1"


def make_guarded_patch_request_id(
    patch_applier_boundary_id: str,
    workspace_id: str,
    workspace_path: str,
    approved: bool,
    write: bool,
) -> str:
    return _execution_readiness_id("guarded-patch-request", {
        "approved": approved,
        "patch_applier_boundary_id": patch_applier_boundary_id,
        "version": GUARDED_PATCH_APPLIER_VERSION,
        "workspace_id": workspace_id,
        "workspace_path": workspace_path,
        "write": write,
    })


def make_guarded_patch_receipt_id(
    request_id: str,
    patch_applier_boundary_id: str,
    workspace_id: str,
    patch_hash: str,
) -> str:
    return _execution_readiness_id("guarded-patch-receipt", {
        "patch_applier_boundary_id": patch_applier_boundary_id,
        "patch_hash": patch_hash,
        "request_id": request_id,
        "version": GUARDED_PATCH_RECEIPT_VERSION,
        "workspace_id": workspace_id,
    })


def make_guarded_patch_request(
    patch_applier_boundary: dict[str, Any],
    workspace_creation_receipt: dict[str, Any],
    *,
    approved: bool = False,
    write: bool = False,
    metadata: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Build a guarded patch request without touching files."""
    validate_patch_applier_boundary(patch_applier_boundary)
    validate_workspace_creation_receipt(workspace_creation_receipt)
    request = {
        "guarded_patch_applier_version": GUARDED_PATCH_APPLIER_VERSION,
        "request_id": make_guarded_patch_request_id(
            patch_applier_boundary["patch_applier_boundary_id"],
            workspace_creation_receipt["workspace_id"],
            workspace_creation_receipt["workspace_path"],
            approved,
            write,
        ),
        "planning_chain_id": patch_applier_boundary["planning_chain_id"],
        "execution_package_id": patch_applier_boundary["execution_package_id"],
        "patch_applier_boundary_id": patch_applier_boundary["patch_applier_boundary_id"],
        "verified_patch_plan_id": patch_applier_boundary["verified_patch_plan_id"],
        "verified_patch_diff_id": patch_applier_boundary["verified_patch_diff_id"],
        "workspace_id": workspace_creation_receipt["workspace_id"],
        "workspace_path": workspace_creation_receipt["workspace_path"],
        "creation_receipt_id": workspace_creation_receipt["creation_receipt_id"],
        "approved": approved,
        "write": write,
        "dry_run": not write,
        "metadata": dict(metadata or {}),
    }
    validate_guarded_patch_request(request, patch_applier_boundary, workspace_creation_receipt)
    return request


def _guarded_patch_repo_root():
    from pathlib import Path

    return Path.cwd().resolve(strict=False)


def _guarded_patch_workspace_path(path: str):
    from pathlib import Path

    workspace = Path(path).expanduser().resolve(strict=False)
    repo_root = _guarded_patch_repo_root()
    try:
        workspace.relative_to(repo_root)
    except ValueError:
        pass
    else:
        raise ValueError("guarded patch workspace must be outside the repository root")
    return workspace


def _guarded_patch_target_path(workspace_path: str, file_path: str):
    workspace = _guarded_patch_workspace_path(workspace_path)
    _patch_applier_validate_target_path(file_path)
    target = (workspace / file_path).resolve(strict=False)
    try:
        target.relative_to(workspace)
    except ValueError as exc:
        raise ValueError("guarded patch target must stay inside workspace") from exc
    return target


def _guarded_patch_file_hash(path) -> str:
    import hashlib

    if not path.exists() or not path.is_file():
        return ""
    return hashlib.sha256(path.read_bytes()).hexdigest()


def _guarded_patch_diff_hash(verified_patch_diff: dict[str, Any]) -> str:
    import hashlib

    return hashlib.sha256(stable_verified_patch_diff_json(verified_patch_diff).encode("utf-8")).hexdigest()


def validate_guarded_patch_request(
    request: dict[str, Any],
    patch_applier_boundary: dict[str, Any] | None = None,
    workspace_creation_receipt: dict[str, Any] | None = None,
) -> None:
    required = (
        "guarded_patch_applier_version", "request_id", "planning_chain_id", "execution_package_id",
        "patch_applier_boundary_id", "verified_patch_plan_id", "verified_patch_diff_id",
        "workspace_id", "workspace_path", "creation_receipt_id", "approved", "write", "dry_run", "metadata",
    )
    missing = [field for field in required if field not in request]
    if missing:
        raise ValueError(f"guarded patch request missing fields: {missing}")
    if request["guarded_patch_applier_version"] != GUARDED_PATCH_APPLIER_VERSION:
        raise ValueError("unsupported guarded patch applier version")
    for field in (
        "request_id", "planning_chain_id", "execution_package_id", "patch_applier_boundary_id",
        "verified_patch_plan_id", "verified_patch_diff_id", "workspace_id", "workspace_path", "creation_receipt_id",
    ):
        _validate_non_empty_string(request[field], field)
    if not isinstance(request["approved"], bool) or not isinstance(request["write"], bool):
        raise TypeError("approved and write must be booleans")
    if request["dry_run"] != (not request["write"]):
        raise ValueError("guarded patch request dry_run must invert write")
    if not isinstance(request["metadata"], dict):
        raise TypeError("metadata must be a dict")
    _guarded_patch_workspace_path(request["workspace_path"])
    expected_id = make_guarded_patch_request_id(
        request["patch_applier_boundary_id"],
        request["workspace_id"],
        request["workspace_path"],
        request["approved"],
        request["write"],
    )
    if request["request_id"] != expected_id:
        raise ValueError("guarded patch request id does not match contents")
    if request["write"] and not request["approved"]:
        raise PermissionError("guarded patch application requires explicit approval")
    if patch_applier_boundary is not None:
        validate_patch_applier_boundary(patch_applier_boundary)
        expected_refs = {
            "planning_chain_id": patch_applier_boundary["planning_chain_id"],
            "execution_package_id": patch_applier_boundary["execution_package_id"],
            "patch_applier_boundary_id": patch_applier_boundary["patch_applier_boundary_id"],
            "verified_patch_plan_id": patch_applier_boundary["verified_patch_plan_id"],
            "verified_patch_diff_id": patch_applier_boundary["verified_patch_diff_id"],
        }
        for field, value in expected_refs.items():
            if request[field] != value:
                raise ValueError(f"guarded patch request {field} does not match boundary")
    if workspace_creation_receipt is not None:
        validate_workspace_creation_receipt(workspace_creation_receipt)
        if request["workspace_id"] != workspace_creation_receipt["workspace_id"]:
            raise ValueError("guarded patch request workspace id mismatch")
        if request["workspace_path"] != workspace_creation_receipt["workspace_path"]:
            raise ValueError("guarded patch request workspace path mismatch")
        if request["creation_receipt_id"] != workspace_creation_receipt["creation_receipt_id"]:
            raise ValueError("guarded patch request creation receipt mismatch")
        if request["write"] and workspace_creation_receipt["status"] != "created":
            raise PermissionError("guarded patch application requires a created workspace")


def _guarded_patch_operation_text(operation: dict[str, Any]) -> str:
    prefix = "#"
    if operation["file_path"].lower().endswith((".md", ".rst", ".txt")):
        prefix = "<!--"
        suffix = " -->"
    else:
        suffix = ""
    if prefix == "<!--":
        return (
            f"\n<!-- Link guarded patch operation: {operation['operation_id']} -->\n"
            f"<!-- Expected result: {operation['expected_result']} -->\n"
        )
    return (
        f"\n# Link guarded patch operation: {operation['operation_id']}\n"
        f"# Expected result: {operation['expected_result']}\n"
    )


def _apply_guarded_patch_operation(workspace_path: str, operation: dict[str, Any]) -> dict[str, Any]:
    target = _guarded_patch_target_path(workspace_path, operation["file_path"])
    before_hash = _guarded_patch_file_hash(target)
    operation_type = operation["operation_type"]
    target.parent.mkdir(parents=True, exist_ok=True)
    if operation_type == "delete_file":
        if target.exists() and target.is_file():
            target.unlink()
        status = "deleted"
    elif operation_type in {"create_file", "add_test"}:
        if target.exists():
            raise FileExistsError("guarded patch create operation refuses to overwrite existing file")
        target.write_text(_guarded_patch_operation_text(operation), encoding="utf-8")
        status = "created"
    elif operation_type in {"modify_file", "update_test", "documentation_update"}:
        existing = target.read_text(encoding="utf-8") if target.exists() else ""
        target.write_text(existing + _guarded_patch_operation_text(operation), encoding="utf-8")
        status = "modified"
    else:
        raise ValueError(f"unsupported guarded patch operation type: {operation_type}")
    after_hash = _guarded_patch_file_hash(target)
    return {
        "operation_id": operation["operation_id"],
        "operation_type": operation_type,
        "file_path": operation["file_path"],
        "status": status,
        "before_hash": before_hash,
        "after_hash": after_hash,
    }


def collect_guarded_patch_receipt(
    request: dict[str, Any],
    patch_applier_boundary: dict[str, Any],
    verified_patch_plan: dict[str, Any],
    verified_patch_diff: dict[str, Any],
    workspace_creation_receipt: dict[str, Any],
    *,
    applied_operations: list[dict[str, Any]],
    skipped_operations: list[dict[str, Any]] | None = None,
    receipt_timestamp: str = "preview-only",
    status: str = "preview",
    metadata: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Collect a guarded patch receipt from already-applied workspace-local operations."""
    validate_guarded_patch_request(request, patch_applier_boundary, workspace_creation_receipt)
    validate_patch_applier_boundary(patch_applier_boundary, verified_patch_plan, verified_patch_diff)
    validate_verified_patch_plan(verified_patch_plan)
    validate_verified_patch_diff(verified_patch_diff)
    validate_workspace_creation_receipt(workspace_creation_receipt)
    applied = sorted([dict(item) for item in applied_operations], key=lambda item: item["operation_id"])
    skipped = sorted([dict(item) for item in (skipped_operations or [])], key=lambda item: item["operation_id"])
    before_hashes = {item["file_path"]: item["before_hash"] for item in applied}
    after_hashes = {item["file_path"]: item["after_hash"] for item in applied}
    changed_files = _normalize_implementation_branch_refs([item["file_path"] for item in applied if item["before_hash"] != item["after_hash"]])
    patch_hash = _guarded_patch_diff_hash(verified_patch_diff)
    safety = {
        "dry_run": not request["write"],
        "write_allowed": bool(request["write"]),
        "automation_allowed": False,
        "writes": changed_files if request["write"] else [],
    }
    receipt = {
        "guarded_patch_receipt_version": GUARDED_PATCH_RECEIPT_VERSION,
        "guarded_patch_receipt_id": make_guarded_patch_receipt_id(
            request["request_id"],
            patch_applier_boundary["patch_applier_boundary_id"],
            workspace_creation_receipt["workspace_id"],
            patch_hash,
        ),
        "request_id": request["request_id"],
        "workspace_id": workspace_creation_receipt["workspace_id"],
        "workspace_path": workspace_creation_receipt["workspace_path"],
        "patch_applier_boundary_id": patch_applier_boundary["patch_applier_boundary_id"],
        "verified_patch_plan_id": verified_patch_plan["verified_patch_plan_id"],
        "verified_patch_diff_id": verified_patch_diff["verified_patch_diff_id"],
        "applied_operations": applied,
        "skipped_operations": skipped,
        "before_file_hashes": before_hashes,
        "after_file_hashes": after_hashes,
        "patch_hash": patch_hash,
        "changed_files": changed_files,
        "added_lines": verified_patch_diff["estimated_added_lines"],
        "removed_lines": verified_patch_diff["estimated_removed_lines"],
        "modified_lines": verified_patch_diff["estimated_modified_lines"],
        "receipt_timestamp": receipt_timestamp,
        "status": status,
        "safety_metadata": safety,
        "metadata": dict(metadata or {}),
    }
    validate_guarded_patch_receipt(receipt, request, patch_applier_boundary, verified_patch_plan, verified_patch_diff, workspace_creation_receipt)
    return receipt


def validate_guarded_patch_receipt(
    receipt: dict[str, Any],
    request: dict[str, Any] | None = None,
    patch_applier_boundary: dict[str, Any] | None = None,
    verified_patch_plan: dict[str, Any] | None = None,
    verified_patch_diff: dict[str, Any] | None = None,
    workspace_creation_receipt: dict[str, Any] | None = None,
) -> None:
    required = (
        "guarded_patch_receipt_version", "guarded_patch_receipt_id", "request_id", "workspace_id",
        "workspace_path", "patch_applier_boundary_id", "verified_patch_plan_id", "verified_patch_diff_id",
        "applied_operations", "skipped_operations", "before_file_hashes", "after_file_hashes",
        "patch_hash", "changed_files", "added_lines", "removed_lines", "modified_lines",
        "receipt_timestamp", "status", "safety_metadata", "metadata",
    )
    missing = [field for field in required if field not in receipt]
    if missing:
        raise ValueError(f"guarded patch receipt missing fields: {missing}")
    if receipt["guarded_patch_receipt_version"] != GUARDED_PATCH_RECEIPT_VERSION:
        raise ValueError("unsupported guarded patch receipt version")
    for field in (
        "guarded_patch_receipt_id", "request_id", "workspace_id", "workspace_path",
        "patch_applier_boundary_id", "verified_patch_plan_id", "verified_patch_diff_id",
        "patch_hash", "receipt_timestamp", "status",
    ):
        _validate_non_empty_string(receipt[field], field)
    if receipt["status"] not in {"preview", "applied"}:
        raise ValueError("invalid guarded patch receipt status")
    for field in ("applied_operations", "skipped_operations"):
        if not isinstance(receipt[field], list):
            raise TypeError(f"{field} must be a list")
    for item in receipt["applied_operations"] + receipt["skipped_operations"]:
        for field in ("operation_id", "operation_type", "file_path", "status"):
            _validate_non_empty_string(item.get(field), f"guarded patch operation {field}")
        _patch_applier_validate_target_path(item["file_path"])
        if item["operation_type"] not in VERIFIED_PATCH_OPERATION_TYPES:
            raise ValueError("guarded patch receipt contains invalid operation type")
    for field in ("before_file_hashes", "after_file_hashes", "safety_metadata", "metadata"):
        if not isinstance(receipt[field], dict):
            raise TypeError(f"{field} must be a dict")
    if receipt["changed_files"] != _normalize_implementation_branch_refs(receipt["changed_files"]):
        raise ValueError("guarded patch changed_files must be normalized")
    for field in ("added_lines", "removed_lines", "modified_lines"):
        if not isinstance(receipt[field], int) or receipt[field] < 0:
            raise ValueError(f"{field} must be a non-negative integer")
    safety = receipt["safety_metadata"]
    if safety.get("automation_allowed") is not False:
        raise ValueError("guarded patch receipt must keep automation disabled")
    if not isinstance(safety.get("writes"), list):
        raise TypeError("guarded patch receipt safety writes must be a list")
    if safety["writes"] != _normalize_implementation_branch_refs(safety["writes"]):
        raise ValueError("guarded patch receipt safety writes must be normalized")
    if receipt["status"] == "preview":
        if safety.get("dry_run") is not True or safety.get("write_allowed") is not False or safety["writes"] != []:
            raise ValueError("guarded patch preview receipt must be read-only")
    if receipt["status"] == "applied":
        if safety.get("dry_run") is not False or safety.get("write_allowed") is not True:
            raise ValueError("guarded patch applied receipt must record write allowance")
        if safety["writes"] != receipt["changed_files"]:
            raise ValueError("guarded patch applied receipt writes must match changed files")
    expected_id = make_guarded_patch_receipt_id(
        receipt["request_id"],
        receipt["patch_applier_boundary_id"],
        receipt["workspace_id"],
        receipt["patch_hash"],
    )
    if receipt["guarded_patch_receipt_id"] != expected_id:
        raise ValueError("guarded patch receipt id does not match contents")
    if request is not None:
        validate_guarded_patch_request(request)
        if receipt["request_id"] != request["request_id"]:
            raise ValueError("guarded patch receipt request mismatch")
        if receipt["status"] == "applied" and not request["write"]:
            raise ValueError("guarded patch applied receipt requires write request")
    if patch_applier_boundary is not None:
        validate_patch_applier_boundary(patch_applier_boundary)
        if receipt["patch_applier_boundary_id"] != patch_applier_boundary["patch_applier_boundary_id"]:
            raise ValueError("guarded patch receipt boundary mismatch")
    if verified_patch_plan is not None:
        validate_verified_patch_plan(verified_patch_plan)
        if receipt["verified_patch_plan_id"] != verified_patch_plan["verified_patch_plan_id"]:
            raise ValueError("guarded patch receipt patch plan mismatch")
        operation_ids = {operation["operation_id"] for operation in verified_patch_plan["patch_operations"]}
        applied_ids = {operation["operation_id"] for operation in receipt["applied_operations"]}
        skipped_ids = {operation["operation_id"] for operation in receipt["skipped_operations"]}
        if applied_ids | skipped_ids != operation_ids:
            raise ValueError("guarded patch receipt must account for every operation")
    if verified_patch_diff is not None:
        validate_verified_patch_diff(verified_patch_diff)
        if receipt["verified_patch_diff_id"] != verified_patch_diff["verified_patch_diff_id"]:
            raise ValueError("guarded patch receipt patch diff mismatch")
        if receipt["patch_hash"] != _guarded_patch_diff_hash(verified_patch_diff):
            raise ValueError("guarded patch receipt patch hash mismatch")
    if workspace_creation_receipt is not None:
        validate_workspace_creation_receipt(workspace_creation_receipt)
        if receipt["workspace_id"] != workspace_creation_receipt["workspace_id"]:
            raise ValueError("guarded patch receipt workspace mismatch")
        if receipt["workspace_path"] != workspace_creation_receipt["workspace_path"]:
            raise ValueError("guarded patch receipt workspace path mismatch")


def _validate_guarded_patch_runtime_inputs(
    request: dict[str, Any],
    patch_applier_boundary: dict[str, Any],
    verified_patch_plan: dict[str, Any],
    verified_patch_diff: dict[str, Any],
    workspace_creation_receipt: dict[str, Any],
    workspace_manifest: dict[str, Any],
    execution_approval_checklist: dict[str, Any],
    execution_gate_stack_preview: dict[str, Any],
    execution_evidence_contract: dict[str, Any],
) -> None:
    validate_guarded_patch_request(request, patch_applier_boundary, workspace_creation_receipt)
    validate_patch_applier_boundary(
        patch_applier_boundary,
        verified_patch_plan,
        verified_patch_diff,
        execution_gate_stack_preview,
        execution_approval_checklist,
        execution_evidence_contract,
    )
    validate_workspace_creation_receipt(workspace_creation_receipt)
    validate_execution_approval_checklist(execution_approval_checklist)
    validate_execution_gate_stack_preview(execution_gate_stack_preview)
    validate_execution_evidence_contract(execution_evidence_contract)
    if workspace_manifest != workspace_creation_receipt["workspace_manifest"]:
        raise ValueError("workspace manifest must match workspace creation receipt")
    if request["write"]:
        if execution_approval_checklist["approval_status"] != "pass":
            raise PermissionError("guarded patch application requires passing approval checklist")
        if execution_gate_stack_preview["block_count"]:
            raise PermissionError("guarded patch application blocked by gate stack")
        if workspace_creation_receipt["status"] != "created":
            raise PermissionError("guarded patch application requires a created workspace")
        workspace_path = _guarded_patch_workspace_path(workspace_creation_receipt["workspace_path"])
        if not workspace_path.exists() or not workspace_path.is_dir():
            raise FileNotFoundError("guarded patch workspace does not exist")
        manifest_path = workspace_path / "workspace_manifest.json"
        if not manifest_path.exists():
            raise FileNotFoundError("guarded patch workspace manifest is missing")
        on_disk_manifest = json.loads(manifest_path.read_text(encoding="utf-8"))
        if on_disk_manifest != workspace_manifest:
            raise ValueError("on-disk workspace manifest does not match receipt")
    if len(verified_patch_plan["patch_operations"]) > patch_applier_boundary["max_operations"]:
        raise ValueError("guarded patch operation count exceeds boundary")
    if len(verified_patch_plan["target_files"]) > patch_applier_boundary["max_files_changed"]:
        raise ValueError("guarded patch target file count exceeds boundary")
    if verified_patch_diff["estimated_added_lines"] > patch_applier_boundary["max_estimated_added_lines"]:
        raise ValueError("guarded patch added lines exceed boundary")
    if verified_patch_diff["estimated_removed_lines"] > patch_applier_boundary["max_estimated_removed_lines"]:
        raise ValueError("guarded patch removed lines exceed boundary")
    allowed_targets = set(patch_applier_boundary["allowed_target_files"])
    allowed_operations = set(patch_applier_boundary["allowed_operation_types"])
    for operation in verified_patch_plan["patch_operations"]:
        if operation["file_path"] not in allowed_targets:
            raise ValueError("guarded patch operation target is not allowed")
        if operation["operation_type"] not in allowed_operations:
            raise ValueError("guarded patch operation type is not allowed")
        _guarded_patch_target_path(workspace_creation_receipt["workspace_path"], operation["file_path"])


def preview_guarded_patch_application(
    request: dict[str, Any],
    patch_applier_boundary: dict[str, Any],
    verified_patch_plan: dict[str, Any],
    verified_patch_diff: dict[str, Any],
    workspace_creation_receipt: dict[str, Any],
    workspace_manifest: dict[str, Any],
    execution_approval_checklist: dict[str, Any],
    execution_gate_stack_preview: dict[str, Any],
    execution_evidence_contract: dict[str, Any],
) -> dict[str, Any]:
    _validate_guarded_patch_runtime_inputs(
        request,
        patch_applier_boundary,
        verified_patch_plan,
        verified_patch_diff,
        workspace_creation_receipt,
        workspace_manifest,
        execution_approval_checklist,
        execution_gate_stack_preview,
        execution_evidence_contract,
    )
    skipped = [
        {
            "operation_id": operation["operation_id"],
            "operation_type": operation["operation_type"],
            "file_path": operation["file_path"],
            "status": "preview_only",
        }
        for operation in verified_patch_plan["patch_operations"]
    ]
    return collect_guarded_patch_receipt(
        request,
        patch_applier_boundary,
        verified_patch_plan,
        verified_patch_diff,
        workspace_creation_receipt,
        applied_operations=[],
        skipped_operations=skipped,
        status="preview",
    )


def apply_guarded_patch(
    request: dict[str, Any],
    patch_applier_boundary: dict[str, Any],
    verified_patch_plan: dict[str, Any],
    verified_patch_diff: dict[str, Any],
    workspace_creation_receipt: dict[str, Any],
    workspace_manifest: dict[str, Any],
    execution_approval_checklist: dict[str, Any],
    execution_gate_stack_preview: dict[str, Any],
    execution_evidence_contract: dict[str, Any],
) -> dict[str, Any]:
    """Apply verified patch operations only inside a guarded temporary workspace."""
    import shutil
    from datetime import datetime, timezone

    _validate_guarded_patch_runtime_inputs(
        request,
        patch_applier_boundary,
        verified_patch_plan,
        verified_patch_diff,
        workspace_creation_receipt,
        workspace_manifest,
        execution_approval_checklist,
        execution_gate_stack_preview,
        execution_evidence_contract,
    )
    if not request["write"]:
        raise PermissionError("guarded patch application requires --write")
    if not request["approved"]:
        raise PermissionError("guarded patch application requires explicit approval")
    workspace_path = _guarded_patch_workspace_path(workspace_creation_receipt["workspace_path"])
    backup_path = workspace_path.parent / f".{workspace_path.name}.patch-backup-{request['request_id']}"
    if backup_path.exists():
        shutil.rmtree(backup_path)
    shutil.copytree(workspace_path, backup_path)
    try:
        applied = [_apply_guarded_patch_operation(str(workspace_path), operation) for operation in verified_patch_plan["patch_operations"]]
        timestamp = datetime.now(timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")
        receipt = collect_guarded_patch_receipt(
            request,
            patch_applier_boundary,
            verified_patch_plan,
            verified_patch_diff,
            workspace_creation_receipt,
            applied_operations=applied,
            skipped_operations=[],
            receipt_timestamp=timestamp,
            status="applied",
        )
        receipt_path = workspace_path / "guarded_patch_receipt.json"
        receipt_path.write_text(_stable_ruflo_json(receipt, indent=2) + "\n", encoding="utf-8")
        shutil.rmtree(backup_path)
        return receipt
    except Exception:
        if workspace_path.exists():
            shutil.rmtree(workspace_path)
        shutil.copytree(backup_path, workspace_path)
        shutil.rmtree(backup_path)
        raise



VERIFICATION_RUNNER_BOUNDARY_VERSION = "link-verification-runner-boundary-v1"
_ALLOWED_VERIFICATION_ACTIONS = ("compile", "tests", "healthcheck")
_OPTIONAL_VERIFICATION_ACTIONS = ("quality_gate_review", "log_summarization")
_FORBIDDEN_VERIFICATION_ACTIONS = ("git", "network", "package_install", "publish", "deploy", "branch", "worktree")
_ALLOWED_COMMAND_FAMILIES = ("python3",)
_FORBIDDEN_COMMAND_FAMILIES = ("bash", "bun", "curl", "git", "node", "npm", "npx", "sh", "wget")


def make_verification_runner_boundary_id(
    planning_chain_id: str,
    execution_package_id: str,
    patch_applier_boundary_id: str,
    guarded_patch_receipt_id: str,
    retry_policy_id: str,
    evidence_contract_id: str,
) -> str:
    return _execution_readiness_id("verification-runner-boundary", {
        "execution_evidence_contract_id": evidence_contract_id,
        "execution_package_id": execution_package_id,
        "guarded_patch_receipt_id": guarded_patch_receipt_id,
        "patch_applier_boundary_id": patch_applier_boundary_id,
        "planning_chain_id": planning_chain_id,
        "retry_policy_id": retry_policy_id,
        "version": VERIFICATION_RUNNER_BOUNDARY_VERSION,
    })


def _verification_boundary_command_patterns() -> list[str]:
    return _normalize_patch_behavior_text_list([
        "python3 -m py_compile <allowed files>",
        "PYTHONDONTWRITEBYTECODE=1 python3 tests/test_growth_pipeline.py",
        "PYTHONDONTWRITEBYTECODE=1 python3 link_healthcheck.py",
    ])


def _verification_boundary_required_evidence(contract: dict[str, Any], evidence_type: str, required_field: str) -> list[str]:
    refs: list[str] = []
    for item in contract["evidence_items"]:
        if item["evidence_type"] == evidence_type and required_field in item["required_fields"]:
            refs.append(f"{item['evidence_id']}:{required_field}")
    return _normalize_implementation_branch_refs(refs)


def collect_verification_runner_boundary(
    guarded_patch_receipt: dict[str, Any],
    patch_applier_boundary: dict[str, Any],
    execution_evidence_contract: dict[str, Any],
    execution_retry_policy: dict[str, Any],
    execution_gate_stack_preview: dict[str, Any],
    execution_approval_checklist: dict[str, Any],
    execution_preflight_checklist: dict[str, Any],
    execution_review: dict[str, Any],
    *,
    metadata: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Return the read-only boundary for future verification execution."""
    validate_guarded_patch_receipt(guarded_patch_receipt)
    validate_patch_applier_boundary(patch_applier_boundary)
    validate_execution_evidence_contract(execution_evidence_contract)
    validate_execution_retry_policy(execution_retry_policy)
    validate_execution_gate_stack_preview(execution_gate_stack_preview)
    validate_execution_approval_checklist(execution_approval_checklist)
    validate_execution_preflight_checklist(execution_preflight_checklist)
    validate_execution_review(execution_review)
    evidence_types = {item["evidence_type"] for item in execution_evidence_contract["evidence_items"]}
    required_stages = _normalize_patch_behavior_text_list(["compile", "healthcheck", "tests"])
    missing_stages = [stage for stage in required_stages if stage not in evidence_types]
    if missing_stages:
        raise ValueError(f"verification boundary missing evidence stages: {missing_stages}")
    action_requires_review = _normalize_patch_behavior_text_list([
        "any command outside allowlist requires human review",
        "any retry after failure requires human review",
        "any rollback trigger requires human review",
    ])
    fail_closed = _normalize_patch_behavior_text_list([
        "approval checklist is not pass",
        "command family is not allowlisted",
        "evidence contract is missing command evidence",
        "guarded patch receipt is not applied",
        "preflight checklist is block",
        "workspace path is inside repository root",
    ])
    rollback_triggers = _normalize_patch_behavior_text_list([
        "compile command exits nonzero after patch application",
        "healthcheck command exits nonzero after patch application",
        "required evidence cannot be produced",
        "test command exits nonzero after patch application",
    ])
    cleanup_triggers = _normalize_patch_behavior_text_list([
        "verification boundary validation fails before command execution",
        "workspace is abandoned before verification",
    ])
    escalation_conditions = _normalize_patch_behavior_text_list([
        *execution_retry_policy["escalation_conditions"],
        "verification command requests forbidden runtime family",
    ])
    boundary = {
        "verification_runner_boundary_version": VERIFICATION_RUNNER_BOUNDARY_VERSION,
        "verification_runner_boundary_id": make_verification_runner_boundary_id(
            guarded_patch_receipt["request_id"].split("guarded-patch-request-", 1)[-1] if False else patch_applier_boundary["planning_chain_id"],
            patch_applier_boundary["execution_package_id"],
            patch_applier_boundary["patch_applier_boundary_id"],
            guarded_patch_receipt["guarded_patch_receipt_id"],
            execution_retry_policy["retry_policy_id"],
            execution_evidence_contract["execution_evidence_contract_id"],
        ),
        "planning_chain_id": patch_applier_boundary["planning_chain_id"],
        "execution_package_id": patch_applier_boundary["execution_package_id"],
        "patch_applier_boundary_id": patch_applier_boundary["patch_applier_boundary_id"],
        "guarded_patch_receipt_id": guarded_patch_receipt["guarded_patch_receipt_id"],
        "workspace_id": guarded_patch_receipt["workspace_id"],
        "workspace_path": guarded_patch_receipt["workspace_path"],
        "execution_evidence_contract_id": execution_evidence_contract["execution_evidence_contract_id"],
        "retry_policy_id": execution_retry_policy["retry_policy_id"],
        "gate_stack_preview_id": execution_gate_stack_preview["gate_stack_preview_id"],
        "approval_checklist_id": execution_approval_checklist["approval_checklist_id"],
        "preflight_checklist_id": execution_preflight_checklist["preflight_checklist_id"],
        "execution_review_id": execution_review["execution_review_id"],
        "allowed_verification_actions": _normalize_patch_behavior_text_list(_ALLOWED_VERIFICATION_ACTIONS),
        "required_verification_actions": required_stages,
        "optional_verification_actions": _normalize_patch_behavior_text_list(_OPTIONAL_VERIFICATION_ACTIONS),
        "forbidden_verification_actions": _normalize_patch_behavior_text_list(_FORBIDDEN_VERIFICATION_ACTIONS),
        "action_requires_review": action_requires_review,
        "allowed_command_families": _normalize_patch_behavior_text_list(_ALLOWED_COMMAND_FAMILIES),
        "forbidden_command_families": _normalize_patch_behavior_text_list(_FORBIDDEN_COMMAND_FAMILIES),
        "allowed_command_patterns": _verification_boundary_command_patterns(),
        "forbidden_command_patterns": _normalize_patch_behavior_text_list([
            "* && *",
            "* | *",
            "bash *",
            "bun *",
            "curl *",
            "git *",
            "node *",
            "npm *",
            "npx *",
            "sh *",
            "wget *",
        ]),
        "max_command_count": 3,
        "max_runtime_seconds": 600,
        "per_command_timeout_seconds": 240,
        "required_command_evidence": _normalize_implementation_branch_refs(_verification_boundary_required_evidence(execution_evidence_contract, "compile", "command") + _verification_boundary_required_evidence(execution_evidence_contract, "tests", "command") + _verification_boundary_required_evidence(execution_evidence_contract, "healthcheck", "command")),
        "required_exit_code_evidence": _normalize_implementation_branch_refs(_verification_boundary_required_evidence(execution_evidence_contract, "compile", "exit_code") + _verification_boundary_required_evidence(execution_evidence_contract, "tests", "exit_code") + _verification_boundary_required_evidence(execution_evidence_contract, "healthcheck", "exit_code")),
        "required_stdout_log_evidence": _normalize_implementation_branch_refs(_verification_boundary_required_evidence(execution_evidence_contract, "compile", "stdout_log_ref") + _verification_boundary_required_evidence(execution_evidence_contract, "tests", "stdout_log_ref") + _verification_boundary_required_evidence(execution_evidence_contract, "healthcheck", "stdout_log_ref")),
        "required_stderr_log_evidence": _normalize_implementation_branch_refs(_verification_boundary_required_evidence(execution_evidence_contract, "compile", "stderr_log_ref") + _verification_boundary_required_evidence(execution_evidence_contract, "tests", "stderr_log_ref") + _verification_boundary_required_evidence(execution_evidence_contract, "healthcheck", "stderr_log_ref")),
        "required_file_hash_evidence": _verification_boundary_required_evidence(execution_evidence_contract, "patch_application", "changed_file_hashes"),
        "required_diff_hash_evidence": _verification_boundary_required_evidence(execution_evidence_contract, "patch_application", "diff_hash"),
        "required_journal_evidence": _normalize_implementation_branch_refs(_verification_boundary_required_evidence(execution_evidence_contract, "compile", "journal_entry_id") + _verification_boundary_required_evidence(execution_evidence_contract, "tests", "journal_entry_id") + _verification_boundary_required_evidence(execution_evidence_contract, "healthcheck", "journal_entry_id")),
        "required_reviewer_summary": True,
        "max_attempts": execution_retry_policy["max_attempts"],
        "retryable_failure_types": _normalize_patch_behavior_text_list(execution_retry_policy["retryable_failures"]),
        "non_retryable_failure_types": _normalize_patch_behavior_text_list(execution_retry_policy["non_retryable_failures"]),
        "stop_conditions": _normalize_patch_behavior_text_list(execution_retry_policy["stop_conditions"]),
        "fail_closed_conditions": fail_closed,
        "rollback_triggers": rollback_triggers,
        "cleanup_triggers": cleanup_triggers,
        "escalation_required_conditions": escalation_conditions,
        "dry_run": True,
        "write_allowed": False,
        "automation_allowed": False,
        "metadata": dict(metadata or {}),
        "writes": [],
    }
    validate_verification_runner_boundary(
        boundary,
        guarded_patch_receipt,
        patch_applier_boundary,
        execution_evidence_contract,
        execution_retry_policy,
        execution_gate_stack_preview,
        execution_approval_checklist,
        execution_preflight_checklist,
        execution_review,
    )
    return boundary


def validate_verification_runner_boundary(
    boundary: dict[str, Any],
    guarded_patch_receipt: dict[str, Any] | None = None,
    patch_applier_boundary: dict[str, Any] | None = None,
    execution_evidence_contract: dict[str, Any] | None = None,
    execution_retry_policy: dict[str, Any] | None = None,
    execution_gate_stack_preview: dict[str, Any] | None = None,
    execution_approval_checklist: dict[str, Any] | None = None,
    execution_preflight_checklist: dict[str, Any] | None = None,
    execution_review: dict[str, Any] | None = None,
) -> None:
    required = (
        "verification_runner_boundary_version", "verification_runner_boundary_id", "planning_chain_id",
        "execution_package_id", "patch_applier_boundary_id", "guarded_patch_receipt_id",
        "workspace_id", "workspace_path", "execution_evidence_contract_id", "retry_policy_id",
        "gate_stack_preview_id", "approval_checklist_id", "preflight_checklist_id",
        "execution_review_id", "allowed_verification_actions", "required_verification_actions",
        "optional_verification_actions", "forbidden_verification_actions", "action_requires_review",
        "allowed_command_families", "forbidden_command_families", "allowed_command_patterns",
        "forbidden_command_patterns", "max_command_count", "max_runtime_seconds",
        "per_command_timeout_seconds", "required_command_evidence", "required_exit_code_evidence",
        "required_stdout_log_evidence", "required_stderr_log_evidence", "required_file_hash_evidence",
        "required_diff_hash_evidence", "required_journal_evidence", "required_reviewer_summary",
        "max_attempts", "retryable_failure_types", "non_retryable_failure_types", "stop_conditions",
        "fail_closed_conditions", "rollback_triggers", "cleanup_triggers", "escalation_required_conditions",
        "dry_run", "write_allowed", "automation_allowed", "metadata", "writes",
    )
    missing = [field for field in required if field not in boundary]
    if missing:
        raise ValueError(f"verification runner boundary missing fields: {missing}")
    if boundary["verification_runner_boundary_version"] != VERIFICATION_RUNNER_BOUNDARY_VERSION:
        raise ValueError("unsupported verification runner boundary version")
    _validate_execution_read_only(boundary, "verification runner boundary")
    for field in (
        "verification_runner_boundary_id", "planning_chain_id", "execution_package_id",
        "patch_applier_boundary_id", "guarded_patch_receipt_id", "workspace_id", "workspace_path",
        "execution_evidence_contract_id", "retry_policy_id", "gate_stack_preview_id",
        "approval_checklist_id", "preflight_checklist_id", "execution_review_id",
    ):
        _validate_non_empty_string(boundary[field], field)
    text_list_fields = (
        "allowed_verification_actions", "required_verification_actions", "optional_verification_actions",
        "forbidden_verification_actions", "action_requires_review", "allowed_command_families",
        "forbidden_command_families", "allowed_command_patterns", "forbidden_command_patterns",
        "required_command_evidence", "required_exit_code_evidence", "required_stdout_log_evidence",
        "required_stderr_log_evidence", "required_file_hash_evidence", "required_diff_hash_evidence",
        "required_journal_evidence", "retryable_failure_types", "non_retryable_failure_types",
        "stop_conditions", "fail_closed_conditions", "rollback_triggers", "cleanup_triggers",
        "escalation_required_conditions",
    )
    for field in text_list_fields:
        values = boundary[field]
        if not isinstance(values, list) or not values:
            raise TypeError(f"{field} must be a non-empty list")
        if values != _normalize_patch_behavior_text_list(values):
            raise ValueError(f"{field} must be normalized and sorted")
    if set(boundary["allowed_verification_actions"]) & set(boundary["forbidden_verification_actions"]):
        raise ValueError("verification actions overlap forbidden actions")
    if not {"compile", "tests", "healthcheck"}.issubset(set(boundary["required_verification_actions"])):
        raise ValueError("verification runner boundary must require compile/tests/healthcheck")
    if set(boundary["allowed_command_families"]) & set(boundary["forbidden_command_families"]):
        raise ValueError("allowed command families overlap forbidden command families")
    if any(family in _FORBIDDEN_COMMAND_FAMILIES for family in boundary["allowed_command_families"]):
        raise ValueError("allowed command families include forbidden family")
    for family in _FORBIDDEN_COMMAND_FAMILIES:
        if family not in boundary["forbidden_command_families"]:
            raise ValueError("verification runner boundary missing forbidden command family")
    for pattern in boundary["allowed_command_patterns"]:
        if not pattern.startswith("PYTHONDONTWRITEBYTECODE=1 python3") and not pattern.startswith("python3"):
            raise ValueError("allowed command pattern must use python3 family")
        if "|" in pattern or "&&" in pattern or ";" in pattern:
            raise ValueError("allowed command pattern must not chain commands")
    for field in ("max_command_count", "max_runtime_seconds", "per_command_timeout_seconds", "max_attempts"):
        if not isinstance(boundary[field], int) or boundary[field] < 1:
            raise ValueError(f"{field} must be a positive integer")
    if boundary["max_command_count"] < len(boundary["required_verification_actions"]):
        raise ValueError("max_command_count must cover required verification actions")
    if boundary["per_command_timeout_seconds"] > boundary["max_runtime_seconds"]:
        raise ValueError("per-command timeout must not exceed max runtime")
    if boundary["max_attempts"] > 5:
        raise ValueError("max_attempts must not exceed retry policy cap")
    if boundary["required_reviewer_summary"] is not True:
        raise ValueError("verification runner boundary must require reviewer summary")
    for required_item in ("guarded patch receipt is not applied", "command family is not allowlisted"):
        if required_item not in boundary["fail_closed_conditions"]:
            raise ValueError("verification runner boundary missing fail-closed condition")
    for trigger in ("compile command exits nonzero after patch application", "test command exits nonzero after patch application", "healthcheck command exits nonzero after patch application"):
        if trigger not in boundary["rollback_triggers"]:
            raise ValueError("verification runner boundary missing rollback trigger")
    expected_id = make_verification_runner_boundary_id(
        boundary["planning_chain_id"],
        boundary["execution_package_id"],
        boundary["patch_applier_boundary_id"],
        boundary["guarded_patch_receipt_id"],
        boundary["retry_policy_id"],
        boundary["execution_evidence_contract_id"],
    )
    if boundary["verification_runner_boundary_id"] != expected_id:
        raise ValueError("verification runner boundary id does not match contents")
    if guarded_patch_receipt is not None:
        validate_guarded_patch_receipt(guarded_patch_receipt)
        if boundary["guarded_patch_receipt_id"] != guarded_patch_receipt["guarded_patch_receipt_id"]:
            raise ValueError("verification runner boundary patch receipt mismatch")
        if boundary["workspace_id"] != guarded_patch_receipt["workspace_id"]:
            raise ValueError("verification runner boundary workspace id mismatch")
        if boundary["workspace_path"] != guarded_patch_receipt["workspace_path"]:
            raise ValueError("verification runner boundary workspace path mismatch")
    if patch_applier_boundary is not None:
        validate_patch_applier_boundary(patch_applier_boundary)
        expected = {
            "planning_chain_id": patch_applier_boundary["planning_chain_id"],
            "execution_package_id": patch_applier_boundary["execution_package_id"],
            "patch_applier_boundary_id": patch_applier_boundary["patch_applier_boundary_id"],
        }
        for field, value in expected.items():
            if boundary[field] != value:
                raise ValueError(f"verification runner boundary {field} does not match patch boundary")
    if execution_evidence_contract is not None:
        validate_execution_evidence_contract(execution_evidence_contract)
        if boundary["execution_evidence_contract_id"] != execution_evidence_contract["execution_evidence_contract_id"]:
            raise ValueError("verification runner boundary evidence contract mismatch")
    if execution_retry_policy is not None:
        validate_execution_retry_policy(execution_retry_policy)
        if boundary["retry_policy_id"] != execution_retry_policy["retry_policy_id"]:
            raise ValueError("verification runner boundary retry policy mismatch")
        if boundary["max_attempts"] != execution_retry_policy["max_attempts"]:
            raise ValueError("verification runner boundary max attempts mismatch")
    if execution_gate_stack_preview is not None:
        validate_execution_gate_stack_preview(execution_gate_stack_preview)
        if boundary["gate_stack_preview_id"] != execution_gate_stack_preview["gate_stack_preview_id"]:
            raise ValueError("verification runner boundary gate stack mismatch")
    if execution_approval_checklist is not None:
        validate_execution_approval_checklist(execution_approval_checklist)
        if boundary["approval_checklist_id"] != execution_approval_checklist["approval_checklist_id"]:
            raise ValueError("verification runner boundary approval checklist mismatch")
    if execution_preflight_checklist is not None:
        validate_execution_preflight_checklist(execution_preflight_checklist)
        if boundary["preflight_checklist_id"] != execution_preflight_checklist["preflight_checklist_id"]:
            raise ValueError("verification runner boundary preflight mismatch")
    if execution_review is not None:
        validate_execution_review(execution_review)
        if boundary["execution_review_id"] != execution_review["execution_review_id"]:
            raise ValueError("verification runner boundary execution review mismatch")


def stable_verification_runner_boundary_json(boundary: dict[str, Any]) -> str:
    validate_verification_runner_boundary(boundary)
    return _stable_ruflo_json(boundary, indent=2) + "\n"


def parse_verification_runner_boundary_json(text: str) -> dict[str, Any]:
    boundary = json.loads(text)
    validate_verification_runner_boundary(boundary)
    return boundary



GUARDED_VERIFICATION_RUNNER_VERSION = "link-guarded-verification-runner-v1"
GUARDED_VERIFICATION_RECEIPT_VERSION = "link-guarded-verification-receipt-v1"


def make_guarded_verification_request_id(
    verification_runner_boundary_id: str,
    workspace_id: str,
    commands: list[str],
    approved: bool,
    write: bool,
) -> str:
    return _execution_readiness_id("guarded-verification-request", {
        "approved": approved,
        "commands": commands,
        "verification_runner_boundary_id": verification_runner_boundary_id,
        "version": GUARDED_VERIFICATION_RUNNER_VERSION,
        "workspace_id": workspace_id,
        "write": write,
    })


def make_guarded_verification_receipt_id(
    request_id: str,
    verification_runner_boundary_id: str,
    workspace_id: str,
    command_hashes: list[str],
) -> str:
    return _execution_readiness_id("guarded-verification-receipt", {
        "command_hashes": command_hashes,
        "request_id": request_id,
        "verification_runner_boundary_id": verification_runner_boundary_id,
        "version": GUARDED_VERIFICATION_RECEIPT_VERSION,
        "workspace_id": workspace_id,
    })


def _guarded_verification_command_hash(command: str) -> str:
    import hashlib

    return hashlib.sha256(command.encode("utf-8")).hexdigest()


def _guarded_verification_split_command(command: str) -> tuple[dict[str, str], list[str]]:
    import shlex

    _validate_non_empty_string(command, "verification command")
    if any(token in command for token in ("|", "&&", ";", "`", "$(", ">", "<")):
        raise ValueError("verification command must not use shell chaining, redirection, or substitution")
    parts = shlex.split(command)
    if not parts:
        raise ValueError("verification command must not be empty")
    env_updates: dict[str, str] = {}
    if parts[0] == "PYTHONDONTWRITEBYTECODE=1":
        env_updates["PYTHONDONTWRITEBYTECODE"] = "1"
        parts = parts[1:]
    if not parts:
        raise ValueError("verification command missing executable")
    return env_updates, parts


def _validate_guarded_verification_command(command: str, boundary: dict[str, Any]) -> None:
    env_updates, parts = _guarded_verification_split_command(command)
    executable = parts[0]
    family = executable.rsplit("/", 1)[-1]
    if family not in boundary["allowed_command_families"]:
        raise ValueError(f"verification command family is not allowed: {family}")
    if family in boundary["forbidden_command_families"]:
        raise ValueError(f"verification command family is forbidden: {family}")
    forbidden_tokens = set(boundary["forbidden_command_families"])
    if any(part.rsplit("/", 1)[-1] in forbidden_tokens for part in parts):
        raise ValueError("verification command references forbidden command family")
    if len(parts) >= 3 and parts[1] == "-m" and parts[2] in {"pip", "ensurepip"}:
        raise ValueError("verification command must not install packages")
    command_text = " ".join(parts[1:]).lower()
    forbidden_python_tokens = (
        "http://", "https://", "os.system", "requests", "socket", "subprocess", "urllib",
    )
    if any(token in command_text for token in forbidden_python_tokens):
        raise ValueError("verification command must not request network or subprocess behavior")
    if env_updates and env_updates != {"PYTHONDONTWRITEBYTECODE": "1"}:
        raise ValueError("verification command contains unsupported environment override")


def make_guarded_verification_request(
    verification_runner_boundary: dict[str, Any],
    *,
    commands: list[str],
    approved: bool = False,
    write: bool = False,
    metadata: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Build a guarded verification request without executing commands."""
    validate_verification_runner_boundary(verification_runner_boundary)
    normalized_commands = [command.strip() for command in commands]
    request = {
        "guarded_verification_runner_version": GUARDED_VERIFICATION_RUNNER_VERSION,
        "request_id": make_guarded_verification_request_id(
            verification_runner_boundary["verification_runner_boundary_id"],
            verification_runner_boundary["workspace_id"],
            normalized_commands,
            approved,
            write,
        ),
        "verification_runner_boundary_id": verification_runner_boundary["verification_runner_boundary_id"],
        "planning_chain_id": verification_runner_boundary["planning_chain_id"],
        "execution_package_id": verification_runner_boundary["execution_package_id"],
        "workspace_id": verification_runner_boundary["workspace_id"],
        "workspace_path": verification_runner_boundary["workspace_path"],
        "commands": normalized_commands,
        "approved": approved,
        "write": write,
        "dry_run": not write,
        "metadata": dict(metadata or {}),
    }
    validate_guarded_verification_request(request, verification_runner_boundary)
    return request


def validate_guarded_verification_request(
    request: dict[str, Any],
    verification_runner_boundary: dict[str, Any] | None = None,
) -> None:
    required = (
        "guarded_verification_runner_version", "request_id", "verification_runner_boundary_id",
        "planning_chain_id", "execution_package_id", "workspace_id", "workspace_path",
        "commands", "approved", "write", "dry_run", "metadata",
    )
    missing = [field for field in required if field not in request]
    if missing:
        raise ValueError(f"guarded verification request missing fields: {missing}")
    if request["guarded_verification_runner_version"] != GUARDED_VERIFICATION_RUNNER_VERSION:
        raise ValueError("unsupported guarded verification runner version")
    for field in ("request_id", "verification_runner_boundary_id", "planning_chain_id", "execution_package_id", "workspace_id", "workspace_path"):
        _validate_non_empty_string(request[field], field)
    if not isinstance(request["approved"], bool) or not isinstance(request["write"], bool):
        raise TypeError("approved and write must be booleans")
    if request["dry_run"] != (not request["write"]):
        raise ValueError("guarded verification request dry_run must invert write")
    if not isinstance(request["metadata"], dict):
        raise TypeError("metadata must be a dict")
    commands = request["commands"]
    if not isinstance(commands, list) or not commands:
        raise TypeError("commands must be a non-empty list")
    if not all(isinstance(command, str) and command.strip() for command in commands):
        raise TypeError("commands must contain non-empty strings")
    if commands != [command.strip() for command in commands]:
        raise ValueError("commands must be stripped")
    _guarded_patch_workspace_path(request["workspace_path"])
    if request["write"] and not request["approved"]:
        raise PermissionError("guarded verification requires explicit approval")
    if verification_runner_boundary is not None:
        validate_verification_runner_boundary(verification_runner_boundary)
        expected_refs = {
            "verification_runner_boundary_id": verification_runner_boundary["verification_runner_boundary_id"],
            "planning_chain_id": verification_runner_boundary["planning_chain_id"],
            "execution_package_id": verification_runner_boundary["execution_package_id"],
            "workspace_id": verification_runner_boundary["workspace_id"],
            "workspace_path": verification_runner_boundary["workspace_path"],
        }
        for field, value in expected_refs.items():
            if request[field] != value:
                raise ValueError(f"guarded verification request {field} does not match boundary")
        if len(commands) > verification_runner_boundary["max_command_count"]:
            raise ValueError("guarded verification command count exceeds boundary")
        for command in commands:
            _validate_guarded_verification_command(command, verification_runner_boundary)
    expected_id = make_guarded_verification_request_id(
        request["verification_runner_boundary_id"],
        request["workspace_id"],
        commands,
        request["approved"],
        request["write"],
    )
    if request["request_id"] != expected_id:
        raise ValueError("guarded verification request id does not match contents")


def collect_guarded_verification_receipt(
    request: dict[str, Any],
    verification_runner_boundary: dict[str, Any],
    guarded_patch_receipt: dict[str, Any],
    workspace_manifest: dict[str, Any],
    workspace_creation_receipt: dict[str, Any],
    execution_evidence_contract: dict[str, Any],
    execution_retry_policy: dict[str, Any],
    *,
    executed_commands: list[dict[str, Any]],
    receipt_timestamp: str,
    retry_count: int = 0,
    metadata: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Collect a guarded verification receipt from command evidence."""
    validate_guarded_verification_request(request, verification_runner_boundary)
    validate_verification_runner_boundary(verification_runner_boundary, guarded_patch_receipt, None, execution_evidence_contract, execution_retry_policy)
    validate_guarded_patch_receipt(guarded_patch_receipt)
    validate_workspace_creation_receipt(workspace_creation_receipt)
    validate_execution_evidence_contract(execution_evidence_contract)
    validate_execution_retry_policy(execution_retry_policy)
    if workspace_manifest != workspace_creation_receipt["workspace_manifest"]:
        raise ValueError("workspace manifest must match workspace creation receipt")
    commands = sorted([dict(command) for command in executed_commands], key=lambda item: item["sequence"])
    command_hashes = [item["command_hash"] for item in commands]
    exit_codes = [item["exit_code"] for item in commands]
    stdout_refs = _normalize_implementation_branch_refs([item["stdout_ref"] for item in commands])
    stderr_refs = _normalize_implementation_branch_refs([item["stderr_ref"] for item in commands])
    evidence_refs = _normalize_implementation_branch_refs([item["evidence_ref"] for item in commands])
    verification_result = "passed" if commands and all(code == 0 for code in exit_codes) else "failed"
    rollback_triggered = verification_result != "passed"
    safety = {
        "dry_run": not request["write"],
        "write_allowed": bool(request["write"]),
        "automation_allowed": False,
        "writes": evidence_refs if request["write"] else [],
    }
    receipt = {
        "guarded_verification_receipt_version": GUARDED_VERIFICATION_RECEIPT_VERSION,
        "verification_receipt_id": make_guarded_verification_receipt_id(
            request["request_id"],
            verification_runner_boundary["verification_runner_boundary_id"],
            request["workspace_id"],
            command_hashes,
        ),
        "request_id": request["request_id"],
        "workspace_id": request["workspace_id"],
        "workspace_path": request["workspace_path"],
        "verification_runner_boundary_id": verification_runner_boundary["verification_runner_boundary_id"],
        "guarded_patch_receipt_id": guarded_patch_receipt["guarded_patch_receipt_id"],
        "executed_commands": commands,
        "exit_codes": exit_codes,
        "stdout_refs": stdout_refs,
        "stderr_refs": stderr_refs,
        "evidence_refs": evidence_refs,
        "verification_result": verification_result,
        "retry_count": retry_count,
        "rollback_triggered": rollback_triggered,
        "receipt_timestamp": receipt_timestamp,
        "safety_metadata": safety,
        "metadata": dict(metadata or {}),
    }
    validate_guarded_verification_receipt(receipt, request, verification_runner_boundary, guarded_patch_receipt, workspace_creation_receipt, execution_evidence_contract, execution_retry_policy)
    return receipt


def validate_guarded_verification_receipt(
    receipt: dict[str, Any],
    request: dict[str, Any] | None = None,
    verification_runner_boundary: dict[str, Any] | None = None,
    guarded_patch_receipt: dict[str, Any] | None = None,
    workspace_creation_receipt: dict[str, Any] | None = None,
    execution_evidence_contract: dict[str, Any] | None = None,
    execution_retry_policy: dict[str, Any] | None = None,
) -> None:
    required = (
        "guarded_verification_receipt_version", "verification_receipt_id", "request_id",
        "workspace_id", "workspace_path", "verification_runner_boundary_id", "guarded_patch_receipt_id",
        "executed_commands", "exit_codes", "stdout_refs", "stderr_refs", "evidence_refs",
        "verification_result", "retry_count", "rollback_triggered", "receipt_timestamp",
        "safety_metadata", "metadata",
    )
    missing = [field for field in required if field not in receipt]
    if missing:
        raise ValueError(f"guarded verification receipt missing fields: {missing}")
    if receipt["guarded_verification_receipt_version"] != GUARDED_VERIFICATION_RECEIPT_VERSION:
        raise ValueError("unsupported guarded verification receipt version")
    for field in ("verification_receipt_id", "request_id", "workspace_id", "workspace_path", "verification_runner_boundary_id", "guarded_patch_receipt_id", "receipt_timestamp"):
        _validate_non_empty_string(receipt[field], field)
    if receipt["verification_result"] not in {"passed", "failed"}:
        raise ValueError("invalid verification_result")
    if not isinstance(receipt["retry_count"], int) or receipt["retry_count"] < 0:
        raise ValueError("retry_count must be a non-negative integer")
    if not isinstance(receipt["rollback_triggered"], bool):
        raise TypeError("rollback_triggered must be a boolean")
    commands = receipt["executed_commands"]
    if not isinstance(commands, list) or not commands:
        raise TypeError("executed_commands must be a non-empty list")
    for index, command in enumerate(commands, start=1):
        for field in ("command", "command_hash", "stdout_ref", "stderr_ref", "evidence_ref", "status"):
            _validate_non_empty_string(command.get(field), f"executed command {field}")
        if command.get("sequence") != index:
            raise ValueError("executed command sequence must be contiguous")
        if not isinstance(command.get("exit_code"), int):
            raise TypeError("executed command exit_code must be an integer")
        if command["command_hash"] != _guarded_verification_command_hash(command["command"]):
            raise ValueError("executed command hash does not match command")
        if command["status"] not in {"passed", "failed"}:
            raise ValueError("invalid executed command status")
    if receipt["exit_codes"] != [item["exit_code"] for item in commands]:
        raise ValueError("exit_codes must match executed commands")
    for field in ("stdout_refs", "stderr_refs", "evidence_refs"):
        values = receipt[field]
        if not isinstance(values, list) or not values:
            raise TypeError(f"{field} must be a non-empty list")
        if values != _normalize_implementation_branch_refs(values):
            raise ValueError(f"{field} must be normalized")
    if receipt["verification_result"] == "passed" and any(code != 0 for code in receipt["exit_codes"]):
        raise ValueError("passed verification cannot include failing exit codes")
    if receipt["verification_result"] == "failed" and all(code == 0 for code in receipt["exit_codes"]):
        raise ValueError("failed verification must include a failing exit code")
    if receipt["rollback_triggered"] != (receipt["verification_result"] == "failed"):
        raise ValueError("rollback_triggered must match verification failure")
    safety = receipt["safety_metadata"]
    if not isinstance(safety, dict):
        raise TypeError("safety_metadata must be a dict")
    if safety.get("automation_allowed") is not False:
        raise ValueError("guarded verification must keep automation disabled")
    if not isinstance(safety.get("writes"), list):
        raise TypeError("guarded verification safety writes must be a list")
    if safety["writes"] != _normalize_implementation_branch_refs(safety["writes"]):
        raise ValueError("guarded verification safety writes must be normalized")
    if not isinstance(receipt["metadata"], dict):
        raise TypeError("metadata must be a dict")
    expected_id = make_guarded_verification_receipt_id(
        receipt["request_id"],
        receipt["verification_runner_boundary_id"],
        receipt["workspace_id"],
        [item["command_hash"] for item in commands],
    )
    if receipt["verification_receipt_id"] != expected_id:
        raise ValueError("guarded verification receipt id does not match contents")
    if request is not None:
        validate_guarded_verification_request(request, verification_runner_boundary)
        if receipt["request_id"] != request["request_id"]:
            raise ValueError("guarded verification receipt request mismatch")
        if receipt["verification_result"] == "passed" and not request["write"]:
            raise ValueError("passed guarded verification receipt requires write request")
        if receipt["verification_result"] == "passed" and safety.get("dry_run") is not False:
            raise ValueError("passed guarded verification receipt must not be dry run")
    if verification_runner_boundary is not None:
        validate_verification_runner_boundary(verification_runner_boundary)
        if receipt["verification_runner_boundary_id"] != verification_runner_boundary["verification_runner_boundary_id"]:
            raise ValueError("guarded verification receipt boundary mismatch")
        if receipt["workspace_id"] != verification_runner_boundary["workspace_id"]:
            raise ValueError("guarded verification receipt workspace mismatch")
    if guarded_patch_receipt is not None:
        validate_guarded_patch_receipt(guarded_patch_receipt)
        if receipt["guarded_patch_receipt_id"] != guarded_patch_receipt["guarded_patch_receipt_id"]:
            raise ValueError("guarded verification receipt patch receipt mismatch")
    if workspace_creation_receipt is not None:
        validate_workspace_creation_receipt(workspace_creation_receipt)
        if receipt["workspace_id"] != workspace_creation_receipt["workspace_id"]:
            raise ValueError("guarded verification receipt workspace creation mismatch")
    if execution_evidence_contract is not None:
        validate_execution_evidence_contract(execution_evidence_contract)
    if execution_retry_policy is not None:
        validate_execution_retry_policy(execution_retry_policy)
        if receipt["retry_count"] > execution_retry_policy["max_attempts"] - 1:
            raise ValueError("guarded verification retry count exceeds retry policy")


def _validate_guarded_verification_runtime_inputs(
    request: dict[str, Any],
    verification_runner_boundary: dict[str, Any],
    guarded_patch_receipt: dict[str, Any],
    workspace_manifest: dict[str, Any],
    workspace_creation_receipt: dict[str, Any],
    execution_evidence_contract: dict[str, Any],
    execution_retry_policy: dict[str, Any],
) -> None:
    validate_guarded_verification_request(request, verification_runner_boundary)
    validate_verification_runner_boundary(verification_runner_boundary, guarded_patch_receipt, None, execution_evidence_contract, execution_retry_policy)
    validate_guarded_patch_receipt(guarded_patch_receipt)
    validate_workspace_creation_receipt(workspace_creation_receipt)
    validate_execution_evidence_contract(execution_evidence_contract)
    validate_execution_retry_policy(execution_retry_policy)
    if workspace_manifest != workspace_creation_receipt["workspace_manifest"]:
        raise ValueError("workspace manifest must match workspace creation receipt")
    if request["workspace_id"] != workspace_creation_receipt["workspace_id"]:
        raise ValueError("guarded verification request workspace must match creation receipt")
    if request["workspace_path"] != workspace_creation_receipt["workspace_path"]:
        raise ValueError("guarded verification request workspace path must match creation receipt")
    if guarded_patch_receipt["workspace_id"] != workspace_creation_receipt["workspace_id"]:
        raise ValueError("guarded verification patch receipt workspace mismatch")
    workspace_path = _guarded_patch_workspace_path(workspace_creation_receipt["workspace_path"])
    if request["write"]:
        if workspace_creation_receipt["status"] != "created":
            raise PermissionError("guarded verification requires a created workspace")
        if guarded_patch_receipt["status"] != "applied":
            raise PermissionError("guarded verification requires an applied patch receipt")
        if not workspace_path.exists() or not workspace_path.is_dir():
            raise FileNotFoundError("guarded verification workspace does not exist")
        manifest_path = workspace_path / "workspace_manifest.json"
        if not manifest_path.exists():
            raise FileNotFoundError("guarded verification workspace manifest is missing")
        on_disk_manifest = json.loads(manifest_path.read_text(encoding="utf-8"))
        if on_disk_manifest != workspace_manifest:
            raise ValueError("on-disk workspace manifest does not match receipt")


def _run_guarded_verification_command(command: str, workspace_path, evidence_dir, sequence: int, timeout: int) -> dict[str, Any]:
    import os
    import subprocess

    env_updates, parts = _guarded_verification_split_command(command)
    env = dict(os.environ)
    env.update(env_updates)
    completed = subprocess.run(
        parts,
        cwd=str(workspace_path),
        env=env,
        text=True,
        capture_output=True,
        timeout=timeout,
        shell=False,
    )
    command_hash = _guarded_verification_command_hash(command)
    stem = f"command-{sequence}-{command_hash[:12]}"
    stdout_ref = f"verification_evidence/{stem}.stdout.log"
    stderr_ref = f"verification_evidence/{stem}.stderr.log"
    evidence_ref = f"verification_evidence/{stem}.evidence.json"
    stdout_path = workspace_path / stdout_ref
    stderr_path = workspace_path / stderr_ref
    evidence_path = workspace_path / evidence_ref
    stdout_path.write_text(completed.stdout, encoding="utf-8")
    stderr_path.write_text(completed.stderr, encoding="utf-8")
    evidence = {
        "command": command,
        "command_hash": command_hash,
        "exit_code": completed.returncode,
        "stdout_ref": stdout_ref,
        "stderr_ref": stderr_ref,
        "status": "passed" if completed.returncode == 0 else "failed",
    }
    evidence_path.write_text(_stable_ruflo_json(evidence, indent=2) + "\n", encoding="utf-8")
    return {
        "sequence": sequence,
        "command": command,
        "command_hash": command_hash,
        "exit_code": completed.returncode,
        "stdout_ref": stdout_ref,
        "stderr_ref": stderr_ref,
        "evidence_ref": evidence_ref,
        "status": evidence["status"],
    }


def run_guarded_verification(
    request: dict[str, Any],
    verification_runner_boundary: dict[str, Any],
    guarded_patch_receipt: dict[str, Any],
    workspace_manifest: dict[str, Any],
    workspace_creation_receipt: dict[str, Any],
    execution_evidence_contract: dict[str, Any],
    execution_retry_policy: dict[str, Any],
) -> dict[str, Any]:
    """Run allowlisted Python verification commands inside a guarded workspace."""
    from datetime import datetime, timezone

    _validate_guarded_verification_runtime_inputs(
        request,
        verification_runner_boundary,
        guarded_patch_receipt,
        workspace_manifest,
        workspace_creation_receipt,
        execution_evidence_contract,
        execution_retry_policy,
    )
    if not request["write"]:
        raise PermissionError("guarded verification requires --write")
    if not request["approved"]:
        raise PermissionError("guarded verification requires explicit approval")
    workspace_path = _guarded_patch_workspace_path(workspace_creation_receipt["workspace_path"])
    evidence_dir = workspace_path / "verification_evidence"
    evidence_dir.mkdir(parents=True, exist_ok=True)
    executed: list[dict[str, Any]] = []
    retry_count = 0
    for index, command in enumerate(request["commands"], start=1):
        result = _run_guarded_verification_command(
            command,
            workspace_path,
            evidence_dir,
            index,
            verification_runner_boundary["per_command_timeout_seconds"],
        )
        executed.append(result)
        if result["exit_code"] != 0:
            break
    timestamp = datetime.now(timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")
    receipt = collect_guarded_verification_receipt(
        request,
        verification_runner_boundary,
        guarded_patch_receipt,
        workspace_manifest,
        workspace_creation_receipt,
        execution_evidence_contract,
        execution_retry_policy,
        executed_commands=executed,
        receipt_timestamp=timestamp,
        retry_count=retry_count,
    )
    receipt_path = workspace_path / "guarded_verification_receipt.json"
    receipt_path.write_text(_stable_ruflo_json(receipt, indent=2) + "\n", encoding="utf-8")
    receipt["safety_metadata"]["writes"] = _normalize_implementation_branch_refs([
        *receipt["evidence_refs"],
        "guarded_verification_receipt.json",
    ])
    validate_guarded_verification_receipt(receipt, request, verification_runner_boundary, guarded_patch_receipt, workspace_creation_receipt, execution_evidence_contract, execution_retry_policy)
    receipt_path.write_text(_stable_ruflo_json(receipt, indent=2) + "\n", encoding="utf-8")
    return receipt



ROLLBACK_RUNTIME_BOUNDARY_VERSION = "link-rollback-runtime-boundary-v1"
_ALLOWED_ROLLBACK_ACTIONS = (
    "create rollback receipt later",
    "mark workspace abandoned",
    "remove workspace-local generated evidence",
    "restore before hashes",
    "restore workspace-local file backups",
)
_FORBIDDEN_ROLLBACK_ACTIONS = (
    "branch/worktree creation",
    "commits/merges",
    "git checkout",
    "git clean",
    "git reset",
    "modify Link repo files",
    "network calls",
    "package install",
    "patch application outside workspace",
)


def make_rollback_runtime_boundary_id(
    planning_chain_id: str,
    execution_package_id: str,
    guarded_patch_receipt_id: str,
    verification_receipt_id: str,
    patch_applier_boundary_id: str,
    verification_runner_boundary_id: str,
) -> str:
    return _execution_readiness_id("rollback-runtime-boundary", {
        "execution_package_id": execution_package_id,
        "guarded_patch_receipt_id": guarded_patch_receipt_id,
        "patch_applier_boundary_id": patch_applier_boundary_id,
        "planning_chain_id": planning_chain_id,
        "verification_receipt_id": verification_receipt_id,
        "verification_runner_boundary_id": verification_runner_boundary_id,
        "version": ROLLBACK_RUNTIME_BOUNDARY_VERSION,
    })


def collect_rollback_runtime_boundary(
    guarded_patch_receipt: dict[str, Any],
    guarded_verification_receipt: dict[str, Any],
    verification_runner_boundary: dict[str, Any],
    patch_applier_boundary: dict[str, Any],
    workspace_manifest: dict[str, Any],
    workspace_creation_receipt: dict[str, Any],
    execution_evidence_contract: dict[str, Any],
    execution_retry_policy: dict[str, Any],
    execution_gate_stack_preview: dict[str, Any],
    execution_review: dict[str, Any],
    *,
    metadata: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Return the read-only boundary for future rollback execution."""
    validate_guarded_patch_receipt(guarded_patch_receipt)
    validate_guarded_verification_receipt(guarded_verification_receipt, None, verification_runner_boundary, guarded_patch_receipt, workspace_creation_receipt, execution_evidence_contract, execution_retry_policy)
    validate_verification_runner_boundary(verification_runner_boundary, guarded_patch_receipt, patch_applier_boundary, execution_evidence_contract, execution_retry_policy, execution_gate_stack_preview, None, None, execution_review)
    validate_patch_applier_boundary(patch_applier_boundary)
    validate_workspace_creation_receipt(workspace_creation_receipt)
    validate_execution_evidence_contract(execution_evidence_contract)
    validate_execution_retry_policy(execution_retry_policy)
    validate_execution_gate_stack_preview(execution_gate_stack_preview)
    validate_execution_review(execution_review)
    if workspace_manifest != workspace_creation_receipt["workspace_manifest"]:
        raise ValueError("workspace manifest must match workspace creation receipt")
    if guarded_patch_receipt["workspace_id"] != guarded_verification_receipt["workspace_id"]:
        raise ValueError("rollback boundary patch and verification receipts must share workspace")
    if guarded_patch_receipt["workspace_path"] != guarded_verification_receipt["workspace_path"]:
        raise ValueError("rollback boundary patch and verification receipts must share workspace path")
    changed_files = _normalize_implementation_branch_refs(guarded_patch_receipt["changed_files"])
    required_triggers = _normalize_patch_behavior_text_list([
        "guarded verification receipt rollback_triggered is true",
        "verification result is failed",
        *verification_runner_boundary["rollback_triggers"],
    ])
    if guarded_verification_receipt["rollback_triggered"] is False:
        required_triggers = _normalize_patch_behavior_text_list([
            "manual reviewer requests rollback after guarded verification",
            "rollback boundary validation fails closed",
        ])
    optional_triggers = _normalize_patch_behavior_text_list([
        "reviewer rejects verification evidence",
        "workspace cleanup cannot complete safely",
    ])
    forbidden_triggers = _normalize_patch_behavior_text_list([
        "rollback requested for repository root",
        "rollback requested for git state mutation",
        "rollback requested outside guarded workspace",
    ])
    evidence = _normalize_implementation_branch_refs([
        "abandon_plan_reference",
        "affected_files",
        "cleanup_plan_reference",
        "failed_command_evidence",
        "guarded_patch_receipt.before_file_hashes",
        "guarded_patch_receipt.after_file_hashes",
        "reviewer_summary",
        "rollback_reason",
        "verification_receipt.verification_result",
    ])
    fail_closed = _normalize_patch_behavior_text_list([
        "affected file is outside guarded workspace",
        "before hash evidence is missing",
        "guarded patch receipt is missing",
        "rollback boundary validation fails",
        "verification receipt is missing",
        "workspace manifest does not match creation receipt",
    ])
    cleanup_triggers = _normalize_patch_behavior_text_list([
        "rollback cannot restore workspace-local before state",
        "workspace path fails safety validation",
    ])
    abandon_triggers = _normalize_patch_behavior_text_list([
        "rollback is required after verification failure",
        "rollback requires human review before execution",
    ])
    escalation = _normalize_patch_behavior_text_list([
        *execution_retry_policy["escalation_conditions"],
        "rollback would touch repository files",
        "rollback would require git mutation",
    ])
    boundary = {
        "rollback_runtime_boundary_version": ROLLBACK_RUNTIME_BOUNDARY_VERSION,
        "rollback_runtime_boundary_id": make_rollback_runtime_boundary_id(
            patch_applier_boundary["planning_chain_id"],
            patch_applier_boundary["execution_package_id"],
            guarded_patch_receipt["guarded_patch_receipt_id"],
            guarded_verification_receipt["verification_receipt_id"],
            patch_applier_boundary["patch_applier_boundary_id"],
            verification_runner_boundary["verification_runner_boundary_id"],
        ),
        "planning_chain_id": patch_applier_boundary["planning_chain_id"],
        "execution_package_id": patch_applier_boundary["execution_package_id"],
        "workspace_id": guarded_patch_receipt["workspace_id"],
        "workspace_path": guarded_patch_receipt["workspace_path"],
        "guarded_patch_receipt_id": guarded_patch_receipt["guarded_patch_receipt_id"],
        "verification_receipt_id": guarded_verification_receipt["verification_receipt_id"],
        "patch_applier_boundary_id": patch_applier_boundary["patch_applier_boundary_id"],
        "verification_runner_boundary_id": verification_runner_boundary["verification_runner_boundary_id"],
        "execution_evidence_contract_id": execution_evidence_contract["execution_evidence_contract_id"],
        "retry_policy_id": execution_retry_policy["retry_policy_id"],
        "gate_stack_preview_id": execution_gate_stack_preview["gate_stack_preview_id"],
        "execution_review_id": execution_review["execution_review_id"],
        "required_rollback_triggers": required_triggers,
        "optional_rollback_triggers": optional_triggers,
        "forbidden_rollback_triggers": forbidden_triggers,
        "trigger_requires_review": _normalize_patch_behavior_text_list([
            "any rollback trigger requires human review",
            "any missing rollback evidence requires human review",
        ]),
        "allowed_rollback_targets": changed_files or ["workspace-local generated evidence"],
        "forbidden_rollback_targets": _normalize_implementation_branch_refs([
            ".git/",
            ".link/",
            ".agents/",
            "research/",
            "repository root",
        ]),
        "workspace_only": True,
        "repo_mutation_allowed": False,
        "git_mutation_allowed": False,
        "allowed_rollback_actions": _normalize_patch_behavior_text_list(_ALLOWED_ROLLBACK_ACTIONS),
        "forbidden_rollback_actions": _normalize_patch_behavior_text_list(_FORBIDDEN_ROLLBACK_ACTIONS),
        "required_rollback_evidence": evidence,
        "fail_closed_conditions": fail_closed,
        "cleanup_triggers": cleanup_triggers,
        "abandon_triggers": abandon_triggers,
        "escalation_required_conditions": escalation,
        "dry_run": True,
        "write_allowed": False,
        "automation_allowed": False,
        "metadata": dict(metadata or {}),
        "writes": [],
    }
    validate_rollback_runtime_boundary(
        boundary,
        guarded_patch_receipt,
        guarded_verification_receipt,
        verification_runner_boundary,
        patch_applier_boundary,
        workspace_manifest,
        workspace_creation_receipt,
        execution_evidence_contract,
        execution_retry_policy,
        execution_gate_stack_preview,
        execution_review,
    )
    return boundary


def validate_rollback_runtime_boundary(
    boundary: dict[str, Any],
    guarded_patch_receipt: dict[str, Any] | None = None,
    guarded_verification_receipt: dict[str, Any] | None = None,
    verification_runner_boundary: dict[str, Any] | None = None,
    patch_applier_boundary: dict[str, Any] | None = None,
    workspace_manifest: dict[str, Any] | None = None,
    workspace_creation_receipt: dict[str, Any] | None = None,
    execution_evidence_contract: dict[str, Any] | None = None,
    execution_retry_policy: dict[str, Any] | None = None,
    execution_gate_stack_preview: dict[str, Any] | None = None,
    execution_review: dict[str, Any] | None = None,
) -> None:
    required = (
        "rollback_runtime_boundary_version", "rollback_runtime_boundary_id", "planning_chain_id",
        "execution_package_id", "workspace_id", "workspace_path", "guarded_patch_receipt_id",
        "verification_receipt_id", "patch_applier_boundary_id", "verification_runner_boundary_id",
        "execution_evidence_contract_id", "retry_policy_id", "gate_stack_preview_id",
        "execution_review_id", "required_rollback_triggers", "optional_rollback_triggers",
        "forbidden_rollback_triggers", "trigger_requires_review", "allowed_rollback_targets",
        "forbidden_rollback_targets", "workspace_only", "repo_mutation_allowed", "git_mutation_allowed",
        "allowed_rollback_actions", "forbidden_rollback_actions", "required_rollback_evidence",
        "fail_closed_conditions", "cleanup_triggers", "abandon_triggers", "escalation_required_conditions",
        "dry_run", "write_allowed", "automation_allowed", "metadata", "writes",
    )
    missing = [field for field in required if field not in boundary]
    if missing:
        raise ValueError(f"rollback runtime boundary missing fields: {missing}")
    if boundary["rollback_runtime_boundary_version"] != ROLLBACK_RUNTIME_BOUNDARY_VERSION:
        raise ValueError("unsupported rollback runtime boundary version")
    _validate_execution_read_only(boundary, "rollback runtime boundary")
    for field in (
        "rollback_runtime_boundary_id", "planning_chain_id", "execution_package_id", "workspace_id",
        "workspace_path", "guarded_patch_receipt_id", "verification_receipt_id", "patch_applier_boundary_id",
        "verification_runner_boundary_id", "execution_evidence_contract_id", "retry_policy_id",
        "gate_stack_preview_id", "execution_review_id",
    ):
        _validate_non_empty_string(boundary[field], field)
    _guarded_patch_workspace_path(boundary["workspace_path"])
    if boundary["workspace_only"] is not True:
        raise ValueError("rollback runtime boundary must be workspace-only")
    if boundary["repo_mutation_allowed"] is not False:
        raise ValueError("rollback runtime boundary must forbid repo mutation")
    if boundary["git_mutation_allowed"] is not False:
        raise ValueError("rollback runtime boundary must forbid git mutation")
    text_list_fields = (
        "required_rollback_triggers", "optional_rollback_triggers", "forbidden_rollback_triggers",
        "trigger_requires_review", "allowed_rollback_actions", "forbidden_rollback_actions",
        "fail_closed_conditions", "cleanup_triggers", "abandon_triggers", "escalation_required_conditions",
    )
    for field in text_list_fields:
        values = boundary[field]
        if not isinstance(values, list) or not values:
            raise TypeError(f"{field} must be a non-empty list")
        if values != _normalize_patch_behavior_text_list(values):
            raise ValueError(f"{field} must be normalized and sorted")
    ref_list_fields = ("allowed_rollback_targets", "forbidden_rollback_targets", "required_rollback_evidence")
    for field in ref_list_fields:
        values = boundary[field]
        if not isinstance(values, list) or not values:
            raise TypeError(f"{field} must be a non-empty list")
        if values != _normalize_implementation_branch_refs(values):
            raise ValueError(f"{field} must be normalized and sorted")
    for target in boundary["allowed_rollback_targets"]:
        if target != "workspace-local generated evidence":
            _patch_applier_validate_target_path(target)
    if set(boundary["allowed_rollback_actions"]) & set(boundary["forbidden_rollback_actions"]):
        raise ValueError("rollback allowed actions overlap forbidden actions")
    for action in _FORBIDDEN_ROLLBACK_ACTIONS:
        if action not in boundary["forbidden_rollback_actions"]:
            raise ValueError("rollback runtime boundary missing forbidden rollback action")
    for action in ("restore workspace-local file backups", "restore before hashes"):
        if action not in boundary["allowed_rollback_actions"]:
            raise ValueError("rollback runtime boundary missing allowed workspace restore action")
    for trigger in ("verification result is failed", "guarded verification receipt rollback_triggered is true"):
        if trigger not in boundary["required_rollback_triggers"] and "manual reviewer requests rollback after guarded verification" not in boundary["required_rollback_triggers"]:
            raise ValueError("rollback runtime boundary missing rollback trigger rule")
    for evidence in (
        "guarded_patch_receipt.before_file_hashes", "guarded_patch_receipt.after_file_hashes",
        "verification_receipt.verification_result", "failed_command_evidence", "rollback_reason",
        "affected_files", "reviewer_summary", "cleanup_plan_reference", "abandon_plan_reference",
    ):
        if evidence not in boundary["required_rollback_evidence"]:
            raise ValueError("rollback runtime boundary missing required evidence")
    for condition in ("affected file is outside guarded workspace", "rollback boundary validation fails"):
        if condition not in boundary["fail_closed_conditions"]:
            raise ValueError("rollback runtime boundary missing fail-closed condition")
    if not isinstance(boundary["metadata"], dict):
        raise TypeError("metadata must be a dict")
    expected_id = make_rollback_runtime_boundary_id(
        boundary["planning_chain_id"],
        boundary["execution_package_id"],
        boundary["guarded_patch_receipt_id"],
        boundary["verification_receipt_id"],
        boundary["patch_applier_boundary_id"],
        boundary["verification_runner_boundary_id"],
    )
    if boundary["rollback_runtime_boundary_id"] != expected_id:
        raise ValueError("rollback runtime boundary id does not match contents")
    if guarded_patch_receipt is not None:
        validate_guarded_patch_receipt(guarded_patch_receipt)
        if boundary["guarded_patch_receipt_id"] != guarded_patch_receipt["guarded_patch_receipt_id"]:
            raise ValueError("rollback runtime boundary patch receipt mismatch")
        if boundary["workspace_id"] != guarded_patch_receipt["workspace_id"]:
            raise ValueError("rollback runtime boundary patch workspace mismatch")
    if guarded_verification_receipt is not None:
        validate_guarded_verification_receipt(guarded_verification_receipt)
        if boundary["verification_receipt_id"] != guarded_verification_receipt["verification_receipt_id"]:
            raise ValueError("rollback runtime boundary verification receipt mismatch")
        if boundary["workspace_id"] != guarded_verification_receipt["workspace_id"]:
            raise ValueError("rollback runtime boundary verification workspace mismatch")
        if guarded_verification_receipt["rollback_triggered"] is True:
            if "guarded verification receipt rollback_triggered is true" not in boundary["required_rollback_triggers"]:
                raise ValueError("rollback runtime boundary must reflect rollback-triggered receipt")
    if verification_runner_boundary is not None:
        validate_verification_runner_boundary(verification_runner_boundary)
        if boundary["verification_runner_boundary_id"] != verification_runner_boundary["verification_runner_boundary_id"]:
            raise ValueError("rollback runtime boundary verification boundary mismatch")
    if patch_applier_boundary is not None:
        validate_patch_applier_boundary(patch_applier_boundary)
        expected = {
            "planning_chain_id": patch_applier_boundary["planning_chain_id"],
            "execution_package_id": patch_applier_boundary["execution_package_id"],
            "patch_applier_boundary_id": patch_applier_boundary["patch_applier_boundary_id"],
        }
        for field, value in expected.items():
            if boundary[field] != value:
                raise ValueError(f"rollback runtime boundary {field} does not match patch boundary")
    if workspace_creation_receipt is not None:
        validate_workspace_creation_receipt(workspace_creation_receipt)
        if boundary["workspace_id"] != workspace_creation_receipt["workspace_id"]:
            raise ValueError("rollback runtime boundary workspace creation mismatch")
        if workspace_manifest is not None and workspace_manifest != workspace_creation_receipt["workspace_manifest"]:
            raise ValueError("rollback runtime boundary manifest mismatch")
    if execution_evidence_contract is not None:
        validate_execution_evidence_contract(execution_evidence_contract)
        if boundary["execution_evidence_contract_id"] != execution_evidence_contract["execution_evidence_contract_id"]:
            raise ValueError("rollback runtime boundary evidence contract mismatch")
    if execution_retry_policy is not None:
        validate_execution_retry_policy(execution_retry_policy)
        if boundary["retry_policy_id"] != execution_retry_policy["retry_policy_id"]:
            raise ValueError("rollback runtime boundary retry policy mismatch")
    if execution_gate_stack_preview is not None:
        validate_execution_gate_stack_preview(execution_gate_stack_preview)
        if boundary["gate_stack_preview_id"] != execution_gate_stack_preview["gate_stack_preview_id"]:
            raise ValueError("rollback runtime boundary gate stack mismatch")
    if execution_review is not None:
        validate_execution_review(execution_review)
        if boundary["execution_review_id"] != execution_review["execution_review_id"]:
            raise ValueError("rollback runtime boundary execution review mismatch")


def stable_rollback_runtime_boundary_json(boundary: dict[str, Any]) -> str:
    validate_rollback_runtime_boundary(boundary)
    return _stable_ruflo_json(boundary, indent=2) + "\n"


def parse_rollback_runtime_boundary_json(text: str) -> dict[str, Any]:
    boundary = json.loads(text)
    validate_rollback_runtime_boundary(boundary)
    return boundary


GUARDED_ROLLBACK_EXECUTOR_VERSION = "link-guarded-rollback-executor-v1"
GUARDED_ROLLBACK_RECEIPT_VERSION = "link-guarded-rollback-receipt-v1"


def make_guarded_rollback_request_id(
    rollback_runtime_boundary_id: str,
    workspace_id: str,
    rollback_reason: str,
    approved: bool,
    write: bool,
) -> str:
    return _execution_readiness_id("guarded-rollback-request", {
        "approved": approved,
        "rollback_reason": rollback_reason,
        "rollback_runtime_boundary_id": rollback_runtime_boundary_id,
        "version": GUARDED_ROLLBACK_EXECUTOR_VERSION,
        "workspace_id": workspace_id,
        "write": write,
    })


def make_guarded_rollback_receipt_id(
    request_id: str,
    rollback_runtime_boundary_id: str,
    workspace_id: str,
    restored_files: list[str],
    removed_files: list[str],
    rollback_result: str,
) -> str:
    return _execution_readiness_id("guarded-rollback-receipt", {
        "removed_files": removed_files,
        "request_id": request_id,
        "restored_files": restored_files,
        "rollback_result": rollback_result,
        "rollback_runtime_boundary_id": rollback_runtime_boundary_id,
        "version": GUARDED_ROLLBACK_RECEIPT_VERSION,
        "workspace_id": workspace_id,
    })


def make_guarded_rollback_request(
    rollback_runtime_boundary: dict[str, Any],
    *,
    rollback_reason: str = "verification failed",
    approved: bool = False,
    write: bool = False,
    metadata: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Build a guarded rollback request without touching files."""
    validate_rollback_runtime_boundary(rollback_runtime_boundary)
    _validate_non_empty_string(rollback_reason, "rollback_reason")
    reason = rollback_reason.strip()
    request = {
        "guarded_rollback_executor_version": GUARDED_ROLLBACK_EXECUTOR_VERSION,
        "request_id": make_guarded_rollback_request_id(
            rollback_runtime_boundary["rollback_runtime_boundary_id"],
            rollback_runtime_boundary["workspace_id"],
            reason,
            approved,
            write,
        ),
        "rollback_runtime_boundary_id": rollback_runtime_boundary["rollback_runtime_boundary_id"],
        "planning_chain_id": rollback_runtime_boundary["planning_chain_id"],
        "execution_package_id": rollback_runtime_boundary["execution_package_id"],
        "workspace_id": rollback_runtime_boundary["workspace_id"],
        "workspace_path": rollback_runtime_boundary["workspace_path"],
        "guarded_patch_receipt_id": rollback_runtime_boundary["guarded_patch_receipt_id"],
        "verification_receipt_id": rollback_runtime_boundary["verification_receipt_id"],
        "rollback_reason": reason,
        "approved": approved,
        "write": write,
        "dry_run": not write,
        "metadata": dict(metadata or {}),
    }
    validate_guarded_rollback_request(request, rollback_runtime_boundary)
    return request


def validate_guarded_rollback_request(
    request: dict[str, Any],
    rollback_runtime_boundary: dict[str, Any] | None = None,
) -> None:
    required = (
        "guarded_rollback_executor_version", "request_id", "rollback_runtime_boundary_id",
        "planning_chain_id", "execution_package_id", "workspace_id", "workspace_path",
        "guarded_patch_receipt_id", "verification_receipt_id", "rollback_reason",
        "approved", "write", "dry_run", "metadata",
    )
    missing = [field for field in required if field not in request]
    if missing:
        raise ValueError(f"guarded rollback request missing fields: {missing}")
    if request["guarded_rollback_executor_version"] != GUARDED_ROLLBACK_EXECUTOR_VERSION:
        raise ValueError("unsupported guarded rollback executor version")
    for field in (
        "request_id", "rollback_runtime_boundary_id", "planning_chain_id", "execution_package_id",
        "workspace_id", "workspace_path", "guarded_patch_receipt_id", "verification_receipt_id", "rollback_reason",
    ):
        _validate_non_empty_string(request[field], field)
    if not isinstance(request["approved"], bool) or not isinstance(request["write"], bool):
        raise TypeError("approved and write must be booleans")
    if request["dry_run"] != (not request["write"]):
        raise ValueError("guarded rollback request dry_run must invert write")
    if request["rollback_reason"] != request["rollback_reason"].strip():
        raise ValueError("rollback_reason must be stripped")
    if not isinstance(request["metadata"], dict):
        raise TypeError("metadata must be a dict")
    _guarded_patch_workspace_path(request["workspace_path"])
    if request["write"] and not request["approved"]:
        raise PermissionError("guarded rollback requires explicit approval")
    expected_id = make_guarded_rollback_request_id(
        request["rollback_runtime_boundary_id"],
        request["workspace_id"],
        request["rollback_reason"],
        request["approved"],
        request["write"],
    )
    if request["request_id"] != expected_id:
        raise ValueError("guarded rollback request id does not match contents")
    if rollback_runtime_boundary is not None:
        validate_rollback_runtime_boundary(rollback_runtime_boundary)
        expected_refs = {
            "rollback_runtime_boundary_id": rollback_runtime_boundary["rollback_runtime_boundary_id"],
            "planning_chain_id": rollback_runtime_boundary["planning_chain_id"],
            "execution_package_id": rollback_runtime_boundary["execution_package_id"],
            "workspace_id": rollback_runtime_boundary["workspace_id"],
            "workspace_path": rollback_runtime_boundary["workspace_path"],
            "guarded_patch_receipt_id": rollback_runtime_boundary["guarded_patch_receipt_id"],
            "verification_receipt_id": rollback_runtime_boundary["verification_receipt_id"],
        }
        for field, value in expected_refs.items():
            if request[field] != value:
                raise ValueError(f"guarded rollback request {field} does not match boundary")


def _rollback_generated_refs(receipt: dict[str, Any]) -> list[str]:
    refs = [
        *receipt.get("stdout_refs", []),
        *receipt.get("stderr_refs", []),
        *receipt.get("evidence_refs", []),
        "guarded_verification_receipt.json",
    ]
    return _normalize_implementation_branch_refs(refs)


def _restore_guarded_patch_operation(workspace_path: str, operation: dict[str, Any]) -> dict[str, Any]:
    target = _guarded_patch_target_path(workspace_path, operation["file_path"])
    before_hash = operation.get("before_hash", "")
    before_rollback_hash = _guarded_patch_file_hash(target)
    status = operation.get("status")
    if status == "created" or before_hash == "":
        if target.exists():
            target.unlink()
    elif status == "modified":
        if not target.exists():
            raise FileNotFoundError("guarded rollback cannot restore missing modified file")
        text = target.read_text(encoding="utf-8")
        if "expected_result" in operation:
            marker = _guarded_patch_operation_text(operation)
            if not text.endswith(marker):
                raise ValueError("guarded rollback cannot restore modified file without matching patch marker")
            restored_text = text[:-len(marker)]
        elif operation["file_path"].lower().endswith((".md", ".rst", ".txt")):
            marker_start = f"\n<!-- Link guarded patch operation: {operation['operation_id']} -->\n<!-- Expected result: "
            index = text.rfind(marker_start)
            if index < 0:
                raise ValueError("guarded rollback cannot find patch marker by operation id")
            restored_text = text[:index]
        else:
            marker_start = f"\n# Link guarded patch operation: {operation['operation_id']}\n# Expected result: "
            index = text.rfind(marker_start)
            if index < 0:
                raise ValueError("guarded rollback cannot find patch marker by operation id")
            restored_text = text[:index]
        target.write_text(restored_text, encoding="utf-8")
    elif status == "deleted":
        raise ValueError("guarded rollback cannot restore deleted file without content snapshot")
    else:
        raise ValueError("guarded rollback received unsupported applied operation status")
    after_rollback_hash = _guarded_patch_file_hash(target)
    if after_rollback_hash != before_hash:
        raise ValueError("guarded rollback restored hash does not match patch before hash")
    return {
        "file_path": operation["file_path"],
        "before_rollback_hash": before_rollback_hash,
        "after_rollback_hash": after_rollback_hash,
        "expected_before_hash": before_hash,
    }


def collect_guarded_rollback_receipt(
    request: dict[str, Any],
    rollback_runtime_boundary: dict[str, Any],
    guarded_patch_receipt: dict[str, Any],
    guarded_verification_receipt: dict[str, Any],
    workspace_manifest: dict[str, Any],
    workspace_creation_receipt: dict[str, Any],
    *,
    restored_files: list[str],
    removed_files: list[str],
    before_hashes: dict[str, str],
    after_hashes: dict[str, str],
    rollback_reason: str,
    rollback_result: str,
    rollback_timestamp: str,
    rollback_evidence_refs: list[str] | None = None,
    metadata: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Collect a guarded rollback receipt for workspace-local rollback actions."""
    validate_guarded_rollback_request(request, rollback_runtime_boundary)
    validate_rollback_runtime_boundary(rollback_runtime_boundary, guarded_patch_receipt, guarded_verification_receipt)
    validate_guarded_patch_receipt(guarded_patch_receipt)
    validate_guarded_verification_receipt(guarded_verification_receipt)
    validate_workspace_creation_receipt(workspace_creation_receipt)
    if workspace_manifest != workspace_creation_receipt["workspace_manifest"]:
        raise ValueError("workspace manifest must match workspace creation receipt")
    restored = _normalize_implementation_branch_refs(restored_files)
    removed = _normalize_implementation_branch_refs(removed_files)
    evidence = _normalize_implementation_branch_refs(rollback_evidence_refs or [])
    writes = _normalize_implementation_branch_refs([
        *restored,
        *removed,
        *evidence,
        "guarded_rollback_receipt.json",
        "rollback_evidence/rollback_evidence.json",
        "workspace_abandoned.json",
    ]) if request["write"] else []
    safety = {
        "dry_run": not request["write"],
        "write_allowed": bool(request["write"]),
        "automation_allowed": False,
        "writes": writes,
    }
    receipt = {
        "guarded_rollback_receipt_version": GUARDED_ROLLBACK_RECEIPT_VERSION,
        "rollback_receipt_id": make_guarded_rollback_receipt_id(
            request["request_id"],
            rollback_runtime_boundary["rollback_runtime_boundary_id"],
            request["workspace_id"],
            restored,
            removed,
            rollback_result,
        ),
        "request_id": request["request_id"],
        "workspace_id": request["workspace_id"],
        "workspace_path": request["workspace_path"],
        "rollback_boundary_id": rollback_runtime_boundary["rollback_runtime_boundary_id"],
        "guarded_patch_receipt_id": guarded_patch_receipt["guarded_patch_receipt_id"],
        "verification_receipt_id": guarded_verification_receipt["verification_receipt_id"],
        "restored_files": restored,
        "removed_files": removed,
        "before_hashes": dict(sorted(before_hashes.items())),
        "after_hashes": dict(sorted(after_hashes.items())),
        "rollback_reason": rollback_reason.strip(),
        "rollback_result": rollback_result,
        "rollback_timestamp": rollback_timestamp,
        "rollback_evidence_refs": evidence,
        "safety_metadata": safety,
        "metadata": dict(metadata or {}),
    }
    validate_guarded_rollback_receipt(receipt, request, rollback_runtime_boundary, guarded_patch_receipt, guarded_verification_receipt, workspace_creation_receipt)
    return receipt


def validate_guarded_rollback_receipt(
    receipt: dict[str, Any],
    request: dict[str, Any] | None = None,
    rollback_runtime_boundary: dict[str, Any] | None = None,
    guarded_patch_receipt: dict[str, Any] | None = None,
    guarded_verification_receipt: dict[str, Any] | None = None,
    workspace_creation_receipt: dict[str, Any] | None = None,
) -> None:
    required = (
        "guarded_rollback_receipt_version", "rollback_receipt_id", "request_id", "workspace_id",
        "workspace_path", "rollback_boundary_id", "guarded_patch_receipt_id", "verification_receipt_id",
        "restored_files", "removed_files", "before_hashes", "after_hashes", "rollback_reason",
        "rollback_result", "rollback_timestamp", "rollback_evidence_refs", "safety_metadata", "metadata",
    )
    missing = [field for field in required if field not in receipt]
    if missing:
        raise ValueError(f"guarded rollback receipt missing fields: {missing}")
    if receipt["guarded_rollback_receipt_version"] != GUARDED_ROLLBACK_RECEIPT_VERSION:
        raise ValueError("unsupported guarded rollback receipt version")
    for field in (
        "rollback_receipt_id", "request_id", "workspace_id", "workspace_path", "rollback_boundary_id",
        "guarded_patch_receipt_id", "verification_receipt_id", "rollback_reason", "rollback_result", "rollback_timestamp",
    ):
        _validate_non_empty_string(receipt[field], field)
    if receipt["rollback_result"] not in {"preview", "rolled_back", "failed"}:
        raise ValueError("invalid rollback_result")
    _guarded_patch_workspace_path(receipt["workspace_path"])
    for field in ("restored_files", "removed_files", "rollback_evidence_refs"):
        values = receipt[field]
        if not isinstance(values, list):
            raise TypeError(f"{field} must be a list")
        if values != _normalize_implementation_branch_refs(values):
            raise ValueError(f"{field} must be normalized")
        for value in values:
            _guarded_patch_target_path(receipt["workspace_path"], value)
    for field in ("before_hashes", "after_hashes", "safety_metadata", "metadata"):
        if not isinstance(receipt[field], dict):
            raise TypeError(f"{field} must be a dict")
    safety = receipt["safety_metadata"]
    if safety.get("automation_allowed") is not False:
        raise ValueError("guarded rollback must keep automation disabled")
    if not isinstance(safety.get("writes"), list):
        raise TypeError("guarded rollback safety writes must be a list")
    if safety["writes"] != _normalize_implementation_branch_refs(safety["writes"]):
        raise ValueError("guarded rollback safety writes must be normalized")
    for value in safety["writes"]:
        _guarded_patch_target_path(receipt["workspace_path"], value)
    if receipt["rollback_result"] == "preview":
        if safety.get("dry_run") is not True or safety.get("write_allowed") is not False or safety["writes"] != []:
            raise ValueError("guarded rollback preview receipt must be read-only")
    if receipt["rollback_result"] == "rolled_back":
        if safety.get("dry_run") is not False or safety.get("write_allowed") is not True:
            raise ValueError("guarded rollback receipt must record workspace-local write allowance")
        for required_write in ("guarded_rollback_receipt.json", "rollback_evidence/rollback_evidence.json", "workspace_abandoned.json"):
            if required_write not in safety["writes"]:
                raise ValueError("guarded rollback receipt missing required workspace-local write")
    expected_id = make_guarded_rollback_receipt_id(
        receipt["request_id"],
        receipt["rollback_boundary_id"],
        receipt["workspace_id"],
        receipt["restored_files"],
        receipt["removed_files"],
        receipt["rollback_result"],
    )
    if receipt["rollback_receipt_id"] != expected_id:
        raise ValueError("guarded rollback receipt id does not match contents")
    if request is not None:
        validate_guarded_rollback_request(request, rollback_runtime_boundary)
        if receipt["request_id"] != request["request_id"]:
            raise ValueError("guarded rollback receipt request mismatch")
        if receipt["rollback_result"] == "rolled_back" and not request["write"]:
            raise ValueError("rolled-back rollback receipt requires write request")
    if rollback_runtime_boundary is not None:
        validate_rollback_runtime_boundary(rollback_runtime_boundary)
        if receipt["rollback_boundary_id"] != rollback_runtime_boundary["rollback_runtime_boundary_id"]:
            raise ValueError("guarded rollback receipt boundary mismatch")
        if receipt["workspace_id"] != rollback_runtime_boundary["workspace_id"]:
            raise ValueError("guarded rollback receipt workspace mismatch")
    if guarded_patch_receipt is not None:
        validate_guarded_patch_receipt(guarded_patch_receipt)
        if receipt["guarded_patch_receipt_id"] != guarded_patch_receipt["guarded_patch_receipt_id"]:
            raise ValueError("guarded rollback receipt patch receipt mismatch")
        for restored_file in receipt["restored_files"]:
            expected_hash = guarded_patch_receipt["before_file_hashes"].get(restored_file, "")
            if receipt["after_hashes"].get(restored_file, "") != expected_hash:
                raise ValueError("guarded rollback after hash must match patch before hash")
    if guarded_verification_receipt is not None:
        validate_guarded_verification_receipt(guarded_verification_receipt)
        if receipt["verification_receipt_id"] != guarded_verification_receipt["verification_receipt_id"]:
            raise ValueError("guarded rollback receipt verification receipt mismatch")
    if workspace_creation_receipt is not None:
        validate_workspace_creation_receipt(workspace_creation_receipt)
        if receipt["workspace_id"] != workspace_creation_receipt["workspace_id"]:
            raise ValueError("guarded rollback receipt workspace creation mismatch")
        if receipt["workspace_path"] != workspace_creation_receipt["workspace_path"]:
            raise ValueError("guarded rollback receipt workspace path mismatch")


def _validate_guarded_rollback_runtime_inputs(
    request: dict[str, Any],
    rollback_runtime_boundary: dict[str, Any],
    guarded_patch_receipt: dict[str, Any],
    guarded_verification_receipt: dict[str, Any],
    workspace_manifest: dict[str, Any],
    workspace_creation_receipt: dict[str, Any],
) -> None:
    validate_guarded_rollback_request(request, rollback_runtime_boundary)
    validate_rollback_runtime_boundary(rollback_runtime_boundary, guarded_patch_receipt, guarded_verification_receipt)
    validate_guarded_patch_receipt(guarded_patch_receipt)
    validate_guarded_verification_receipt(guarded_verification_receipt)
    validate_workspace_creation_receipt(workspace_creation_receipt)
    if workspace_manifest != workspace_creation_receipt["workspace_manifest"]:
        raise ValueError("workspace manifest must match workspace creation receipt")
    if request["workspace_id"] != workspace_creation_receipt["workspace_id"]:
        raise ValueError("guarded rollback request workspace must match creation receipt")
    if request["workspace_path"] != workspace_creation_receipt["workspace_path"]:
        raise ValueError("guarded rollback request workspace path must match creation receipt")
    if guarded_patch_receipt["workspace_id"] != workspace_creation_receipt["workspace_id"]:
        raise ValueError("guarded rollback patch receipt workspace mismatch")
    if guarded_verification_receipt["workspace_id"] != workspace_creation_receipt["workspace_id"]:
        raise ValueError("guarded rollback verification receipt workspace mismatch")
    if guarded_verification_receipt["rollback_triggered"] is not True:
        raise PermissionError("guarded rollback requires rollback-triggered verification receipt")
    workspace_path = _guarded_patch_workspace_path(workspace_creation_receipt["workspace_path"])
    if request["write"]:
        if workspace_creation_receipt["status"] != "created":
            raise PermissionError("guarded rollback requires a created workspace")
        if not workspace_path.exists() or not workspace_path.is_dir():
            raise FileNotFoundError("guarded rollback workspace does not exist")
        manifest_path = workspace_path / "workspace_manifest.json"
        if not manifest_path.exists():
            raise FileNotFoundError("guarded rollback workspace manifest is missing")
        on_disk_manifest = json.loads(manifest_path.read_text(encoding="utf-8"))
        if on_disk_manifest != workspace_manifest:
            raise ValueError("on-disk workspace manifest does not match receipt")


def execute_guarded_rollback(
    request: dict[str, Any],
    rollback_runtime_boundary: dict[str, Any],
    guarded_patch_receipt: dict[str, Any],
    guarded_verification_receipt: dict[str, Any],
    workspace_manifest: dict[str, Any],
    workspace_creation_receipt: dict[str, Any],
) -> dict[str, Any]:
    """Rollback workspace-local patch and verification artifacts inside a guarded workspace."""
    import shutil
    from datetime import datetime, timezone

    _validate_guarded_rollback_runtime_inputs(
        request,
        rollback_runtime_boundary,
        guarded_patch_receipt,
        guarded_verification_receipt,
        workspace_manifest,
        workspace_creation_receipt,
    )
    if not request["write"]:
        raise PermissionError("guarded rollback requires --write")
    if not request["approved"]:
        raise PermissionError("guarded rollback requires explicit approval")
    workspace_path = _guarded_patch_workspace_path(workspace_creation_receipt["workspace_path"])
    backup_path = workspace_path.parent / f".{workspace_path.name}.rollback-backup-{request['request_id']}"
    if backup_path.exists():
        shutil.rmtree(backup_path)
    shutil.copytree(workspace_path, backup_path)
    try:
        restored_records = [_restore_guarded_patch_operation(str(workspace_path), operation) for operation in guarded_patch_receipt["applied_operations"]]
        restored_files = _normalize_implementation_branch_refs([record["file_path"] for record in restored_records])
        removed_files: list[str] = []
        before_hashes = {record["file_path"]: record["before_rollback_hash"] for record in restored_records}
        after_hashes = {record["file_path"]: record["after_rollback_hash"] for record in restored_records}
        for ref in _rollback_generated_refs(guarded_verification_receipt):
            target = _guarded_patch_target_path(str(workspace_path), ref)
            if target.exists():
                before_hashes[ref] = _guarded_patch_file_hash(target)
                if target.is_dir():
                    shutil.rmtree(target)
                else:
                    target.unlink()
                after_hashes[ref] = ""
                removed_files.append(ref)
        rollback_evidence_ref = "rollback_evidence/rollback_evidence.json"
        rollback_evidence_path = _guarded_patch_target_path(str(workspace_path), rollback_evidence_ref)
        rollback_evidence_path.parent.mkdir(parents=True, exist_ok=True)
        timestamp = datetime.now(timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")
        evidence_payload = {
            "rollback_reason": request["rollback_reason"],
            "restored_files": restored_files,
            "removed_files": _normalize_implementation_branch_refs(removed_files),
            "guarded_patch_receipt_id": guarded_patch_receipt["guarded_patch_receipt_id"],
            "verification_receipt_id": guarded_verification_receipt["verification_receipt_id"],
            "timestamp": timestamp,
        }
        rollback_evidence_path.write_text(_stable_ruflo_json(evidence_payload, indent=2) + "\n", encoding="utf-8")
        abandoned_ref = "workspace_abandoned.json"
        abandoned_path = _guarded_patch_target_path(str(workspace_path), abandoned_ref)
        abandoned_payload = {
            "workspace_id": workspace_creation_receipt["workspace_id"],
            "abandonment_reason": request["rollback_reason"],
            "rollback_required": True,
            "timestamp": timestamp,
        }
        abandoned_path.write_text(_stable_ruflo_json(abandoned_payload, indent=2) + "\n", encoding="utf-8")
        receipt = collect_guarded_rollback_receipt(
            request,
            rollback_runtime_boundary,
            guarded_patch_receipt,
            guarded_verification_receipt,
            workspace_manifest,
            workspace_creation_receipt,
            restored_files=restored_files,
            removed_files=_normalize_implementation_branch_refs(removed_files),
            before_hashes=before_hashes,
            after_hashes=after_hashes,
            rollback_reason=request["rollback_reason"],
            rollback_result="rolled_back",
            rollback_timestamp=timestamp,
            rollback_evidence_refs=[rollback_evidence_ref],
        )
        receipt_path = _guarded_patch_target_path(str(workspace_path), "guarded_rollback_receipt.json")
        receipt_path.write_text(_stable_ruflo_json(receipt, indent=2) + "\n", encoding="utf-8")
        shutil.rmtree(backup_path)
        return receipt
    except Exception:
        if workspace_path.exists():
            shutil.rmtree(workspace_path)
        shutil.copytree(backup_path, workspace_path)
        shutil.rmtree(backup_path)
        raise


EXECUTION_EVIDENCE_BUNDLE_VERSION = "link-execution-evidence-bundle-v1"
EXECUTION_EVIDENCE_RECEIPT_VERSION = "link-execution-evidence-receipt-v1"


def make_execution_evidence_bundle_id(
    planning_chain_id: str,
    execution_package_id: str,
    workspace_id: str,
    evidence_refs: list[str],
    missing_evidence: list[str],
) -> str:
    return _execution_readiness_id("execution-evidence-bundle", {
        "evidence_refs": evidence_refs,
        "execution_package_id": execution_package_id,
        "missing_evidence": missing_evidence,
        "planning_chain_id": planning_chain_id,
        "version": EXECUTION_EVIDENCE_BUNDLE_VERSION,
        "workspace_id": workspace_id,
    })


def make_execution_evidence_receipt_id(
    execution_evidence_bundle_id: str,
    workspace_id: str,
    evidence_status: str,
    evidence_file_count: int,
    missing_evidence_count: int,
    receipt_hash: str,
) -> str:
    return _execution_readiness_id("execution-evidence-receipt", {
        "evidence_file_count": evidence_file_count,
        "evidence_status": evidence_status,
        "execution_evidence_bundle_id": execution_evidence_bundle_id,
        "missing_evidence_count": missing_evidence_count,
        "receipt_hash": receipt_hash,
        "version": EXECUTION_EVIDENCE_RECEIPT_VERSION,
        "workspace_id": workspace_id,
    })


def _execution_evidence_hash(path) -> str:
    import hashlib

    return hashlib.sha256(path.read_bytes()).hexdigest()


def _execution_evidence_ref_status(workspace_path: str, refs: list[str]) -> tuple[list[str], dict[str, dict[str, Any]]]:
    present: list[str] = []
    hashes: dict[str, dict[str, Any]] = {}
    for ref in _normalize_implementation_branch_refs(refs):
        target = _guarded_patch_target_path(workspace_path, ref)
        exists = target.exists() and target.is_file()
        if exists:
            present.append(ref)
            hashes[ref] = {
                "file_ref": ref,
                "sha256": _execution_evidence_hash(target),
                "present": True,
            }
        else:
            hashes[ref] = {
                "file_ref": ref,
                "sha256": "",
                "present": False,
            }
    return _normalize_implementation_branch_refs(present), dict(sorted(hashes.items()))


def _execution_evidence_contract_types(contract: dict[str, Any]) -> list[str]:
    return _normalize_implementation_branch_refs([item["evidence_type"] for item in contract["evidence_items"]])


def collect_execution_evidence_bundle(
    workspace_creation_receipt: dict[str, Any],
    workspace_manifest: dict[str, Any],
    guarded_patch_receipt: dict[str, Any],
    guarded_verification_receipt: dict[str, Any],
    guarded_rollback_receipt: dict[str, Any] | None,
    execution_evidence_contract: dict[str, Any],
    execution_review: dict[str, Any],
    execution_gate_stack_preview: dict[str, Any],
    *,
    write: bool = False,
    metadata: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Collect workspace-local execution artifacts into one reviewable evidence bundle."""
    validate_workspace_creation_receipt(workspace_creation_receipt)
    validate_guarded_patch_receipt(guarded_patch_receipt)
    validate_guarded_verification_receipt(guarded_verification_receipt)
    if guarded_rollback_receipt is not None:
        validate_guarded_rollback_receipt(guarded_rollback_receipt)
    validate_execution_evidence_contract(execution_evidence_contract)
    validate_execution_review(execution_review)
    validate_execution_gate_stack_preview(execution_gate_stack_preview)
    if workspace_manifest != workspace_creation_receipt["workspace_manifest"]:
        raise ValueError("workspace manifest must match workspace creation receipt")
    workspace_path = _guarded_patch_workspace_path(workspace_creation_receipt["workspace_path"])
    if write and (not workspace_path.exists() or not workspace_path.is_dir()):
        raise FileNotFoundError("execution evidence workspace does not exist")
    expected_refs = {
        "planning_chain_id": workspace_creation_receipt["planning_chain_id"],
        "execution_package_id": workspace_creation_receipt["execution_package_id"],
        "workspace_id": workspace_creation_receipt["workspace_id"],
        "workspace_path": workspace_creation_receipt["workspace_path"],
    }
    for receipt_name, receipt in (
        ("guarded patch receipt", guarded_patch_receipt),
        ("guarded verification receipt", guarded_verification_receipt),
    ):
        for field in ("workspace_id", "workspace_path"):
            if receipt[field] != expected_refs[field]:
                raise ValueError(f"{receipt_name} {field} does not match workspace")
    if guarded_rollback_receipt is not None:
        for field in ("workspace_id", "workspace_path"):
            if guarded_rollback_receipt[field] != expected_refs[field]:
                raise ValueError(f"guarded rollback receipt {field} does not match workspace")
    if execution_evidence_contract["planning_chain_id"] != expected_refs["planning_chain_id"]:
        raise ValueError("execution evidence contract planning chain mismatch")
    if execution_review["planning_chain_id"] != expected_refs["planning_chain_id"]:
        raise ValueError("execution review planning chain mismatch")
    if execution_gate_stack_preview["planning_chain_id"] != expected_refs["planning_chain_id"]:
        raise ValueError("gate stack planning chain mismatch")

    workspace_receipt_refs = _normalize_implementation_branch_refs(["workspace_manifest.json", "workspace_creation_receipt.json"])
    patch_receipt_refs = _normalize_implementation_branch_refs(["guarded_patch_receipt.json"])
    verification_receipt_refs = _normalize_implementation_branch_refs([
        "guarded_verification_receipt.json",
        *guarded_verification_receipt["stdout_refs"],
        *guarded_verification_receipt["stderr_refs"],
        *guarded_verification_receipt["evidence_refs"],
    ])
    rollback_receipt_refs = _normalize_implementation_branch_refs([
        "guarded_rollback_receipt.json",
        "workspace_abandoned.json",
        *(guarded_rollback_receipt or {}).get("rollback_evidence_refs", []),
    ]) if guarded_rollback_receipt is not None else []
    log_refs = _normalize_implementation_branch_refs([
        *guarded_verification_receipt["stdout_refs"],
        *guarded_verification_receipt["stderr_refs"],
    ])
    all_refs = _normalize_implementation_branch_refs([
        *workspace_receipt_refs,
        *patch_receipt_refs,
        *verification_receipt_refs,
        *rollback_receipt_refs,
    ])
    present_refs, hash_refs = _execution_evidence_ref_status(str(workspace_path), all_refs)
    present_types = {"quality_gate"}
    if "guarded_patch_receipt.json" in present_refs:
        present_types.add("patch_application")
    verification_artifacts_present = any(ref in present_refs for ref in guarded_verification_receipt["evidence_refs"])
    if verification_artifacts_present:
        present_types.update({"compile", "tests", "healthcheck"})
    if guarded_rollback_receipt is not None and "guarded_rollback_receipt.json" in present_refs:
        present_types.add("rollback")
    required_types = set(_execution_evidence_contract_types(execution_evidence_contract))
    missing_evidence = _normalize_implementation_branch_refs(sorted(required_types - present_types))
    required_evidence = _normalize_implementation_branch_refs([item["evidence_id"] for item in execution_evidence_contract["evidence_items"]])
    present_evidence = _normalize_implementation_branch_refs([
        *present_refs,
        *sorted(present_types),
    ])
    evidence_status = "complete" if not missing_evidence else "missing_evidence"
    reviewer_summary = (
        "Execution evidence is complete for reviewer handoff."
        if evidence_status == "complete"
        else f"Execution evidence is missing {len(missing_evidence)} required evidence type(s): {', '.join(missing_evidence)}."
    )
    recommended_next_action = (
        "review evidence bundle before cleanup"
        if evidence_status == "complete"
        else "review missing evidence before final handoff"
    )
    evidence_file_count = len([ref for ref, item in hash_refs.items() if item["present"]])
    bundle = {
        "execution_evidence_bundle_version": EXECUTION_EVIDENCE_BUNDLE_VERSION,
        "execution_evidence_bundle_id": make_execution_evidence_bundle_id(
            expected_refs["planning_chain_id"],
            expected_refs["execution_package_id"],
            expected_refs["workspace_id"],
            all_refs,
            missing_evidence,
        ),
        "planning_chain_id": expected_refs["planning_chain_id"],
        "execution_package_id": expected_refs["execution_package_id"],
        "workspace_id": expected_refs["workspace_id"],
        "workspace_path": expected_refs["workspace_path"],
        "workspace_receipt_refs": workspace_receipt_refs,
        "patch_receipt_refs": patch_receipt_refs,
        "verification_receipt_refs": verification_receipt_refs,
        "rollback_receipt_refs": rollback_receipt_refs,
        "log_refs": log_refs,
        "hash_refs": hash_refs,
        "evidence_file_count": evidence_file_count,
        "missing_evidence_count": len(missing_evidence),
        "workspace_receipt_count": len(workspace_receipt_refs),
        "patch_receipt_count": len(patch_receipt_refs),
        "verification_receipt_count": len(verification_receipt_refs),
        "rollback_receipt_count": len(rollback_receipt_refs),
        "required_evidence": required_evidence,
        "present_evidence": present_evidence,
        "missing_evidence": missing_evidence,
        "evidence_status": evidence_status,
        "reviewer_summary": reviewer_summary,
        "recommended_next_action": recommended_next_action,
        "safety_metadata": {
            "dry_run": not write,
            "write_allowed": bool(write),
            "automation_allowed": False,
            "writes": ["execution_evidence_bundle.json"] if write else [],
        },
        "metadata": dict(metadata or {}),
    }
    validate_execution_evidence_bundle(bundle, workspace_creation_receipt, guarded_patch_receipt, guarded_verification_receipt, guarded_rollback_receipt, execution_evidence_contract, execution_review, execution_gate_stack_preview)
    if write:
        bundle_path = _guarded_patch_target_path(str(workspace_path), "execution_evidence_bundle.json")
        bundle_path.write_text(stable_execution_evidence_bundle_json(bundle), encoding="utf-8")
    return bundle


def validate_execution_evidence_bundle(
    bundle: dict[str, Any],
    workspace_creation_receipt: dict[str, Any] | None = None,
    guarded_patch_receipt: dict[str, Any] | None = None,
    guarded_verification_receipt: dict[str, Any] | None = None,
    guarded_rollback_receipt: dict[str, Any] | None = None,
    execution_evidence_contract: dict[str, Any] | None = None,
    execution_review: dict[str, Any] | None = None,
    execution_gate_stack_preview: dict[str, Any] | None = None,
) -> None:
    required = (
        "execution_evidence_bundle_version", "execution_evidence_bundle_id", "planning_chain_id",
        "execution_package_id", "workspace_id", "workspace_path", "workspace_receipt_refs",
        "patch_receipt_refs", "verification_receipt_refs", "rollback_receipt_refs", "log_refs",
        "hash_refs", "evidence_file_count", "missing_evidence_count", "workspace_receipt_count",
        "patch_receipt_count", "verification_receipt_count", "rollback_receipt_count",
        "required_evidence", "present_evidence", "missing_evidence", "evidence_status",
        "reviewer_summary", "recommended_next_action", "safety_metadata", "metadata",
    )
    missing = [field for field in required if field not in bundle]
    if missing:
        raise ValueError(f"execution evidence bundle missing fields: {missing}")
    if bundle["execution_evidence_bundle_version"] != EXECUTION_EVIDENCE_BUNDLE_VERSION:
        raise ValueError("unsupported execution evidence bundle version")
    for field in ("execution_evidence_bundle_id", "planning_chain_id", "execution_package_id", "workspace_id", "workspace_path", "evidence_status", "reviewer_summary", "recommended_next_action"):
        _validate_non_empty_string(bundle[field], field)
    if bundle["evidence_status"] not in {"complete", "missing_evidence"}:
        raise ValueError("invalid execution evidence status")
    for field in ("evidence_file_count", "missing_evidence_count", "workspace_receipt_count", "patch_receipt_count", "verification_receipt_count", "rollback_receipt_count"):
        if not isinstance(bundle[field], int) or bundle[field] < 0:
            raise ValueError(f"{field} must be a non-negative integer")
    if bundle["workspace_receipt_count"] != len(bundle["workspace_receipt_refs"]):
        raise ValueError("workspace_receipt_count must match workspace_receipt_refs")
    if bundle["patch_receipt_count"] != len(bundle["patch_receipt_refs"]):
        raise ValueError("patch_receipt_count must match patch_receipt_refs")
    if bundle["verification_receipt_count"] != len(bundle["verification_receipt_refs"]):
        raise ValueError("verification_receipt_count must match verification_receipt_refs")
    if bundle["rollback_receipt_count"] != len(bundle["rollback_receipt_refs"]):
        raise ValueError("rollback_receipt_count must match rollback_receipt_refs")
    if bundle["missing_evidence_count"] != len(bundle["missing_evidence"]):
        raise ValueError("missing_evidence_count must match missing_evidence")
    _guarded_patch_workspace_path(bundle["workspace_path"])
    ref_list_fields = (
        "workspace_receipt_refs", "patch_receipt_refs", "verification_receipt_refs",
        "rollback_receipt_refs", "log_refs", "required_evidence", "present_evidence", "missing_evidence",
    )
    for field in ref_list_fields:
        values = bundle[field]
        if not isinstance(values, list):
            raise TypeError(f"{field} must be a list")
        if values != _normalize_implementation_branch_refs(values):
            raise ValueError(f"{field} must be normalized")
    for field in ("workspace_receipt_refs", "patch_receipt_refs", "verification_receipt_refs", "log_refs"):
        if not bundle[field]:
            raise ValueError(f"{field} must not be empty")
    for ref in [*bundle["workspace_receipt_refs"], *bundle["patch_receipt_refs"], *bundle["verification_receipt_refs"], *bundle["rollback_receipt_refs"], *bundle["log_refs"]]:
        _guarded_patch_target_path(bundle["workspace_path"], ref)
    if not isinstance(bundle["hash_refs"], dict):
        raise TypeError("hash_refs must be a dict")
    for ref, item in bundle["hash_refs"].items():
        if item.get("file_ref") != ref:
            raise ValueError("hash ref file_ref must match key")
        _guarded_patch_target_path(bundle["workspace_path"], ref)
        if not isinstance(item.get("present"), bool):
            raise TypeError("hash ref present must be a boolean")
        if item["present"]:
            _validate_non_empty_string(item.get("sha256"), "hash sha256")
        elif item.get("sha256") != "":
            raise ValueError("missing hash ref must use empty sha256")
    safety = bundle["safety_metadata"]
    if not isinstance(safety, dict):
        raise TypeError("safety_metadata must be a dict")
    if safety.get("automation_allowed") is not False:
        raise ValueError("execution evidence bundle must keep automation disabled")
    if not isinstance(safety.get("writes"), list):
        raise TypeError("execution evidence bundle writes must be a list")
    if safety["writes"] != _normalize_implementation_branch_refs(safety["writes"]):
        raise ValueError("execution evidence bundle writes must be normalized")
    for ref in safety["writes"]:
        _guarded_patch_target_path(bundle["workspace_path"], ref)
    if safety.get("dry_run") is True:
        if safety.get("write_allowed") is not False or safety["writes"] != []:
            raise ValueError("dry-run execution evidence bundle must not allow writes")
    else:
        if safety.get("dry_run") is not False or safety.get("write_allowed") is not True:
            raise ValueError("written execution evidence bundle must record workspace-local write allowance")
        if safety["writes"] != ["execution_evidence_bundle.json"]:
            raise ValueError("execution evidence bundle writes must contain only the bundle file")
    actual_evidence_file_count = len([ref for ref, item in bundle["hash_refs"].items() if item["present"]])
    if bundle["evidence_file_count"] != actual_evidence_file_count:
        raise ValueError("evidence_file_count must match present hash refs")
    if bundle["evidence_status"] == "complete" and bundle["missing_evidence"]:
        raise ValueError("complete evidence bundle cannot have missing evidence")
    if bundle["evidence_status"] == "missing_evidence" and not bundle["missing_evidence"]:
        raise ValueError("missing_evidence status requires missing evidence")
    expected_id = make_execution_evidence_bundle_id(
        bundle["planning_chain_id"],
        bundle["execution_package_id"],
        bundle["workspace_id"],
        _normalize_implementation_branch_refs([
            *bundle["workspace_receipt_refs"],
            *bundle["patch_receipt_refs"],
            *bundle["verification_receipt_refs"],
            *bundle["rollback_receipt_refs"],
        ]),
        bundle["missing_evidence"],
    )
    if bundle["execution_evidence_bundle_id"] != expected_id:
        raise ValueError("execution evidence bundle id does not match contents")
    if not isinstance(bundle["metadata"], dict):
        raise TypeError("metadata must be a dict")
    if workspace_creation_receipt is not None:
        validate_workspace_creation_receipt(workspace_creation_receipt)
        if bundle["workspace_id"] != workspace_creation_receipt["workspace_id"]:
            raise ValueError("execution evidence bundle workspace creation mismatch")
        if bundle["workspace_path"] != workspace_creation_receipt["workspace_path"]:
            raise ValueError("execution evidence bundle workspace path mismatch")
    if guarded_patch_receipt is not None:
        validate_guarded_patch_receipt(guarded_patch_receipt)
        if bundle["workspace_id"] != guarded_patch_receipt["workspace_id"]:
            raise ValueError("execution evidence bundle patch receipt workspace mismatch")
    if guarded_verification_receipt is not None:
        validate_guarded_verification_receipt(guarded_verification_receipt)
        if bundle["workspace_id"] != guarded_verification_receipt["workspace_id"]:
            raise ValueError("execution evidence bundle verification receipt workspace mismatch")
    if guarded_rollback_receipt is not None:
        validate_guarded_rollback_receipt(guarded_rollback_receipt)
        if bundle["workspace_id"] != guarded_rollback_receipt["workspace_id"]:
            raise ValueError("execution evidence bundle rollback receipt workspace mismatch")
    if execution_evidence_contract is not None:
        validate_execution_evidence_contract(execution_evidence_contract)
        if bundle["planning_chain_id"] != execution_evidence_contract["planning_chain_id"]:
            raise ValueError("execution evidence bundle contract planning chain mismatch")
    if execution_review is not None:
        validate_execution_review(execution_review)
        if bundle["planning_chain_id"] != execution_review["planning_chain_id"]:
            raise ValueError("execution evidence bundle review planning chain mismatch")
    if execution_gate_stack_preview is not None:
        validate_execution_gate_stack_preview(execution_gate_stack_preview)
        if bundle["planning_chain_id"] != execution_gate_stack_preview["planning_chain_id"]:
            raise ValueError("execution evidence bundle gate stack planning chain mismatch")


def stable_execution_evidence_bundle_json(bundle: dict[str, Any]) -> str:
    validate_execution_evidence_bundle(bundle)
    return _stable_ruflo_json(bundle, indent=2) + "\n"


def parse_execution_evidence_bundle_json(text: str) -> dict[str, Any]:
    bundle = json.loads(text)
    validate_execution_evidence_bundle(bundle)
    return bundle


def collect_execution_evidence_receipt(
    execution_evidence_bundle: dict[str, Any],
    *,
    write: bool = False,
    collected_at: str | None = None,
    metadata: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Create a workspace-local receipt for an execution evidence bundle."""
    from datetime import datetime, timezone

    validate_execution_evidence_bundle(execution_evidence_bundle)
    workspace_path = _guarded_patch_workspace_path(execution_evidence_bundle["workspace_path"])
    if write and (not workspace_path.exists() or not workspace_path.is_dir()):
        raise FileNotFoundError("execution evidence receipt workspace does not exist")
    timestamp = collected_at or datetime.now(timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")
    bundle_text = stable_execution_evidence_bundle_json(execution_evidence_bundle)
    import hashlib

    receipt_hash = hashlib.sha256(bundle_text.encode("utf-8")).hexdigest()
    present_files = [ref for ref, item in execution_evidence_bundle["hash_refs"].items() if item["present"]]
    safety = {
        "dry_run": not write,
        "write_allowed": bool(write),
        "automation_allowed": False,
        "writes": ["execution_evidence_receipt.json"] if write else [],
    }
    receipt = {
        "execution_evidence_receipt_version": EXECUTION_EVIDENCE_RECEIPT_VERSION,
        "execution_evidence_receipt_id": make_execution_evidence_receipt_id(
            execution_evidence_bundle["execution_evidence_bundle_id"],
            execution_evidence_bundle["workspace_id"],
            execution_evidence_bundle["evidence_status"],
            len(present_files),
            len(execution_evidence_bundle["missing_evidence"]),
            receipt_hash,
        ),
        "execution_evidence_bundle_id": execution_evidence_bundle["execution_evidence_bundle_id"],
        "workspace_id": execution_evidence_bundle["workspace_id"],
        "workspace_path": execution_evidence_bundle["workspace_path"],
        "collected_at": timestamp,
        "evidence_status": execution_evidence_bundle["evidence_status"],
        "evidence_file_count": len(present_files),
        "missing_evidence_count": len(execution_evidence_bundle["missing_evidence"]),
        "receipt_hash": receipt_hash,
        "safety_metadata": safety,
        "metadata": dict(metadata or {}),
    }
    validate_execution_evidence_receipt(receipt, execution_evidence_bundle)
    if write:
        receipt_path = _guarded_patch_target_path(str(workspace_path), "execution_evidence_receipt.json")
        receipt_path.write_text(_stable_ruflo_json(receipt, indent=2) + "\n", encoding="utf-8")
    return receipt


def validate_execution_evidence_receipt(
    receipt: dict[str, Any],
    execution_evidence_bundle: dict[str, Any] | None = None,
) -> None:
    required = (
        "execution_evidence_receipt_version", "execution_evidence_receipt_id", "execution_evidence_bundle_id",
        "workspace_id", "workspace_path", "collected_at", "evidence_status", "evidence_file_count",
        "missing_evidence_count", "receipt_hash", "safety_metadata", "metadata",
    )
    missing = [field for field in required if field not in receipt]
    if missing:
        raise ValueError(f"execution evidence receipt missing fields: {missing}")
    if receipt["execution_evidence_receipt_version"] != EXECUTION_EVIDENCE_RECEIPT_VERSION:
        raise ValueError("unsupported execution evidence receipt version")
    for field in ("execution_evidence_receipt_id", "execution_evidence_bundle_id", "workspace_id", "workspace_path", "collected_at", "evidence_status", "receipt_hash"):
        _validate_non_empty_string(receipt[field], field)
    if receipt["evidence_status"] not in {"complete", "missing_evidence"}:
        raise ValueError("invalid execution evidence receipt status")
    for field in ("evidence_file_count", "missing_evidence_count"):
        if not isinstance(receipt[field], int) or receipt[field] < 0:
            raise ValueError(f"{field} must be a non-negative integer")
    _guarded_patch_workspace_path(receipt["workspace_path"])
    safety = receipt["safety_metadata"]
    if not isinstance(safety, dict):
        raise TypeError("safety_metadata must be a dict")
    if safety.get("automation_allowed") is not False:
        raise ValueError("execution evidence receipt must keep automation disabled")
    if not isinstance(safety.get("writes"), list):
        raise TypeError("execution evidence receipt writes must be a list")
    if safety["writes"] != _normalize_implementation_branch_refs(safety["writes"]):
        raise ValueError("execution evidence receipt writes must be normalized")
    for ref in safety["writes"]:
        _guarded_patch_target_path(receipt["workspace_path"], ref)
    if safety.get("dry_run") is True:
        if safety.get("write_allowed") is not False or safety["writes"] != []:
            raise ValueError("dry-run execution evidence receipt must not allow writes")
    else:
        if safety.get("dry_run") is not False or safety.get("write_allowed") is not True:
            raise ValueError("written execution evidence receipt must record workspace-local write allowance")
        if safety["writes"] != ["execution_evidence_receipt.json"]:
            raise ValueError("execution evidence receipt writes must contain only the receipt file")
    if not isinstance(receipt["metadata"], dict):
        raise TypeError("metadata must be a dict")
    expected_id = make_execution_evidence_receipt_id(
        receipt["execution_evidence_bundle_id"],
        receipt["workspace_id"],
        receipt["evidence_status"],
        receipt["evidence_file_count"],
        receipt["missing_evidence_count"],
        receipt["receipt_hash"],
    )
    if receipt["execution_evidence_receipt_id"] != expected_id:
        raise ValueError("execution evidence receipt id does not match contents")
    if execution_evidence_bundle is not None:
        validate_execution_evidence_bundle(execution_evidence_bundle)
        if receipt["execution_evidence_bundle_id"] != execution_evidence_bundle["execution_evidence_bundle_id"]:
            raise ValueError("execution evidence receipt bundle mismatch")
        if receipt["workspace_id"] != execution_evidence_bundle["workspace_id"]:
            raise ValueError("execution evidence receipt workspace mismatch")
        if receipt["workspace_path"] != execution_evidence_bundle["workspace_path"]:
            raise ValueError("execution evidence receipt workspace path mismatch")
        if receipt["evidence_status"] != execution_evidence_bundle["evidence_status"]:
            raise ValueError("execution evidence receipt status mismatch")
        present_files = [ref for ref, item in execution_evidence_bundle["hash_refs"].items() if item["present"]]
        if receipt["evidence_file_count"] != len(present_files):
            raise ValueError("execution evidence receipt file count mismatch")
        if receipt["missing_evidence_count"] != len(execution_evidence_bundle["missing_evidence"]):
            raise ValueError("execution evidence receipt missing count mismatch")
        import hashlib

        expected_hash = hashlib.sha256(stable_execution_evidence_bundle_json(execution_evidence_bundle).encode("utf-8")).hexdigest()
        if receipt["receipt_hash"] != expected_hash:
            raise ValueError("execution evidence receipt hash mismatch")



SUPERVISED_EXECUTION_PLAN_VERSION = "link-supervised-execution-plan-v1"
SUPERVISED_EXECUTION_REQUEST_VERSION = "link-supervised-execution-request-v1"
SUPERVISED_EXECUTION_RECEIPT_VERSION = "link-supervised-execution-receipt-v1"


def make_supervised_execution_plan_id(
    planning_chain_id: str,
    execution_package_id: str,
    workspace_boundary_id: str,
    patch_applier_boundary_id: str,
    evidence_contract_id: str,
    lifecycle_steps: list[dict[str, Any]],
) -> str:
    return _execution_readiness_id("supervised-execution-plan", {
        "evidence_contract_id": evidence_contract_id,
        "execution_package_id": execution_package_id,
        "lifecycle_steps": lifecycle_steps,
        "patch_applier_boundary_id": patch_applier_boundary_id,
        "planning_chain_id": planning_chain_id,
        "version": SUPERVISED_EXECUTION_PLAN_VERSION,
        "workspace_boundary_id": workspace_boundary_id,
    })


def make_supervised_execution_request_id(
    supervised_execution_plan_id: str,
    workspace_root: str,
    verification_commands: list[str],
    approved: bool,
    write: bool,
) -> str:
    return _execution_readiness_id("supervised-execution-request", {
        "approved": approved,
        "supervised_execution_plan_id": supervised_execution_plan_id,
        "verification_commands": verification_commands,
        "version": SUPERVISED_EXECUTION_REQUEST_VERSION,
        "workspace_root": workspace_root,
        "write": write,
    })


def make_supervised_execution_receipt_id(
    request_id: str,
    supervised_execution_plan_id: str,
    workspace_receipt_id: str,
    patch_receipt_id: str,
    verification_receipt_id: str,
    rollback_receipt_id: str,
    evidence_bundle_id: str,
    final_status: str,
) -> str:
    return _execution_readiness_id("supervised-execution-receipt", {
        "evidence_bundle_id": evidence_bundle_id,
        "final_status": final_status,
        "patch_receipt_id": patch_receipt_id,
        "request_id": request_id,
        "rollback_receipt_id": rollback_receipt_id,
        "supervised_execution_plan_id": supervised_execution_plan_id,
        "verification_receipt_id": verification_receipt_id,
        "version": SUPERVISED_EXECUTION_RECEIPT_VERSION,
        "workspace_receipt_id": workspace_receipt_id,
    })


def _supervised_execution_lifecycle_steps() -> list[dict[str, Any]]:
    steps = [
        ("workspace", "create guarded temporary workspace"),
        ("patch", "apply verified patch inside guarded workspace"),
        ("verify", "run allowlisted Python verification inside guarded workspace"),
        ("rollback_if_needed", "rollback workspace-local changes when verification fails"),
        ("evidence", "collect workspace-local execution evidence"),
        ("review_package", "produce supervised execution receipt for human review"),
    ]
    return [
        {
            "order": index,
            "stage": stage,
            "description": description,
            "stop_on_failure": stage in {"workspace", "patch", "verify", "evidence"},
        }
        for index, (stage, description) in enumerate(steps, start=1)
    ]


def collect_supervised_execution_plan(
    planning_chain: dict[str, Any] | None = None,
    *,
    verification_commands: list[str] | None = None,
    metadata: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Build a deterministic supervised execution plan without touching the filesystem."""
    chain = planning_chain or collect_growth_planning_chain_preview()
    validate_growth_planning_chain_preview(chain)
    workspace_boundary = collect_workspace_creator_runtime_boundary(chain)
    workspace_plan = collect_workspace_creator_runtime_plan(chain)
    patch_boundary = collect_patch_boundary_preview_from_chain(chain)
    execution_review = collect_execution_review(chain)
    commands = [command.strip() for command in (verification_commands or ["python3 -c \"print('link supervised execution preview')\""])]
    lifecycle_steps = _supervised_execution_lifecycle_steps()
    evidence_requirements = _normalize_implementation_branch_refs([
        "workspace_creation_receipt",
        "guarded_patch_receipt",
        "guarded_verification_receipt",
        "execution_evidence_bundle",
        "execution_evidence_receipt",
    ])
    planned_steps = {step["stage"]: step for step in lifecycle_steps}
    plan = {
        "supervised_execution_plan_version": SUPERVISED_EXECUTION_PLAN_VERSION,
        "supervised_execution_plan_id": make_supervised_execution_plan_id(
            chain["planning_chain_id"],
            chain["autonomous_execution_package"]["execution_package_id"],
            workspace_boundary["workspace_boundary_id"],
            patch_boundary["patch_applier_boundary_id"],
            chain["execution_evidence_contract"]["execution_evidence_contract_id"],
            lifecycle_steps,
        ),
        "planning_chain_id": chain["planning_chain_id"],
        "execution_package_id": chain["autonomous_execution_package"]["execution_package_id"],
        "workspace_boundary_id": workspace_boundary["workspace_boundary_id"],
        "runtime_workspace_plan_id": workspace_plan["runtime_workspace_plan_id"],
        "patch_applier_boundary_id": patch_boundary["patch_applier_boundary_id"],
        "execution_evidence_contract_id": chain["execution_evidence_contract"]["execution_evidence_contract_id"],
        "execution_retry_policy_id": chain["execution_retry_policy"]["retry_policy_id"],
        "execution_review_id": execution_review["execution_review_id"],
        "lifecycle_steps": lifecycle_steps,
        "planned_workspace_step": planned_steps["workspace"],
        "planned_patch_step": planned_steps["patch"],
        "planned_verification_step": planned_steps["verify"],
        "planned_rollback_step": planned_steps["rollback_if_needed"],
        "planned_evidence_step": planned_steps["evidence"],
        "approval_required": True,
        "write_required": True,
        "verification_commands": commands,
        "success_criteria": _normalize_patch_behavior_text_list([
            "workspace receipt created",
            "patch receipt created",
            "verification receipt created",
            "evidence bundle created",
            "repository files remain unchanged",
        ]),
        "failure_criteria": _normalize_patch_behavior_text_list([
            "boundary validation fails",
            "explicit approval missing for write execution",
            "patch application fails",
            "verification command fails",
            "workspace path is inside repository root",
        ]),
        "rollback_policy": "rollback workspace-local patch changes when verification fails",
        "evidence_requirements": evidence_requirements,
        "review_package_requirements": _normalize_implementation_branch_refs([
            "supervised_execution_receipt",
            "execution_evidence_bundle",
            "execution_evidence_receipt",
        ]),
        "recommended_next_action": "review supervised execution plan before enabling --write",
        "dry_run": True,
        "write_allowed": False,
        "automation_allowed": False,
        "writes": [],
        "metadata": dict(metadata or {}),
    }
    validate_supervised_execution_plan(plan, chain)
    return plan


def validate_supervised_execution_plan(
    plan: dict[str, Any],
    planning_chain: dict[str, Any] | None = None,
) -> None:
    required = (
        "supervised_execution_plan_version", "supervised_execution_plan_id", "planning_chain_id",
        "execution_package_id", "workspace_boundary_id", "runtime_workspace_plan_id",
        "patch_applier_boundary_id", "execution_evidence_contract_id", "execution_retry_policy_id",
        "execution_review_id", "lifecycle_steps", "planned_workspace_step", "planned_patch_step",
        "planned_verification_step", "planned_rollback_step", "planned_evidence_step",
        "approval_required", "write_required", "verification_commands", "success_criteria",
        "failure_criteria", "rollback_policy", "evidence_requirements", "review_package_requirements",
        "recommended_next_action", "dry_run", "write_allowed", "automation_allowed", "writes", "metadata",
    )
    missing = [field for field in required if field not in plan]
    if missing:
        raise ValueError(f"supervised execution plan missing fields: {missing}")
    if plan["supervised_execution_plan_version"] != SUPERVISED_EXECUTION_PLAN_VERSION:
        raise ValueError("unsupported supervised execution plan version")
    for field in (
        "supervised_execution_plan_id", "planning_chain_id", "execution_package_id",
        "workspace_boundary_id", "runtime_workspace_plan_id", "patch_applier_boundary_id",
        "execution_evidence_contract_id", "execution_retry_policy_id", "execution_review_id",
        "rollback_policy",
    ):
        _validate_non_empty_string(plan[field], field)
    steps = plan["lifecycle_steps"]
    if not isinstance(steps, list) or len(steps) != 6:
        raise TypeError("lifecycle_steps must contain six ordered stages")
    expected_stages = ["workspace", "patch", "verify", "rollback_if_needed", "evidence", "review_package"]
    for index, step in enumerate(steps, start=1):
        if step.get("order") != index:
            raise ValueError("supervised execution lifecycle steps must be ordered")
        if step.get("stage") != expected_stages[index - 1]:
            raise ValueError("supervised execution lifecycle stage mismatch")
        _validate_non_empty_string(step.get("description"), "lifecycle step description")
        if not isinstance(step.get("stop_on_failure"), bool):
            raise TypeError("lifecycle step stop_on_failure must be boolean")
    planned_step_refs = {
        "planned_workspace_step": "workspace",
        "planned_patch_step": "patch",
        "planned_verification_step": "verify",
        "planned_rollback_step": "rollback_if_needed",
        "planned_evidence_step": "evidence",
    }
    stage_to_step = {step["stage"]: step for step in steps}
    for field, stage in planned_step_refs.items():
        if plan[field] != stage_to_step[stage]:
            raise ValueError(f"{field} must match lifecycle step {stage}")
    if plan["approval_required"] is not True or plan["write_required"] is not True:
        raise ValueError("supervised execution must require approval and write for runtime execution")
    _validate_non_empty_string(plan["recommended_next_action"], "recommended_next_action")
    commands = plan["verification_commands"]
    if not isinstance(commands, list) or not commands:
        raise TypeError("verification_commands must be a non-empty list")
    for command in commands:
        _validate_non_empty_string(command, "verification command")
        if command != command.strip():
            raise ValueError("verification commands must be stripped")
        _guarded_verification_split_command(command)
    for field in ("success_criteria", "failure_criteria", "evidence_requirements", "review_package_requirements", "writes"):
        values = plan[field]
        if not isinstance(values, list):
            raise TypeError(f"{field} must be a list")
        if values != _normalize_implementation_branch_refs(values):
            raise ValueError(f"{field} must be normalized")
    if not plan["success_criteria"] or not plan["failure_criteria"] or not plan["evidence_requirements"]:
        raise ValueError("supervised execution plan criteria and evidence requirements must not be empty")
    if plan["dry_run"] is not True or plan["write_allowed"] is not False or plan["automation_allowed"] is not False or plan["writes"] != []:
        raise ValueError("supervised execution plan must be read-only")
    if not isinstance(plan["metadata"], dict):
        raise TypeError("metadata must be a dict")
    expected_id = make_supervised_execution_plan_id(
        plan["planning_chain_id"],
        plan["execution_package_id"],
        plan["workspace_boundary_id"],
        plan["patch_applier_boundary_id"],
        plan["execution_evidence_contract_id"],
        steps,
    )
    if plan["supervised_execution_plan_id"] != expected_id:
        raise ValueError("supervised execution plan id does not match contents")
    if planning_chain is not None:
        validate_growth_planning_chain_preview(planning_chain)
        if plan["planning_chain_id"] != planning_chain["planning_chain_id"]:
            raise ValueError("supervised execution plan planning chain mismatch")
        if plan["execution_package_id"] != planning_chain["autonomous_execution_package"]["execution_package_id"]:
            raise ValueError("supervised execution plan execution package mismatch")
        if plan["execution_evidence_contract_id"] != planning_chain["execution_evidence_contract"]["execution_evidence_contract_id"]:
            raise ValueError("supervised execution plan evidence contract mismatch")


def stable_supervised_execution_plan_json(plan: dict[str, Any]) -> str:
    validate_supervised_execution_plan(plan)
    return _stable_ruflo_json(plan, indent=2) + "\n"


def parse_supervised_execution_plan_json(text: str) -> dict[str, Any]:
    plan = json.loads(text)
    validate_supervised_execution_plan(plan)
    return plan



SUPERVISED_EXECUTION_WRITE_BOUNDARY_VERSION = "link-supervised-execution-write-boundary-v1"


def make_supervised_execution_write_boundary_id(
    supervised_execution_plan_id: str,
    approval_status: str,
    gate_status: str,
    evidence_status: str,
    workspace_status: str,
    patch_status: str,
    verification_status: str,
    rollback_status: str,
    blockers: list[str],
    warnings: list[str],
) -> str:
    return _execution_readiness_id("supervised-execution-write-boundary", {
        "approval_status": approval_status,
        "blockers": blockers,
        "evidence_status": evidence_status,
        "gate_status": gate_status,
        "patch_status": patch_status,
        "rollback_status": rollback_status,
        "supervised_execution_plan_id": supervised_execution_plan_id,
        "verification_status": verification_status,
        "version": SUPERVISED_EXECUTION_WRITE_BOUNDARY_VERSION,
        "warnings": warnings,
        "workspace_status": workspace_status,
    })


def _supervised_boundary_status_from_gate_stack(gate_stack: dict[str, Any]) -> str:
    if gate_stack["block_count"]:
        return "block"
    if gate_stack["review_count"]:
        return "review"
    return "pass"


def _supervised_boundary_contract_status(contract: dict[str, Any]) -> tuple[str, list[str]]:
    required_types = {"compile", "healthcheck", "patch_application", "quality_gate", "rollback", "tests"}
    present_types = {item["evidence_type"] for item in contract["evidence_items"]}
    missing = _normalize_implementation_branch_refs(sorted(required_types - present_types))
    return ("block" if missing else "pass", missing)


def collect_supervised_execution_write_boundary(
    planning_chain: dict[str, Any] | None = None,
    *,
    supervised_execution_plan: dict[str, Any] | None = None,
    execution_review: dict[str, Any] | None = None,
    execution_approval_checklist: dict[str, Any] | None = None,
    execution_gate_stack_preview: dict[str, Any] | None = None,
    execution_evidence_contract: dict[str, Any] | None = None,
    workspace_boundary: dict[str, Any] | None = None,
    patch_boundary: dict[str, Any] | None = None,
    verification_boundary: dict[str, Any] | None = None,
    rollback_boundary: dict[str, Any] | None = None,
    metadata: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Return the read-only authorization boundary for future supervised --write."""
    chain = planning_chain or collect_growth_planning_chain_preview()
    validate_growth_planning_chain_preview(chain)
    plan = supervised_execution_plan or collect_supervised_execution_plan(chain)
    review = execution_review or collect_execution_review(chain)
    approval = execution_approval_checklist or collect_execution_approval_checklist(chain)
    gate_stack = execution_gate_stack_preview or chain["execution_gate_stack_preview"]
    evidence_contract = execution_evidence_contract or chain["execution_evidence_contract"]
    workspace = workspace_boundary or collect_workspace_creator_runtime_boundary(chain)
    patch = patch_boundary or collect_patch_boundary_preview_from_chain(chain)
    verification = verification_boundary or collect_verification_boundary_preview_from_chain(chain)
    rollback = rollback_boundary or collect_rollback_boundary_preview_from_chain(chain)

    validate_supervised_execution_plan(plan, chain)
    validate_execution_review(review)
    validate_execution_approval_checklist(approval)
    validate_execution_gate_stack_preview(gate_stack)
    validate_execution_evidence_contract(evidence_contract)
    validate_workspace_creator_runtime_boundary(workspace)
    validate_patch_applier_boundary(patch)
    validate_verification_runner_boundary(verification)
    validate_rollback_runtime_boundary(rollback)

    approval_status = approval["approval_status"]
    gate_status = _supervised_boundary_status_from_gate_stack(gate_stack)
    evidence_status, missing_evidence = _supervised_boundary_contract_status(evidence_contract)
    workspace_status = workspace["boundary_status"]
    patch_status = "pass"
    verification_status = "pass"
    rollback_status = "pass"
    blockers: list[str] = []
    warnings: list[str] = []
    required_actions: list[str] = [
        "human reviewer must explicitly approve supervised execution before --write",
        *approval["required_approvals"],
    ]
    if approval_status != "pass":
        blockers.append(f"approval checklist status is {approval_status}")
    if gate_status != "pass":
        blockers.append(f"execution gate stack status is {gate_status}")
    if evidence_status != "pass":
        blockers.append("execution evidence contract is missing required evidence definitions")
    if workspace_status != "pass":
        blockers.append(f"workspace boundary status is {workspace_status}")
    for label, status in (
        ("patch boundary", patch_status),
        ("verification boundary", verification_status),
        ("rollback boundary", rollback_status),
    ):
        if status != "pass":
            blockers.append(f"{label} status is {status}")
    warnings.extend(approval["approval_warnings"])
    warnings.extend(gate.get("warnings", []) for gate in gate_stack["gates"])
    flattened_warnings: list[str] = []
    for item in warnings:
        if isinstance(item, list):
            flattened_warnings.extend(item)
        else:
            flattened_warnings.append(item)
    warnings = flattened_warnings
    if workspace["warning_count"]:
        warnings.append(f"workspace boundary has {workspace['warning_count']} warning(s)")
    blockers = _normalize_patch_behavior_text_list(blockers)
    warnings = _normalize_patch_behavior_text_list(warnings)
    required_actions = _normalize_patch_behavior_text_list(required_actions)
    authorization = "allowed" if not blockers else "denied"
    if authorization == "allowed":
        next_action = "Supervised execution write boundary is clear; require explicit human approval before --write."
    else:
        next_action = "Resolve supervised execution write blockers before exposing or running --write."
    boundary = {
        "supervised_execution_write_boundary_version": SUPERVISED_EXECUTION_WRITE_BOUNDARY_VERSION,
        "supervised_execution_write_boundary_id": make_supervised_execution_write_boundary_id(
            plan["supervised_execution_plan_id"],
            approval_status,
            gate_status,
            evidence_status,
            workspace_status,
            patch_status,
            verification_status,
            rollback_status,
            blockers,
            warnings,
        ),
        "planning_chain_id": chain["planning_chain_id"],
        "execution_package_id": plan["execution_package_id"],
        "supervised_execution_plan_id": plan["supervised_execution_plan_id"],
        "execution_review_id": review["execution_review_id"],
        "approval_checklist_id": approval["approval_checklist_id"],
        "gate_stack_preview_id": gate_stack["gate_stack_preview_id"],
        "execution_evidence_contract_id": evidence_contract["execution_evidence_contract_id"],
        "workspace_boundary_id": workspace["workspace_boundary_id"],
        "patch_applier_boundary_id": patch["patch_applier_boundary_id"],
        "verification_runner_boundary_id": verification["verification_runner_boundary_id"],
        "rollback_runtime_boundary_id": rollback["rollback_runtime_boundary_id"],
        "approval_status": approval_status,
        "gate_status": gate_status,
        "evidence_status": evidence_status,
        "workspace_status": workspace_status,
        "patch_status": patch_status,
        "verification_status": verification_status,
        "rollback_status": rollback_status,
        "write_authorization_status": authorization,
        "missing_evidence": missing_evidence,
        "blockers": blockers,
        "warnings": warnings,
        "required_human_actions": required_actions,
        "recommended_next_action": next_action,
        "dry_run": True,
        "write_allowed": False,
        "automation_allowed": False,
        "writes": [],
        "metadata": dict(metadata or {}),
    }
    validate_supervised_execution_write_boundary(
        boundary,
        planning_chain=chain,
        supervised_execution_plan=plan,
        execution_review=review,
        execution_approval_checklist=approval,
        execution_gate_stack_preview=gate_stack,
        execution_evidence_contract=evidence_contract,
        workspace_boundary=workspace,
        patch_boundary=patch,
        verification_boundary=verification,
        rollback_boundary=rollback,
    )
    return boundary


def validate_supervised_execution_write_boundary(
    boundary: dict[str, Any],
    *,
    planning_chain: dict[str, Any] | None = None,
    supervised_execution_plan: dict[str, Any] | None = None,
    execution_review: dict[str, Any] | None = None,
    execution_approval_checklist: dict[str, Any] | None = None,
    execution_gate_stack_preview: dict[str, Any] | None = None,
    execution_evidence_contract: dict[str, Any] | None = None,
    workspace_boundary: dict[str, Any] | None = None,
    patch_boundary: dict[str, Any] | None = None,
    verification_boundary: dict[str, Any] | None = None,
    rollback_boundary: dict[str, Any] | None = None,
) -> None:
    required = (
        "supervised_execution_write_boundary_version", "supervised_execution_write_boundary_id",
        "planning_chain_id", "execution_package_id", "supervised_execution_plan_id",
        "execution_review_id", "approval_checklist_id", "gate_stack_preview_id",
        "execution_evidence_contract_id", "workspace_boundary_id", "patch_applier_boundary_id",
        "verification_runner_boundary_id", "rollback_runtime_boundary_id", "approval_status",
        "gate_status", "evidence_status", "workspace_status", "patch_status", "verification_status",
        "rollback_status", "write_authorization_status", "missing_evidence", "blockers", "warnings",
        "required_human_actions", "recommended_next_action", "dry_run", "write_allowed",
        "automation_allowed", "writes", "metadata",
    )
    missing = [field for field in required if field not in boundary]
    if missing:
        raise ValueError(f"supervised execution write boundary missing fields: {missing}")
    if boundary["supervised_execution_write_boundary_version"] != SUPERVISED_EXECUTION_WRITE_BOUNDARY_VERSION:
        raise ValueError("unsupported supervised execution write boundary version")
    for field in (
        "supervised_execution_write_boundary_id", "planning_chain_id", "execution_package_id",
        "supervised_execution_plan_id", "execution_review_id", "approval_checklist_id",
        "gate_stack_preview_id", "execution_evidence_contract_id", "workspace_boundary_id",
        "patch_applier_boundary_id", "verification_runner_boundary_id", "rollback_runtime_boundary_id",
        "approval_status", "gate_status", "evidence_status", "workspace_status", "patch_status",
        "verification_status", "rollback_status", "write_authorization_status", "recommended_next_action",
    ):
        _validate_non_empty_string(boundary[field], field)
    for field in ("approval_status", "gate_status", "evidence_status", "workspace_status", "patch_status", "verification_status", "rollback_status"):
        if boundary[field] not in {"pass", "review", "block"}:
            raise ValueError(f"invalid {field}")
    if boundary["write_authorization_status"] not in {"allowed", "denied"}:
        raise ValueError("invalid write_authorization_status")
    for field in ("blockers", "warnings", "required_human_actions"):
        values = boundary[field]
        if not isinstance(values, list):
            raise TypeError(f"{field} must be a list")
        if field == "required_human_actions" and not values:
            raise ValueError("required_human_actions must not be empty")
        if values != _normalize_patch_behavior_text_list(values):
            raise ValueError(f"{field} must be normalized and sorted")
    if boundary["missing_evidence"] != _normalize_implementation_branch_refs(boundary["missing_evidence"]):
        raise ValueError("missing_evidence must be normalized and sorted")
    if boundary["blockers"] and boundary["write_authorization_status"] != "denied":
        raise ValueError("write authorization must be denied when blockers exist")
    if not boundary["blockers"] and boundary["write_authorization_status"] != "allowed":
        raise ValueError("write authorization may be allowed only without blockers")
    if boundary["write_authorization_status"] == "allowed":
        for field in ("approval_status", "gate_status", "evidence_status", "workspace_status", "patch_status", "verification_status", "rollback_status"):
            if boundary[field] != "pass":
                raise ValueError("allowed write authorization requires every status to pass")
    if boundary["dry_run"] is not True or boundary["write_allowed"] is not False or boundary["automation_allowed"] is not False or boundary["writes"] != []:
        raise ValueError("supervised execution write boundary must be read-only")
    if not isinstance(boundary["metadata"], dict):
        raise TypeError("metadata must be a dict")
    expected_id = make_supervised_execution_write_boundary_id(
        boundary["supervised_execution_plan_id"],
        boundary["approval_status"],
        boundary["gate_status"],
        boundary["evidence_status"],
        boundary["workspace_status"],
        boundary["patch_status"],
        boundary["verification_status"],
        boundary["rollback_status"],
        boundary["blockers"],
        boundary["warnings"],
    )
    if boundary["supervised_execution_write_boundary_id"] != expected_id:
        raise ValueError("supervised execution write boundary id does not match contents")
    if planning_chain is not None:
        validate_growth_planning_chain_preview(planning_chain)
        if boundary["planning_chain_id"] != planning_chain["planning_chain_id"]:
            raise ValueError("write boundary planning chain mismatch")
        if boundary["execution_package_id"] != planning_chain["autonomous_execution_package"]["execution_package_id"]:
            raise ValueError("write boundary execution package mismatch")
    if supervised_execution_plan is not None:
        validate_supervised_execution_plan(supervised_execution_plan)
        if boundary["supervised_execution_plan_id"] != supervised_execution_plan["supervised_execution_plan_id"]:
            raise ValueError("write boundary supervised plan mismatch")
    if execution_review is not None:
        validate_execution_review(execution_review)
        if boundary["execution_review_id"] != execution_review["execution_review_id"]:
            raise ValueError("write boundary execution review mismatch")
    if execution_approval_checklist is not None:
        validate_execution_approval_checklist(execution_approval_checklist)
        if boundary["approval_checklist_id"] != execution_approval_checklist["approval_checklist_id"]:
            raise ValueError("write boundary approval checklist mismatch")
        if boundary["approval_status"] != execution_approval_checklist["approval_status"]:
            raise ValueError("write boundary approval status mismatch")
    if execution_gate_stack_preview is not None:
        validate_execution_gate_stack_preview(execution_gate_stack_preview)
        if boundary["gate_stack_preview_id"] != execution_gate_stack_preview["gate_stack_preview_id"]:
            raise ValueError("write boundary gate stack mismatch")
        if boundary["gate_status"] != _supervised_boundary_status_from_gate_stack(execution_gate_stack_preview):
            raise ValueError("write boundary gate status mismatch")
    if execution_evidence_contract is not None:
        validate_execution_evidence_contract(execution_evidence_contract)
        if boundary["execution_evidence_contract_id"] != execution_evidence_contract["execution_evidence_contract_id"]:
            raise ValueError("write boundary evidence contract mismatch")
        expected_status, expected_missing = _supervised_boundary_contract_status(execution_evidence_contract)
        if boundary["evidence_status"] != expected_status or boundary["missing_evidence"] != expected_missing:
            raise ValueError("write boundary evidence status mismatch")
    if workspace_boundary is not None:
        validate_workspace_creator_runtime_boundary(workspace_boundary)
        if boundary["workspace_boundary_id"] != workspace_boundary["workspace_boundary_id"]:
            raise ValueError("write boundary workspace boundary mismatch")
        if boundary["workspace_status"] != workspace_boundary["boundary_status"]:
            raise ValueError("write boundary workspace status mismatch")
    if patch_boundary is not None:
        validate_patch_applier_boundary(patch_boundary)
        if boundary["patch_applier_boundary_id"] != patch_boundary["patch_applier_boundary_id"]:
            raise ValueError("write boundary patch boundary mismatch")
    if verification_boundary is not None:
        validate_verification_runner_boundary(verification_boundary)
        if boundary["verification_runner_boundary_id"] != verification_boundary["verification_runner_boundary_id"]:
            raise ValueError("write boundary verification boundary mismatch")
    if rollback_boundary is not None:
        validate_rollback_runtime_boundary(rollback_boundary)
        if boundary["rollback_runtime_boundary_id"] != rollback_boundary["rollback_runtime_boundary_id"]:
            raise ValueError("write boundary rollback boundary mismatch")


def stable_supervised_execution_write_boundary_json(boundary: dict[str, Any]) -> str:
    validate_supervised_execution_write_boundary(boundary)
    return _stable_ruflo_json(boundary, indent=2) + "\n"


def parse_supervised_execution_write_boundary_json(text: str) -> dict[str, Any]:
    boundary = json.loads(text)
    validate_supervised_execution_write_boundary(boundary)
    return boundary


SUPERVISED_EXECUTION_REVIEW_PACKAGE_VERSION = "link-supervised-execution-review-package-v1"


def make_supervised_execution_review_package_id(
    planning_chain_id: str,
    supervised_execution_plan_id: str,
    supervised_execution_write_boundary_id: str,
    execution_package_id: str,
    workspace_status: str,
    patch_status: str,
    verification_status: str,
    rollback_status: str,
    evidence_status: str,
    blockers: list[str],
    warnings: list[str],
    required_human_actions: list[str],
) -> str:
    return _execution_readiness_id("supervised-execution-review-package", {
        "blockers": blockers,
        "evidence_status": evidence_status,
        "execution_package_id": execution_package_id,
        "patch_status": patch_status,
        "planning_chain_id": planning_chain_id,
        "required_human_actions": required_human_actions,
        "rollback_status": rollback_status,
        "supervised_execution_plan_id": supervised_execution_plan_id,
        "supervised_execution_write_boundary_id": supervised_execution_write_boundary_id,
        "verification_status": verification_status,
        "version": SUPERVISED_EXECUTION_REVIEW_PACKAGE_VERSION,
        "warnings": warnings,
        "workspace_status": workspace_status,
    })


def _supervised_execution_review_recommendation(
    blockers: list[str],
    warnings: list[str],
    write_boundary: dict[str, Any],
) -> str:
    if blockers or write_boundary["write_authorization_status"] == "denied":
        return "do_not_execute"
    if warnings:
        return "review_before_execute"
    return "ready_for_human_approval"


def collect_supervised_execution_review_package(
    planning_chain: dict[str, Any] | None = None,
    *,
    supervised_execution_plan: dict[str, Any] | None = None,
    supervised_execution_write_boundary: dict[str, Any] | None = None,
    execution_review: dict[str, Any] | None = None,
    evidence_bundle: dict[str, Any] | None = None,
    approval_checklist: dict[str, Any] | None = None,
    gate_stack: dict[str, Any] | None = None,
    metadata: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Return a compact read-only package summarizing the whole execution state."""
    chain = planning_chain or collect_growth_planning_chain_preview()
    validate_growth_planning_chain_preview(chain)
    plan = supervised_execution_plan or collect_supervised_execution_plan(chain)
    boundary = supervised_execution_write_boundary or collect_supervised_execution_write_boundary(chain, supervised_execution_plan=plan)
    review = execution_review or collect_execution_review(chain)
    approval = approval_checklist or collect_execution_approval_checklist(chain)
    gates = gate_stack or chain["execution_gate_stack_preview"]

    validate_supervised_execution_plan(plan, chain)
    validate_supervised_execution_write_boundary(boundary, planning_chain=chain, supervised_execution_plan=plan)
    validate_execution_review(review)
    validate_execution_approval_checklist(approval)
    validate_execution_gate_stack_preview(gates)
    if evidence_bundle is not None:
        validate_execution_evidence_bundle(evidence_bundle)
        if evidence_bundle["planning_chain_id"] != chain["planning_chain_id"]:
            raise ValueError("supervised execution review package evidence planning chain mismatch")
        if evidence_bundle["execution_package_id"] != plan["execution_package_id"]:
            raise ValueError("supervised execution review package evidence execution package mismatch")

    evidence_status = evidence_bundle["evidence_status"] if evidence_bundle is not None else boundary["evidence_status"]
    evidence_bundle_id = evidence_bundle["execution_evidence_bundle_id"] if evidence_bundle is not None else ""
    blockers = [
        *boundary["blockers"],
        *review["blocker_summary"]["top_blockers"],
        *approval["approval_blockers"],
        *(f"{gate['gate_type']}: {blocker}" for gate in gates["gates"] for blocker in gate["blockers"]),
    ]
    if evidence_bundle is not None and evidence_bundle["missing_evidence"]:
        blockers.append(f"evidence bundle missing {len(evidence_bundle['missing_evidence'])} evidence item(s)")
    blockers = _normalize_patch_behavior_text_list(blockers)
    warnings = [
        *boundary["warnings"],
        *review["warning_summary"]["top_warnings"],
        *approval["approval_warnings"],
        *(f"{gate['gate_type']}: {warning}" for gate in gates["gates"] for warning in gate["warnings"]),
    ]
    if evidence_bundle is not None and evidence_bundle["evidence_status"] == "missing_evidence":
        warnings.append(evidence_bundle["reviewer_summary"])
    warnings = _normalize_patch_behavior_text_list(warnings)
    required_actions = _normalize_patch_behavior_text_list([
        *boundary["required_human_actions"],
        *approval["required_approvals"],
    ])
    recommendation = _supervised_execution_review_recommendation(blockers, warnings, boundary)
    if recommendation == "do_not_execute":
        next_action = "Resolve supervised execution blockers before any write-enabled execution."
    elif recommendation == "review_before_execute":
        next_action = "Review supervised execution warnings and required human actions before write authorization."
    else:
        next_action = "Package is ready for explicit human approval; runtime execution remains disabled by default."
    package = {
        "supervised_execution_review_package_version": SUPERVISED_EXECUTION_REVIEW_PACKAGE_VERSION,
        "supervised_execution_review_package_id": make_supervised_execution_review_package_id(
            chain["planning_chain_id"],
            plan["supervised_execution_plan_id"],
            boundary["supervised_execution_write_boundary_id"],
            plan["execution_package_id"],
            boundary["workspace_status"],
            boundary["patch_status"],
            boundary["verification_status"],
            boundary["rollback_status"],
            evidence_status,
            blockers,
            warnings,
            required_actions,
        ),
        "planning_chain_id": chain["planning_chain_id"],
        "supervised_execution_plan_id": plan["supervised_execution_plan_id"],
        "supervised_execution_write_boundary_id": boundary["supervised_execution_write_boundary_id"],
        "execution_package_id": plan["execution_package_id"],
        "execution_review_id": review["execution_review_id"],
        "execution_evidence_bundle_id": evidence_bundle_id,
        "approval_checklist_id": approval["approval_checklist_id"],
        "gate_stack_preview_id": gates["gate_stack_preview_id"],
        "workspace_status": boundary["workspace_status"],
        "patch_status": boundary["patch_status"],
        "verification_status": boundary["verification_status"],
        "rollback_status": boundary["rollback_status"],
        "evidence_status": evidence_status,
        "blockers": blockers,
        "warnings": warnings,
        "required_human_actions": required_actions,
        "review_recommendation": recommendation,
        "recommended_next_action": next_action,
        "dry_run": True,
        "write_allowed": False,
        "automation_allowed": False,
        "writes": [],
        "metadata": dict(metadata or {}),
    }
    validate_supervised_execution_review_package(
        package,
        planning_chain=chain,
        supervised_execution_plan=plan,
        supervised_execution_write_boundary=boundary,
        execution_review=review,
        evidence_bundle=evidence_bundle,
        approval_checklist=approval,
        gate_stack=gates,
    )
    return package


def validate_supervised_execution_review_package(
    package: dict[str, Any],
    *,
    planning_chain: dict[str, Any] | None = None,
    supervised_execution_plan: dict[str, Any] | None = None,
    supervised_execution_write_boundary: dict[str, Any] | None = None,
    execution_review: dict[str, Any] | None = None,
    evidence_bundle: dict[str, Any] | None = None,
    approval_checklist: dict[str, Any] | None = None,
    gate_stack: dict[str, Any] | None = None,
) -> None:
    required = (
        "supervised_execution_review_package_version", "supervised_execution_review_package_id",
        "planning_chain_id", "supervised_execution_plan_id", "supervised_execution_write_boundary_id",
        "execution_package_id", "execution_review_id", "execution_evidence_bundle_id",
        "approval_checklist_id", "gate_stack_preview_id", "workspace_status", "patch_status",
        "verification_status", "rollback_status", "evidence_status", "blockers", "warnings",
        "required_human_actions", "review_recommendation", "recommended_next_action",
        "dry_run", "write_allowed", "automation_allowed", "writes", "metadata",
    )
    missing = [field for field in required if field not in package]
    if missing:
        raise ValueError(f"supervised execution review package missing fields: {missing}")
    if package["supervised_execution_review_package_version"] != SUPERVISED_EXECUTION_REVIEW_PACKAGE_VERSION:
        raise ValueError("unsupported supervised execution review package version")
    _validate_execution_read_only(package, "supervised execution review package")
    for field in (
        "supervised_execution_review_package_id", "planning_chain_id", "supervised_execution_plan_id",
        "supervised_execution_write_boundary_id", "execution_package_id", "execution_review_id",
        "approval_checklist_id", "gate_stack_preview_id", "workspace_status", "patch_status",
        "verification_status", "rollback_status", "evidence_status", "review_recommendation",
        "recommended_next_action",
    ):
        _validate_non_empty_string(package[field], field)
    if not isinstance(package["execution_evidence_bundle_id"], str):
        raise TypeError("execution_evidence_bundle_id must be a string")
    for field in ("workspace_status", "patch_status", "verification_status", "rollback_status"):
        if package[field] not in {"pass", "review", "block"}:
            raise ValueError(f"invalid {field}")
    if package["evidence_status"] not in {"pass", "block", "complete", "missing_evidence"}:
        raise ValueError("invalid evidence_status")
    if package["review_recommendation"] not in {"do_not_execute", "review_before_execute", "ready_for_human_approval"}:
        raise ValueError("invalid review_recommendation")
    for field in ("blockers", "warnings", "required_human_actions"):
        values = package[field]
        if not isinstance(values, list):
            raise TypeError(f"{field} must be a list")
        if field == "required_human_actions" and not values:
            raise ValueError("required_human_actions must not be empty")
        if values != _normalize_patch_behavior_text_list(values):
            raise ValueError(f"{field} must be normalized and sorted")
    if package["blockers"] and package["review_recommendation"] != "do_not_execute":
        raise ValueError("review recommendation must block when blockers exist")
    if not package["blockers"] and package["review_recommendation"] == "do_not_execute":
        raise ValueError("do_not_execute requires blockers")
    expected_id = make_supervised_execution_review_package_id(
        package["planning_chain_id"],
        package["supervised_execution_plan_id"],
        package["supervised_execution_write_boundary_id"],
        package["execution_package_id"],
        package["workspace_status"],
        package["patch_status"],
        package["verification_status"],
        package["rollback_status"],
        package["evidence_status"],
        package["blockers"],
        package["warnings"],
        package["required_human_actions"],
    )
    if package["supervised_execution_review_package_id"] != expected_id:
        raise ValueError("supervised execution review package id does not match contents")
    if not isinstance(package["metadata"], dict):
        raise TypeError("metadata must be a dict")
    if planning_chain is not None:
        validate_growth_planning_chain_preview(planning_chain)
        if package["planning_chain_id"] != planning_chain["planning_chain_id"]:
            raise ValueError("review package planning chain mismatch")
        if package["execution_package_id"] != planning_chain["autonomous_execution_package"]["execution_package_id"]:
            raise ValueError("review package execution package mismatch")
    if supervised_execution_plan is not None:
        validate_supervised_execution_plan(supervised_execution_plan)
        if package["supervised_execution_plan_id"] != supervised_execution_plan["supervised_execution_plan_id"]:
            raise ValueError("review package supervised plan mismatch")
        if package["execution_package_id"] != supervised_execution_plan["execution_package_id"]:
            raise ValueError("review package supervised plan execution package mismatch")
    if supervised_execution_write_boundary is not None:
        validate_supervised_execution_write_boundary(supervised_execution_write_boundary)
        if package["supervised_execution_write_boundary_id"] != supervised_execution_write_boundary["supervised_execution_write_boundary_id"]:
            raise ValueError("review package write boundary mismatch")
        for field in ("workspace_status", "patch_status", "verification_status", "rollback_status"):
            if package[field] != supervised_execution_write_boundary[field]:
                raise ValueError(f"review package {field} mismatch")
    if execution_review is not None:
        validate_execution_review(execution_review)
        if package["execution_review_id"] != execution_review["execution_review_id"]:
            raise ValueError("review package execution review mismatch")
    if evidence_bundle is not None:
        validate_execution_evidence_bundle(evidence_bundle)
        if package["execution_evidence_bundle_id"] != evidence_bundle["execution_evidence_bundle_id"]:
            raise ValueError("review package evidence bundle mismatch")
        if package["evidence_status"] != evidence_bundle["evidence_status"]:
            raise ValueError("review package evidence status mismatch")
    if approval_checklist is not None:
        validate_execution_approval_checklist(approval_checklist)
        if package["approval_checklist_id"] != approval_checklist["approval_checklist_id"]:
            raise ValueError("review package approval checklist mismatch")
    if gate_stack is not None:
        validate_execution_gate_stack_preview(gate_stack)
        if package["gate_stack_preview_id"] != gate_stack["gate_stack_preview_id"]:
            raise ValueError("review package gate stack mismatch")


def stable_supervised_execution_review_package_json(package: dict[str, Any]) -> str:
    validate_supervised_execution_review_package(package)
    return _stable_ruflo_json(package, indent=2) + "\n"


def parse_supervised_execution_review_package_json(text: str) -> dict[str, Any]:
    package = json.loads(text)
    validate_supervised_execution_review_package(package)
    return package


def make_supervised_execution_request(
    supervised_execution_plan: dict[str, Any],
    *,
    approved: bool = False,
    write: bool = False,
    workspace_root: str | None = None,
    verification_commands: list[str] | None = None,
    metadata: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Build a supervised execution request without executing runtime actions."""
    validate_supervised_execution_plan(supervised_execution_plan)
    root = workspace_root or "/tmp/link-supervised-execution"
    commands = [command.strip() for command in (verification_commands or supervised_execution_plan["verification_commands"])]
    request = {
        "supervised_execution_request_version": SUPERVISED_EXECUTION_REQUEST_VERSION,
        "request_id": make_supervised_execution_request_id(
            supervised_execution_plan["supervised_execution_plan_id"],
            root,
            commands,
            approved,
            write,
        ),
        "supervised_execution_plan_id": supervised_execution_plan["supervised_execution_plan_id"],
        "planning_chain_id": supervised_execution_plan["planning_chain_id"],
        "execution_package_id": supervised_execution_plan["execution_package_id"],
        "workspace_root": root,
        "verification_commands": commands,
        "approved": approved,
        "write": write,
        "dry_run": not write,
        "metadata": dict(metadata or {}),
    }
    validate_supervised_execution_request(request, supervised_execution_plan)
    return request


def validate_supervised_execution_request(
    request: dict[str, Any],
    supervised_execution_plan: dict[str, Any] | None = None,
) -> None:
    required = (
        "supervised_execution_request_version", "request_id", "supervised_execution_plan_id",
        "planning_chain_id", "execution_package_id", "workspace_root", "verification_commands",
        "approved", "write", "dry_run", "metadata",
    )
    missing = [field for field in required if field not in request]
    if missing:
        raise ValueError(f"supervised execution request missing fields: {missing}")
    if request["supervised_execution_request_version"] != SUPERVISED_EXECUTION_REQUEST_VERSION:
        raise ValueError("unsupported supervised execution request version")
    for field in ("request_id", "supervised_execution_plan_id", "planning_chain_id", "execution_package_id", "workspace_root"):
        _validate_non_empty_string(request[field], field)
    _guarded_patch_workspace_path(request["workspace_root"])
    if not isinstance(request["approved"], bool) or not isinstance(request["write"], bool):
        raise TypeError("approved and write must be booleans")
    if request["dry_run"] != (not request["write"]):
        raise ValueError("supervised execution request dry_run must invert write")
    if request["write"] and not request["approved"]:
        raise PermissionError("supervised execution requires explicit approval")
    commands = request["verification_commands"]
    if not isinstance(commands, list) or not commands:
        raise TypeError("verification_commands must be a non-empty list")
    for command in commands:
        _validate_non_empty_string(command, "verification command")
        if command != command.strip():
            raise ValueError("verification commands must be stripped")
        _guarded_verification_split_command(command)
    if not isinstance(request["metadata"], dict):
        raise TypeError("metadata must be a dict")
    expected_id = make_supervised_execution_request_id(
        request["supervised_execution_plan_id"],
        request["workspace_root"],
        commands,
        request["approved"],
        request["write"],
    )
    if request["request_id"] != expected_id:
        raise ValueError("supervised execution request id does not match contents")
    if supervised_execution_plan is not None:
        validate_supervised_execution_plan(supervised_execution_plan)
        if request["supervised_execution_plan_id"] != supervised_execution_plan["supervised_execution_plan_id"]:
            raise ValueError("supervised execution request plan mismatch")
        if request["planning_chain_id"] != supervised_execution_plan["planning_chain_id"]:
            raise ValueError("supervised execution request planning chain mismatch")
        if request["execution_package_id"] != supervised_execution_plan["execution_package_id"]:
            raise ValueError("supervised execution request package mismatch")


def collect_supervised_execution_receipt(
    request: dict[str, Any],
    supervised_execution_plan: dict[str, Any],
    *,
    workspace_creation_receipt: dict[str, Any],
    guarded_patch_receipt: dict[str, Any],
    guarded_verification_receipt: dict[str, Any],
    guarded_rollback_receipt: dict[str, Any] | None,
    execution_evidence_bundle: dict[str, Any],
    execution_evidence_receipt: dict[str, Any],
    final_status: str,
    review_recommendation: str,
    metadata: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Collect a supervised execution receipt from component receipts."""
    validate_supervised_execution_request(request, supervised_execution_plan)
    validate_workspace_creation_receipt(workspace_creation_receipt)
    validate_guarded_patch_receipt(guarded_patch_receipt)
    validate_guarded_verification_receipt(guarded_verification_receipt)
    if guarded_rollback_receipt is not None:
        validate_guarded_rollback_receipt(guarded_rollback_receipt)
    validate_execution_evidence_bundle(execution_evidence_bundle)
    validate_execution_evidence_receipt(execution_evidence_receipt, execution_evidence_bundle)
    if final_status not in {"preview", "passed", "failed", "rolled_back"}:
        raise ValueError("invalid supervised execution final_status")
    _validate_non_empty_string(review_recommendation, "review_recommendation")
    rollback_id = guarded_rollback_receipt["rollback_receipt_id"] if guarded_rollback_receipt is not None else ""
    writes = _normalize_implementation_branch_refs([
        *guarded_patch_receipt["safety_metadata"].get("writes", []),
        *guarded_verification_receipt["safety_metadata"].get("writes", []),
        *(guarded_rollback_receipt or {"safety_metadata": {"writes": []}})["safety_metadata"].get("writes", []),
        *execution_evidence_bundle["safety_metadata"].get("writes", []),
        *execution_evidence_receipt["safety_metadata"].get("writes", []),
    ]) if request["write"] else []
    safety = {
        "dry_run": not request["write"],
        "write_allowed": bool(request["write"]),
        "automation_allowed": False,
        "writes": writes,
    }
    receipt = {
        "supervised_execution_receipt_version": SUPERVISED_EXECUTION_RECEIPT_VERSION,
        "supervised_execution_id": make_supervised_execution_receipt_id(
            request["request_id"],
            supervised_execution_plan["supervised_execution_plan_id"],
            workspace_creation_receipt["creation_receipt_id"],
            guarded_patch_receipt["guarded_patch_receipt_id"],
            guarded_verification_receipt["verification_receipt_id"],
            rollback_id,
            execution_evidence_bundle["execution_evidence_bundle_id"],
            final_status,
        ),
        "request_id": request["request_id"],
        "supervised_execution_plan_id": supervised_execution_plan["supervised_execution_plan_id"],
        "planning_chain_id": supervised_execution_plan["planning_chain_id"],
        "execution_package_id": supervised_execution_plan["execution_package_id"],
        "workspace_receipt_id": workspace_creation_receipt["creation_receipt_id"],
        "patch_receipt_id": guarded_patch_receipt["guarded_patch_receipt_id"],
        "verification_receipt_id": guarded_verification_receipt["verification_receipt_id"],
        "rollback_receipt_id": rollback_id,
        "evidence_bundle_id": execution_evidence_bundle["execution_evidence_bundle_id"],
        "evidence_receipt_id": execution_evidence_receipt["execution_evidence_receipt_id"],
        "component_receipts": {
            "workspace": workspace_creation_receipt["creation_receipt_id"],
            "patch": guarded_patch_receipt["guarded_patch_receipt_id"],
            "verification": guarded_verification_receipt["verification_receipt_id"],
            "rollback": rollback_id,
            "evidence_bundle": execution_evidence_bundle["execution_evidence_bundle_id"],
            "evidence_receipt": execution_evidence_receipt["execution_evidence_receipt_id"],
        },
        "final_status": final_status,
        "review_recommendation": review_recommendation,
        "safety_metadata": safety,
        "metadata": dict(metadata or {}),
    }
    validate_supervised_execution_receipt(
        receipt,
        request,
        supervised_execution_plan,
        workspace_creation_receipt,
        guarded_patch_receipt,
        guarded_verification_receipt,
        guarded_rollback_receipt,
        execution_evidence_bundle,
        execution_evidence_receipt,
    )
    return receipt


def validate_supervised_execution_receipt(
    receipt: dict[str, Any],
    request: dict[str, Any] | None = None,
    supervised_execution_plan: dict[str, Any] | None = None,
    workspace_creation_receipt: dict[str, Any] | None = None,
    guarded_patch_receipt: dict[str, Any] | None = None,
    guarded_verification_receipt: dict[str, Any] | None = None,
    guarded_rollback_receipt: dict[str, Any] | None = None,
    execution_evidence_bundle: dict[str, Any] | None = None,
    execution_evidence_receipt: dict[str, Any] | None = None,
) -> None:
    required = (
        "supervised_execution_receipt_version", "supervised_execution_id", "request_id",
        "supervised_execution_plan_id", "planning_chain_id", "execution_package_id",
        "workspace_receipt_id", "patch_receipt_id", "verification_receipt_id",
        "rollback_receipt_id", "evidence_bundle_id", "evidence_receipt_id",
        "component_receipts", "final_status", "review_recommendation", "safety_metadata", "metadata",
    )
    missing = [field for field in required if field not in receipt]
    if missing:
        raise ValueError(f"supervised execution receipt missing fields: {missing}")
    if receipt["supervised_execution_receipt_version"] != SUPERVISED_EXECUTION_RECEIPT_VERSION:
        raise ValueError("unsupported supervised execution receipt version")
    for field in (
        "supervised_execution_id", "request_id", "supervised_execution_plan_id", "planning_chain_id",
        "execution_package_id", "workspace_receipt_id", "patch_receipt_id", "verification_receipt_id",
        "evidence_bundle_id", "evidence_receipt_id", "final_status", "review_recommendation",
    ):
        _validate_non_empty_string(receipt[field], field)
    if receipt["final_status"] not in {"preview", "passed", "failed", "rolled_back"}:
        raise ValueError("invalid supervised execution final_status")
    if not isinstance(receipt["component_receipts"], dict):
        raise TypeError("component_receipts must be a dict")
    for field in ("workspace", "patch", "verification", "rollback", "evidence_bundle", "evidence_receipt"):
        if field not in receipt["component_receipts"]:
            raise ValueError(f"component_receipts missing {field}")
    safety = receipt["safety_metadata"]
    if not isinstance(safety, dict):
        raise TypeError("safety_metadata must be a dict")
    if safety.get("automation_allowed") is not False:
        raise ValueError("supervised execution must keep automation disabled")
    if not isinstance(safety.get("writes"), list):
        raise TypeError("supervised execution writes must be a list")
    if safety["writes"] != _normalize_implementation_branch_refs(safety["writes"]):
        raise ValueError("supervised execution writes must be normalized")
    if safety.get("dry_run") is True:
        if safety.get("write_allowed") is not False or safety["writes"] != []:
            raise ValueError("dry-run supervised execution receipt must not allow writes")
    else:
        if safety.get("dry_run") is not False or safety.get("write_allowed") is not True:
            raise ValueError("written supervised execution receipt must record workspace-local write allowance")
    if not isinstance(receipt["metadata"], dict):
        raise TypeError("metadata must be a dict")
    expected_id = make_supervised_execution_receipt_id(
        receipt["request_id"],
        receipt["supervised_execution_plan_id"],
        receipt["workspace_receipt_id"],
        receipt["patch_receipt_id"],
        receipt["verification_receipt_id"],
        receipt["rollback_receipt_id"],
        receipt["evidence_bundle_id"],
        receipt["final_status"],
    )
    if receipt["supervised_execution_id"] != expected_id:
        raise ValueError("supervised execution receipt id does not match contents")
    if request is not None:
        validate_supervised_execution_request(request, supervised_execution_plan)
        if receipt["request_id"] != request["request_id"]:
            raise ValueError("supervised execution receipt request mismatch")
        if request["write"] and receipt["final_status"] == "preview":
            raise ValueError("write supervised execution cannot produce preview final status")
        if not request["write"] and receipt["final_status"] != "preview":
            raise ValueError("dry-run supervised execution must produce preview final status")
    if supervised_execution_plan is not None:
        validate_supervised_execution_plan(supervised_execution_plan)
        if receipt["supervised_execution_plan_id"] != supervised_execution_plan["supervised_execution_plan_id"]:
            raise ValueError("supervised execution receipt plan mismatch")
        if receipt["planning_chain_id"] != supervised_execution_plan["planning_chain_id"]:
            raise ValueError("supervised execution receipt planning chain mismatch")
    if workspace_creation_receipt is not None:
        validate_workspace_creation_receipt(workspace_creation_receipt)
        if receipt["workspace_receipt_id"] != workspace_creation_receipt["creation_receipt_id"]:
            raise ValueError("supervised execution workspace receipt mismatch")
    if guarded_patch_receipt is not None:
        validate_guarded_patch_receipt(guarded_patch_receipt)
        if receipt["patch_receipt_id"] != guarded_patch_receipt["guarded_patch_receipt_id"]:
            raise ValueError("supervised execution patch receipt mismatch")
    if guarded_verification_receipt is not None:
        validate_guarded_verification_receipt(guarded_verification_receipt)
        if receipt["verification_receipt_id"] != guarded_verification_receipt["verification_receipt_id"]:
            raise ValueError("supervised execution verification receipt mismatch")
    if guarded_rollback_receipt is not None:
        validate_guarded_rollback_receipt(guarded_rollback_receipt)
        if receipt["rollback_receipt_id"] != guarded_rollback_receipt["rollback_receipt_id"]:
            raise ValueError("supervised execution rollback receipt mismatch")
    if execution_evidence_bundle is not None:
        validate_execution_evidence_bundle(execution_evidence_bundle)
        if receipt["evidence_bundle_id"] != execution_evidence_bundle["execution_evidence_bundle_id"]:
            raise ValueError("supervised execution evidence bundle mismatch")
    if execution_evidence_receipt is not None:
        validate_execution_evidence_receipt(execution_evidence_receipt, execution_evidence_bundle)
        if receipt["evidence_receipt_id"] != execution_evidence_receipt["execution_evidence_receipt_id"]:
            raise ValueError("supervised execution evidence receipt mismatch")


def stable_supervised_execution_receipt_json(receipt: dict[str, Any]) -> str:
    validate_supervised_execution_receipt(receipt)
    return _stable_ruflo_json(receipt, indent=2) + "\n"


def parse_supervised_execution_receipt_json(text: str) -> dict[str, Any]:
    receipt = json.loads(text)
    validate_supervised_execution_receipt(receipt)
    return receipt


def _supervised_execution_receipt_files(workspace_path: str, workspace_receipt: dict[str, Any], patch_receipt: dict[str, Any]) -> None:
    workspace = _guarded_patch_workspace_path(workspace_path)
    (workspace / "workspace_creation_receipt.json").write_text(stable_workspace_creation_receipt_json(workspace_receipt), encoding="utf-8")
    (workspace / "guarded_patch_receipt.json").write_text(_stable_ruflo_json(patch_receipt, indent=2) + "\n", encoding="utf-8")


def _collect_preview_verification_receipt(
    verification_request: dict[str, Any],
    verification_boundary: dict[str, Any],
    patch_receipt: dict[str, Any],
    workspace_receipt: dict[str, Any],
    evidence_contract: dict[str, Any],
    retry_policy: dict[str, Any],
) -> dict[str, Any]:
    command = verification_request["commands"][0]
    command_hash = _guarded_verification_command_hash(command)
    return collect_guarded_verification_receipt(
        verification_request,
        verification_boundary,
        patch_receipt,
        workspace_receipt["workspace_manifest"],
        workspace_receipt,
        evidence_contract,
        retry_policy,
        executed_commands=[{
            "sequence": 1,
            "command": command,
            "command_hash": command_hash,
            "exit_code": 1,
            "stdout_ref": "verification_evidence/preview.stdout.log",
            "stderr_ref": "verification_evidence/preview.stderr.log",
            "evidence_ref": "verification_evidence/preview.evidence.json",
            "status": "failed",
        }],
        receipt_timestamp="preview-only",
        retry_count=0,
    )


def execute_supervised_execution(
    request: dict[str, Any],
    supervised_execution_plan: dict[str, Any],
    *,
    planning_chain: dict[str, Any] | None = None,
    execution_gate_stack_preview: dict[str, Any] | None = None,
    execution_approval_checklist: dict[str, Any] | None = None,
    execution_review: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Coordinate guarded runtime components as one fail-closed execution path."""
    validate_supervised_execution_request(request, supervised_execution_plan)
    chain = planning_chain or collect_growth_planning_chain_preview()
    validate_growth_planning_chain_preview(chain)
    validate_supervised_execution_plan(supervised_execution_plan, chain)

    gate_stack = execution_gate_stack_preview or chain["execution_gate_stack_preview"]
    approval = execution_approval_checklist or collect_execution_approval_checklist(chain)
    review = execution_review or collect_execution_review(chain)
    validate_execution_gate_stack_preview(gate_stack)
    validate_execution_approval_checklist(approval)
    validate_execution_review(review)
    if request["write"]:
        if approval["approval_status"] != "pass":
            raise PermissionError("supervised execution requires passing approval checklist")
        if gate_stack["block_count"]:
            raise PermissionError("supervised execution blocked by gate stack")
        if review["approval_summary"]["approval_status"] != "pass":
            raise PermissionError("supervised execution requires passing execution review approval summary")

    evidence_contract = chain["execution_evidence_contract"]
    retry_policy = chain["execution_retry_policy"]
    workspace_boundary = collect_workspace_creator_runtime_boundary(chain)
    workspace_plan = collect_workspace_creator_runtime_plan(chain)
    patch_boundary = collect_patch_applier_boundary(
        chain["verified_patch_plan"],
        chain["verified_patch_diff"],
        gate_stack,
        approval,
        evidence_contract,
        workspace_boundary,
        workspace_plan,
        planning_chain_id=chain["planning_chain_id"],
    )

    runtime_plan = dict(workspace_plan)
    if request["write"]:
        runtime_plan["plan_status"] = "pass"
        runtime_plan["recommended_next_action"] = "supervised execution approved for guarded workspace creation"
    workspace_request = make_guarded_workspace_request(
        runtime_plan,
        approved=request["approved"],
        write=request["write"],
        workspace_root=request["workspace_root"],
        metadata={"supervised_execution_request_id": request["request_id"]},
    )
    if request["write"]:
        workspace_receipt = create_guarded_workspace(workspace_request, runtime_plan)
    else:
        workspace_receipt = preview_guarded_workspace_creation(workspace_request, runtime_plan)

    patch_request = make_guarded_patch_request(
        patch_boundary,
        workspace_receipt,
        approved=request["approved"],
        write=request["write"],
        metadata={"supervised_execution_request_id": request["request_id"]},
    )
    if request["write"]:
        patch_receipt = apply_guarded_patch(
            patch_request,
            patch_boundary,
            chain["verified_patch_plan"],
            chain["verified_patch_diff"],
            workspace_receipt,
            workspace_receipt["workspace_manifest"],
            approval,
            gate_stack,
            evidence_contract,
        )
        _supervised_execution_receipt_files(workspace_receipt["workspace_path"], workspace_receipt, patch_receipt)
    else:
        patch_receipt = preview_guarded_patch_application(
            patch_request,
            patch_boundary,
            chain["verified_patch_plan"],
            chain["verified_patch_diff"],
            workspace_receipt,
            workspace_receipt["workspace_manifest"],
            approval,
            gate_stack,
            evidence_contract,
        )

    verification_boundary = collect_verification_runner_boundary(
        patch_receipt,
        patch_boundary,
        evidence_contract,
        retry_policy,
        gate_stack,
        approval,
        chain["execution_preflight_checklist"],
        review,
    )
    verification_request = make_guarded_verification_request(
        verification_boundary,
        commands=request["verification_commands"],
        approved=request["approved"],
        write=request["write"],
        metadata={"supervised_execution_request_id": request["request_id"]},
    )
    if request["write"]:
        verification_receipt = run_guarded_verification(
            verification_request,
            verification_boundary,
            patch_receipt,
            workspace_receipt["workspace_manifest"],
            workspace_receipt,
            evidence_contract,
            retry_policy,
        )
    else:
        verification_receipt = _collect_preview_verification_receipt(
            verification_request,
            verification_boundary,
            patch_receipt,
            workspace_receipt,
            evidence_contract,
            retry_policy,
        )

    rollback_receipt: dict[str, Any] | None = None
    if request["write"] and verification_receipt["rollback_triggered"]:
        rollback_boundary = collect_rollback_runtime_boundary(
            patch_receipt,
            verification_receipt,
            verification_boundary,
            patch_boundary,
            workspace_receipt["workspace_manifest"],
            workspace_receipt,
            evidence_contract,
            retry_policy,
            gate_stack,
            review,
        )
        rollback_request = make_guarded_rollback_request(
            rollback_boundary,
            rollback_reason="verification failed",
            approved=True,
            write=True,
            metadata={"supervised_execution_request_id": request["request_id"]},
        )
        rollback_receipt = execute_guarded_rollback(
            rollback_request,
            rollback_boundary,
            patch_receipt,
            verification_receipt,
            workspace_receipt["workspace_manifest"],
            workspace_receipt,
        )

    bundle = collect_execution_evidence_bundle(
        workspace_receipt,
        workspace_receipt["workspace_manifest"],
        patch_receipt,
        verification_receipt,
        rollback_receipt,
        evidence_contract,
        review,
        gate_stack,
        write=request["write"],
        metadata={"supervised_execution_request_id": request["request_id"]},
    )
    evidence_receipt = collect_execution_evidence_receipt(
        bundle,
        write=request["write"],
        collected_at=None if request["write"] else "preview-only",
        metadata={"supervised_execution_request_id": request["request_id"]},
    )
    if not request["write"]:
        final_status = "preview"
        recommendation = "review supervised execution plan before --write"
    elif verification_receipt["verification_result"] == "passed":
        final_status = "passed"
        recommendation = "review evidence bundle before workspace cleanup"
    elif rollback_receipt is not None:
        final_status = "rolled_back"
        recommendation = "review rollback evidence before workspace cleanup or abandon"
    else:
        final_status = "failed"
        recommendation = "inspect workspace before cleanup"
    return collect_supervised_execution_receipt(
        request,
        supervised_execution_plan,
        workspace_creation_receipt=workspace_receipt,
        guarded_patch_receipt=patch_receipt,
        guarded_verification_receipt=verification_receipt,
        guarded_rollback_receipt=rollback_receipt,
        execution_evidence_bundle=bundle,
        execution_evidence_receipt=evidence_receipt,
        final_status=final_status,
        review_recommendation=recommendation,
        metadata={"evidence_status": bundle["evidence_status"]},
    )

def validate_verified_patch_diff_entry(entry: dict[str, Any]) -> None:
    required = (
        "diff_entry_id", "operation_id", "file_path", "operation_type", "before_summary",
        "after_summary", "change_description", "diff_preview", "estimated_added_lines",
        "estimated_removed_lines", "estimated_modified_lines", "compile_impact", "test_impact",
        "healthcheck_impact", "confidence_score", "risk_score",
    )
    missing = [field for field in required if field not in entry]
    if missing:
        raise ValueError(f"verified patch diff entry missing fields: {missing}")
    for field in ("diff_entry_id", "operation_id", "file_path", "operation_type", "before_summary", "after_summary", "change_description", "diff_preview"):
        if not isinstance(entry[field], str) or not entry[field].strip():
            raise ValueError(f"{field} must be a non-empty string")
    if entry["operation_type"] not in VERIFIED_PATCH_OPERATION_TYPES:
        raise ValueError(f"invalid verified patch diff operation type: {entry['operation_type']}")
    if not entry["diff_preview"].startswith("--- old\n+++ new\n@@"):
        raise ValueError("diff_preview must use unified-diff-style headers")
    for field in ("estimated_added_lines", "estimated_removed_lines", "estimated_modified_lines"):
        if not isinstance(entry[field], int) or entry[field] < 0:
            raise ValueError(f"{field} must be a non-negative integer")
    if entry["estimated_added_lines"] + entry["estimated_removed_lines"] + entry["estimated_modified_lines"] <= 0:
        raise ValueError("diff entry must estimate at least one changed line")
    for field in ("compile_impact", "test_impact", "healthcheck_impact"):
        values = entry[field]
        if not isinstance(values, list) or not values:
            raise TypeError(f"{field} must be a non-empty list")
        if not all(isinstance(value, str) and value.strip() for value in values):
            raise TypeError(f"{field} must contain non-empty strings")
    _validate_probability_score(entry["confidence_score"], "entry confidence_score")
    _validate_probability_score(entry["risk_score"], "entry risk_score")


def _verified_patch_diff_entry(operation: dict[str, Any]) -> dict[str, Any]:
    validate_verified_patch_operation(operation, {operation["file_path"]})
    line_counts = _verified_patch_diff_line_counts(operation["operation_type"])
    entry = {
        "diff_entry_id": make_verified_patch_diff_entry_id(operation),
        "operation_id": operation["operation_id"],
        "file_path": operation["file_path"],
        "operation_type": operation["operation_type"],
        "before_summary": _verified_patch_diff_before_summary(operation),
        "after_summary": _verified_patch_diff_after_summary(operation),
        "change_description": operation["rationale"],
        "diff_preview": _verified_patch_diff_preview(operation),
        "estimated_added_lines": line_counts["added"],
        "estimated_removed_lines": line_counts["removed"],
        "estimated_modified_lines": line_counts["modified"],
        "compile_impact": _verified_patch_diff_compile_impact(operation),
        "test_impact": _verified_patch_diff_test_impact(operation),
        "healthcheck_impact": ["link_healthcheck.py should remain passing after the planned patch"],
        "confidence_score": _verified_patch_diff_entry_confidence(operation),
        "risk_score": _verified_patch_risk_score(operation["risk_level"]),
    }
    validate_verified_patch_diff_entry(entry)
    return entry


def _verified_patch_diff_line_counts(operation_type: str) -> dict[str, int]:
    counts = {
        "create_file": {"added": 24, "removed": 0, "modified": 0},
        "modify_file": {"added": 18, "removed": 4, "modified": 8},
        "delete_file": {"added": 0, "removed": 20, "modified": 0},
        "add_test": {"added": 18, "removed": 0, "modified": 0},
        "update_test": {"added": 16, "removed": 2, "modified": 6},
        "documentation_update": {"added": 10, "removed": 1, "modified": 4},
    }
    if operation_type not in counts:
        raise ValueError(f"invalid verified patch operation type: {operation_type}")
    return counts[operation_type]


def _verified_patch_diff_before_summary(operation: dict[str, Any]) -> str:
    if operation["operation_type"] in {"create_file", "add_test"}:
        return f"{operation['file_path']} is not yet represented in the planned implementation surface."
    if operation["operation_type"] == "delete_file":
        return f"{operation['file_path']} is present before the reviewed cleanup."
    return f"{operation['file_path']} contains current behavior before the planned upgrade."


def _verified_patch_diff_after_summary(operation: dict[str, Any]) -> str:
    if operation["operation_type"] == "delete_file":
        return f"{operation['file_path']} is removed only after review and verification confirm it is obsolete."
    return operation["expected_result"]


def _verified_patch_diff_preview(operation: dict[str, Any]) -> str:
    old_behavior = _verified_patch_diff_before_summary(operation)
    new_behavior = _verified_patch_diff_after_summary(operation)
    return "\n".join([
        "--- old",
        "+++ new",
        "@@",
        f"- {old_behavior}",
        f"+ {new_behavior}",
    ])


def _verified_patch_diff_compile_impact(operation: dict[str, Any]) -> list[str]:
    if operation["file_path"].endswith(".py"):
        return [f"py_compile should include {operation['file_path']} or the closest affected Python module"]
    return ["compile impact is expected to remain unchanged for non-Python target"]


def _verified_patch_diff_test_impact(operation: dict[str, Any]) -> list[str]:
    if _verified_patch_is_test_path(operation["file_path"]):
        return [f"{operation['file_path']} should include or update regression coverage"]
    return ["tests/test_growth_pipeline.py should cover the planned behavior when this slice touches Growth helpers"]


def _verified_patch_diff_entry_confidence(operation: dict[str, Any]) -> float:
    base = 0.82
    if operation["operation_type"] in {"create_file", "delete_file"}:
        base -= 0.12
    if operation["risk_level"] == "high":
        base -= 0.18
    elif operation["risk_level"] == "medium":
        base -= 0.08
    return round(max(0.0, min(1.0, base)), 4)


def _verified_patch_diff_confidence_score(patch_plan: dict[str, Any], diff_entries: list[dict[str, Any]]) -> float:
    if not diff_entries:
        return 0.0
    missing_penalty = min(0.3, len(patch_plan["missing_evidence"]) * 0.02)
    average = sum(entry["confidence_score"] for entry in diff_entries) / len(diff_entries)
    return round(max(0.0, min(1.0, average - missing_penalty)), 4)


def _verified_patch_diff_risk_score(diff_entries: list[dict[str, Any]]) -> float:
    if not diff_entries:
        return 0.0
    return round(max(entry["risk_score"] for entry in diff_entries), 4)


def _verified_patch_risk_score(risk_level: str) -> float:
    if risk_level not in UPGRADE_RISK_LEVELS:
        raise ValueError(f"invalid verified patch risk level: {risk_level}")
    return {"low": 0.2, "medium": 0.5, "high": 0.85}[risk_level]


def _validate_probability_score(value: Any, field_name: str) -> None:
    if isinstance(value, bool) or not isinstance(value, int | float):
        raise ValueError(f"{field_name} must be numeric between 0.0 and 1.0")
    number = float(value)
    if not (0.0 <= number <= 1.0):
        raise ValueError(f"{field_name} must be between 0.0 and 1.0")


def make_patch_behavior_quality_gate_id(
    patch_plan: dict[str, Any],
    patch_diff: dict[str, Any] | None,
    findings: list[dict[str, Any]],
    assumptions: list[str],
) -> str:
    import hashlib

    payload = _stable_ruflo_json({
        "assumptions": assumptions,
        "finding_ids": [finding["finding_id"] for finding in findings],
        "verified_patch_diff_id": patch_diff["verified_patch_diff_id"] if patch_diff else "",
        "verified_patch_plan_id": patch_plan["verified_patch_plan_id"],
        "version": PATCH_BEHAVIOR_QUALITY_GATE_VERSION,
    })
    digest = hashlib.sha256(payload.encode("utf-8")).hexdigest()[:12]
    return f"patch-behavior-quality-gate-{digest}"


def make_patch_behavior_quality_finding_id(category: str, severity: str, message: str) -> str:
    import hashlib

    payload = _stable_ruflo_json({
        "category": category,
        "message": message,
        "severity": severity,
        "version": PATCH_BEHAVIOR_QUALITY_GATE_VERSION,
    })
    digest = hashlib.sha256(payload.encode("utf-8")).hexdigest()[:12]
    return f"patch-behavior-finding-{digest}"


def collect_patch_behavior_quality_gate(
    patch_plan: dict[str, Any],
    *,
    patch_diff: dict[str, Any] | None = None,
    assumptions: list[str] | None = None,
    metadata: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Score a verified patch plan/diff for Karpathy-style behavior risks without writing."""
    validate_verified_patch_plan(patch_plan)
    if patch_diff is not None:
        validate_verified_patch_diff(patch_diff)
        if patch_diff["verified_patch_plan_id"] != patch_plan["verified_patch_plan_id"]:
            raise ValueError("patch_diff must reference the verified patch plan")
    normalized_assumptions = _normalize_patch_behavior_text_list(assumptions or [])
    findings = _collect_patch_behavior_findings(patch_plan, patch_diff, normalized_assumptions)
    findings.sort(key=lambda item: (item["severity"], item["category"], item["finding_id"]))
    risk_score = _patch_behavior_risk_score(patch_plan, patch_diff, findings)
    quality_score = _patch_behavior_quality_score(findings, risk_score)
    pass_status = _patch_behavior_pass_status(findings, quality_score, risk_score)
    required_clarifications = _patch_behavior_required_clarifications(findings)
    gate = {
        "quality_gate_version": PATCH_BEHAVIOR_QUALITY_GATE_VERSION,
        "quality_gate_id": make_patch_behavior_quality_gate_id(
            patch_plan,
            patch_diff,
            findings,
            normalized_assumptions,
        ),
        "verified_patch_plan_id": patch_plan["verified_patch_plan_id"],
        "verified_patch_diff_id": patch_diff["verified_patch_diff_id"] if patch_diff else "",
        "pass_status": pass_status,
        "quality_score": quality_score,
        "risk_score": risk_score,
        "assumptions": normalized_assumptions,
        "findings": findings,
        "required_clarifications": required_clarifications,
        "recommended_next_action": _patch_behavior_recommended_next_action(pass_status, required_clarifications),
        "dry_run": True,
        "write_allowed": False,
        "automation_allowed": False,
        "metadata": dict(metadata or {}),
        "writes": [],
    }
    validate_patch_behavior_quality_gate(gate)
    return gate


def validate_patch_behavior_quality_gate(gate: dict[str, Any]) -> None:
    required = (
        "quality_gate_version", "quality_gate_id", "verified_patch_plan_id", "verified_patch_diff_id",
        "pass_status", "quality_score", "risk_score", "assumptions", "findings",
        "required_clarifications", "recommended_next_action", "dry_run", "write_allowed",
        "automation_allowed", "metadata", "writes",
    )
    missing = [field for field in required if field not in gate]
    if missing:
        raise ValueError(f"patch behavior quality gate missing fields: {missing}")
    if gate["quality_gate_version"] != PATCH_BEHAVIOR_QUALITY_GATE_VERSION:
        raise ValueError("unsupported patch behavior quality gate version")
    for field in ("quality_gate_id", "verified_patch_plan_id", "pass_status", "recommended_next_action"):
        if not isinstance(gate[field], str) or not gate[field].strip():
            raise ValueError(f"{field} must be a non-empty string")
    if gate["pass_status"] not in {"pass", "review", "block"}:
        raise ValueError(f"invalid patch behavior pass_status: {gate['pass_status']}")
    if not isinstance(gate["verified_patch_diff_id"], str):
        raise TypeError("verified_patch_diff_id must be a string")
    _validate_probability_score(gate["quality_score"], "quality_score")
    _validate_probability_score(gate["risk_score"], "risk_score")
    if gate["dry_run"] is not True or gate["write_allowed"] is not False or gate["automation_allowed"] is not False:
        raise ValueError("patch behavior quality gate must remain read-only")
    if gate["writes"] != []:
        raise ValueError("patch behavior quality gate must not write files")
    if not isinstance(gate["metadata"], dict):
        raise TypeError("patch behavior quality gate metadata must be a dict")
    for field in ("assumptions", "required_clarifications"):
        values = gate[field]
        if not isinstance(values, list):
            raise TypeError(f"{field} must be a list")
        if values != _normalize_patch_behavior_text_list(values):
            raise ValueError(f"{field} must be normalized and sorted")
    findings = gate["findings"]
    if not isinstance(findings, list):
        raise TypeError("findings must be a list")
    finding_ids: set[str] = set()
    for finding in findings:
        validate_patch_behavior_quality_finding(finding)
        if finding["finding_id"] in finding_ids:
            raise ValueError(f"duplicate patch behavior finding id: {finding['finding_id']}")
        finding_ids.add(finding["finding_id"])
    if findings and [item["finding_id"] for item in findings] != sorted(item["finding_id"] for item in findings):
        raise ValueError("findings must be sorted by finding_id")
    severities = {finding["severity"] for finding in findings}
    if gate["pass_status"] == "pass" and severities:
        raise ValueError("pass status cannot include findings")
    if gate["pass_status"] == "block" and "block" not in severities:
        raise ValueError("block status requires a block finding")
    if gate["pass_status"] == "review" and "block" in severities:
        raise ValueError("review status cannot include block findings")


def stable_patch_behavior_quality_gate_json(gate: dict[str, Any]) -> str:
    validate_patch_behavior_quality_gate(gate)
    return _stable_ruflo_json(gate, indent=2) + "\n"


def parse_patch_behavior_quality_gate_json(text: str) -> dict[str, Any]:
    import json as _json

    gate = _json.loads(text)
    validate_patch_behavior_quality_gate(gate)
    return gate


def validate_patch_behavior_quality_finding(finding: dict[str, Any]) -> None:
    required = ("finding_id", "category", "severity", "message", "evidence")
    missing = [field for field in required if field not in finding]
    if missing:
        raise ValueError(f"patch behavior finding missing fields: {missing}")
    for field in ("finding_id", "category", "severity", "message"):
        if not isinstance(finding[field], str) or not finding[field].strip():
            raise ValueError(f"{field} must be a non-empty string")
    if finding["severity"] not in {"info", "review", "block"}:
        raise ValueError(f"invalid patch behavior finding severity: {finding['severity']}")
    evidence = finding["evidence"]
    if not isinstance(evidence, list) or not evidence:
        raise TypeError("patch behavior finding evidence must be a non-empty list")
    if evidence != _normalize_patch_behavior_text_list(evidence):
        raise ValueError("patch behavior finding evidence must be normalized and sorted")


def _collect_patch_behavior_findings(
    patch_plan: dict[str, Any],
    patch_diff: dict[str, Any] | None,
    assumptions: list[str],
) -> list[dict[str, Any]]:
    findings: list[dict[str, Any]] = []
    if not assumptions:
        findings.append(_patch_behavior_finding(
            "assumptions",
            "review",
            "No assumptions were surfaced before implementation.",
            [patch_plan["verified_patch_plan_id"]],
        ))
    if patch_plan["missing_evidence"]:
        severity = "block" if len(patch_plan["missing_evidence"]) >= 8 else "review"
        findings.append(_patch_behavior_finding(
            "missing_evidence",
            severity,
            f"{len(patch_plan['missing_evidence'])} required evidence item(s) are missing.",
            patch_plan["missing_evidence"],
        ))
    if patch_plan["estimated_files_changed"] > 10:
        findings.append(_patch_behavior_finding(
            "surgicality",
            "block",
            "Planned patch touches more than 10 files before implementation.",
            patch_plan["target_files"],
        ))
    elif patch_plan["estimated_files_changed"] > 5:
        findings.append(_patch_behavior_finding(
            "surgicality",
            "review",
            "Planned patch touches more than 5 files and may be overbroad.",
            patch_plan["target_files"],
        ))
    risky_operations = [operation for operation in patch_plan["patch_operations"] if operation["operation_type"] in {"create_file", "delete_file"}]
    if risky_operations:
        severity = "block" if any(operation["operation_type"] == "delete_file" for operation in risky_operations) else "review"
        findings.append(_patch_behavior_finding(
            "risky_operations",
            severity,
            "Patch plan contains create/delete operations that need explicit review.",
            [f"{operation['operation_type']}:{operation['file_path']}" for operation in risky_operations],
        ))
    unclear = [operation for operation in patch_plan["patch_operations"] if _patch_behavior_operation_unclear(operation)]
    if unclear:
        findings.append(_patch_behavior_finding(
            "clarity",
            "review",
            "One or more patch operations have unclear rationale or expected_result.",
            [operation["operation_id"] for operation in unclear],
        ))
    if not _patch_behavior_has_verification_coverage(patch_plan, patch_diff):
        findings.append(_patch_behavior_finding(
            "verification_coverage",
            "block",
            "Patch operations are not covered by compile, test, and healthcheck expectations.",
            [patch_plan["verified_patch_plan_id"]],
        ))
    if _patch_behavior_overengineering_risk(patch_plan, patch_diff):
        findings.append(_patch_behavior_finding(
            "overengineering",
            "review",
            "Patch preview suggests unnecessary breadth or abstraction risk for this slice.",
            [patch_plan["verified_patch_plan_id"]],
        ))
    if patch_diff is not None and patch_diff["risk_score"] >= 0.8:
        findings.append(_patch_behavior_finding(
            "diff_risk",
            "block",
            "Verified patch diff risk score is high before implementation.",
            [patch_diff["verified_patch_diff_id"]],
        ))
    return _dedupe_patch_behavior_findings(findings)


def _patch_behavior_finding(category: str, severity: str, message: str, evidence: list[str]) -> dict[str, Any]:
    normalized_evidence = _normalize_patch_behavior_text_list(evidence)
    finding = {
        "finding_id": make_patch_behavior_quality_finding_id(category, severity, message),
        "category": category,
        "severity": severity,
        "message": message,
        "evidence": normalized_evidence,
    }
    validate_patch_behavior_quality_finding(finding)
    return finding


def _dedupe_patch_behavior_findings(findings: list[dict[str, Any]]) -> list[dict[str, Any]]:
    by_id: dict[str, dict[str, Any]] = {}
    for finding in findings:
        by_id[finding["finding_id"]] = finding
    return sorted(by_id.values(), key=lambda item: item["finding_id"])


def _patch_behavior_operation_unclear(operation: dict[str, Any]) -> bool:
    vague_terms = {"todo", "tbd", "fix stuff", "update things", "change code", "implement"}
    rationale = operation.get("rationale", "").strip().lower()
    expected = operation.get("expected_result", "").strip().lower()
    if len(rationale) < 24 or len(expected) < 24:
        return True
    return rationale in vague_terms or expected in vague_terms


def _patch_behavior_has_verification_coverage(patch_plan: dict[str, Any], patch_diff: dict[str, Any] | None) -> bool:
    if not patch_plan["compile_expectations"] or not patch_plan["test_expectations"] or not patch_plan["healthcheck_expectations"]:
        return False
    if patch_diff is None:
        return True
    return bool(patch_diff["compile_impact"] and patch_diff["test_impact"] and patch_diff["healthcheck_impact"])


def _patch_behavior_overengineering_risk(patch_plan: dict[str, Any], patch_diff: dict[str, Any] | None) -> bool:
    if len(patch_plan["patch_operations"]) > 6:
        return True
    if any(operation["operation_type"] == "create_file" for operation in patch_plan["patch_operations"]):
        return True
    if patch_diff is not None and patch_diff["estimated_added_lines"] > 180:
        return True
    return False


def _patch_behavior_quality_score(findings: list[dict[str, Any]], risk_score: float) -> float:
    score = 1.0 - min(0.35, risk_score * 0.25)
    for finding in findings:
        if finding["severity"] == "block":
            score -= 0.28
        elif finding["severity"] == "review":
            score -= 0.12
        else:
            score -= 0.03
    return round(max(0.0, min(1.0, score)), 4)


def _patch_behavior_risk_score(
    patch_plan: dict[str, Any],
    patch_diff: dict[str, Any] | None,
    findings: list[dict[str, Any]],
) -> float:
    operation_risk = max((_verified_patch_risk_score(operation["risk_level"]) for operation in patch_plan["patch_operations"]), default=0.0)
    diff_risk = patch_diff["risk_score"] if patch_diff is not None else 0.0
    finding_risk = 0.0
    for finding in findings:
        if finding["severity"] == "block":
            finding_risk += 0.18
        elif finding["severity"] == "review":
            finding_risk += 0.08
        else:
            finding_risk += 0.02
    return round(max(0.0, min(1.0, max(operation_risk, diff_risk) + finding_risk)), 4)


def _patch_behavior_pass_status(findings: list[dict[str, Any]], quality_score: float, risk_score: float) -> str:
    severities = {finding["severity"] for finding in findings}
    if "block" in severities or quality_score < 0.55 or risk_score >= 0.85:
        return "block"
    if "review" in severities or quality_score < 0.82 or risk_score >= 0.55:
        return "review"
    return "pass"


def _patch_behavior_required_clarifications(findings: list[dict[str, Any]]) -> list[str]:
    prompts: list[str] = []
    for finding in findings:
        if finding["category"] == "assumptions":
            prompts.append("State the assumptions that make this patch safe and scoped before implementation.")
        elif finding["category"] == "clarity":
            prompts.append("Clarify the rationale and expected result for each vague patch operation.")
        elif finding["category"] == "surgicality":
            prompts.append("Confirm why the planned file count is necessary for the smallest safe slice.")
        elif finding["category"] == "risky_operations":
            prompts.append("Confirm the create/delete operation is necessary and has rollback coverage.")
        elif finding["category"] == "missing_evidence":
            prompts.append("Provide or explicitly waive the missing evidence before implementation.")
        elif finding["severity"] == "block":
            prompts.append(f"Resolve blocking finding: {finding['message']}")
    return _normalize_patch_behavior_text_list(prompts)


def _patch_behavior_recommended_next_action(pass_status: str, required_clarifications: list[str]) -> str:
    if pass_status == "pass":
        return "Proceed to human review of the patch plan; do not execute without approval."
    if pass_status == "review":
        return "Review findings and answer required clarifications before implementation."
    if required_clarifications:
        return "Do not implement until blocking findings are resolved and clarifications are answered."
    return "Do not implement until the patch behavior quality gate passes review."


def _normalize_patch_behavior_text_list(values: list[str] | tuple[str, ...]) -> list[str]:
    if not isinstance(values, (list, tuple)):
        raise TypeError("patch behavior text values must be a list or tuple")
    normalized: list[str] = []
    for raw in values:
        value = str(raw or "").strip()
        if not value:
            raise ValueError("patch behavior text values cannot be empty")
        if "\x00" in value:
            raise ValueError("patch behavior text values cannot contain null bytes")
        if value not in normalized:
            normalized.append(value)
    return sorted(normalized)




def make_autonomous_execution_package_id(
    patch_plan: dict[str, Any],
    verification_entry: dict[str, Any],
    quality_gate: dict[str, Any],
    stages: list[dict[str, Any]],
) -> str:
    import hashlib

    payload = _stable_ruflo_json({
        "quality_gate_id": quality_gate["quality_gate_id"],
        "stage_ids": [stage["stage_id"] for stage in stages],
        "verification_plan_id": verification_entry["verification_plan_id"],
        "verified_patch_plan_id": patch_plan["verified_patch_plan_id"],
        "version": AUTONOMOUS_EXECUTION_PACKAGE_VERSION,
    })
    digest = hashlib.sha256(payload.encode("utf-8")).hexdigest()[:12]
    return f"autonomous-execution-package-{digest}"


def make_autonomous_execution_stage_id(package_seed: str, order: int, stage_name: str) -> str:
    import hashlib

    payload = _stable_ruflo_json({
        "order": order,
        "package_seed": package_seed,
        "stage_name": stage_name,
        "version": AUTONOMOUS_EXECUTION_PACKAGE_VERSION,
    })
    digest = hashlib.sha256(payload.encode("utf-8")).hexdigest()[:12]
    return f"autonomous-execution-stage-{digest}"


def collect_autonomous_execution_package(
    patch_plan: dict[str, Any],
    *,
    verification_plan: dict[str, Any] | None = None,
    patch_diff: dict[str, Any] | None = None,
    quality_gate: dict[str, Any] | None = None,
    assumptions: list[str] | None = None,
    metadata: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Describe how an upgrade would execute later, without executing anything."""
    validate_verified_patch_plan(patch_plan)
    verification_entry = _autonomous_execution_verification_entry(patch_plan, verification_plan)
    if patch_diff is None:
        patch_diff = collect_verified_patch_diff(patch_plan)
    else:
        validate_verified_patch_diff(patch_diff)
        if patch_diff["verified_patch_plan_id"] != patch_plan["verified_patch_plan_id"]:
            raise ValueError("patch_diff must reference the verified patch plan")
    if quality_gate is None:
        quality_gate = collect_patch_behavior_quality_gate(
            patch_plan,
            patch_diff=patch_diff,
            assumptions=assumptions or [],
        )
    else:
        validate_patch_behavior_quality_gate(quality_gate)
        if quality_gate["verified_patch_plan_id"] != patch_plan["verified_patch_plan_id"]:
            raise ValueError("quality_gate must reference the verified patch plan")
        if quality_gate["verified_patch_diff_id"] and quality_gate["verified_patch_diff_id"] != patch_diff["verified_patch_diff_id"]:
            raise ValueError("quality_gate must reference the verified patch diff")
    stages = _autonomous_execution_stages(patch_plan, patch_diff, verification_entry, quality_gate)
    package = {
        "execution_package_version": AUTONOMOUS_EXECUTION_PACKAGE_VERSION,
        "execution_package_id": make_autonomous_execution_package_id(
            patch_plan,
            verification_entry,
            quality_gate,
            stages,
        ),
        "upgrade_id": patch_plan["upgrade_id"],
        "branch_plan_id": patch_plan["branch_plan_id"],
        "work_package_id": patch_plan["work_package_id"],
        "verification_plan_id": verification_entry["verification_plan_id"],
        "verified_patch_plan_id": patch_plan["verified_patch_plan_id"],
        "verified_patch_diff_id": patch_diff["verified_patch_diff_id"],
        "quality_gate_id": quality_gate["quality_gate_id"],
        "execution_stages": stages,
        "stage_count": len(stages),
        "dry_run": True,
        "write_allowed": False,
        "automation_allowed": False,
        "metadata": dict(metadata or {}),
        "writes": [],
    }
    validate_autonomous_execution_package(package)
    return package


def validate_autonomous_execution_package(package: dict[str, Any]) -> None:
    required = (
        "execution_package_version", "execution_package_id", "upgrade_id", "branch_plan_id",
        "work_package_id", "verification_plan_id", "verified_patch_plan_id", "verified_patch_diff_id",
        "quality_gate_id", "execution_stages", "stage_count", "dry_run", "write_allowed",
        "automation_allowed", "metadata", "writes",
    )
    missing = [field for field in required if field not in package]
    if missing:
        raise ValueError(f"autonomous execution package missing fields: {missing}")
    if package["execution_package_version"] != AUTONOMOUS_EXECUTION_PACKAGE_VERSION:
        raise ValueError("unsupported autonomous execution package version")
    for field in (
        "execution_package_id", "upgrade_id", "branch_plan_id", "work_package_id",
        "verification_plan_id", "verified_patch_plan_id", "verified_patch_diff_id", "quality_gate_id",
    ):
        if not isinstance(package[field], str) or not package[field].strip():
            raise ValueError(f"{field} must be a non-empty string")
    if package["dry_run"] is not True or package["write_allowed"] is not False or package["automation_allowed"] is not False:
        raise ValueError("autonomous execution package must remain read-only")
    if package["writes"] != []:
        raise ValueError("autonomous execution package must not write files")
    if not isinstance(package["metadata"], dict):
        raise TypeError("autonomous execution package metadata must be a dict")
    stages = package["execution_stages"]
    if not isinstance(stages, list) or not stages:
        raise TypeError("execution_stages must be a non-empty list")
    if not isinstance(package["stage_count"], int) or package["stage_count"] != len(stages):
        raise ValueError("stage_count must match execution_stages length")
    expected_names = list(_AUTONOMOUS_EXECUTION_STAGE_NAMES)
    stage_ids: set[str] = set()
    for index, stage in enumerate(stages, start=1):
        validate_autonomous_execution_stage(stage)
        if stage["stage_id"] in stage_ids:
            raise ValueError(f"duplicate autonomous execution stage id: {stage['stage_id']}")
        stage_ids.add(stage["stage_id"])
        if stage["order"] != index:
            raise ValueError("execution stages must be ordered from 1 without gaps")
        if stage["stage_name"] != expected_names[index - 1]:
            raise ValueError("execution stages must use the canonical execution order")


def stable_autonomous_execution_package_json(package: dict[str, Any]) -> str:
    validate_autonomous_execution_package(package)
    return _stable_ruflo_json(package, indent=2) + "\n"


def parse_autonomous_execution_package_json(text: str) -> dict[str, Any]:
    import json as _json

    package = _json.loads(text)
    validate_autonomous_execution_package(package)
    return package


_AUTONOMOUS_EXECUTION_STAGE_NAMES = (
    "create workspace",
    "create branch",
    "apply patch operations",
    "run compile",
    "run tests",
    "run healthcheck",
    "evaluate quality gate",
    "produce review bundle",
)


def validate_autonomous_execution_stage(stage: dict[str, Any]) -> None:
    required = (
        "stage_id", "order", "stage_name", "inputs", "outputs", "success_criteria",
        "failure_criteria", "rollback_action",
    )
    missing = [field for field in required if field not in stage]
    if missing:
        raise ValueError(f"autonomous execution stage missing fields: {missing}")
    if not isinstance(stage["stage_id"], str) or not stage["stage_id"].strip():
        raise ValueError("stage_id must be a non-empty string")
    if not isinstance(stage["order"], int) or stage["order"] < 1:
        raise ValueError("stage order must be a positive integer")
    if stage["stage_name"] not in _AUTONOMOUS_EXECUTION_STAGE_NAMES:
        raise ValueError(f"invalid autonomous execution stage name: {stage['stage_name']}")
    for field in ("inputs", "outputs", "success_criteria", "failure_criteria"):
        values = stage[field]
        if not isinstance(values, list) or not values:
            raise TypeError(f"{field} must be a non-empty list")
        if values != _normalize_patch_behavior_text_list(values):
            raise ValueError(f"{field} must be normalized and sorted")
    if not isinstance(stage["rollback_action"], str) or not stage["rollback_action"].strip():
        raise ValueError("rollback_action must be a non-empty string")


def _autonomous_execution_verification_entry(
    patch_plan: dict[str, Any],
    verification_plan: dict[str, Any] | None,
) -> dict[str, Any]:
    if verification_plan is None:
        return {
            "verification_plan_id": "verification-plan-unresolved",
            "package_id": patch_plan["work_package_id"],
            "branch_plan_id": patch_plan["branch_plan_id"],
            "upgrade_id": patch_plan["upgrade_id"],
            "compile_commands": [item.replace("compile command should pass: ", "") for item in patch_plan["compile_expectations"]],
            "test_commands": [item.replace("test command should pass: ", "") for item in patch_plan["test_expectations"]],
            "healthcheck_commands": [item.replace("healthcheck command should pass: ", "") for item in patch_plan["healthcheck_expectations"]],
        }
    if "plans" in verification_plan:
        validate_verification_plan(verification_plan)
        for plan in verification_plan["plans"]:
            if plan["package_id"] == patch_plan["work_package_id"]:
                return dict(plan)
        raise ValueError("verification_plan does not contain a plan for the patch plan work package")
    validate_verification_plan_entry(verification_plan)
    if verification_plan["package_id"] != patch_plan["work_package_id"]:
        raise ValueError("verification plan package_id does not match patch plan work package")
    return dict(verification_plan)


def _autonomous_execution_stages(
    patch_plan: dict[str, Any],
    patch_diff: dict[str, Any],
    verification_entry: dict[str, Any],
    quality_gate: dict[str, Any],
) -> list[dict[str, Any]]:
    seed = f"{patch_plan['verified_patch_plan_id']}:{patch_diff['verified_patch_diff_id']}:{quality_gate['quality_gate_id']}"
    stage_specs = [
        (
            "create workspace",
            [patch_plan["verified_patch_plan_id"], "approved execution request"],
            ["isolated workspace path planned", "workspace remains uncreated in this package"],
            ["workspace location is inside the approved repository boundary"],
            ["workspace path is outside repository boundary", "workspace cannot be isolated"],
            "Do not create the workspace; discard the planned workspace path.",
        ),
        (
            "create branch",
            [patch_plan["branch_plan_id"], "approved branch request"],
            ["implementation branch name planned", "branch remains uncreated in this package"],
            ["branch name is reviewable and tied to branch_plan_id"],
            ["branch name is missing", "branch request lacks approval"],
            "Do not create the branch; keep HEAD unchanged.",
        ),
        (
            "apply patch operations",
            [patch_plan["verified_patch_plan_id"], patch_diff["verified_patch_diff_id"]],
            ["patch operations planned as data", "no files modified by this package"],
            ["every patch operation maps to a target file and diff preview"],
            ["patch operation is outside target files", "patch behavior quality gate blocks implementation"],
            "Discard planned patch operations; keep working tree unchanged.",
        ),
        (
            "run compile",
            list(verification_entry["compile_commands"]),
            ["compile command list planned", "compile commands remain unexecuted"],
            ["all compile commands would be expected to pass"],
            ["compile command is missing", "compile command exits nonzero during later execution"],
            "Stop execution and revert any applied patch before review.",
        ),
        (
            "run tests",
            list(verification_entry["test_commands"]),
            ["test command list planned", "test commands remain unexecuted"],
            ["all test commands would be expected to pass"],
            ["test command is missing", "test command exits nonzero during later execution"],
            "Stop execution and revert any applied patch before review.",
        ),
        (
            "run healthcheck",
            list(verification_entry["healthcheck_commands"]),
            ["healthcheck command list planned", "healthcheck commands remain unexecuted"],
            ["healthcheck would be expected to pass"],
            ["healthcheck command is missing", "healthcheck exits nonzero during later execution"],
            "Stop execution and revert any applied patch before review.",
        ),
        (
            "evaluate quality gate",
            [quality_gate["quality_gate_id"], quality_gate["pass_status"]],
            ["quality gate decision planned", "quality gate remains read-only"],
            ["quality gate pass_status is pass before execution approval"],
            ["quality gate pass_status is review or block", "required clarifications remain unanswered"],
            "Do not proceed to execution until quality gate findings are resolved.",
        ),
        (
            "produce review bundle",
            [patch_plan["verified_patch_plan_id"], patch_diff["verified_patch_diff_id"], quality_gate["quality_gate_id"]],
            ["review bundle contents planned", "review bundle file remains unwritten"],
            ["review bundle references plan, diff, gate, verification, and rollback data"],
            ["review bundle omits required evidence", "review bundle would require runtime state writes"],
            "Do not write review artifacts; keep package as JSON preview only.",
        ),
    ]
    stages: list[dict[str, Any]] = []
    for order, (stage_name, inputs, outputs, success, failure, rollback) in enumerate(stage_specs, start=1):
        stage = {
            "stage_id": make_autonomous_execution_stage_id(seed, order, stage_name),
            "order": order,
            "stage_name": stage_name,
            "inputs": _normalize_patch_behavior_text_list(inputs),
            "outputs": _normalize_patch_behavior_text_list(outputs),
            "success_criteria": _normalize_patch_behavior_text_list(success),
            "failure_criteria": _normalize_patch_behavior_text_list(failure),
            "rollback_action": rollback,
        }
        validate_autonomous_execution_stage(stage)
        stages.append(stage)
    return stages




def _normalize_feedback_status(status: str) -> str:
    raw = str(status or "").strip().lower().replace("-", "_").replace(" ", "_")
    aliases = {
        "accept": "accepted",
        "approved": "accepted",
        "yes": "accepted",
        "reject": "rejected",
        "no": "rejected",
        "declined": "rejected",
        "defer": "deferred",
        "later": "deferred",
        "review": "deferred",
    }
    normalized = aliases.get(raw, raw)
    if normalized not in SELF_LEARNING_FEEDBACK_STATUSES:
        raise ValueError(f"invalid self-learning feedback status: {status}")
    return normalized


def _normalize_feedback_confidence(confidence: float) -> float:
    if isinstance(confidence, bool) or not isinstance(confidence, int | float):
        raise ValueError("confidence must be numeric between 0.0 and 1.0")
    value = float(confidence)
    if not (0.0 <= value <= 1.0):
        raise ValueError("confidence must be between 0.0 and 1.0")
    return round(value, 4)


def _normalize_feedback_tags(tags: list[str] | None) -> list[str]:
    normalized: list[str] = []
    for tag in tags or []:
        text = str(tag or "").strip().lower().replace(" ", "_")
        if text and text not in normalized:
            normalized.append(text)
    return normalized


def _normalize_feedback_category(category: str) -> str:
    raw = str(category or "").strip().lower().replace("-", "_").replace(" ", "_")
    return raw if raw in RUFLO_UPGRADE_CATEGORIES else "performance"


def _normalize_feedback_recommendation(recommendation: str) -> str:
    raw = str(recommendation or "").strip().lower()
    return raw if raw in RUFLO_RECOMMENDATIONS else "review"


# ── archive code queue entry point ──────────────────────────────────────
_CODE_EXTS: set[str] = {
    ".ts", ".tsx", ".js", ".jsx", ".mjs", ".cjs",
    ".py", ".json", ".yaml", ".yml", ".toml", ".cfg",
}

_CODE_HIGH_VALUE_NAMES: set[str] = {
    "index.ts", "main.ts", "app.ts", "cli.ts", "server.ts",
    "router.ts", "agent.ts", "orchestrator.ts",
    "package.json", "tsconfig.json",
    "index.tsx", "main.tsx", "app.tsx",
    "index.js", "main.js", "app.js",
}

_CODE_ARCHITECTURE_KEYWORDS: list[str] = [
    "agent", "planner", "executor", "orchestrator", "workflow",
    "pipeline", "router", "tool", "memory", "context", "schema",
    "types", "prompt", "eval", "command", "runtime", "worker",
    "queue", "receipt", "verifier", "control", "dashboard",
    "task", "skill", "config", "server", "service", "adapter",
    "bridge", "handler", "factory", "delegate", "provider",
    "store", "state", "feature", "module",
]

_CODE_CONFIG_PREFIXES: list[str] = [
    "vite.", "next.", "webpack.", "docker", "eslint", "babel",
    "tsup.", "rollup.", "postcss", "tailwind", "jest.",
]

_CODE_LOCKFILE_NAMES: set[str] = {
    "package-lock.json", "yarn.lock", "pnpm-lock.yaml",
    "poetry.lock", "pipfile.lock", "cargo.lock",
}

_INDEX_WRAPPER_NAMES: set[str] = {
    "index.ts", "index.tsx", "index.js", "index.jsx",
}
_MAX_INDEX_WRAPPER_BYTES = 1_200
_MAX_CODE_FILE_BYTES = 500_000
_MAX_CODE_QUEUE_TOP = 20
_DEFAULT_CODE_QUEUE_TOP = 10


def archive_code_queue_main(argv: list[str] | None = None) -> int:
    """Entry point for ``python3 link.py growth archive-code-queue``.

    Reads archive catalog JSON files and walks extracted source_paths
    to rank code files (TypeScript, JavaScript, Python, configs, etc.)
    by architecture research value.  Read-only.  No files written.

    Flags:
        --top <N>         Number of top-ranked sources (default 10, max 20).
        --catalog <path>  Read only this one catalog.
        --json            Machine-readable output.
        --root <path>     Override repo root (for test isolation).
    """
    args = sys.argv[1:] if argv is None else argv

    if "--help" in args or "-h" in args:
        print("Growth archive-code-queue: rank code files for research mining")
        print("")
        print("Usage:")
        print("  python3 link.py growth archive-code-queue")
        print("  python3 link.py growth archive-code-queue --top <N>")
        print("  python3 link.py growth archive-code-queue --catalog <path>")
        print("  python3 link.py growth archive-code-queue --json")
        print("")
        print("Walks extracted source directories and ranks code files")
        print(f"by architecture value.  Default top is {_DEFAULT_CODE_QUEUE_TOP}.")
        print(f"Hard cap at {_MAX_CODE_QUEUE_TOP}.  Read-only — no files written.")
        return 0

    top_arg = _parse_arg(args, "--top")
    top = _resolve_code_queue_top(top_arg)

    if isinstance(top, str):
        print(f"error: {top}", file=sys.stderr)
        print("Run 'python3 link.py growth archive-code-queue --help' for usage.",
              file=sys.stderr)
        return 1

    catalog_arg = _parse_arg(args, "--catalog")
    root_override = _parse_arg(args, "--root")
    data = collect_archive_code_queue(
        catalog_path=catalog_arg, top=top, root=root_override,
    )

    if "--json" in args:
        print(json.dumps(data, indent=2, default=str))
        return 0

    render_archive_code_queue_view(data)
    return 0


def _resolve_code_queue_top(top_arg: str | None) -> int | str:
    if top_arg is None:
        return _DEFAULT_CODE_QUEUE_TOP
    try:
        n = int(top_arg)
    except ValueError:
        return f"top must be an integer, got {top_arg!r}"
    if n < 1:
        return f"top must be >= 1, got {n}"
    return n


def collect_archive_code_queue(
    catalog_path: str | None = None,
    top: int = _DEFAULT_CODE_QUEUE_TOP,
    root: str | None = None,
) -> dict[str, Any]:
    """Load catalogs, walk source_paths, and rank code files for mining.

    When ``catalog_path`` is omitted every catalog under
    ``_CATALOG_OUTPUT_DIR`` is loaded.

    Source directories are walked for code-relevant files.  Each file is
    scored by ``_score_code_source`` and ranked descending.

    Read-only.  No files written.  No source content read.
    """
    import json as _json
    from pathlib import Path

    repo_root = Path(root) if root else Path.cwd()
    catalogs_dir = repo_root / _CATALOG_OUTPUT_DIR

    effective_top = min(top, _MAX_CODE_QUEUE_TOP)
    warnings: list[str] = []
    if top > _MAX_CODE_QUEUE_TOP:
        warnings.append(
            f"top {top} capped at {_MAX_CODE_QUEUE_TOP} (hard limit)"
        )

    # ── load catalogs ──
    if catalog_path:
        catalog_file = repo_root / catalog_path
        if not catalog_file.exists():
            return _code_queue_empty(
                warnings=warnings + [{
                    "type": "catalog_missing",
                    "detail": f"catalog not found: {catalog_file}",
                }],
                top=effective_top,
            )
        raw_catalogs = [catalog_file]
    else:
        if not catalogs_dir.exists():
            return _code_queue_empty(
                warnings=warnings + [{
                    "type": "no_catalogs",
                    "detail": f"no catalogs directory: {catalogs_dir}",
                }],
                top=effective_top,
            )
        raw_catalogs = sorted(catalogs_dir.glob("*.json"))

    catalogs: list[dict] = []
    for cf in raw_catalogs:
        try:
            cat = _json.loads(cf.read_text(encoding="utf-8"))
        except Exception as exc:
            warnings.append(
                f"catalog_invalid_json: {cf.name}: {exc}"
            )
            continue
        if not isinstance(cat, dict):
            warnings.append(f"catalog_not_dict: {cf.name}")
            continue
        catalogs.append(cat)

    if not catalogs:
        if not warnings:
            warnings.append("no catalogs found")
        return _code_queue_empty(warnings=warnings,
                                 top=effective_top)

    # ── walk source_paths and score code files ──
    all_entries: list[dict] = []
    skipped: list[dict] = []

    for catalog in catalogs:
        source_name = catalog.get("source_name", "?")
        source_root_str = catalog.get("source_path", "")
        src_root = Path(source_root_str)
        if not src_root.exists() or not src_root.is_dir():
            warnings.append(
                f"source_missing: {source_name}: {source_root_str}"
            )
            continue

        code_file_count = 0
        for entry in sorted(src_root.rglob("*")):
            if not entry.is_file():
                continue
            suffix = entry.suffix.lower()
            if suffix not in _CODE_EXTS:
                continue

            rel = str(entry.relative_to(src_root))
            path_lower = rel.lower()
            name_lower = entry.name.lower()
            size = entry.stat().st_size

            # Skip dirs
            if any(seg in path_lower for seg in _SKIP_DIR_NAMES):
                skipped.append({
                    "path": str(src_root / rel),
                    "reason": f"in skipped directory ({rel.split('/')[0]})",
                })
                continue

            # Skip trivial / huge
            if size < 50:
                skipped.append({
                    "path": str(src_root / rel),
                    "reason": f"trivial file ({size}B)",
                })
                continue
            if size > _MAX_CODE_FILE_BYTES:
                skipped.append({
                    "path": str(src_root / rel),
                    "reason": f"too large ({_human_size(size)})",
                })
                continue

            # Binary check
            if _code_is_binary(entry):
                skipped.append({
                    "path": str(src_root / rel),
                    "reason": "binary file",
                })
                continue

            code_file_count += 1
            score = _score_code_source(rel, name_lower, suffix, size, catalog)

            reason = _code_reason(rel, name_lower, suffix, score)

            if score <= 0:
                skipped.append({
                    "path": str(src_root / rel),
                    "reason": reason,
                })
                continue

            is_index_wrapper = _is_index_wrapper(entry, size)
            sibling_count = _sibling_code_file_count(entry)
            resolved_target = _resolve_index_wrapper_target(entry) if is_index_wrapper else None
            resolved_type = "file" if resolved_target else ""

            if is_index_wrapper and resolved_target:
                score = max(score - 4, 1)
                reason = f"{reason} | tiny index wrapper; brief resolved target"
            elif is_index_wrapper and sibling_count > 0:
                score = max(score - 8, 1)
                reason = f"{reason} | tiny index wrapper; brief parent directory"
            elif is_index_wrapper:
                skipped.append({
                    "path": str(src_root / rel),
                    "reason": "tiny index wrapper with no safe local target",
                })
                continue

            est_val = "high" if score >= 13 else ("medium" if score >= 8 else "low")
            if resolved_target:
                recommended_source = resolved_target
                recommended_type = "file"
            elif is_index_wrapper and sibling_count > 0:
                recommended_source = entry.parent
                recommended_type = "directory"
            else:
                recommended_source = entry
                recommended_type = "file"

            all_entries.append({
                "source_path": str(src_root / rel),
                "catalog_source_name": source_name,
                "source_type": "file",
                "category": _code_category(name_lower, suffix),
                "reason": reason,
                "score": score,
                "estimated_value": est_val,
                "size_human": _human_size(size),
                "extension": suffix,
                "is_index_wrapper": is_index_wrapper,
                "sibling_code_file_count": sibling_count,
                "resolved_target_path": str(resolved_target) if resolved_target else "",
                "resolved_target_type": resolved_type,
                "recommended_source_path": str(recommended_source),
                "recommended_source_type": recommended_type,
                "suggested_command": f"python3 link.py growth archive-code-brief --source {recommended_source} --write",
            })

        if code_file_count == 0 and not catalog_path:
            warnings.append(
                f"no_code_files: {source_name}: no code files found"
            )

    # Sort descending by score, then by name
    all_entries.sort(key=lambda e: (-e["score"], e["source_path"].lower()))

    # Assign ranks, limit to top
    for i, entry in enumerate(all_entries):
        entry["rank"] = i + 1

    displayed = all_entries[:effective_top]

    # Recommendations
    recommendations: list[str] = []
    for e in displayed[:3]:
        recommendations.append(e["suggested_command"])

    if not displayed and not skipped:
        warnings.append(
            "no_code_files: no eligible code files found in any catalog"
        )

    return {
        "catalog_count": len(catalogs),
        "queue_count": len(displayed),
        "skipped_count": len(skipped),
        "total_discovered": len(all_entries),
        "top_requested": effective_top,
        "source_queue": displayed,
        "skipped_entries": skipped[:20],
        "recommendations": recommendations,
        "warnings": warnings if warnings else [],
        "error": None,
    }


def _is_index_wrapper(path: Path, size: int) -> bool:
    """Return True for tiny JS/TS index wrapper files."""
    return path.name.lower() in _INDEX_WRAPPER_NAMES and size <= _MAX_INDEX_WRAPPER_BYTES


def _resolve_index_wrapper_target(path: Path) -> Path | None:
    """Resolve a tiny index wrapper's first safe local import/export target."""
    import re

    if path.name.lower() not in _INDEX_WRAPPER_NAMES:
        return None
    try:
        if path.stat().st_size > _MAX_INDEX_WRAPPER_BYTES:
            return None
        text = path.read_text(encoding="utf-8", errors="replace")
    except Exception:
        return None

    patterns = (
        r"(?:import|export)\s+(?:[^;]*?\s+from\s+)?[\"']([^\"']+)[\"']",
        r"require\(\s*[\"']([^\"']+)[\"']\s*\)",
    )
    for pattern in patterns:
        for match in re.finditer(pattern, text):
            target = _safe_local_code_target(path, match.group(1))
            if target:
                return target
    return None


def _safe_local_code_target(wrapper_path: Path, specifier: str) -> Path | None:
    """Return a safe local file target for a relative JS/TS import specifier."""
    from pathlib import Path

    raw = str(specifier or "").strip()
    if not raw.startswith("."):
        return None

    base_dir = wrapper_path.parent.resolve()
    candidate_base = (wrapper_path.parent / raw).resolve()
    try:
        candidate_base.relative_to(base_dir)
    except ValueError:
        return None

    candidates: list[Path] = []
    if candidate_base.suffix:
        candidates.append(candidate_base)
    else:
        preferred = [wrapper_path.suffix.lower(), ".ts", ".tsx", ".js", ".jsx", ".mjs", ".cjs"]
        for suffix in dict.fromkeys(preferred):
            candidates.append(Path(str(candidate_base) + suffix))
        candidates.extend(candidate_base / f"index{suffix}" for suffix in dict.fromkeys(preferred))

    for candidate in candidates:
        try:
            candidate.relative_to(base_dir)
        except ValueError:
            continue
        if candidate == wrapper_path or not candidate.is_file() or candidate.is_symlink():
            continue
        if candidate.suffix.lower() not in _CODE_EXTS:
            continue
        if candidate.name.lower() in _CODE_LOCKFILE_NAMES:
            continue
        try:
            size = candidate.stat().st_size
        except OSError:
            continue
        if size < 50 or size > _MAX_CODE_FILE_BYTES:
            continue
        if _code_is_binary(candidate):
            continue
        return candidate

    return None


def _sibling_code_file_count(path: Path) -> int:
    """Count meaningful sibling code files near a tiny index wrapper."""
    if path.name.lower() not in _INDEX_WRAPPER_NAMES:
        return 0

    count = 0
    try:
        siblings = sorted(path.parent.iterdir())
    except Exception:
        return 0

    for sibling in siblings:
        if sibling == path or not sibling.is_file() or sibling.is_symlink():
            continue
        parts = {part.lower() for part in sibling.parts}
        if parts.intersection(_SKIP_DIR_NAMES):
            continue
        suffix = sibling.suffix.lower()
        if suffix not in _CODE_EXTS:
            continue
        if sibling.name.lower() in _CODE_LOCKFILE_NAMES or sibling.name.lower() in _INDEX_WRAPPER_NAMES:
            continue
        try:
            size = sibling.stat().st_size
        except OSError:
            continue
        if size < 50 or size > _MAX_CODE_FILE_BYTES:
            continue
        if _code_is_binary(sibling):
            continue
        count += 1

    return count


def _code_is_binary(path: Path) -> bool:
    """Return True if the first 512 bytes contain a null byte."""
    try:
        with open(path, "rb") as fh:
            return b"\x00" in fh.read(512)
    except Exception:
        return True


def _score_code_source(
    rel: str, name: str, suffix: str, size: int, catalog: dict,
) -> int:
    """Score a code file for architecture research value."""
    score = 0
    path_lower = rel.lower()

    # Exact high-value filenames
    if name in _CODE_HIGH_VALUE_NAMES:
        score += 10
    # Config/build prefixes
    elif any(name.startswith(p) for p in _CODE_CONFIG_PREFIXES):
        score += 8

    # Architecture keywords in path
    for kw in _CODE_ARCHITECTURE_KEYWORDS:
        if kw in path_lower:
            score += 6
            break

    # Source code bonus (TS/JS/Py carry more weight than JSON/YAML)
    if suffix in (".ts", ".tsx", ".js", ".jsx", ".mjs", ".py"):
        score += 3
    elif suffix in (".json", ".yaml", ".yml", ".toml", ".cfg"):
        score -= 2

    # Catalog context bonuses
    important_files = catalog.get("important_files", []) or []
    imp_types = {i.get("type") for i in important_files}
    if "package_json" in imp_types:
        score += 2
    if "tsconfig" in str(imp_types) or "pyproject_toml" in imp_types:
        score += 2

    # Source directory bonus
    if "/src/" in f"/{path_lower}" or "/lib/" in f"/{path_lower}" or "/app/" in f"/{path_lower}":
        score += 2

    # Penalties
    if name in _CODE_LOCKFILE_NAMES:
        score -= 10
    if suffix in (".json", ".yaml", ".yml") and size > 50_000:
        score -= 5  # Huge config files are usually generated

    return max(score, -100)


def _code_reason(rel: str, name: str, suffix: str, score: int) -> str:
    """Generate a human-readable reason for a code file's score."""
    path_lower = rel.lower()
    parts = []

    if name in _CODE_HIGH_VALUE_NAMES:
        parts.append(f"key file: {name}")
    elif any(name.startswith(p) for p in _CODE_CONFIG_PREFIXES):
        parts.append(f"config file: {name}")
    elif any(k in path_lower for k in _CODE_ARCHITECTURE_KEYWORDS):
        matched = [k for k in _CODE_ARCHITECTURE_KEYWORDS if k in path_lower]
        parts.append(f"architecture keywords: {', '.join(matched[:3])}")

    if suffix in (".ts", ".tsx"):
        parts.append("TypeScript source")
    elif suffix in (".js", ".jsx", ".mjs"):
        parts.append("JavaScript source")
    elif suffix == ".py":
        parts.append("Python source")
    elif suffix in (".json", ".yaml", ".yml"):
        parts.append("config/metadata")

    if not parts:
        parts.append(f"code file ({suffix})")

    if score >= 13:
        parts.append("— high-priority")
    elif score >= 8:
        parts.append("— medium-priority")

    return " | ".join(parts)


def _code_category(name: str, suffix: str) -> str:
    """Return a human-readable category label for a code file."""
    cat_map = {
        ".ts": "typescript", ".tsx": "typescript",
        ".js": "javascript", ".jsx": "javascript", ".mjs": "javascript",
        ".cjs": "javascript", ".py": "python",
        ".json": "json_config", ".yaml": "yaml_config", ".yml": "yaml_config",
        ".toml": "toml_config", ".cfg": "config_file",
    }
    return cat_map.get(suffix, "code_file")


def _code_queue_empty(
    warnings: list | None = None,
    top: int = 0,
) -> dict[str, Any]:
    return {
        "catalog_count": 0,
        "queue_count": 0,
        "skipped_count": 0,
        "total_discovered": 0,
        "top_requested": top or _DEFAULT_CODE_QUEUE_TOP,
        "source_queue": [],
        "skipped_entries": [],
        "recommendations": [],
        "warnings": warnings or [
            {"type": "no_catalogs", "detail": "no catalogs found"},
        ],
        "error": None,
    }


# ── code queue rich renderer ────────────────────────────────────────────


def render_archive_code_queue_with_rich(data: dict[str, Any]) -> None:
    """Render a code queue using rich."""
    from rich.console import Console
    from rich.panel import Panel
    from rich.rule import Rule
    from rich.table import Table
    from rich.text import Text

    console = Console(highlight=False, soft_wrap=True)
    catalog_count: int = data.get("catalog_count", 0)
    queue_count: int = data.get("queue_count", 0)
    skipped_count: int = data.get("skipped_count", 0)
    total: int = data.get("total_discovered", 0)
    queue: list = data.get("source_queue", [])
    recs: list = data.get("recommendations", [])
    warnings: list = data.get("warnings", [])

    header = Table.grid(padding=(0, 1))
    header.add_column(justify="left")
    header.add_column(justify="right")
    header.add_row(
        f"[bold bright_cyan]LINK GROWTH CODE QUEUE[/]",
        f"[dim]{catalog_count} catalog{'s' if catalog_count != 1 else ''}  "
        f"{queue_count} queued  (top {data.get('top_requested', '?')})[/]",
    )
    console.print(header)
    console.print(Rule(style="dim"))

    if catalog_count == 0:
        empty = Text()
        empty.append("\nNo catalog files found.\n\n", style="dim")
        empty.append("To create a catalog:\n", style="dim")
        empty.append("  python3 link.py growth archive-extract --archive <path> --write\n", style="dim")
        empty.append("  python3 link.py growth archive-catalog --source <dir> --write\n", style="dim")
        empty.append("\n")
        empty.append("  [dim]python3 link.py growth archive-inventory  -- find archives[/]\n", style="dim")
        empty.append("  [dim]python3 link.py growth run               -- guided workflow[/]\n", style="dim")
        console.print(Panel(empty, border_style="dim"))
        console.print(Rule(style="dim"))
        return

    for w in warnings:
        console.print(Panel(Text(str(w), style="yellow"), border_style="yellow"))

    if queue_count == 0:
        empty_q = Text()
        empty_q.append(
            f"\n{catalog_count} catalog(s) scanned — {total} code files discovered, "
            f"0 eligible for queue.\n",
            style="dim",
        )
        if skipped_count:
            empty_q.append(f"{skipped_count} file(s) were skipped.\n", style="dim")
        console.print(Panel(empty_q, border_style="dim"))
        console.print(Rule(style="dim"))
        console.print("  [dim]python3 link.py growth run  -- guided workflow dashboard[/]")
        return

    value_colors = {"high": "green", "medium": "yellow", "low": "dim"}
    for entry in queue[:15]:
        entry_text = Text()
        ev = entry.get("estimated_value", "medium")
        vc = value_colors.get(ev, "dim")

        entry_text.append(
            f"[bold]#{entry.get('rank')}[/]  "
            f"[{vc}]{ev.upper()}[/]  "
            f"score: {entry.get('score')}  "
            f"[dim]{entry.get('category', '')}[/]"
        )
        entry_text.append(
            f"\n[dim]path:  [/]{entry.get('source_path', '?')}"
        )
        entry_text.append(
            f"\n[dim]reason:[/] {entry.get('reason', '?')}"
        )
        entry_text.append(
            f"\n[dim]size:  [/]{entry.get('size_human', '?')}"
        )
        entry_text.append(
            f"\n[dim]cmd:   [/]$ {entry.get('suggested_command', '?')}"
        )

        panel_title = f"CODE QUEUE  {entry.get('catalog_source_name', '?')}"
        console.print(Panel(entry_text, title=panel_title, border_style=vc))

    if len(queue) > 15:
        console.print(f"  [dim]... and {len(queue) - 15} more entries[/]")

    if recs:
        rec_text = Text()
        rec_text.append("Top command:\n", style="bold green")
        rec_text.append(f"  $ {recs[0]}\n\n", style="dim")
        if len(recs) > 1:
            rec_text.append("Next:\n", style="bold")
            for r in recs[1:4]:
                rec_text.append(f"  $ {r}\n", style="dim")
        console.print(Panel(rec_text, title="RECOMMENDED NEXT STEPS", border_style="green"))

    console.print(Rule(style="dim"))
    console.print("  [dim]python3 link.py growth archive-code-brief --source <path>  -- brief a code source[/]")
    console.print("  [dim]python3 link.py growth run                         -- guided workflow[/]")


# ── code queue plain fallback ───────────────────────────────────────────


def render_archive_code_queue_plain(data: dict[str, Any]) -> None:
    """Render a code queue using plain print."""
    catalog_count: int = data.get("catalog_count", 0)
    queue_count: int = data.get("queue_count", 0)
    skipped_count: int = data.get("skipped_count", 0)
    total: int = data.get("total_discovered", 0)
    queue: list = data.get("source_queue", [])
    recs: list = data.get("recommendations", [])
    warnings: list = data.get("warnings", [])
    out: list[str] = []
    out.append(
        f"== LINK GROWTH CODE QUEUE ({catalog_count} catalogs, "
        f"{queue_count} queued, {skipped_count} skipped) =="
    )
    out.append("")

    if catalog_count == 0:
        out.append("No catalog files found.")
        out.append("To create a catalog:")
        out.append("  python3 link.py growth archive-extract --archive <path> --write")
        out.append("  python3 link.py growth archive-catalog --source <dir> --write")
        out.append("")
        out.append("python3 link.py growth archive-inventory  -- find archives")
        out.append("python3 link.py growth run               -- guided workflow")
        print("\n".join(out))
        return

    for w in warnings:
        out.append(f"WARNING: {w}")

    if queue_count == 0:
        out.append("")
        out.append(f"{catalog_count} catalog(s) scanned — {total} code files discovered, 0 eligible.")
        out.append("")
        out.append("python3 link.py growth run  -- guided workflow dashboard")
        print("\n".join(out))
        return

    for entry in queue[:15]:
        out.append(
            f"--- #{entry.get('rank')} [{entry.get('estimated_value', 'medium').upper()}] "
            f"score={entry.get('score')}  {entry.get('category', '')} ---"
        )
        out.append(f"path:   {entry.get('source_path', '?')}")
        out.append(f"reason: {entry.get('reason', '?')}")
        out.append(f"size:   {entry.get('size_human', '?')}")
        out.append(f"cmd:    $ {entry.get('suggested_command', '?')}")
        out.append("")

    if recs:
        out.append("-- RECOMMENDED NEXT STEPS --")
        out.append(f"Top: $ {recs[0]}")
        for r in recs[1:4]:
            out.append(f"Next: $ {r}")
        out.append("")

    out.append("python3 link.py growth archive-code-brief --source <path>  -- brief a code source")
    out.append("python3 link.py growth run                         -- guided workflow")
    print("\n".join(out))


# ── code queue render orchestrator ──────────────────────────────────────


def render_archive_code_queue_view(data: dict[str, Any]) -> None:
    """Render code queue with rich if available; fall back to plain."""
    try:
        import rich  # noqa: F401
    except ImportError:
        render_archive_code_queue_plain(data)
        return
    render_archive_code_queue_with_rich(data)


# ── archive code brief entry point ──────────────────────────────────────
_CODE_BRIEFS_DIR = "research/_catalog/code_briefs"
_CODE_BRIEF_MAX_FILE_BYTES = 250_000
_CODE_BRIEF_MAX_TOTAL_BYTES = 1_000_000
_CODE_BRIEF_MAX_FILES_PER_DIR = 30


def archive_code_brief_main(argv: list[str] | None = None) -> int:
    """Entry point for ``python3 link.py growth archive-code-brief --source <path>``.

    Reads a code file or directory and produces a markdown research brief
    summarising its architecture value.  Dry-run by default; ``--write``
    persists the brief to ``research/_catalog/code_briefs/<slug>.md``.

    No code is executed.  Only plain text is read.  Existing extracted
    files are never modified.

    Flags:
        --source <path>  Required. Code file or directory.
        --write          Persist the brief to disk.
        --json           Machine-readable output.
        --root <path>    Override repo root (for test isolation).
    """
    args = sys.argv[1:] if argv is None else argv

    if not args or "--help" in args or "-h" in args:
        print("Growth archive-code-brief: create a markdown research brief")
        print("")
        print("Usage:")
        print("  python3 link.py growth archive-code-brief --source <path>")
        print("  python3 link.py growth archive-code-brief --source <path> --write")
        print("  python3 link.py growth archive-code-brief --source <path> --json")
        print("")
        print("Reads a code file or directory and produces a markdown")
        print("research brief so the proposal miner can understand it.")
        print("Dry-run by default.  No code is executed.")
        return 0

    source_arg = _parse_arg(args, "--source")
    if not source_arg:
        print("error: --source <path> is required", file=sys.stderr)
        print("Run 'python3 link.py growth archive-code-brief --help' for usage.",
              file=sys.stderr)
        return 2

    write = "--write" in args
    root_override = _parse_arg(args, "--root")
    data = collect_code_brief(source_arg, write=write, root=root_override)

    if "--json" in args:
        print(json.dumps(data, indent=2, default=str))
        return 0 if data.get("ok") else 1

    render_code_brief_view(data)
    return 0 if data.get("ok") else 1


def collect_code_brief(
    source: str,
    write: bool = False,
    root: str | None = None,
    include_brief_text: bool = False,
) -> dict[str, Any]:
    """Read a code file or directory and produce a markdown research brief.

    For directories, sibling implementation files are included alongside
    index files.  Files are capped at ``_CODE_BRIEF_MAX_FILE_BYTES`` and
    ``_CODE_BRIEF_MAX_TOTAL_BYTES``.  Binary files, lockfiles, and files
    in skipped directories are excluded.

    When ``write=True`` the brief is persisted to
    ``research/_catalog/code_briefs/<slug>.md``.

    Returns a dict with ``ok``, ``brief_preview``, ``brief_path``,
    ``files_read``, ``files_skipped``, and suggested next commands.

    No code is executed.  Read-only text extraction.
    """
    from pathlib import Path

    repo_root = Path(root) if root else Path.cwd()
    source_path = (repo_root / source).resolve()

    if not source_path.exists():
        return _brief_error(f"source not found: {source_path}")

    is_dir = source_path.is_dir()

    # ── collect files ──
    files_read: list[dict] = []
    files_skipped: list[dict] = []
    total_bytes = 0
    source_type = "directory" if is_dir else "file"

    source_files = _collect_brief_files(
        source_path, is_dir, _CODE_BRIEF_MAX_FILES_PER_DIR,
    )

    for fpath in source_files:
        size = fpath.stat().st_size
        rel = str(fpath.relative_to(source_path)) if is_dir else fpath.name

        if size > _CODE_BRIEF_MAX_FILE_BYTES:
            files_skipped.append({"path": rel, "reason": f"too large ({_human_size(size)})"})
            continue
        if _code_is_binary(fpath):
            files_skipped.append({"path": rel, "reason": "binary"})
            continue
        if total_bytes + size > _CODE_BRIEF_MAX_TOTAL_BYTES:
            files_skipped.append({"path": rel, "reason": "total bytes cap reached"})
            continue

        try:
            content = fpath.read_text(encoding="utf-8", errors="replace")
        except Exception:
            files_skipped.append({"path": rel, "reason": "unreadable"})
            continue

        total_bytes += size
        files_read.append({
            "path": rel,
            "size_bytes": size,
            "content": content,
        })

    if not files_read:
        return _brief_error(
            f"no readable source files found in {source_path}. "
            f"All files were skipped or the source is empty.",
            files_read=files_read,
            files_skipped=files_skipped,
            source_type=source_type,
        )

    # ── build brief ──
    source_name = source_path.name
    slug = _slugify(source_name)
    brief_md = _build_code_brief(source_path, source_name, slug, files_read)

    brief_path = ""
    if write:
        briefs_dir = repo_root / _CODE_BRIEFS_DIR
        briefs_dir.mkdir(parents=True, exist_ok=True)
        brief_file = briefs_dir / f"{slug}.md"
        if brief_file.exists():
            return _brief_error(
                f"brief already exists: {brief_file}",
                files_read=files_read,
                files_skipped=files_skipped,
                source_type=source_type,
            )
        brief_file.write_text(brief_md, encoding="utf-8")
        brief_path = str(brief_file)

    result = {
        "ok": True,
        "source_path": str(source_path),
        "source_name": source_name,
        "source_type": source_type,
        "slug": slug,
        "files_read": [{k: v for k, v in f.items() if k != "content"} for f in files_read],
        "files_read_count": len(files_read),
        "files_skipped": files_skipped,
        "total_bytes_read": total_bytes,
        "total_human": _human_size(total_bytes),
        "brief_path": brief_path,
        "brief_preview": brief_md.split("\n")[:60],
        "dry_run": not write,
        "next_commands": [
            f"python3 link.py growth code-brief-propose --source {brief_path}" if brief_path else (
                f"python3 link.py growth archive-code-brief --source {source_path} --write"
            ),
            "python3 link.py growth proposals",
            "python3 link.py growth approve <proposal_id>",
        ],
        "warnings": [],
        "error": None,
    }
    if include_brief_text:
        result["brief_markdown"] = brief_md
    return result


def _collect_brief_files(
    source_path: Path, is_dir: bool, max_files: int,
) -> list[Path]:
    """Collect readable source files for a brief."""
    files: list[Path] = []

    if not is_dir:
        files.append(source_path)
        return files

    # Gather all files in directory, sorted
    for entry in sorted(source_path.rglob("*")):
        if not entry.is_file():
            continue
        if entry.is_symlink():
            continue

        rel = str(entry.relative_to(source_path))
        path_lower = rel.lower()

        # Skip dirs
        skip = False
        for sd in _SKIP_DIR_NAMES:
            if sd in path_lower.split("/"):
                skip = True
                break
        if skip:
            continue
        if "__MACOSX" in path_lower:
            continue

        # Skip lockfiles
        if entry.name.lower() in _CODE_LOCKFILE_NAMES:
            continue

        # Skip non-code extensions
        suffix = entry.suffix.lower()
        if suffix not in _CODE_EXTS:
            continue

        files.append(entry)
        if len(files) >= max_files:
            break

    return files


def _build_code_brief(
    source_path: Path,
    source_name: str,
    slug: str,
    files_read: list[dict],
) -> str:
    """Build a markdown research brief from code files."""
    lines: list[str] = []
    lines.append(f"# Code Research Brief: {source_name}")
    lines.append("")
    lines.append(f"**Source path:** `{source_path}`")
    lines.append(f"**Files read:** {len(files_read)}")
    lines.append(f"**Generated by:** Link Growth archive-code-brief")
    lines.append(f"**Suggested mining:**")
    lines.append(f"")
    lines.append(f"    python3 link.py growth code-brief-propose --source research/_catalog/code_briefs/{slug}.md")
    lines.append("")
    lines.append("---")
    lines.append("")
    lines.append("## File Inventory")
    lines.append("")

    for f in files_read:
        lines.append(f"- `{f['path']}` ({_human_size(f['size_bytes'])})")

    lines.append("")
    lines.append("## Architecture Signals")
    lines.append("")

    all_text = "\n".join(f["content"] for f in files_read)
    signals = _detect_architecture_signals(all_text)
    for sig in signals:
        lines.append(f"- {sig}")

    if not signals:
        lines.append("- No strong architecture patterns detected automatically.")
    lines.append("")
    lines.append("## Source Excerpts")
    lines.append("")

    for f in files_read:
        excerpt = f["content"][:800].rstrip()
        lines.append(f"### {f['path']}")
        lines.append("")
        lines.append("```")
        if f["path"].endswith(".ts") or f["path"].endswith(".tsx"):
            lines.append("typescript")
        elif f["path"].endswith(".js") or f["path"].endswith(".jsx"):
            lines.append("javascript")
        elif f["path"].endswith(".py"):
            lines.append("python")
        elif f["path"].endswith(".json"):
            lines.append("json")
        elif f["path"].endswith((".yaml", ".yml")):
            lines.append("yaml")
        lines.append(excerpt)
        lines.append("```")
        lines.append("")

    lines.append("---")
    lines.append("")
    lines.append("## Growth Upgrade Candidates")
    lines.append("")

    text_lower = all_text.lower()
    sig_text = " ".join(signals).lower()
    candidates = _build_upgrade_candidates(
        source_name, text_lower, all_text, files_read, signals, sig_text,
    )
    for cand in candidates:
        lines.append(cand)
        lines.append("")

    if not candidates:
        lines.append("No upgrade candidates generated.")

    lines.append("")
    lines.append("---")
    lines.append("")
    lines.append("## Possible Link Upgrade Ideas")
    lines.append("")

    ideas = _infer_upgrade_ideas(source_name, signals)
    for idea in ideas:
        lines.append(f"- {idea}")

    if not ideas:
        lines.append("- No specific upgrade ideas inferred.")

    lines.append("")
    return "\n".join(lines)


def _build_upgrade_candidates(
    source_name: str,
    text_lower: str,
    all_text: str,
    files_read: list[dict],
    signals: list[str],
    sig_text: str,
) -> list[str]:
    """Build miner-compatible upgrade candidate blocks."""
    candidates: list[str] = []

    def _add(title: str, problem: str, evidence: str, pattern: str,
             upgrade: str, files_subsystem: str, risk: str, test_idea: str) -> None:
        # Collect file paths for evidence
        file_list = "\n".join(
            f"- `{f['path']}`" for f in files_read
        ) if files_read else f"- `{source_name}`"

        candidates.append(
            f"### UPGRADE CANDIDATE: {title}\n\n"
            f"**Problem:**\n{problem}\n\n"
            f"**Evidence from source:**\n{file_list}\n{evidence}\n\n"
            f"**Pattern observed:**\n{pattern}\n\n"
            f"**Proposed Link upgrade:**\n{upgrade}\n\n"
            f"**Likely Link files or subsystem:**\n{files_subsystem}\n\n"
            f"**Risk level:**\n{risk}\n\n"
            f"**Acceptance test idea:**\n{test_idea}\n"
        )

    has_branch = "branch" in text_lower or "fork" in text_lower
    has_transcript = any("transcript" in s.lower() for s in signals)
    has_session = any("session" in s.lower() for s in signals)
    has_storage = any("storage" in s.lower() for s in signals)
    has_content_replacement = "contentreplacement" in text_lower or "content replacement" in text_lower
    has_sandbox = any(k in text_lower for k in ("sandbox", "isolat"))
    has_worker = any("worker" in s.lower() for s in signals)
    has_receipt = any("receipt" in s.lower() for s in signals)
    has_verifier = any("verif" in s.lower() for s in signals)
    has_router = any(k in text_lower for k in ("router", "routing", "dispatch"))
    has_pipeline = any(k in text_lower for k in ("pipeline", "workflow"))
    has_permission = any(k in text_lower for k in ("permission", "auth"))
    has_factory = any(k in text_lower for k in ("factory", "delegate", "provider"))

    # 1. Branch/fork traceability
    if has_branch and (has_transcript or has_session):
        _add(
            "Add branch/fork traceability receipts to Link sessions",
            "Link can create independent runs but lacks a first-class way to "
            "preserve fork lineage between related sessions. Without traceability, "
            "branching a session means starting a new run with no provenance back "
            "to the original context.",
            "Source code implements transcript copy logic that preserves message "
            "history, rewrites session identifiers, and stores fork metadata. "
            "The command supports aliases for branch/fork terminology.",
            "Session branching with transcript preservation, session ID rewriting, "
            "and fork source metadata capture.",
            "Link should maintain a fork lineage receipt that records the parent "
            "session UUID, the fork point (message index or timestamp), and "
            "whether each child session diverged. This enables safe collaboration "
            "traces without losing provenance across the Link session graph.",
            "link_core/context/ or link_core/agent_memory/ — session management "
            "and conversation state layer.",
            "low",
            "Branch a Link run session and verify both parent and child runs "
            "contain reciprocal cross-reference metadata in their execution receipts.",
        )

    # 2. Content replacement preservation
    if has_content_replacement and has_transcript:
        _add(
            "Preserve content replacement history across session forks",
            "When a session is forked, inline content edits and replacements "
            "made during the original session may be lost. Link's upgrade "
            "candidate pipeline loses evidence of prior edit decisions when "
            "content is replaced without an audit trail.",
            "Source code includes ContentReplacementEntry type definitions "
            "with fields tracking original and replacement content within "
            "transcript entries. These types describe a structured record "
            "of content edits but may not survive session forks.",
            "Content replacement tracking with structured entry types, "
            "transcript serialization, and fork/copy logic.",
            "Link should track content replacement lineage by preserving "
            "ContentReplacementEntry records in the fork lineage receipt. "
            "This ensures audit trails for inline content edits survive "
            "session branching and can be used for proposal evidence tracing.",
            "link_core/context/ or link_core/receipts/ — evidence tracking "
            "and execution receipt layer.",
            "low",
            "Create a session with multiple content replacements, fork it, "
            "then verify the forked session still lists all original "
            "replacement entries with their source session IDs.",
        )

    # 3. Session transcript preservation
    if has_session and has_storage:
        _add(
            "Add safe transcript copy with traceability metadata for Link sessions",
            "Link produces execution transcripts but does not currently store "
            "a normalized session transcript with provenance metadata such as "
            "the originating session, copy timestamp, and fork depth. This "
            "gap creates a missing audit trail for research mining.",
            "Source code copies transcript entries, rewrites session IDs, "
            "and serializes the transcript to persistent storage. The code "
            "includes structured logging and analytics event hooks.",
            "Structured session storage with transcript serialization, "
            "session ID rewriting, and log event publishing.",
            "Link should store a complete session transcript snapshot at fork "
            "points, along with provenance metadata (parent session, fork "
            "depth, copy timestamp). This gives Growth mode a recoverable "
            "research source for auditing and evidence.",
            "link_core/receipts/ or link_core/memory/ — execution evidence "
            "and session persistence layer.",
            "low",
            "Create a session, generate 10 messages, fork it. Verify the "
            "fork point transcript is persisted and contains a parent_session "
            "field with the original session UUID.",
        )

    # 4. Branch title collision
    if has_branch and has_session:
        _add(
            "Add unique branch title collision handling with deduplication",
            "Link currently creates proposals with candidate_id hashes that "
            "are deduplicated by title. When multiple sessions fork from the "
            "same source, collision in branch naming could lose distinct "
            "upgrade candidates if titles are identical.",
            "Source code accepts an optional [name] argument for branch "
            "naming but does not validate uniqueness. The command description "
            "mentions 'Create a branch of the current conversation at this "
            "point' without collision handling.",
            "Branch naming with optional user-defined titles, no uniqueness "
            "validation, and conversation snapshot semantics.",
            "Link should auto-generate branch titles when none are provided "
            "(e.g., timestamp-based or UUID-suffixed) and validate uniqueness "
            "when a custom title is given. This prevents silent overwrites "
            "of distinct proposal upgrades.",
            "link_core/context/ or link.py CLI — session management and "
            "command dispatch layer.",
            "low",
            "Create two branches with the same custom title from the same "
            "session and verify the second branch receives a warning or "
            "auto-suffix to avoid collision.",
        )

    # 5. Sandbox worker isolation
    if has_sandbox and has_worker:
        _add(
            "Add sandboxed worker isolation for safe patch executor handoff",
            "Link's Growth pipeline can generate patch plans and worker "
            "handoffs, but the execution gate around applying patches is not "
            "yet sandboxed by default. Workers could benefit from isolation "
            "patterns found in existing safe-execution systems.",
            "Source code imports sandbox workers with isolation flags, "
            "wraps executor logic in sandbox containers, and verifies "
            "receipts after execution. The pattern demonstrates worker "
            "isolation with verification gating.",
            "Sandboxed worker execution with isolation flags, receipt "
            "verification, and pipeline orchestration.",
            "Link should extend its worker handoff executor to support a "
            "sandbox profile that restricts file-system writes, enforces "
            "allowed_files lists, and requires a verification receipt before "
            "the worker can mark a patch as complete.",
            "link_core/safety/ or link_core/control_plane/ — capability gate "
            "and patch executor layer.",
            "medium",
            "Create a worker handoff with a restricted allowed_files list, "
            "execute it in a sandboxed subprocess that cannot write outside "
            "those paths, and verify the receipt is rejected if any "
            "disallowed write is attempted.",
        )

    # 6. Auto-generate execution receipts
    if has_receipt and has_verifier:
        _add(
            "Auto-generate execution receipts after handoff verification",
            "Link creates patch plans and worker handoffs but does not currently "
            "auto-generate an execution receipt after each handoff verification "
            "step. This gap makes it harder to audit whether a handoff was "
            "fully executed and what evidence was produced.",
            "Source code verifies receipts after worker execution and returns "
            "receipt objects through the orchestration pipeline. The pattern "
            "shows a gated execute-then-verify flow with receipt propagation.",
            "Verification receipt generation after sandboxed execution, "
            "with receipt objects propagated through pipeline stages.",
            "Link should auto-generate a verifier receipt after each handoff "
            "worker completes, even when --write is not used. The receipt "
            "should record the handoff_id, verification_id, execution "
            "timestamp, and whether all verification commands passed.",
            "link_core/receipts/ or link_core/control_plane/ — execution "
            "evidence and verifier receipt layer.",
            "low",
            "Create and approve a proposal, create a handoff, then run "
            "the execute command. Verify a verifier receipt is produced "
            "even in dry-run mode, containing handoff_id and verification "
            "command status.",
        )

    # 7. Router enhancement
    if has_router:
        _add(
            "Add capability-gated tool routing from command dispatch table",
            "Link's tool registry maps tools to endpoints but does not have "
            "a profile-gated routing layer similar to the command dispatch "
            "pattern found in TS/JS command routers. A capability gate per "
            "tool route would improve safety.",
            "Source code implements a command router that maps command "
            "names to handler functions with lazy-load support and alias "
            "resolution. Each command is registered with a type definition.",
            "Command router with name-to-handler mapping, lazy-load "
            "deferred imports, alias resolution, and type-safe command "
            "definitions.",
            "Link should extend its tool registry to support a routing "
            "dispatch table that maps tool names to handler profiles, with "
            "lazy-importer support for on-demand loading and a capability "
            "gate that checks the active worker profile before dispatching.",
            "link_core/routing/ or link_core/safety/ — model routing and "
            "capability gate layer.",
            "medium",
            "Register two tools with different required profiles (readOnly "
            "and patchWorker). Verify that a readOnly worker cannot dispatch "
            "to the patchWorker tool.",
        )

    # 8. Pipeline progress tracking
    if has_pipeline:
        _add(
            "Add pipeline stage progress tracking to the control plane dashboard",
            "Link's control plane has 9 pipeline stages but no terminal-visible "
            "progress tracker that shows how many proposals are at each stage "
            "and whether the pipeline has stalled. The existing Growth dashboard "
            "could benefit from a stage-progress view.",
            "Source code defines a Pipeline interface with sequential Stage "
            "enumeration, retry logic, and fallback stages. This structured "
            "pipeline definition is similar to Link's ResearchIngest → "
            "Finalizer stages.",
            "Pipeline interface with typed stages, retry/fallback support, "
            "and sequential stage progression.",
            "Link should add a pipeline progress tracker to the Growth run "
            "and status dashboards that shows proposal counts per stage, "
            "any blocked stages, and a visual indicator of pipeline flow. "
            "This makes the control plane observable from the terminal.",
            "link_core/control_plane/ or link_modes/growth/ — control plane "
            "pipeline and Growth console.",
            "low",
            "Create 3 proposals at different stages (pending, approved, "
            "handoff-written). Run growth status and verify the pipeline "
            "progress section shows all 3 stages with correct counts.",
        )

    # 9. Permission gating
    if has_permission:
        _add(
            "Add profile gate permission check before every tool execution",
            "Link's tool registry and worker profiles exist but the permission "
            "check does not yet run as a pre-dispatch gate for every tool "
            "invocation. A centralized permission check would improve safety.",
            "Source code includes permission and authentication patterns "
            "in command dispatch and tool registration flows. Commands are "
            "defined with type safety and can be feature-gated.",
            "Permission patterns in tool registration, command dispatch, "
            "and feature flag gating for command availability.",
            "Link should add a mandatory profile tool gate check before "
            "every tool execution in the runtime loop, not just at worker "
            "profile assignment time. Each tool call should verify the "
            "active worker profile is permitted for the requested tool.",
            "link_core/safety/ or link_core/routing/ — profile gate and "
            "tool registry layer.",
            "medium",
            "Assign a restricted worker profile and attempt to call a "
            "high-approval tool. Verify the tool call is rejected with "
            "a profile-gate rejection receipt before any execution occurs.",
        )

    # Cap at 6
    return candidates[:6]


def _detect_architecture_signals(text: str) -> list[str]:
    """Detect architecture patterns in source text."""
    signals: list[str] = []
    text_lower = text.lower()

    patterns = [
        ("router", "Routing / dispatch table patterns detected"),
        ("orchestrat", "Orchestration patterns detected"),
        ("agent", "Agent / autonomous actor patterns detected"),
        ("planner", "Planning workflow patterns detected"),
        ("executor", "Execution / task runner patterns detected"),
        ("workflow", "Workflow / pipeline patterns detected"),
        ("pipeline", "Pipeline / sequential processing patterns detected"),
        ("tool", "Tool registration / capability patterns detected"),
        ("memory", "Memory / state persistence patterns detected"),
        ("context", "Context / session management patterns detected"),
        ("schema", "Schema / validation patterns detected"),
        ("verifier", "Verification / check patterns detected"),
        ("receipt", "Receipt / evidence patterns detected"),
        ("worker", "Worker / parallel execution patterns detected"),
        ("queue", "Queue / task scheduling patterns detected"),
        ("dashboard", "Dashboard / admin UI patterns detected"),
        ("lazy", "Lazy-load / dynamic import patterns detected"),
        ("import(", "Dynamic import patterns detected"),
        ("permission", "Permission / access control patterns detected"),
        ("auth", "Authentication patterns detected"),
        ("session", "Session management patterns detected"),
        ("transcript", "Transcript / logging patterns detected"),
        ("storage", "Storage / persistence patterns detected"),
        ("error", "Error handling patterns detected"),
        ("retry", "Retry / resilience patterns detected"),
        ("fallback", "Fallback / degradation patterns detected"),
        ("sandbox", "Sandbox / isolation patterns detected"),
        ("isolat", "Isolation / containment patterns detected"),
        ("safe", "Safety / guard patterns detected"),
        ("factory", "Factory / builder patterns detected"),
        ("delegate", "Delegation patterns detected"),
        ("adapter", "Adapter / bridge patterns detected"),
        ("bridge", "Bridge / translation patterns detected"),
        ("provider", "Provider / injection patterns detected"),
    ]

    for keyword, label in patterns:
        if keyword in text_lower and label not in signals:
            signals.append(label)

    if len(signals) > 15:
        signals = signals[:15]

    return signals


def _infer_upgrade_ideas(source_name: str, signals: list[str]) -> list[str]:
    """Infer possible Link upgrade ideas from detected patterns."""
    ideas: list[str] = []
    sig_text = " ".join(signals).lower()

    if "agent" in sig_text and "tool" in sig_text:
        ideas.append(
            "Review agent/tool registration model for tool-canister or "
            "profile-gated tool dispatch patterns adaptable to Link's tool registry."
        )
    if "router" in sig_text:
        ideas.append(
            "Study routing/dispatch architecture for Link's model router "
            "or worker delegation routing."
        )
    if "worker" in sig_text and "queue" in sig_text:
        ideas.append(
            "Review worker/queue model for Link task scheduler or "
            "autonomous agent task queue."
        )
    if "sandbox" in sig_text or "isolat" in sig_text:
        ideas.append(
            "Study sandbox/isolation patterns for Link's worker isolation "
            "and safe-code-execution story."
        )
    if "context" in sig_text and "session" in sig_text:
        ideas.append(
            "Review context/session management for Link's long-session "
            "memory and context-truncation upgrade."
        )
    if "permission" in sig_text or "auth" in sig_text:
        ideas.append(
            "Study permission/auth patterns for Link's capability gate "
            "and profile tool gate."
        )
    if "receipt" in sig_text or "verifier" in sig_text:
        ideas.append(
            "Review receipt/verifier patterns for Link's execution "
            "evidence and healthcheck receipt system."
        )
    if "pipeline" in sig_text or "workflow" in sig_text:
        ideas.append(
            "Study pipeline/workflow patterns for Link's control-plane "
            "proposal pipeline."
        )
    if "error" in sig_text or "retry" in sig_text or "fallback" in sig_text:
        ideas.append(
            "Review error/retry/fallback patterns for Link's agent loop "
            "recovery and provider fallback."
        )
    if "lazy" in sig_text or "import(" in sig_text:
        ideas.append(
            "Study lazy-load/dynamic import patterns for Link's dynamic "
            "tool loading and provider routing."
        )
    if "factory" in sig_text or "delegate" in sig_text or "provider" in sig_text:
        ideas.append(
            "Review factory/delegate/provider patterns for Link's worker "
            "profile and mode factory architecture."
        )

    if not ideas:
        ideas.append(
            "General architecture review — compare command/event patterns "
            "to Link's CLI dispatcher and control-plane event model."
        )

    return ideas[:6]


def _slugify(name: str) -> str:
    """Create a safe slug from a name."""
    import re
    slug = name.lower().strip()
    slug = re.sub(r"[^a-z0-9]+", "-", slug)
    slug = slug.strip("-")
    return slug or "unnamed"


def _brief_error(
    error: str,
    files_read: list | None = None,
    files_skipped: list | None = None,
    source_type: str = "",
) -> dict[str, Any]:
    return {
        "ok": False,
        "source_path": "",
        "source_name": "",
        "source_type": source_type,
        "slug": "",
        "files_read": files_read or [],
        "files_skipped": files_skipped or [],
        "total_bytes_read": 0,
        "total_human": "0",
        "brief_path": "",
        "brief_preview": [],
        "dry_run": True,
        "next_commands": [
            "python3 link.py growth archive-code-queue",
            "python3 link.py growth run",
        ],
        "warnings": [],
        "error": error,
        "files_read_count": len(files_read) if files_read else 0,
    }


# ── code brief rich renderer ────────────────────────────────────────────


def render_code_brief_with_rich(data: dict[str, Any]) -> None:
    """Render a code brief preview/receipt using rich."""
    from rich.console import Console
    from rich.panel import Panel
    from rich.rule import Rule
    from rich.table import Table
    from rich.text import Text

    console = Console(highlight=False, soft_wrap=True)
    ok: bool = data.get("ok", True)
    dry_run: bool = data.get("dry_run", True)

    header = Table.grid(padding=(0, 1))
    header.add_column(justify="left")
    header.add_column(justify="right")
    if not ok:
        label, color = "ERROR", "red"
    elif dry_run:
        label, color = "DRY RUN", "yellow"
    else:
        label, color = "WRITTEN", "bold green"
    header.add_row(
        f"[bold bright_cyan]LINK GROWTH CODE BRIEF[/]",
        f"[{color}]{label}[/]",
    )
    console.print(header)

    if not ok:
        error_text = Text()
        sk = data.get("files_skipped", [])
        if sk:
            error_text.append("All files were skipped or unreadable:\n", style="dim")
            for s in sk[:5]:
                error_text.append(f"  {s['path']}: {s['reason']}\n", style="dim")
        error_text.append(f"\n[red]{data.get('error', 'unknown error')}[/]")
        console.print(Panel(error_text, border_style="red"))
        console.print(Rule(style="dim"))
        return

    # ── source info ──
    info = Text()
    info.append("source: ", style="dim")
    info.append(data.get("source_path", "?"), style="bold")
    info.append(f"\n[dim]type:   [/]{data.get('source_type', '?')}")
    info.append(
        f"\n[dim]files:  [/]{data.get('files_read_count', 0)} read  "
        f"{len(data.get('files_skipped', []))} skipped  "
        f"[dim]total: {data.get('total_human', '?')}[/]"
    )
    console.print(Panel(info, title="SOURCE", border_style="dim"))

    # ── files read ──
    files = data.get("files_read", [])
    if files:
        ft = Text()
        for f in files[:12]:
            ft.append(
                f"\n\u2022 {f.get('path', '?')}  "
                f"[dim]({_human_size(f.get('size_bytes', 0))})[/]"
            )
        console.print(Panel(ft, title="FILES READ", border_style="dim"))

    # ── files skipped ──
    skipped = data.get("files_skipped", [])
    if skipped:
        st = Text()
        for s in skipped[:8]:
            st.append(
                f"\n[dim]\u2717 {s.get('path', '?')} — {s.get('reason', '?')}[/]"
            )
        console.print(Panel(st, title="SKIPPED", border_style="yellow"))

    # ── brief preview ──
    preview = data.get("brief_preview", [])
    if preview:
        prev_text = Text()
        prev_text.append("\n".join(preview[:20]))
        console.print(Panel(prev_text, title="BRIEF PREVIEW", border_style="dim"))

    # ── written path ──
    brief_path = data.get("brief_path", "")
    if brief_path:
        wt = Text()
        wt.append("Brief written to:\n", style="bold green")
        wt.append(f"  {brief_path}", style="dim")
        console.print(Panel(wt, border_style="dim green"))

    # ── next commands ──
    next_cmds = data.get("next_commands", [])
    nc = Text()
    nc.append("Next:\n", style="bold")
    for cmd in next_cmds:
        nc.append(f"  $ {cmd}\n", style="dim")

    console.print(Rule(style="dim"))
    console.print(Panel(nc, title="SUGGESTED NEXT STEPS", border_style="green"))
    console.print("  [dim]No code was executed by this command.[/]")
    console.print("  [dim]python3 link.py growth run  -- guided workflow[/]")


# ── code brief plain fallback ───────────────────────────────────────────


def render_code_brief_plain(data: dict[str, Any]) -> None:
    """Render a code brief using plain print."""
    ok: bool = data.get("ok", True)
    dry_run: bool = data.get("dry_run", True)
    label = "ERROR" if not ok else ("DRY RUN" if dry_run else "WRITTEN")
    out: list[str] = []
    out.append(f"== LINK GROWTH CODE BRIEF ({label}) ==")
    out.append("")

    if not ok:
        skipped = data.get("files_skipped", [])
        if skipped:
            out.append("Files skipped:")
            for s in skipped[:5]:
                out.append(f"  {s['path']}: {s['reason']}")
        out.append(f"error: {data.get('error', 'unknown error')}")
        print("\n".join(out))
        return

    out.append(f"source: {data.get('source_path', '?')}")
    out.append(f"type:   {data.get('source_type', '?')}")
    out.append(f"files:  {data.get('files_read_count', 0)} read  "
               f"{len(data.get('files_skipped', []))} skipped  "
               f"total: {data.get('total_human', '?')}")
    out.append("")

    files = data.get("files_read", [])
    if files:
        out.append("-- FILES READ --")
        for f in files[:12]:
            out.append(f"  - {f.get('path', '?')} ({_human_size(f.get('size_bytes', 0))})")
        out.append("")

    skipped = data.get("files_skipped", [])
    if skipped:
        out.append("-- SKIPPED --")
        for s in skipped[:8]:
            out.append(f"  - {s.get('path', '?')}: {s.get('reason', '?')}")
        out.append("")

    preview = data.get("brief_preview", [])
    if preview:
        out.append("-- BRIEF PREVIEW --")
        out.extend(preview[:20])
        out.append("")

    brief_path = data.get("brief_path", "")
    if brief_path:
        out.append(f"Brief written to: {brief_path}")
        out.append("")

    next_cmds = data.get("next_commands", [])
    out.append("-- SUGGESTED NEXT STEPS --")
    for cmd in next_cmds:
        out.append(f"  $ {cmd}")
    out.append("")
    out.append("No code was executed by this command.")
    out.append("python3 link.py growth run  -- guided workflow")
    print("\n".join(out))


# ── code brief render orchestrator ──────────────────────────────────────


def render_code_brief_view(data: dict[str, Any]) -> None:
    """Render code brief with rich if available; fall back to plain."""
    try:
        import rich  # noqa: F401
    except ImportError:
        render_code_brief_plain(data)
        return
    render_code_brief_with_rich(data)



# ── batch code brief proposal preview entry point ───────────────────────


def _normalize_cli_dashes(args: list[str]) -> list[str]:
    """Normalize pasted en/em dash options to regular CLI dashes."""
    return [arg.replace("\u2013", "--", 1).replace("\u2014", "--", 1) for arg in args]


def code_brief_propose_batch_main(argv: list[str] | None = None) -> int:
    """Entry point for ``growth code-brief-propose-batch``.

    Ranks code sources, builds in-memory code briefs, previews proposal generation,
    and optionally persists generated proposals with --write.
    """
    args = _normalize_cli_dashes(sys.argv[1:] if argv is None else argv)
    write = "--write" in args

    if "--help" in args or "-h" in args:
        print("Growth code-brief-propose-batch: preview proposals for top code queue entries")
        print("")
        print("Usage:")
        print("  python3 link.py growth code-brief-propose-batch --top <N>")
        print("  python3 link.py growth code-brief-propose-batch --top <N> --json")
        print("  python3 link.py growth code-brief-propose-batch --top <N> --write")
        print("")
        print("Reads source text and writes proposals only with --write.")
        return 0

    top_arg = _parse_arg(args, "--top")
    top = _resolve_code_queue_top(top_arg)
    if isinstance(top, str):
        print(f"error: {top}", file=sys.stderr)
        return 1

    root_override = _parse_arg(args, "--root")
    data = collect_code_brief_propose_batch(top=top, root=root_override, write=write)

    if "--json" in args:
        print(json.dumps(data, indent=2, default=str))
        return 0

    render_code_brief_propose_batch_view(data)
    return 0


def collect_code_brief_propose_batch(
    top: int = _DEFAULT_CODE_QUEUE_TOP,
    root: str | None = None,
    write: bool = False,
) -> dict[str, Any]:
    """Preview or write code-brief proposal generation for top archive-code-queue entries."""
    from pathlib import Path

    from link_core.control_plane import write_proposal as _write_proposal
    from link_core.control_plane.link_control_plane_proposals import (
        proposal_storage_dir as _proposal_storage_dir,
    )

    repo_root = Path(root) if root else Path.cwd()
    effective_top = min(max(int(top), 1), _MAX_CODE_QUEUE_TOP)
    warnings: list[Any] = []
    if top > _MAX_CODE_QUEUE_TOP:
        warnings.append(f"top {top} capped at {_MAX_CODE_QUEUE_TOP} (hard limit)")

    queue_data = collect_archive_code_queue(top=effective_top, root=str(repo_root))
    queue_entries = list(queue_data.get("source_queue", []))[:effective_top]
    warnings.extend(queue_data.get("warnings", []) or [])

    source_summaries: list[dict[str, Any]] = []
    written_paths: list[str] = []
    candidate_total = 0
    proposal_total = 0
    weak_total = 0
    duplicate_total = 0

    for entry in queue_entries:
        source_path = str(entry.get("recommended_source_path") or entry.get("source_path") or "")
        source_warnings: list[Any] = []
        brief_data = collect_code_brief(
            source_path,
            write=False,
            root=str(repo_root),
            include_brief_text=True,
        )
        source_warnings.extend(brief_data.get("warnings", []) or [])

        candidates: list[dict[str, Any]] = []
        proposals: list[dict[str, Any]] = []
        quality_warnings: list[dict[str, Any]] = []
        weak_count = 0
        duplicate_count = 0

        if brief_data.get("ok"):
            brief_md = str(brief_data.get("brief_markdown") or "")
            candidates = _parse_code_brief_candidates(brief_md, source_path)
            seen_titles: set[str] = set()
            proposals = [
                _code_brief_candidate_to_proposal(c, source_path, seen_titles=seen_titles)
                for c in candidates
            ]
            quality = _analyze_code_brief_proposal_quality(
                candidates,
                proposals,
                proposal_dir=_proposal_storage_dir(repo_root),
            )
            quality_warnings = quality["quality_warnings"]
            weak_count = quality["weak_candidate_count"]
            duplicate_count = quality["duplicate_count"]
            if write:
                for proposal in proposals:
                    path = _write_proposal(proposal, root=repo_root)
                    written_paths.append(str(path))
        else:
            source_warnings.append(brief_data.get("error") or "code brief preview failed")

        candidate_total += len(candidates)
        proposal_total += len(proposals)
        weak_total += weak_count
        duplicate_total += duplicate_count

        source_summaries.append({
            "source_path": source_path,
            "source_type": brief_data.get("source_type") or entry.get("recommended_source_type", ""),
            "rank": entry.get("rank"),
            "suggested_brief_command": f"python3 link.py growth archive-code-brief --source {source_path} --write",
            "suggested_propose_command": "python3 link.py growth code-brief-propose --source <brief.md>",
            "candidate_count": len(candidates),
            "proposal_count": len(proposals),
            "weak_candidate_count": weak_count,
            "duplicate_count": duplicate_count,
            "warnings": source_warnings + quality_warnings,
            "ok": bool(brief_data.get("ok")),
        })

    if not queue_entries:
        warnings.append("no code queue entries available for batch preview")

    return {
        "ok": True,
        "dry_run": not write,
        "top_requested": effective_top,
        "queued_source_count": len(queue_entries),
        "processed_source_count": len(source_summaries),
        "candidate_count": candidate_total,
        "proposal_count": proposal_total,
        "weak_candidate_count": weak_total,
        "duplicate_count": duplicate_total,
        "sources": source_summaries,
        "warnings": warnings,
        "written_paths": written_paths,
        "next_commands": [
            "python3 link.py growth archive-code-queue",
            "python3 link.py growth archive-code-brief --source <path> --write",
            "python3 link.py growth code-brief-propose --source <brief.md>",
        ],
        "error": None,
    }


def render_code_brief_propose_batch_view(data: dict[str, Any]) -> None:
    """Render batch proposal preview with rich if available."""
    try:
        import rich  # noqa: F401
    except ImportError:
        render_code_brief_propose_batch_plain(data)
        return
    render_code_brief_propose_batch_with_rich(data)


def render_code_brief_propose_batch_with_rich(data: dict[str, Any]) -> None:
    from rich.console import Console
    from rich.panel import Panel
    from rich.rule import Rule
    from rich.text import Text

    console = Console(highlight=False, soft_wrap=True)
    header = Text()
    header.append("LINK GROWTH CODE BRIEF PROPOSE BATCH", style="bold bright_cyan")
    header.append("  DRY RUN" if data.get("dry_run") else "  WRITTEN", style="yellow" if data.get("dry_run") else "green")
    console.print(header)
    console.print(Panel(
        f"queued: {data.get('queued_source_count', 0)}  "
        f"processed: {data.get('processed_source_count', 0)}  "
        f"candidates: {data.get('candidate_count', 0)}  "
        f"proposals: {data.get('proposal_count', 0)}",
        border_style="dim",
    ))

    for warning in data.get("warnings", []):
        console.print(Panel(Text(str(warning), style="yellow"), title="WARNING", border_style="yellow"))

    for source in data.get("sources", [])[:10]:
        body = Text()
        body.append(str(source.get("source_path", "?")), style="bold")
        body.append(f"\ncandidates: {source.get('candidate_count', 0)}  proposals: {source.get('proposal_count', 0)}")
        body.append(f"\ncmd: $ {source.get('suggested_brief_command', '?')}", style="dim")
        console.print(Panel(body, title=f"SOURCE #{source.get('rank', '?')}", border_style="dim"))

    next_text = Text()
    for command in data.get("next_commands", []):
        next_text.append(f"  $ {command}\n", style="dim")
    if data.get("written_paths"):
        written = Text()
        for path in data.get("written_paths", [])[:10]:
            written.append(f"{path}\n", style="green")
        console.print(Panel(written, title="WRITTEN PROPOSALS", border_style="green"))
    console.print(Rule(style="dim"))
    console.print(Panel(next_text, title="SUGGESTED NEXT STEPS", border_style="green"))


def render_code_brief_propose_batch_plain(data: dict[str, Any]) -> None:
    out: list[str] = []
    out.append("== LINK GROWTH CODE BRIEF PROPOSE BATCH (DRY RUN) ==" if data.get("dry_run") else "== LINK GROWTH CODE BRIEF PROPOSE BATCH (WRITTEN) ==")
    out.append(
        f"queued: {data.get('queued_source_count', 0)}  "
        f"processed: {data.get('processed_source_count', 0)}  "
        f"candidates: {data.get('candidate_count', 0)}  "
        f"proposals: {data.get('proposal_count', 0)}"
    )
    if data.get("warnings"):
        out.append("")
        out.append("-- WARNINGS --")
        for warning in data.get("warnings", []):
            out.append(f"  - {warning}")
    out.append("")
    for source in data.get("sources", []):
        out.append(f"--- SOURCE #{source.get('rank', '?')} ---")
        out.append(f"source:     {source.get('source_path', '?')}")
        out.append(f"candidates: {source.get('candidate_count', 0)}")
        out.append(f"proposals:  {source.get('proposal_count', 0)}")
        out.append(f"brief:      $ {source.get('suggested_brief_command', '?')}")
        out.append("")
    out.append("-- SUGGESTED NEXT STEPS --")
    if data.get("written_paths"):
        out.append("written proposals:")
        for path in data.get("written_paths", [])[:10]:
            out.append(f"  {path}")
    for command in data.get("next_commands", []):
        out.append(f"  $ {command}")
    print("\n".join(out))


# ── code brief propose entry point ───────────────────────────────────────


def code_brief_propose_main(argv: list[str] | None = None) -> int:
    """Entry point for ``python3 link.py growth code-brief-propose``.

    Reads a markdown code brief generated by ``archive-code-brief`` and
    converts its structured ``UPGRADE CANDIDATE`` blocks into normal pending
    Growth proposals. Dry-run by default; ``--write`` persists proposals via
    the existing control-plane ``write_proposal`` helper.

    No code is executed. No subprocess. No network. Markdown is read only.
    """
    args = sys.argv[1:] if argv is None else argv

    if not args or "--help" in args or "-h" in args:
        print("Growth code-brief-propose: convert code brief candidates to proposals")
        print("")
        print("Usage:")
        print("  python3 link.py growth code-brief-propose --source <brief.md>")
        print("  python3 link.py growth code-brief-propose --source <brief.md> --json")
        print("  python3 link.py growth code-brief-propose --source <brief.md> --write")
        print("")
        print("Reads markdown only. Dry-run by default. Proposals are")
        print("written only when --write is provided.")
        return 0

    source_arg = _parse_arg(args, "--source")
    if not source_arg:
        print("error: --source <brief.md> is required", file=sys.stderr)
        print("Run 'python3 link.py growth code-brief-propose --help' for usage.",
              file=sys.stderr)
        return 2

    write = "--write" in args
    root_override = _parse_arg(args, "--root")
    data = collect_code_brief_propose(source_arg, write=write, root=root_override)

    if "--json" in args:
        print(json.dumps(data, indent=2, default=str))
        return 0

    render_code_brief_propose_view(data)
    return 0


def collect_code_brief_propose(
    source: str,
    write: bool = False,
    root: str | None = None,
) -> dict[str, Any]:
    """Parse a markdown code brief and optionally persist proposals.

    Only ``### UPGRADE CANDIDATE: <title>`` blocks are parsed. The source
    markdown is read as text and is never modified. ``write=True`` writes only
    proposal JSON through ``link_core.control_plane.write_proposal``.
    """
    from pathlib import Path

    from link_core.control_plane import write_proposal as _write_proposal
    from link_core.control_plane.link_control_plane_proposals import (
        proposal_storage_dir as _proposal_storage_dir,
    )

    repo_root = Path(root) if root else Path.cwd()
    source_path = Path(source)
    if not source_path.is_absolute():
        source_path = (repo_root / source).resolve()
    else:
        source_path = source_path.resolve()

    if not source_path.exists() or not source_path.is_file():
        return _code_brief_propose_error(
            f"source not found: {source_path}",
            source=str(source_path),
            source_exists=False,
            dry_run=not write,
        )

    try:
        brief_text = source_path.read_text(encoding="utf-8", errors="replace")
    except Exception as exc:
        return _code_brief_propose_error(
            f"could not read source: {exc}",
            source=str(source_path),
            source_exists=True,
            dry_run=not write,
        )

    candidates = _parse_code_brief_candidates(brief_text, str(source_path))
    seen_titles: set[str] = set()
    proposals = [
        _code_brief_candidate_to_proposal(c, str(source_path), seen_titles=seen_titles)
        for c in candidates
    ]
    quality = _analyze_code_brief_proposal_quality(
        candidates,
        proposals,
        proposal_dir=_proposal_storage_dir(repo_root),
    )

    written_paths: list[str] = []
    if write:
        for proposal in proposals:
            path = _write_proposal(proposal, root=repo_root)
            written_paths.append(str(path))

    return {
        "ok": True,
        "source": str(source_path),
        "source_exists": True,
        "candidate_count": len(candidates),
        "proposal_count": len(proposals),
        "candidates": candidates,
        "proposals": proposals,
        "dry_run": not write,
        "written_paths": written_paths,
        "quality_warnings": quality["quality_warnings"],
        "weak_candidate_count": quality["weak_candidate_count"],
        "duplicate_count": quality["duplicate_count"],
        "next_commands": [
            "python3 link.py growth proposals",
            "python3 link.py growth approve <proposal_id>",
            "python3 link.py growth run",
        ],
        "warnings": [],
        "error": None if candidates else "no upgrade candidate blocks found in source",
    }


def _parse_code_brief_candidates(text: str, source_path: str) -> list[dict[str, Any]]:
    """Extract structured candidate blocks from a code brief markdown file."""
    import re

    heading = re.compile(r"^### UPGRADE CANDIDATE:\s*(.+?)\s*$", re.MULTILINE)
    matches = list(heading.finditer(text))
    candidates: list[dict[str, Any]] = []

    for idx, match in enumerate(matches):
        title = match.group(1).strip()
        if not title:
            continue
        start = match.end()
        end = matches[idx + 1].start() if idx + 1 < len(matches) else len(text)
        block = _trim_code_brief_candidate_block(text[start:end])

        problem = _extract_code_brief_field(block, "Problem")
        evidence_text = _extract_code_brief_field(block, "Evidence from source")
        pattern = _extract_code_brief_field(block, "Pattern observed")
        proposed = _extract_code_brief_field(block, "Proposed Link upgrade")
        likely_files = _extract_code_brief_field(block, "Likely Link files or subsystem")
        risk_raw = _extract_code_brief_field(block, "Risk level")
        acceptance = _extract_code_brief_field(block, "Acceptance test idea")
        risk = _normalize_code_brief_risk(risk_raw)

        candidates.append({
            "title": title,
            "problem": problem,
            "evidence_from_source": evidence_text,
            "pattern_observed": pattern,
            "proposed_link_upgrade": proposed,
            "likely_link_files_or_subsystem": likely_files,
            "risk": risk,
            "risk_raw": risk_raw,
            "acceptance_test_idea": acceptance,
            "source_path": source_path,
        })

    return candidates


def _trim_code_brief_candidate_block(block: str) -> str:
    """Remove trailing non-candidate sections from a candidate block."""
    import re

    boundary = re.search(r"(?m)^(?:---\s*|##\s+.+)$", block)
    return block[:boundary.start()] if boundary else block


def _extract_code_brief_field(block: str, label: str) -> str:
    """Return text under a ``**Label:**`` markdown field."""
    import re

    marker = f"**{label}:**"
    start = block.find(marker)
    if start < 0:
        return ""

    rest = block[start + len(marker):].lstrip("\r\n")
    next_field = re.search(r"(?m)^\*\*[^*\n]+:\*\*\s*$", rest)
    value = rest[:next_field.start()] if next_field else rest
    return value.strip()


def _normalize_code_brief_risk(risk: str) -> str:
    value = str(risk or "").strip().lower()
    if value in ("low", "medium", "high"):
        return value
    return "medium"


def _code_brief_text_is_vague(text: str) -> bool:
    value = " ".join(str(text or "").strip().lower().split())
    if not value:
        return True
    vague_values = {
        "n/a", "na", "none", "unknown", "tbd", "todo",
        "needs tests", "add tests", "write tests", "test", "tests",
        "link", "growth", "repo", "repository", "system", "subsystem",
        "files", "code", "runtime",
    }
    if value in vague_values:
        return True
    vague_markers = ("tbd", "todo", "unknown", "not sure", "unclear", "needs research")
    return any(marker in value for marker in vague_markers)


def _code_brief_likely_files_are_vague(text: str) -> bool:
    value = str(text or "").strip()
    if _code_brief_text_is_vague(value):
        return True
    items = _split_code_brief_list(value)
    if not items:
        return True
    for item in items:
        lower = item.lower()
        if "/" in item or "." in item:
            return False
        if lower.startswith(("link_core", "link_modes", "tests")):
            return False
    return True


def _analyze_code_brief_proposal_quality(
    candidates: list[dict[str, Any]],
    proposals: list[dict[str, Any]],
    proposal_dir: Any,
) -> dict[str, Any]:
    """Return warnings for weak or duplicate code-brief proposal candidates."""
    from pathlib import Path

    warnings: list[dict[str, Any]] = []
    weak_indexes: set[int] = set()
    duplicate_count = 0
    title_counts: dict[str, int] = {}

    for candidate in candidates:
        title_key = str(candidate.get("title") or "").strip().lower()
        if title_key:
            title_counts[title_key] = title_counts.get(title_key, 0) + 1

    seen_titles: set[str] = set()
    storage = Path(proposal_dir)
    for idx, candidate in enumerate(candidates):
        proposal = proposals[idx] if idx < len(proposals) else {}
        title = str(candidate.get("title") or proposal.get("title") or "").strip()
        title_key = title.lower()
        proposal_id = str(proposal.get("proposal_id") or "").strip()

        def add_warning(code: str, message: str, weak: bool = True) -> None:
            warnings.append({
                "code": code,
                "candidate_index": idx,
                "title": title,
                "proposal_id": proposal_id,
                "message": message,
            })
            if weak:
                weak_indexes.add(idx)

        acceptance = str(candidate.get("acceptance_test_idea") or "").strip()
        if _code_brief_text_is_vague(acceptance):
            add_warning("weak_acceptance_test", "missing or vague acceptance test idea")

        likely_files = str(candidate.get("likely_link_files_or_subsystem") or "").strip()
        if _code_brief_likely_files_are_vague(likely_files):
            add_warning("weak_likely_files", "missing or vague likely Link files/subsystem")

        risk_raw = str(candidate.get("risk_raw") or "").strip().lower()
        if risk_raw not in ("low", "medium", "high"):
            add_warning("unknown_risk_level", "unknown or empty risk level")

        evidence = str(candidate.get("evidence_from_source") or "").strip()
        if _code_brief_text_is_vague(evidence):
            add_warning("missing_source_evidence", "missing evidence from source")

        duplicate_title = bool(title_key and title_counts.get(title_key, 0) > 1)
        if duplicate_title:
            duplicate_count += 1
            if title_key in seen_titles:
                add_warning(
                    "duplicate_candidate_title",
                    "duplicate candidate title within this brief",
                    weak=False,
                )
            seen_titles.add(title_key)

        duplicate_existing = bool(proposal_id and (storage / f"{proposal_id}.json").exists())
        if duplicate_existing:
            duplicate_count += 1
            add_warning(
                "existing_proposal_id",
                "proposal_id already exists in .agents/control_plane/proposals",
                weak=False,
            )

        candidate["duplicate_existing"] = duplicate_existing
        if proposal:
            proposal["duplicate_existing"] = duplicate_existing

    return {
        "quality_warnings": warnings,
        "weak_candidate_count": len(weak_indexes),
        "duplicate_count": duplicate_count,
    }


def _code_brief_recommendation(risk: str) -> str:
    return "accept" if risk == "low" else "review"


def _split_code_brief_list(text: str) -> list[str]:
    items: list[str] = []
    for raw in str(text or "").splitlines():
        line = raw.strip().strip("-").strip()
        if not line:
            continue
        line = line.strip("`")
        if line:
            items.append(line)
    return items


def _code_brief_candidate_to_proposal(
    candidate: dict[str, Any],
    source_path: str,
    seen_titles: set[str] | None = None,
) -> dict[str, Any]:
    """Convert one parsed code-brief candidate to a proposal artifact."""
    from link_core.control_plane import make_proposal_id
    from link_core.receipts import make_unique_title

    title = make_unique_title(
        candidate.get("title"),
        existing_titles=seen_titles,
    )
    if seen_titles is not None:
        seen_titles.add(" ".join(title.split()).lower())
    risk = _normalize_code_brief_risk(str(candidate.get("risk") or ""))
    problem = str(candidate.get("problem") or "").strip()
    pattern = str(candidate.get("pattern_observed") or "").strip()
    proposed = str(candidate.get("proposed_link_upgrade") or "").strip()
    likely_files = str(candidate.get("likely_link_files_or_subsystem") or "").strip()
    acceptance = str(candidate.get("acceptance_test_idea") or "").strip()
    evidence_text = str(candidate.get("evidence_from_source") or "").strip()

    implementation_plan = [proposed] if proposed else [f"Review code brief candidate: {title}"]
    if pattern:
        implementation_plan.append(f"Adapt observed pattern: {pattern}")

    verification_commands = [acceptance] if acceptance else [
        "Add a focused smoke check for the proposed Link behavior."
    ]

    affected_files = _split_code_brief_list(likely_files)
    if not affected_files and likely_files:
        affected_files = [likely_files]

    summary_parts = [p for p in (problem, proposed) if p]
    source_summary = " ".join(summary_parts) or title

    return {
        "proposal_id": make_proposal_id(title, source_path),
        "title": title,
        "source_path": source_path,
        "source_summary": source_summary,
        "extracted_capabilities": [p for p in (pattern, proposed) if p],
        "link_takeaways": [p for p in (problem, proposed) if p],
        "affected_files": affected_files,
        "risk_level": risk,
        "expected_behavior_change": proposed or problem or title,
        "implementation_plan": implementation_plan,
        "verification_commands": verification_commands,
        "rollback_plan": "Do not merge; revert the proposal patch branch if verification fails.",
        "recommendation": _code_brief_recommendation(risk),
        "status": "pending",
        "created_at": _utc_now(),
        "source_reference": f"code brief: {source_path}",
        "code_brief_evidence": evidence_text,
    }


def _code_brief_propose_error(
    error: str,
    source: str = "",
    source_exists: bool = False,
    dry_run: bool = True,
) -> dict[str, Any]:
    return {
        "ok": False,
        "source": source,
        "source_exists": source_exists,
        "candidate_count": 0,
        "proposal_count": 0,
        "candidates": [],
        "proposals": [],
        "dry_run": dry_run,
        "written_paths": [],
        "quality_warnings": [],
        "weak_candidate_count": 0,
        "duplicate_count": 0,
        "next_commands": [
            "python3 link.py growth archive-code-brief --source <path> --write",
            "python3 link.py growth run",
        ],
        "warnings": [],
        "error": error,
    }


def render_code_brief_propose_view(data: dict[str, Any]) -> None:
    """Render code-brief proposal conversion with rich if available."""
    try:
        import rich  # noqa: F401
    except ImportError:
        render_code_brief_propose_plain(data)
        return
    render_code_brief_propose_with_rich(data)


def render_code_brief_propose_with_rich(data: dict[str, Any]) -> None:
    """Render code-brief proposal conversion using rich."""
    from rich.console import Console
    from rich.panel import Panel
    from rich.rule import Rule
    from rich.table import Table
    from rich.text import Text

    console = Console(highlight=False, soft_wrap=True)
    ok = data.get("source_exists", False)
    dry_run = data.get("dry_run", True)
    label = "FAILED" if not ok else ("DRY RUN" if dry_run else "WRITTEN")
    color = "red" if not ok else ("yellow" if dry_run else "bold green")

    header = Table.grid(padding=(0, 1))
    header.add_column(justify="left")
    header.add_column(justify="right")
    header.add_row("[bold bright_cyan]LINK GROWTH CODE BRIEF PROPOSE[/]",
                   f"[{color}]{label}[/]")
    console.print(header)

    if not ok:
        console.print(Panel(Text(data.get("error", "unknown error"), style="red"),
                            border_style="red"))
        console.print(Rule(style="dim"))
        return

    info = Text()
    info.append("source: ", style="dim")
    info.append(data.get("source", "?"), style="bold")
    info.append(f"\n[dim]candidates: {data.get('candidate_count', 0)}  proposals: {data.get('proposal_count', 0)}[/]")
    console.print(Panel(info, border_style="dim"))

    if data.get("error"):
        console.print(Panel(Text(str(data.get("error")), style="yellow"),
                            border_style="yellow"))

    quality_warnings = data.get("quality_warnings", [])
    if quality_warnings:
        warn_text = Text()
        for warning in quality_warnings:
            title = warning.get("title") or "candidate"
            message = warning.get("message") or warning.get("code") or "quality warning"
            warn_text.append(f"- {title}: {message}\n", style="yellow")
        console.print(Panel(warn_text, title="QUALITY WARNINGS", border_style="yellow"))

    for proposal in data.get("proposals", [])[:8]:
        card = Text()
        card.append(f"[bold]{proposal.get('title', '?')}[/]")
        card.append(f"\n[dim]risk:[/] {proposal.get('risk_level', '?')}  ")
        card.append(f"[dim]recommendation:[/] {proposal.get('recommendation', '?')}")
        summary = proposal.get("source_summary", "")
        if summary:
            card.append(f"\n[dim]summary:[/] {summary[:180]}")
        tests = proposal.get("verification_commands", [])
        if tests:
            card.append(f"\n[dim]acceptance:[/] {tests[0][:160]}")
        console.print(Panel(card, title=proposal.get("proposal_id", "?"),
                            border_style="dim"))

    if data.get("written_paths"):
        wrote = Text()
        for path in data.get("written_paths", []):
            wrote.append(f"  {path}\n", style="dim")
        console.print(Panel(wrote, title="WRITTEN", border_style="dim green"))

    next_text = Text()
    for command in data.get("next_commands", []):
        next_text.append(f"  $ {command}\n", style="dim")
    if data.get("written_paths"):
        written = Text()
        for path in data.get("written_paths", [])[:10]:
            written.append(f"{path}\n", style="green")
        console.print(Panel(written, title="WRITTEN PROPOSALS", border_style="green"))
    console.print(Rule(style="dim"))
    console.print(Panel(next_text, title="SUGGESTED NEXT STEPS", border_style="green"))


def render_code_brief_propose_plain(data: dict[str, Any]) -> None:
    """Render code-brief proposal conversion using plain text."""
    ok = data.get("source_exists", False)
    dry_run = data.get("dry_run", True)
    label = "FAILED" if not ok else ("DRY RUN" if dry_run else "WRITTEN")
    out = [f"== LINK GROWTH CODE BRIEF PROPOSE ({label}) ==", ""]

    if not ok:
        out.append(f"error: {data.get('error', 'unknown error')}")
        print("\n".join(out))
        return

    out.append(f"source: {data.get('source', '?')}")
    out.append(f"candidates: {data.get('candidate_count', 0)}  proposals: {data.get('proposal_count', 0)}")
    if data.get("error"):
        out.append(f"note: {data.get('error')}")

    quality_warnings = data.get("quality_warnings", [])
    if quality_warnings:
        out.append("")
        out.append("-- QUALITY WARNINGS --")
        for warning in quality_warnings:
            title = warning.get("title") or "candidate"
            message = warning.get("message") or warning.get("code") or "quality warning"
            out.append(f"  - {title}: {message}")
    out.append("")

    for proposal in data.get("proposals", []):
        out.append(f"--- {proposal.get('proposal_id', '?')} ---")
        out.append(f"title:          {proposal.get('title', '?')}")
        out.append(f"risk_level:     {proposal.get('risk_level', '?')}")
        out.append(f"recommendation: {proposal.get('recommendation', '?')}")
        tests = proposal.get("verification_commands", [])
        if tests:
            out.append(f"acceptance:     {tests[0]}")
        out.append("")

    if data.get("written_paths"):
        out.append("Written:")
        for path in data.get("written_paths", []):
            out.append(f"  {path}")
        out.append("")

    out.append("-- SUGGESTED NEXT STEPS --")
    if data.get("written_paths"):
        out.append("written proposals:")
        for path in data.get("written_paths", [])[:10]:
            out.append(f"  {path}")
    for command in data.get("next_commands", []):
        out.append(f"  $ {command}")
    print("\n".join(out))


# ── run guide entry point ────────────────────────────────────────────────


def run_main(argv: list[str] | None = None) -> int:
    """Entry point for ``python3 link.py growth run``.

    A read-only guided Growth workflow dashboard. Shows the current
    pipeline stage, proposal counts, and the next recommended command.
    When ``--source <path>`` is given, includes a dry-run mining preview.

    Flags:
        --source <path>  Optional research source for a mining preview.
        --json           Machine-readable output.
    """
    args = _normalize_cli_dashes(sys.argv[1:] if argv is None else argv)

    if "--help" in args or "-h" in args:
        print("Growth run: guided Growth workflow dashboard")
        print("")
        print("Usage:")
        print("  python3 link.py growth run")
        print("  python3 link.py growth run --json")
        print("  python3 link.py growth run --source <path>")
        print("  python3 link.py growth run --source <path> --json")
        print("")
        print("This command is a read-only guide/router. It shows")
        print("your current Growth pipeline stage and the next")
        print("safest command to run. No files are written.")
        return 0

    source = _parse_arg(args, "--source")
    data = collect_run_data(source=source)

    if "--json" in args:
        print(json.dumps(data, indent=2, default=str))
        return 0

    render_run(data)
    return 0


def collect_run_data(
    source: str | None = None,
    root: str | None = None,
) -> dict[str, Any]:
    """Gather all Growth workflow guide data from existing collectors.

    Composes ``collect_console_data``, ``list_proposals``,
    ``build_dashboard``, and (optionally) ``collect_propose_data``
    into a single state dictionary describing where the user is in
    the Growth pipeline and what to do next.

    Read-only. No mutation. No network. No subprocess.
    """
    from pathlib import Path

    from link_core.control_plane import list_proposals

    repo_root = Path(root) if root else Path.cwd()
    base_data = _collect_growth_run_base_data(repo_root)

    proposals = list_proposals(root=repo_root)
    patch_draft_counts = _collect_patch_draft_counts(repo_root)

    status_counts: dict[str, int] = {}
    accepted_ids: list[str] = []
    for p in proposals:
        s = p.get("status", "?")
        status_counts[s] = status_counts.get(s, 0) + 1
        if s == "accepted":
            accepted_ids.append(p.get("proposal_id", ""))

    total = len(proposals)

    handoff_dir = repo_root / ".agents" / "control_plane" / "worker_handoffs"
    has_handoffs = handoff_dir.exists() and any(handoff_dir.glob("*.json"))

    router_state = _collect_growth_router_state(repo_root, proposals)
    router_state["accepted_proposal_ids"] = accepted_ids

    stage, next_action, commands = _derive_workflow_state(
        total=total,
        accepted_count=status_counts.get("accepted", 0),
        pending_count=status_counts.get("pending", 0),
        has_handoffs=has_handoffs,
        router_state=router_state,
    )
    coverage = _collect_growth_coverage_data(
        repo_root=repo_root,
        proposals=proposals,
        proposal_counts=status_counts,
        router_state=router_state,
        commands=commands,
    )

    result: dict[str, Any] = {
        "version": base_data.get("version", ""),
        "repo": base_data.get("repo", {}),
        "healthcheck": base_data.get("healthcheck", {}),
        "mode": base_data.get("mode", {}),
        "pipeline_stages": base_data.get("pipeline_stages", []),
        "pipeline_stage": stage,
        "proposal_counts": status_counts,
        "proposals_total": total,
        "accepted_proposal_ids": accepted_ids,
        "has_handoffs": has_handoffs,
        "router_state": router_state,
        "patch_draft_counts": patch_draft_counts,
        "coverage": coverage,
        "next_action": next_action,
        "commands": commands,
        "source_preview": None,
    }

    if source:
        try:
            preview = collect_propose_data(source, write=False, root=root)
            result["source_preview"] = {
                "source": preview.get("source", ""),
                "source_exists": preview.get("source_exists", False),
                "chunk_count": preview.get("chunk_count", 0),
                "candidate_count": preview.get("candidate_count", 0),
                "proposal_count": preview.get("proposal_count", 0),
                "error": preview.get("error"),
            }
        except Exception as exc:
            result["source_preview"] = {
                "source": source,
                "source_exists": False,
                "chunk_count": 0,
                "candidate_count": 0,
                "proposal_count": 0,
                "error": str(exc),
            }

    return result


def _collect_growth_coverage_data(
    repo_root: "Path",
    proposals: list[dict[str, Any]],
    proposal_counts: dict[str, int],
    router_state: dict[str, Any],
    commands: list[str],
) -> dict[str, Any]:
    """Collect read-only Growth pipeline coverage counts for run JSON."""
    code_queue = collect_archive_code_queue(
        top=_MAX_CODE_QUEUE_TOP,
        root=str(repo_root),
    )
    code_queue_count = int(code_queue.get("queue_count", 0) or 0)
    skipped_count = int(code_queue.get("skipped_count", 0) or 0)
    discovered_count = int(code_queue.get("total_discovered", 0) or 0) + skipped_count

    candidate_count = 0
    briefs_dir = repo_root / _CODE_BRIEFS_DIR
    if briefs_dir.exists():
        for path in sorted(briefs_dir.glob("*.md")):
            try:
                text = path.read_text(encoding="utf-8", errors="replace")
            except Exception:
                continue
            candidate_count += len(_parse_code_brief_candidates(text, str(path)))

    next_commands = list(commands or [])
    return {
        "archive_count": int(router_state.get("archive_count", 0) or 0),
        "extracted_source_count": int(router_state.get("extracted_source_count", 0) or 0),
        "catalog_count": int(router_state.get("catalog_count", 0) or 0),
        "discovered_code_file_count": discovered_count,
        "queued_code_file_count": code_queue_count,
        "skipped_code_file_count": skipped_count,
        "code_brief_count": int(router_state.get("code_brief_count", 0) or 0),
        "candidate_count": candidate_count,
        "proposal_count": len(proposals),
        "pending_proposal_count": int(proposal_counts.get("pending", 0) or 0),
        "accepted_proposal_count": int(proposal_counts.get("accepted", 0) or 0),
        "rejected_proposal_count": int(proposal_counts.get("rejected", 0) or 0),
        "handoff_count": int(router_state.get("handoff_count", 0) or 0),
        "verifier_receipt_count": int(router_state.get("verifier_receipt_count", 0) or 0),
        "next_safest_command": next_commands[0] if next_commands else "",
        "next_commands": next_commands,
    }


def _collect_growth_run_base_data(repo_root: "Path") -> dict[str, Any]:
    """Collect Growth run header data without mutating runtime state."""
    import subprocess

    from link_core.control_plane import CONTROL_PLANE_STAGES
    from link_modes.growth import MODE_NAME, TEAM_CONFIG, control_plane_stages
    from link_modes.growth.link_candidate_proposal_bridge import BRIDGE_VERSION

    def git(args: list[str]) -> str:
        try:
            proc = subprocess.run(
                ["git", *args],
                cwd=repo_root,
                text=True,
                stdout=subprocess.PIPE,
                stderr=subprocess.DEVNULL,
                timeout=5,
            )
        except Exception:
            return ""
        if proc.returncode != 0:
            return ""
        return (proc.stdout or "").strip()

    status = git(["status", "--short"])
    return {
        "version": CONSOLE_VERSION,
        "repo": {
            "branch": git(["branch", "--show-current"]),
            "head": git(["rev-parse", "--short", "HEAD"]),
            "safe_tag": git(["rev-parse", "--short", "safe-link-latest"]),
            "dirty": bool(status),
        },
        "healthcheck": {"ok": None, "note": "not run by growth run"},
        "mode": {
            "name": MODE_NAME,
            "team_config": TEAM_CONFIG,
            "entrypoint": "link_modes.growth.propose()",
            "bridge_version": BRIDGE_VERSION,
            "has_propose": True,
        },
        "pipeline_stages": list(CONTROL_PLANE_STAGES) or list(control_plane_stages()),
    }


def _collect_patch_draft_counts(repo_root: "Path") -> dict[str, int]:
    """Count patch draft runtime files without creating directories."""
    draft_root = repo_root / ".link" / "patch_drafts"
    states = ("pending", "approved", "rejected", "retry", "receipts")
    return {
        state: len(list((draft_root / state).glob("*.json")))
        if (draft_root / state).exists() else 0
        for state in states
    }


def _collect_growth_router_state(
    repo_root: "Path",
    proposals: list[dict[str, Any]],
) -> dict[str, Any]:
    """Collect read-only Growth routing signals from local artifacts."""
    proposal_ids = {str(p.get("proposal_id", "")) for p in proposals}
    briefs_dir = repo_root / _CODE_BRIEFS_DIR
    catalogs_dir = repo_root / _CATALOG_OUTPUT_DIR
    extracted_dir = repo_root / _EXTRACTED_DIR
    handoff_dir = repo_root / ".agents" / "control_plane" / "worker_handoffs"
    receipt_dir = repo_root / ".agents" / "control_plane" / "verifier_receipts"

    candidate_briefs: list[dict[str, Any]] = []
    if briefs_dir.exists():
        for path in sorted(briefs_dir.glob("*.md")):
            try:
                text = path.read_text(encoding="utf-8", errors="replace")
            except Exception:
                continue
            candidates = _parse_code_brief_candidates(text, str(path))
            if not candidates:
                continue
            generated_ids = {
                _code_brief_candidate_to_proposal(c, str(path))["proposal_id"]
                for c in candidates
            }
            missing_count = len(generated_ids - proposal_ids)
            if missing_count > 0:
                try:
                    display_path = str(path.relative_to(repo_root))
                except ValueError:
                    display_path = str(path)
                candidate_briefs.append({
                    "path": display_path,
                    "absolute_path": str(path),
                    "candidate_count": len(candidates),
                    "ungenerated_proposal_count": missing_count,
                    "suggested_command": (
                        f"python3 link.py growth code-brief-propose --source {display_path}"
                    ),
                })

    handoff_paths = sorted(handoff_dir.glob("*.json")) if handoff_dir.exists() else []
    receipt_paths = sorted(receipt_dir.glob("*.json")) if receipt_dir.exists() else []
    catalog_paths = sorted(catalogs_dir.glob("*.json")) if catalogs_dir.exists() else []
    if extracted_dir.exists():
        extracted_paths = [p for p in sorted(extracted_dir.iterdir()) if p.is_dir()]
    else:
        extracted_paths = []

    return {
        "code_brief_count": len(list(briefs_dir.glob("*.md"))) if briefs_dir.exists() else 0,
        "candidate_brief_count": len(candidate_briefs),
        "next_candidate_brief": candidate_briefs[0] if candidate_briefs else None,
        "catalog_count": len(catalog_paths),
        "extracted_source_count": len(extracted_paths),
        "archive_count": len(_discover_growth_archives(repo_root)),
        "handoff_count": len(handoff_paths),
        "next_handoff_id": handoff_paths[0].stem if handoff_paths else None,
        "verifier_receipt_count": len(receipt_paths),
    }


def _discover_growth_archives(repo_root: "Path") -> list[str]:
    """Return research archive paths without reading archive contents."""
    research_root = repo_root / "research"
    if not research_root.exists():
        return []

    archives: list[str] = []
    for path in sorted(research_root.rglob("*")):
        if not path.is_file():
            continue
        rel = str(path.relative_to(research_root))
        if rel.startswith("_extracted/") or rel.startswith("_catalog/"):
            continue
        lower_name = path.name.lower()
        if any(lower_name.endswith(suffix) for suffix in _ARCHIVE_SUFFIXES):
            archives.append(str(path))
    return archives


def _derive_workflow_state(
    total: int,
    accepted_count: int,
    pending_count: int,
    has_handoffs: bool,
    router_state: dict[str, Any] | None = None,
) -> tuple[str, str, list[str]]:
    """Derive pipeline stage, next_action, and recommended commands."""
    router_state = router_state or {}
    next_brief = router_state.get("next_candidate_brief") or {}

    if total == 0:
        if next_brief:
            brief_path = next_brief.get("path", "<brief.md>")
            return (
                "ProposalWriter",
                "Code brief candidates are ready to convert into pending proposals.",
                [
                    f"python3 link.py growth code-brief-propose --source {brief_path}",
                    f"python3 link.py growth code-brief-propose --source {brief_path} --write",
                    "python3 link.py growth proposals",
                ],
            )

        if router_state.get("catalog_count", 0) > 0 and router_state.get("code_brief_count", 0) == 0:
            return (
                "CandidateExtractor",
                "Cataloged extracted code exists. Queue code sources, then write a code brief for one source.",
                [
                    "python3 link.py growth archive-code-queue",
                    "python3 link.py growth archive-code-brief --source <path> --write",
                    "python3 link.py growth code-brief-propose --source research/_catalog/code_briefs/<slug>.md",
                ],
            )

        if router_state.get("extracted_source_count", 0) > 0 and router_state.get("catalog_count", 0) == 0:
            return (
                "ResearchIngest",
                "Extracted archives exist. Catalog them before mining code upgrade candidates.",
                [
                    "python3 link.py growth archive-catalog --source <extracted_path> --write",
                    "python3 link.py growth archive-code-queue",
                ],
            )

        if router_state.get("archive_count", 0) > 0:
            return (
                "ResearchIngest",
                "Research archives exist. Inventory, extract, and catalog them before mining proposals.",
                [
                    "python3 link.py growth archive-inventory",
                    "python3 link.py growth archive-extract --source <archive_path> --write",
                    "python3 link.py growth archive-catalog --source <extracted_path> --write",
                ],
            )

        return (
            "ResearchIngest",
            "No proposals or cataloged research found. Start with archive inventory or provide a source.",
            [
                "python3 link.py growth archive-inventory",
                "python3 link.py growth propose --source <path>",
            ],
        )

    if accepted_count > 0 and not has_handoffs:
        accepted_ids = router_state.get("accepted_proposal_ids") or []
        proposal_id = accepted_ids[0] if accepted_ids else "<id>"
        return (
            "PatchWorker",
            "Accepted proposals are ready for handoff creation.",
            [
                "python3 link.py growth proposals",
                f"python3 link.py growth handoff {proposal_id}",
                f"python3 link.py growth handoff {proposal_id} --write",
            ],
        )

    if has_handoffs and router_state.get("verifier_receipt_count", 0) == 0:
        handoff_id = router_state.get("next_handoff_id") or "<handoff_id>"
        return (
            "Verifier",
            "Worker handoffs exist. Create a verifier receipt through the safe execute path.",
            [
                "python3 link.py growth handoffs",
                f"python3 link.py growth execute {handoff_id}",
                f"python3 link.py growth execute {handoff_id} --write",
            ],
        )

    if accepted_count > 0 and has_handoffs:
        return (
            "Verifier",
            "Handoffs and verifier receipts exist. Review receipts and finish the accepted work.",
            [
                "python3 link.py growth receipts",
                "python3 link.py growth handoffs",
            ],
        )

    if pending_count > 0:
        return (
            "HumanApproval",
            "Proposals are pending review. Approve or reject them.",
            [
                "python3 link.py growth proposals",
                "python3 link.py growth approve <id>",
                "python3 link.py growth reject <id> --reason \"...\"",
            ],
        )

    return (
        "HumanApproval",
        "Proposals present. Review status and take next action.",
        [
            "python3 link.py growth proposals",
            "python3 link.py growth approve <id>",
        ],
    )


# ── run rich renderer ───────────────────────────────────────────────────


def render_run_with_rich(data: dict[str, Any]) -> None:
    """Render the Growth run guide using rich."""
    from rich.console import Console
    from rich.panel import Panel
    from rich.rule import Rule
    from rich.table import Table
    from rich.text import Text

    console = Console(highlight=False, soft_wrap=True)
    repo = data.get("repo", {})
    hc = data.get("healthcheck", {})
    stage = data.get("pipeline_stage", "?")
    next_action = data.get("next_action", "")
    commands = data.get("commands", [])
    counts = data.get("proposal_counts", {})
    total = data.get("proposals_total", 0)
    accepted_ids = data.get("accepted_proposal_ids", [])
    has_handoffs = data.get("has_handoffs", False)
    source_preview = data.get("source_preview")

    stage_colors = {
        "ResearchIngest": "dim", "CandidateExtractor": "dim",
        "HumanApproval": "yellow", "ProposalWriter": "dim",
        "PatchWorker": "green", "Verifier": "cyan",
        "Finalizer": "bright_green", "PatchPlanner": "dim",
        "FeasibilityReviewer": "dim",
    }

    # ── header ──
    header = Table.grid(padding=(0, 1))
    header.add_column(justify="left")
    header.add_column(justify="right")
    header.add_row(
        f"[bold bright_cyan]LINK GROWTH RUN GUIDE[/]",
        f"[dim]v{data.get('version', '?')}[/]",
    )
    console.print(header)

    # ── repo bar ──
    repo_line = (
        f"branch: [bold]{repo.get('branch', '?')}[/]  "
        f"HEAD: [bold]{repo.get('head', '?')[:8]}[/]  "
        f"dirty: [{'red' if repo.get('dirty') else 'green'}]{'YES' if repo.get('dirty') else 'no'}[/]"
    )
    console.print(Panel(repo_line, border_style="dim"))

    # ── pipeline stage panel ──
    sc = stage_colors.get(stage, "")
    stage_text = Text()
    stage_text.append("Current stage: ", style="dim")
    stage_text.append(str(stage), style=sc or "")
    if next_action:
        stage_text.append(f"\n{next_action}", style="dim")
    console.print(Panel(stage_text, title="PIPELINE STAGE", border_style=sc or "dim"))

    # ── health quick status ──
    hc_ok = hc.get("ok")
    hc_label = "PASS" if hc_ok is True else ("FAIL" if hc_ok is False else "not run")
    hc_color = "green" if hc_ok is True else ("red" if hc_ok is False else "yellow")
    hc_text = Text()
    hc_text.append(f"healthcheck: {hc_label}", style=hc_color)
    if hc.get("note"):
        hc_text.append(f"  ({hc.get('note')})", style="dim")
    console.print(Panel(hc_text, border_style=hc_color))

    # ── proposal counts panel ──
    count_text = Text()
    count_labels = [
        ("pending", "yellow"), ("accepted", "green"), ("rejected", "red"),
        ("deferred", "magenta"), ("needs_smaller_plan", "orange1"),
        ("converted_to_patch", "cyan"),
    ]
    first = True
    for label, color in count_labels:
        val = counts.get(label, 0)
        if val == 0 and label not in ("pending", "accepted", "rejected"):
            continue
        if not first:
            count_text.append("  ")
        first = False
        count_text.append(f"{label}: {val}", style=color)
    count_text.append(f"\ntotal: {total}", style="dim")
    console.print(Panel(count_text, title="PROPOSAL COUNTS", border_style="dim"))

    # ── accepted ready for handoff ──
    if accepted_ids:
        ready_text = Text()
        ready_text.append(f"{len(accepted_ids)} accepted proposal(s) ready for handoff:\n", style="green")
        for a_id in accepted_ids[:10]:
            ready_text.append(f"  {a_id}\n", style="dim")
        console.print(Panel(ready_text, title="READY FOR HANDOFF", border_style="green"))

    if has_handoffs:
        hf_text = Text("Worker handoff directory contains files.", style="cyan")
        console.print(Panel(hf_text, title="HANDOFFS EXIST", border_style="cyan"))

    # ── source preview ──
    if source_preview:
        sp = source_preview
        sp_text = Text()
        exists = sp.get("source_exists", False)
        if not exists:
            sp_text.append(f"source not found: {sp.get('source', '?')}", style="red")
        else:
            sp_text.append(f"source: {sp.get('source', '?')}\n", style="bold")
            sp_text.append(
                f"[dim]chunks: {sp.get('chunk_count', 0)}  "
                f"candidates: {sp.get('candidate_count', 0)}  "
                f"proposals (dry-run): {sp.get('proposal_count', 0)}[/]"
            )
            if sp.get("candidate_count", 0) == 0:
                sp_text.append(
                    "\n[dim]no candidates — check keyword matches or duplicate titles[/]"
                )
            else:
                sp_text.append(
                    "\n[dim]use --write to persist proposals to disk[/]"
                )
        console.print(Panel(sp_text, title="SOURCE PREVIEW", border_style="dim"))

    # ── next commands panel ──
    import textwrap

    cmd_text = Text()
    cmd_text.append("Next commands:\n", style="bold")
    for cmd in commands:
        wrapped = textwrap.wrap(
            f"$ {cmd}",
            width=68,
            subsequent_indent="  ",
            break_long_words=False,
            break_on_hyphens=False,
        ) or [f"$ {cmd}"]
        for idx, line in enumerate(wrapped):
            prefix = "  " if idx == 0 else "    "
            cmd_text.append(f"{prefix}{line}\n", style="dim")
    console.print(Panel(cmd_text, title="RECOMMENDED NEXT STEP", border_style="green"))

    console.print(Rule(style="dim"))
    console.print(
        "  [dim]python3 link.py growth status  -- status console[/]"
    )


# ── run plain fallback ──────────────────────────────────────────────────


def render_run_plain(data: dict[str, Any]) -> None:
    """Render the Growth run guide using plain print."""
    repo = data.get("repo", {})
    hc = data.get("healthcheck", {})
    stage = data.get("pipeline_stage", "?")
    next_action = data.get("next_action", "")
    commands = data.get("commands", [])
    counts = data.get("proposal_counts", {})
    total = data.get("proposals_total", 0)
    accepted_ids = data.get("accepted_proposal_ids", [])
    has_handoffs = data.get("has_handoffs", False)
    source_preview = data.get("source_preview")

    out: list[str] = []
    out.append("== LINK GROWTH RUN GUIDE ==")
    out.append(
        f"branch: {repo.get('branch', '?')}  "
        f"HEAD: {repo.get('head', '?')[:8]}  "
        f"dirty: {'YES' if repo.get('dirty') else 'no'}"
    )
    out.append("")
    out.append(f"-- PIPELINE STAGE: {stage} --")
    out.append(next_action)
    out.append("")
    hc_ok = hc.get("ok")
    hc_label = "PASS" if hc_ok is True else ("FAIL" if hc_ok is False else "not run")
    out.append(f"healthcheck: {hc_label}")
    out.append("")
    out.append("-- PROPOSAL COUNTS --")
    out.append(
        f"pending: {counts.get('pending', 0)}  "
        f"accepted: {counts.get('accepted', 0)}  "
        f"rejected: {counts.get('rejected', 0)}  "
        f"total: {total}"
    )
    out.append("")

    if accepted_ids:
        out.append("-- READY FOR HANDOFF --")
        for a_id in accepted_ids[:10]:
            out.append(f"  {a_id}")
        out.append("")
    if has_handoffs:
        out.append("Handoff directory contains files.")
        out.append("")

    if source_preview:
        sp = source_preview
        out.append("-- SOURCE PREVIEW --")
        if not sp.get("source_exists", False):
            out.append(f"source not found: {sp.get('source', '?')}")
        else:
            out.append(f"source: {sp.get('source', '?')}")
            out.append(
                f"chunks: {sp.get('chunk_count', 0)}  "
                f"candidates: {sp.get('candidate_count', 0)}  "
                f"proposals (dry-run): {sp.get('proposal_count', 0)}"
            )
        out.append("")

    out.append("-- RECOMMENDED NEXT STEP --")
    for cmd in commands:
        out.append(f"  $ {cmd}")
    out.append("")

    out.append("python3 link.py growth status  -- status console")
    print("\n".join(out))


# ── run render orchestrator ─────────────────────────────────────────────


def render_run(data: dict[str, Any]) -> None:
    """Render the Growth run guide with rich if available."""
    try:
        import rich  # noqa: F401
    except ImportError:
        render_run_plain(data)
        return
    render_run_with_rich(data)


def main(argv: list[str] | None = None) -> int:
    """Entry point for ``python3 link.py growth status``.

    Passes through to render_console unless --json is requested.
    """
    args = sys.argv[1:] if argv is None else argv
    data = collect_console_data()
    if "--json" in args:
        print(json.dumps(data, indent=2, default=str))
        return 0
    render_console(data)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())